(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,254881,(n,t,i)=>{t.exports=JSON.parse('{"visa":[{"slug":"d-4-hoc-tieng","title":"Visa D-4-1: học tiếng Hàn tại 어학당","summary":"Điều kiện, hồ sơ và cách nộp visa học tiếng D-4-1 từ Việt Nam theo hướng dẫn mới nhất của cơ quan ngoại giao Hàn Quốc.","updated":"2026-09-25","facts":{"group":"Du học","code":"D-4"},"html":"<h2 id=\\"danh-cho-ai\\">Dành cho ai</h2>\\n<p>Người muốn sang Hàn học khoá tiếng Hàn tại 어학당 (trường tiếng) của một trường đại học hoặc cao đẳng. Mã visa là D-4-1 (일반연수, tu nghiệp phổ thông – học tiếng Hàn).</p>\\n<p>Nếu muốn vào thẳng hệ đại học, cao học thì xem bài visa D-2.</p>\\n<h2 id=\\"dieu-kien-chinh\\">Điều kiện chính</h2>\\n<ul>\\n<li>Có <strong>giấy nhập học tiêu chuẩn</strong> (표준입학허가서) của trường tiếng.</li>\\n<li>Chứng minh được học lực và tài chính. Với D-4, kể cả trường &quot;ưu tú&quot; (tỷ lệ bất hợp pháp dưới 1%) vẫn phải nộp hai loại giấy này.</li>\\n<li><strong>Tài chính</strong> (theo hướng dẫn ngày 05/01/2026 của Tổng Lãnh sự quán TP.HCM; thông báo của KVAC Hà Nội cập nhật 11/06/2026 ghi cùng mức): sổ tiết kiệm đứng tên người xin visa,<ul>\\n<li>trường ở vùng thủ đô: số dư ít nhất <strong>10 triệu won</strong>, đã gửi <strong>từ 6 tháng</strong> trở lên;</li>\\n<li>trường ở địa phương: ít nhất <strong>8 triệu won</strong>, đã gửi từ 6 tháng trở lên.</li>\\n<li>Sổ bằng tiền đồng được quy đổi theo tỷ giá ngày nộp. Không nhận sổ tiết kiệm chuyển nhượng.</li>\\n</ul>\\n</li>\\n<li>Nguyên tắc là <strong>bố mẹ bảo lãnh tài chính</strong>.</li>\\n</ul>\\n<h3 id=\\"nguoi-viet-nam-di-duong-nao-tuy-loai-truong\\">Người Việt Nam: đi đường nào tuỳ loại trường</h3>\\n<p>Hàn Quốc chia trường thành nhiều nhóm. Theo bảng của Tổng Lãnh sự quán TP.HCM (2026):</p>\\n<ul>\\n<li><strong>Trường chứng nhận</strong> (인증대학): nộp visa D-4-1 trực tiếp tại cơ quan ngoại giao.</li>\\n<li><strong>Trường thường</strong> (일반대학) và <strong>trường top dưới</strong> (하위대학): công dân Việt Nam, Trung Quốc, Mông Cổ, Uzbekistan <strong>chỉ</strong> xin D-4-1 được bằng <strong>mã code</strong> (사증발급인정서, giấy chứng nhận cấp visa). Trường ở Hàn xin mã tại Cục Xuất nhập cảnh, sau đó bạn mang mã đi nộp.</li>\\n</ul>\\n<p>Hỏi trường thuộc nhóm nào trước khi đóng tiền.</p>\\n<h2 id=\\"ho-so-can-chuan-bi\\">Hồ sơ cần chuẩn bị</h2>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1rwl51i\\"><span>Đơn xin cấp visa (사증발급신청서)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"fs77ud\\"><span>Hộ chiếu gốc và bản sao</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"zces3z\\"><span>1 ảnh 3,5 × 4,5 cm nền trắng, chụp trong 6 tháng gần nhất</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"x0fn9f\\"><span>Bản sao CCCD (hai mặt)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"9n88kg\\"><span>Giấy nhập học tiêu chuẩn (표준입학허가서)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"wpikjz\\"><span>Bản sao giấy đăng ký kinh doanh hoặc mã số của trường (사업자등록증 / 고유번호증)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1ohjxrf\\"><span>Kế hoạch đào tạo của trường: thời khoá biểu, giáo viên, cơ sở vật chất</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"z9p1xq\\"><span>Bằng cấp cao nhất, học bạ/bảng điểm đã hợp pháp hoá lãnh sự tại Bộ Ngoại giao Việt Nam và được xác nhận lãnh sự trong vòng 1 năm, kèm bản dịch công chứng</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"whhdiz\\"><span>Phiếu xét nghiệm lao phổi (결핵 검사) của bệnh viện do cơ quan ngoại giao chỉ định</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1aezmlv\\"><span>Giấy xác nhận số dư (cấp trong vòng 10 ngày gần nhất) và sổ tiết kiệm gốc</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"qb7mck\\"><span>Giấy tờ quan hệ gia đình (CT07, giấy khai sinh), giấy tờ nghề nghiệp – thu nhập của bố mẹ, cam kết bảo lãnh tài chính</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"i55bhr\\"><span>Kế hoạch học tập và bản tự giới thiệu (학업계획서, 자기소개서) viết bằng tiếng Hàn hoặc tiếng Anh (Đại sứ quán Hà Nội yêu cầu)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"drlgms\\"><span>Mẫu đăng ký thông tin người xin visa du học/học tiếng (Đại sứ quán Hà Nội yêu cầu)</span></label></li>\\n</ul>\\n<p>Giấy tờ Việt Nam cấp phải có bản dịch tiếng Hàn hoặc tiếng Anh có công chứng. Các giấy tờ kèm theo phải cấp trong vòng 3 tháng tính tới ngày nộp.</p>\\n<h2 id=\\"le-phi-va-thoi-gian-xu-ly\\">Lệ phí và thời gian xử lý</h2>\\n<ul>\\n<li><strong>Phí visa</strong>: theo trang hướng dẫn của Đại sứ quán Hà Nội và bảng phí cho công dân Việt Nam của KVAC Hà Nội, visa một lần trên 90 ngày (D-1 đến G-1) là <strong>50 USD</strong>.</li>\\n<li><strong>Phí nộp hộ tại Trung tâm tiếp nhận hồ sơ visa (KVAC) Hà Nội</strong>: 390.000 đồng/bộ, tính riêng ngoài phí visa, chỉ nhận tiền mặt.</li>\\n<li><strong>Thời gian xét</strong> (bảng của Đại sứ quán Hà Nội): hồ sơ du học/học tiếng thông thường khoảng <strong>20 ngày làm việc</strong>; nộp bằng mã code khoảng <strong>7 ngày làm việc</strong>. Có thể lâu hơn nếu phải bổ sung giấy hoặc phỏng vấn.</li>\\n</ul>\\n<h2 id=\\"cac-buoc-nop-ho-so\\">Các bước nộp hồ sơ</h2>\\n<ol>\\n<li>Chọn trường, nhận giấy nhập học. Nếu phải đi bằng mã code, chờ trường báo mã.</li>\\n<li>Đi khám lao ở bệnh viện chỉ định. Danh sách được Đại sứ quán cập nhật (bản gần nhất: 15/09/2025).</li>\\n<li>Hợp pháp hoá bằng cấp, dịch công chứng, xin giấy xác nhận số dư.</li>\\n<li>Nộp hồ sơ tại Trung tâm tiếp nhận hồ sơ visa (KVAC). Về nguyên tắc, nộp ở nơi thuộc thẩm quyền của cơ quan ngoại giao quản lý tỉnh bạn tốt nghiệp bậc học cao nhất (Đại sứ quán Hà Nội, Tổng Lãnh sự quán TP.HCM hoặc Đà Nẵng). Hỏi KVAC nếu không chắc mình thuộc khu vực nào.</li>\\n<li>Có thể được gọi <strong>phỏng vấn</strong>. Trượt phỏng vấn là bị từ chối.</li>\\n<li>Tra kết quả tại visa.go.kr.</li>\\n</ol>\\n<p>Từ 20/10/2025, Đại sứ quán cho phép trung tâm du học nộp hộ hồ sơ D-2, D-4 theo hình thức uỷ quyền. Bạn vẫn được tự nộp.</p>\\n<h2 id=\\"lien-quan-toi-kiip-va-topik\\">Liên quan tới KIIP và TOPIK</h2>\\n<p>D-4-1 không bắt buộc có TOPIK. Học xong 어학당 và muốn lên đại học thì xem bài D-2: khi đó TOPIK hoặc KIIP có thể được dùng để chứng minh tiếng Hàn.</p>\\n<h2 id=\\"luu-y\\">Lưu ý</h2>\\n<ul>\\n<li><strong>Không đổi hộ khẩu để nộp nơi khác.</strong> Đổi địa chỉ để xin visa thì về nguyên tắc bị từ chối.</li>\\n<li><strong>Giấy giả bị xử rất nặng.</strong> Đại sứ quán thông báo (26/05/2025) đã phát hiện nhiều phiếu lao, giấy khai sinh, giấy ngân hàng giả. Người nộp có thể bị báo công an Việt Nam và bị cấm nhập cảnh Hàn Quốc.</li>\\n<li>Bị từ chối thì phải chờ <strong>3 tháng</strong> mới được nộp lại.</li>\\n<li>Sau khi nhập cảnh, bạn phải làm 외국인등록증 (thẻ người nước ngoài) tại cơ quan xuất nhập cảnh.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://overseas.mofa.go.kr/vn-hochiminh-vi/brd/m_3360/view.do?seq=6&amp;page=2\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Tổng Lãnh sự quán Hàn Quốc tại TP.HCM — Visa du học (D-4, D-2), file &quot;VISA DU HOC 26.01&quot; (05/01/2026)</a> <span class=\\"source-domain\\">overseas.mofa.go.kr</span></li>\\n<li><a href=\\"https://overseas.mofa.go.kr/vn-vi/brd/m_2156/view.do?seq=681710\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Đại sứ quán Hàn Quốc tại Việt Nam — Visa du học (D-2, D-4), thực hiện từ 15/07/2024</a> <span class=\\"source-domain\\">overseas.mofa.go.kr</span></li>\\n<li><a href=\\"https://overseas.mofa.go.kr/vn-vi/brd/m_2164/view.do?seq=758111\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Đại sứ quán — Thời gian thẩm tra hồ sơ visa</a> <span class=\\"source-domain\\">overseas.mofa.go.kr</span></li>\\n<li><a href=\\"https://overseas.mofa.go.kr/vn-vi/brd/m_2164/view.do?seq=758165\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Đại sứ quán — Uỷ quyền xin visa du học từ 20/10/2025</a> <span class=\\"source-domain\\">overseas.mofa.go.kr</span></li>\\n<li><a href=\\"https://overseas.mofa.go.kr/vn-vi/brd/m_2164/view.do?seq=758162\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Đại sứ quán — Lưu ý khi xin thị thực (26/05/2025)</a> <span class=\\"source-domain\\">overseas.mofa.go.kr</span></li>\\n<li><a href=\\"https://overseas.mofa.go.kr/vn-vi/brd/m_2164/view.do?seq=758163\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Đại sứ quán — Danh sách cơ sở khám lao chỉ định (15/09/2025)</a> <span class=\\"source-domain\\">overseas.mofa.go.kr</span></li>\\n<li><a href=\\"https://overseas.mofa.go.kr/vn-vi/wpge/m_2154/contents.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Đại sứ quán — Hướng dẫn thủ tục visa (phí visa)</a> <span class=\\"source-domain\\">overseas.mofa.go.kr</span></li>\\n<li><a href=\\"https://visaforkorea-vt.com/info/service\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">KVAC Hà Nội — Lệ phí nộp hồ sơ và dịch vụ hỗ trợ</a> <span class=\\"source-domain\\">visaforkorea-vt.com</span></li>\\n<li><a href=\\"https://visaforkorea-vt.com/customercenter/faq/list/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">KVAC Hà Nội — Câu hỏi thường gặp, mục &quot;Phí visa&quot; (bảng phí thẩm tra cho công dân Việt Nam)</a> <span class=\\"source-domain\\">visaforkorea-vt.com</span></li>\\n<li><a href=\\"https://visaforkorea-vt.com/customercenter/notice/view/611\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">KVAC Hà Nội — Hồ sơ cần thiết khi xin visa du học (thay đổi ngày 11/06/2026)</a> <span class=\\"source-domain\\">visaforkorea-vt.com</span></li>\\n<li><a href=\\"https://www.visa.go.kr/openPage.do?MENU_ID=10301\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Korea Visa Portal — Tra cứu kết quả visa</a> <span class=\\"source-domain\\">visa.go.kr</span></li>\\n</ul>","headings":[{"id":"danh-cho-ai","text":"Dành cho ai","level":2},{"id":"dieu-kien-chinh","text":"Điều kiện chính","level":2},{"id":"nguoi-viet-nam-di-duong-nao-tuy-loai-truong","text":"Người Việt Nam: đi đường nào tuỳ loại trường","level":3},{"id":"ho-so-can-chuan-bi","text":"Hồ sơ cần chuẩn bị","level":2},{"id":"le-phi-va-thoi-gian-xu-ly","text":"Lệ phí và thời gian xử lý","level":2},{"id":"cac-buoc-nop-ho-so","text":"Các bước nộp hồ sơ","level":2},{"id":"lien-quan-toi-kiip-va-topik","text":"Liên quan tới KIIP và TOPIK","level":2},{"id":"luu-y","text":"Lưu ý","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":13},{"slug":"d-2-du-hoc","title":"Visa D-2: du học đại học và sau đại học","summary":"Hồ sơ xin visa D-2 từ Việt Nam và cách đổi từ D-4 sang D-2 ngay tại Hàn sau khi học xong trường tiếng.","updated":"2026-09-25","facts":{"group":"Du học","code":"D-2"},"html":"<h2 id=\\"danh-cho-ai\\">Dành cho ai</h2>\\n<p>Người học chương trình có bằng cấp tại Hàn Quốc. D-2-1 là cao đẳng, D-2-2 đại học, D-2-3 thạc sĩ, D-2-4 tiến sĩ. Các mã D-2-5 đến D-2-8 dành cho nghiên cứu sinh, trao đổi, vừa học vừa làm, du học ngắn hạn.</p>\\n<p>Có hai đường: xin visa từ Việt Nam, hoặc đang ở Hàn với visa D-4 (học tiếng) rồi đổi sang D-2.</p>\\n<h2 id=\\"dieu-kien-chinh\\">Điều kiện chính</h2>\\n<ul>\\n<li>Có <strong>giấy nhập học tiêu chuẩn</strong> (표준입학허가서) của trường.</li>\\n<li><strong>Tài chính</strong> (hướng dẫn ngày 05/01/2026 của Tổng Lãnh sự quán TP.HCM; thông báo của KVAC Hà Nội cập nhật 11/06/2026 ghi cùng mức): sổ tiết kiệm đứng tên người xin visa,<ul>\\n<li>trường vùng thủ đô: ít nhất <strong>20 triệu won</strong>, đã gửi <strong>từ 3 tháng</strong> trở lên;</li>\\n<li>trường địa phương: ít nhất <strong>16 triệu won</strong>, đã gửi từ 3 tháng trở lên.</li>\\n<li>D-2-4 đến D-2-8 không cần gửi đủ 3 tháng. &quot;Trường consulting&quot; thì phải gửi từ 6 tháng.</li>\\n<li>Học bổng toàn phần (học phí và sinh hoạt phí): nộp giấy chứng nhận học bổng thay cho chứng minh tài chính.</li>\\n</ul>\\n</li>\\n<li><strong>Tiếng Hàn</strong>: bắt buộc nếu vào <strong>trường top dưới</strong> (하위대학). Trường chứng nhận và trường thường không bắt buộc, nhưng có thì được ưu tiên khi xét visa.</li>\\n</ul>\\n<p>Với người Việt Nam, D-2 hệ cao đẳng, đại học, thạc sĩ ở trường thường và trường top dưới nộp trực tiếp tại cơ quan ngoại giao, không cần mã code (bảng của Tổng Lãnh sự quán TP.HCM, 2026).</p>\\n<h2 id=\\"ho-so-can-chuan-bi\\">Hồ sơ cần chuẩn bị</h2>\\n<h3 id=\\"nop-tu-viet-nam\\">Nộp từ Việt Nam</h3>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1rwl51i\\"><span>Đơn xin cấp visa (사증발급신청서)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"fs77ud\\"><span>Hộ chiếu gốc và bản sao</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"zces3z\\"><span>1 ảnh 3,5 × 4,5 cm nền trắng, chụp trong 6 tháng gần nhất</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"x0fn9f\\"><span>Bản sao CCCD (hai mặt)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"idnyud\\"><span>Giấy nhập học tiêu chuẩn (표준입학허가서), hoặc thư mời nếu có học bổng chính phủ</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"wpikjz\\"><span>Bản sao giấy đăng ký kinh doanh hoặc mã số của trường (사업자등록증 / 고유번호증)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"bdcpfr\\"><span>Bằng cấp cao nhất và bảng điểm đã hợp pháp hoá lãnh sự, được xác nhận lãnh sự trong vòng 1 năm, kèm bản dịch công chứng</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"7du7j3\\"><span>Phiếu xét nghiệm lao phổi của bệnh viện chỉ định</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"7zdbl4\\"><span>Giấy xác nhận số dư (cấp trong vòng 10 ngày) và sổ tiết kiệm gốc</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1ocp9nj\\"><span>Giấy tờ quan hệ gia đình, thu nhập của bố mẹ, cam kết bảo lãnh tài chính</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"143nra5\\"><span>Kế hoạch học tập và bản tự giới thiệu (학업계획서, 자기소개서) bằng tiếng Hàn hoặc tiếng Anh (Đại sứ quán Hà Nội yêu cầu)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"pe89t8\\"><span>Chứng chỉ TOPIK hoặc KIIP nếu trường thuộc nhóm bắt buộc</span></label></li>\\n</ul>\\n<p>Trường &quot;ưu tú&quot; (tỷ lệ bất hợp pháp dưới 1%) được giảm bớt: không phải nộp bằng cấp và chứng minh tài chính.</p>\\n<h3 id=\\"doi-tu-d-4-sang-d-2-tai-han\\">Đổi từ D-4 sang D-2 tại Hàn (체류자격 변경허가)</h3>\\n<p>Danh sách dưới đây theo hướng dẫn của Đại học Yonsei. Trường khác có thể yêu cầu thêm, hỏi phòng quốc tế của trường.</p>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"fr1d8y\\"><span>Đơn xin (통합신청서) và 1 ảnh chụp trong 6 tháng, không dùng lại ảnh cũ</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"uof4rr\\"><span>외국인등록증 (thẻ người nước ngoài) D-4 đang dùng</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"m4t1c4\\"><span>Bản sao hộ chiếu</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"z2xpkd\\"><span>Giấy nhập học (표준입학허가서)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"c2ilpi\\"><span>Bảng điểm và giấy xác nhận đang học của khoá tiếng (có tỷ lệ chuyên cần)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1dpw5ik\\"><span>Giấy xác nhận số dư tài khoản ngân hàng Hàn Quốc, hoặc giấy tờ tài chính thay thế theo yêu cầu của trường</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"yvxbq4\\"><span>Giấy tờ chứng minh chỗ ở (체류지 입증서류): hợp đồng thuê nhà hoặc xác nhận ký túc xá</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"47a8da\\"><span>Bằng cấp cao nhất đã hợp pháp hoá lãnh sự hoặc Apostille</span></label></li>\\n</ul>\\n<h2 id=\\"le-phi-va-thoi-gian-xu-ly\\">Lệ phí và thời gian xử lý</h2>\\n<p><strong>Nộp từ Việt Nam:</strong></p>\\n<ul>\\n<li>Phí visa: theo trang hướng dẫn của Đại sứ quán Hà Nội và bảng phí cho công dân Việt Nam của KVAC Hà Nội, visa một lần trên 90 ngày (D-1 đến G-1) là <strong>50 USD</strong>.</li>\\n<li>Phí nộp hộ tại KVAC Hà Nội: 390.000 đồng/bộ, chỉ nhận tiền mặt.</li>\\n<li>Thời gian xét: khoảng <strong>20 ngày làm việc</strong>. Học bổng toàn phần và D-2-4 đến D-2-8 khoảng <strong>10 ngày làm việc</strong>.</li>\\n</ul>\\n<p><strong>Đổi tư cách tại Hàn</strong> (bảng phí HiKorea):</p>\\n<ul>\\n<li>Phí đổi tư cách lưu trú: <strong>100.000 won</strong>.</li>\\n<li>Phí cấp thẻ người nước ngoài mới: <strong>35.000 won</strong> (áp dụng từ 01/01/2025).</li>\\n<li>Theo hướng dẫn của Yonsei, tổng 135.000 won, xử lý mất khoảng 5–6 tuần. Chưa xong thủ tục thì không được rời Hàn Quốc.</li>\\n</ul>\\n<h2 id=\\"cac-buoc-nop-ho-so\\">Các bước nộp hồ sơ</h2>\\n<p><strong>Từ Việt Nam:</strong></p>\\n<ol>\\n<li>Nhận giấy nhập học.</li>\\n<li>Khám lao, hợp pháp hoá bằng cấp, xin giấy xác nhận số dư.</li>\\n<li>Nộp tại Trung tâm tiếp nhận hồ sơ visa (KVAC) thuộc khu vực của bạn. Từ 20/10/2025, có thể uỷ quyền cho trung tâm du học nộp hộ.</li>\\n<li>Chuẩn bị cho khả năng bị gọi <strong>phỏng vấn</strong>.</li>\\n<li>Tra kết quả tại visa.go.kr.</li>\\n</ol>\\n<p><strong>Đổi D-4 sang D-2 tại Hàn:</strong></p>\\n<ol>\\n<li>Nhận giấy nhập học hệ đại học/cao học.</li>\\n<li>Hỏi phòng quốc tế: có trường nộp hộ cho sinh viên bằng giấy uỷ quyền.</li>\\n<li>Nếu tự nộp: đặt lịch trên HiKorea (hikorea.go.kr) rồi đến cơ quan xuất nhập cảnh quản lý nơi bạn ở.</li>\\n<li>Nhận thẻ người nước ngoài mới ghi D-2.</li>\\n</ol>\\n<h2 id=\\"lien-quan-toi-kiip-va-topik\\">Liên quan tới KIIP và TOPIK</h2>\\n<p>Cơ quan ngoại giao Hàn Quốc tại Việt Nam công nhận <strong>KIIP</strong> (사회통합프로그램) như một cách chứng minh tiếng Hàn, ngang với TOPIK. Mức yêu cầu khi vào trường top dưới:</p>\\n<ul>\\n<li><strong>Đại học trở lên</strong>: TOPIK 4, hoặc hoàn thành KIIP <strong>giai đoạn 4</strong> trở lên, hoặc đạt <strong>81 điểm</strong> bài đánh giá (사전평가) trở lên.</li>\\n<li><strong>Khoa năng khiếu nghệ thuật – thể thao</strong> (nới lỏng): TOPIK 3, hoặc KIIP giai đoạn 3, hoặc 61 điểm.</li>\\n<li><strong>Sinh viên trao đổi</strong>: TOPIK 2, hoặc KIIP giai đoạn 2, hoặc 41 điểm.</li>\\n</ul>\\n<p>Học chương trình dạy bằng tiếng Anh thì dùng chứng chỉ tiếng Anh: TOEFL iBT 71, IELTS 5.5, CEFR B2 hoặc TEPS 601 trở lên.</p>\\n<p>Giai đoạn KIIP bạn hoàn thành còn được tính điểm khi xin visa cư trú F-2-7 sau này (giai đoạn 4 được 15 điểm). Xem bài F-2-7.</p>\\n<h2 id=\\"luu-y\\">Lưu ý</h2>\\n<ul>\\n<li>Giấy nhập học, giấy tờ học lực, tài chính phải cấp trong vòng 3 tháng tính tới ngày nộp.</li>\\n<li>Đổi hộ khẩu để nộp nơi khác thì về nguyên tắc bị từ chối.</li>\\n<li>Nộp giấy giả: bị từ chối, có thể bị báo công an Việt Nam và bị cấm nhập cảnh Hàn Quốc.</li>\\n<li>Bị từ chối phải chờ <strong>3 tháng</strong> mới nộp lại.</li>\\n<li>Học xong thạc sĩ tại Hàn và ở Hàn đủ 3 năm (D-2 và D-10 cộng lại) thì có thể xin F-2-7. Xem bài F-2-7.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://overseas.mofa.go.kr/vn-hochiminh-vi/brd/m_3360/view.do?seq=6&amp;page=2\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Tổng Lãnh sự quán Hàn Quốc tại TP.HCM — Visa du học (D-4, D-2), file &quot;VISA DU HOC 26.01&quot; (05/01/2026)</a> <span class=\\"source-domain\\">overseas.mofa.go.kr</span></li>\\n<li><a href=\\"https://overseas.mofa.go.kr/vn-vi/brd/m_2156/view.do?seq=681710\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Đại sứ quán Hàn Quốc tại Việt Nam — Visa du học (D-2, D-4), thực hiện từ 15/07/2024</a> <span class=\\"source-domain\\">overseas.mofa.go.kr</span></li>\\n<li><a href=\\"https://overseas.mofa.go.kr/vn-vi/brd/m_2164/view.do?seq=758111\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Đại sứ quán — Thời gian thẩm tra hồ sơ visa</a> <span class=\\"source-domain\\">overseas.mofa.go.kr</span></li>\\n<li><a href=\\"https://overseas.mofa.go.kr/vn-vi/brd/m_2164/view.do?seq=758165\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Đại sứ quán — Uỷ quyền xin visa du học từ 20/10/2025</a> <span class=\\"source-domain\\">overseas.mofa.go.kr</span></li>\\n<li><a href=\\"https://overseas.mofa.go.kr/vn-vi/wpge/m_2154/contents.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Đại sứ quán — Hướng dẫn thủ tục visa (phí visa)</a> <span class=\\"source-domain\\">overseas.mofa.go.kr</span></li>\\n<li><a href=\\"https://visaforkorea-vt.com/info/service\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">KVAC Hà Nội — Lệ phí nộp hồ sơ</a> <span class=\\"source-domain\\">visaforkorea-vt.com</span></li>\\n<li><a href=\\"https://visaforkorea-vt.com/customercenter/faq/list/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">KVAC Hà Nội — Câu hỏi thường gặp, mục &quot;Phí visa&quot; (bảng phí thẩm tra cho công dân Việt Nam)</a> <span class=\\"source-domain\\">visaforkorea-vt.com</span></li>\\n<li><a href=\\"https://visaforkorea-vt.com/customercenter/notice/view/611\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">KVAC Hà Nội — Hồ sơ cần thiết khi xin visa du học (thay đổi ngày 11/06/2026)</a> <span class=\\"source-domain\\">visaforkorea-vt.com</span></li>\\n<li><a href=\\"https://www.hikorea.go.kr/info/InfoDatail.pt?CAT_SEQ=174&amp;PARENT_ID=19\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">HiKorea — Bảng lệ phí thủ tục lưu trú</a> <span class=\\"source-domain\\">hikorea.go.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/bbs/immigration/47/590299/artclView.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 출입국·외국인정책본부 — Tăng phí cấp thẻ người nước ngoài từ 01/01/2025</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n<li><a href=\\"https://graduate.yonsei.ac.kr/graduate/academic/notice_haksa.do?mode=download&amp;articleNo=124577&amp;attachNo=105616\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Đại học Yonsei — Hướng dẫn đổi visa D-4 sang D-2 (PDF)</a> <span class=\\"source-domain\\">graduate.yonsei.ac.kr</span></li>\\n<li><a href=\\"https://www.law.go.kr/LSW/admRulInfoP.do?admRulSeq=2100000190908\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국가법령정보센터 — Tiêu chuẩn F-2-7 (법무부고시 제2020-243호)</a> <span class=\\"source-domain\\">law.go.kr</span></li>\\n</ul>","headings":[{"id":"danh-cho-ai","text":"Dành cho ai","level":2},{"id":"dieu-kien-chinh","text":"Điều kiện chính","level":2},{"id":"ho-so-can-chuan-bi","text":"Hồ sơ cần chuẩn bị","level":2},{"id":"nop-tu-viet-nam","text":"Nộp từ Việt Nam","level":3},{"id":"doi-tu-d-4-sang-d-2-tai-han","text":"Đổi từ D-4 sang D-2 tại Hàn (체류자격 변경허가)","level":3},{"id":"le-phi-va-thoi-gian-xu-ly","text":"Lệ phí và thời gian xử lý","level":2},{"id":"cac-buoc-nop-ho-so","text":"Các bước nộp hồ sơ","level":2},{"id":"lien-quan-toi-kiip-va-topik","text":"Liên quan tới KIIP và TOPIK","level":2},{"id":"luu-y","text":"Lưu ý","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":20},{"slug":"f-2-7-cu-tru-theo-diem","title":"Visa F-2-7: cư trú theo thang điểm","summary":"Ai được xin F-2-7, cách tự tính điểm, và KIIP giúp bạn được bao nhiêu điểm.","updated":"2026-09-25","facts":{"group":"Gia đình và định cư","code":"F-2-7"},"html":"<h2 id=\\"danh-cho-ai\\">Dành cho ai</h2>\\n<p>F-2-7 là visa cư trú dành cho nhân lực ưu tú (점수제 우수인재 거주). Bộ Tư pháp chấm điểm theo tuổi, học vấn, tiếng Hàn, thu nhập. Đạt từ <strong>80 điểm</strong> thì được xét.</p>\\n<p>Các số liệu dưới đây lấy từ 법무부고시 제2020-243호 (có hiệu lực từ 01/12/2020), là bản đang hiển thị trên 국가법령정보센터 khi kiểm tra tháng 9/2026.</p>\\n<p>Có ba nhóm được nộp:</p>\\n<ol>\\n<li><strong>Đang làm chuyên môn</strong> với visa E-1 đến E-7, D-5 đến D-9, ở liên tục <strong>từ 3 năm</strong> với visa đó. Không áp dụng cho E-6-2 (khách sạn, giải trí) và E-7-4 (lao động lành nghề). Được miễn điều kiện 3 năm nếu thu nhập năm từ <strong>40 triệu won</strong> trở lên.</li>\\n<li><strong>Du học sinh</strong>: có D-2 hoặc D-10, cộng lại ở liên tục từ 3 năm, đã lấy <strong>bằng thạc sĩ trở lên</strong> tại Hàn và đã có việc làm thuộc nhóm E-1 đến E-7 (trừ E-6-2, E-7-4).</li>\\n<li>Người làm việc cho công ty niêm yết KOSPI/KOSDAQ ở vị trí quản lý hoặc chuyên gia.</li>\\n</ol>\\n<p>Visa E-9, H-2, F-6, D-4 <strong>không</strong> nằm trong danh sách trên.</p>\\n<h2 id=\\"dieu-kien-chinh\\">Điều kiện chính</h2>\\n<ul>\\n<li>Tổng điểm từ <strong>80/170</strong>.</li>\\n<li>Đáp ứng điều kiện gia hạn của visa đang có.</li>\\n<li>Không vướng lý do bị loại, ví dụ:<ul>\\n<li>bị kết án tù (kể cả án treo) trong 5 năm gần đây;</li>\\n<li>bị phạt tiền từ 3 triệu won trở lên trong 3 năm gần đây;</li>\\n<li>nộp giấy tờ giả trong 3 năm gần đây.</li>\\n</ul>\\n</li>\\n</ul>\\n<h2 id=\\"cach-tinh-diem\\">Cách tính điểm</h2>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Mục</th>\\n<th>Tối đa</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>Tuổi</td>\\n<td>25</td>\\n</tr>\\n<tr>\\n<td>Học vấn</td>\\n<td>25</td>\\n</tr>\\n<tr>\\n<td>Tiếng Hàn / KIIP</td>\\n<td>20</td>\\n</tr>\\n<tr>\\n<td>Thu nhập năm</td>\\n<td>60</td>\\n</tr>\\n<tr>\\n<td>Điểm cộng</td>\\n<td>40</td>\\n</tr>\\n</tbody></table></div>\\n<p><strong>Tuổi:</strong> 18–24 tuổi: 23 · 25–29: 25 · 30–34: 23 · 35–39: 20 · 40–44: 12 · 45–50: 8 · từ 51: 3.</p>\\n<p><strong>Học vấn</strong> (khối kỹ thuật – tự nhiên hoặc có từ 2 bằng / ngành khác):</p>\\n<ul>\\n<li>tiến sĩ: 25 / 20</li>\\n<li>thạc sĩ: 20 / 17</li>\\n<li>cử nhân: 17 / 15</li>\\n<li>cao đẳng: 15 / 10</li>\\n</ul>\\n<p><strong>Thu nhập năm</strong> (theo 소득금액증명, giấy xác nhận thu nhập của sở thuế):</p>\\n<ul>\\n<li>từ 100 triệu won: 60</li>\\n<li>90–100 triệu: 58</li>\\n<li>80–90 triệu: 56</li>\\n<li>70–80 triệu: 53</li>\\n<li>60–70 triệu: 50</li>\\n<li>50–60 triệu: 45</li>\\n<li>40–50 triệu: 40</li>\\n<li>30–40 triệu: 30</li>\\n<li>từ lương tối thiểu tới 30 triệu: 10</li>\\n<li>không có việc hoặc dưới lương tối thiểu: 0</li>\\n</ul>\\n<p><strong>Điểm cộng</strong> (tính tối đa 40): hoàn thành KIIP giai đoạn 5: +10. Bằng tiến sĩ / thạc sĩ / cử nhân của trường Hàn Quốc: +10 / +7 / +5; trường top 500 thế giới (THE, QS): +30 / +20 / +15. Làm tình nguyện tại Hàn trong 1–3 năm gần đây (mỗi năm ít nhất 6 lần, tổng từ 50 giờ): 1–2 năm: +1, 2–3 năm: +5, từ 3 năm: +7. Còn một số mục cộng điểm khác theo đề cử của cơ quan nhà nước.</p>\\n<p><strong>Điểm trừ:</strong> vi phạm luật xuất nhập cảnh, bị phạt tiền, bị kết án đều bị trừ, tối đa trừ 80 điểm.</p>\\n<h2 id=\\"lien-quan-toi-kiip-va-topik\\">Liên quan tới KIIP và TOPIK</h2>\\n<p>Đây là phần người học KIIP nên quan tâm nhất.</p>\\n<p><strong>1. KIIP thay được TOPIK ở mục tiếng Hàn (tối đa 20 điểm).</strong> Tính theo giai đoạn KIIP đã hoàn thành (이수 단계) hoặc cấp TOPIK:</p>\\n<ul>\\n<li>giai đoạn 5 / TOPIK 5 trở lên: 20</li>\\n<li>giai đoạn 4 / TOPIK 4: 15</li>\\n<li>giai đoạn 3 / TOPIK 3: 10</li>\\n<li>giai đoạn 2 / TOPIK 2: 5</li>\\n<li>giai đoạn 1 / TOPIK 1: 3</li>\\n</ul>\\n<p>Chỉ tính một trong hai. Mục này tối đa 20 điểm.</p>\\n<p><strong>2. Hoàn thành giai đoạn 5 được cộng thêm 10 điểm.</strong> Vậy hoàn thành KIIP giai đoạn 5 mang về tới <strong>30 điểm</strong>: 20 ở mục tiếng Hàn và 10 điểm cộng. TOPIK 6 chỉ được 20.</p>\\n<p><strong>3. Không phải nộp giấy.</strong> Người đã hoàn thành KIIP không cần nộp chứng nhận, cơ quan xuất nhập cảnh tự tra trên hệ thống 사회통합정보망 (socinet.go.kr).</p>\\n<p><strong>Ví dụ:</strong> 29 tuổi (25), thạc sĩ Hàn Quốc ngành xã hội (17), thu nhập 35 triệu won (30):</p>\\n<ul>\\n<li>có TOPIK 4: 25 + 17 + 15 + 30 + 7 (bằng thạc sĩ Hàn) = <strong>94</strong>;</li>\\n<li>có KIIP giai đoạn 5: 25 + 17 + 20 + 30 + 7 + 10 = <strong>109</strong>.</li>\\n</ul>\\n<p>Điểm cao hơn còn giúp được cấp thời hạn lưu trú dài hơn (xem Lưu ý).</p>\\n<h2 id=\\"ho-so-can-chuan-bi\\">Hồ sơ cần chuẩn bị</h2>\\n<p>Chỉ nộp giấy chứng minh cho những mục bạn tự khai điểm. Hồ sơ chấm trên giấy đã nộp.</p>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1mmzxfy\\"><span>Hộ chiếu</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"fm8wp5\\"><span>외국인등록증 (thẻ người nước ngoài)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1eqy8ep\\"><span>Bảng tự chấm điểm (점수표, mẫu 1 của 고시)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"qeh9a2\\"><span>Hợp đồng lao động hoặc giấy xác nhận đang làm việc (고용계약서 / 재직증명서)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1tsaxcm\\"><span>Giấy xác nhận thu nhập của sở thuế (소득금액증명)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"19i65p5\\"><span>Bằng tốt nghiệp (학위증), không nhận giấy hoàn thành khoá học (수료증)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"5m4rcm\\"><span>Bảng điểm TOPIK (không cần nếu dùng KIIP)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"v5d043\\"><span>Giấy tờ chứng minh điểm cộng, ví dụ giấy xác nhận tình nguyện từ 1365.go.kr hoặc vms.or.kr</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"3df90y\\"><span>Giấy tờ quan hệ gia đình (nếu xin kèm vợ/chồng, con chưa thành niên)</span></label></li>\\n</ul>\\n<h2 id=\\"le-phi-va-thoi-gian-xu-ly\\">Lệ phí và thời gian xử lý</h2>\\n<p>Theo bảng phí HiKorea:</p>\\n<ul>\\n<li>Đổi tư cách lưu trú: <strong>100.000 won</strong>.</li>\\n<li>Cấp thẻ người nước ngoài mới: <strong>35.000 won</strong> (từ 01/01/2025).</li>\\n</ul>\\n<p>Thời hạn lưu trú được cấp theo điểm:</p>\\n<ul>\\n<li>từ 130 điểm, hoặc điểm thu nhập từ 50: 3–5 năm</li>\\n<li>100–129 điểm, hoặc điểm thu nhập 30–49: 1–3 năm</li>\\n<li>80–99 điểm: tối đa 1 năm</li>\\n</ul>\\n<h2 id=\\"cac-buoc-nop-ho-so\\">Các bước nộp hồ sơ</h2>\\n<ol>\\n<li>Tự chấm điểm theo bảng trên.</li>\\n<li>Gom giấy chứng minh cho từng mục đã khai.</li>\\n<li>Đặt lịch trên HiKorea (hikorea.go.kr), đến cơ quan xuất nhập cảnh quản lý nơi bạn ở.</li>\\n<li>Vợ/chồng, con đi kèm về nguyên tắc nộp cùng lúc.</li>\\n<li>Hỏi thêm qua tổng đài 1345.</li>\\n</ol>\\n<h2 id=\\"luu-y\\">Lưu ý</h2>\\n<ul>\\n<li>Không có thu nhập từ 6 tháng trở lên, hoặc làm việc lao động giản đơn, giải trí: có thể bị rút ngắn thời hạn hoặc huỷ tư cách.</li>\\n<li>Gia hạn mà dưới 80 điểm thì bị từ chối. Khi đó có thể đổi sang visa khác đủ điều kiện, hoặc D-10 (tìm việc) tối đa 1 năm.</li>\\n<li>Vợ/chồng, con chỉ được đi làm khi thu nhập của bạn từ mức GNI bình quân đầu người mới nhất do Ngân hàng Trung ương Hàn Quốc công bố.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://www.law.go.kr/LSW/admRulInfoP.do?admRulSeq=2100000190908\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국가법령정보센터 — Tiêu chuẩn F-2-7, 법무부고시 제2020-243호</a> <span class=\\"source-domain\\">law.go.kr</span></li>\\n<li><a href=\\"https://www.moj.go.kr/bbs/moj/158/409044/download.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 — Tài liệu tiêu chuẩn F-2-7 (bảng điểm, thời hạn lưu trú)</a> <span class=\\"source-domain\\">moj.go.kr</span></li>\\n<li><a href=\\"https://www.hikorea.go.kr/info/InfoDatail.pt?CAT_SEQ=174&amp;PARENT_ID=19\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">HiKorea — Bảng lệ phí thủ tục lưu trú</a> <span class=\\"source-domain\\">hikorea.go.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/bbs/immigration/47/590299/artclView.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 출입국·외국인정책본부 — Tăng phí cấp thẻ người nước ngoài từ 01/01/2025</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n<li><a href=\\"https://www.socinet.go.kr\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">사회통합정보망 (socinet)</a> <span class=\\"source-domain\\">socinet.go.kr</span></li>\\n</ul>","headings":[{"id":"danh-cho-ai","text":"Dành cho ai","level":2},{"id":"dieu-kien-chinh","text":"Điều kiện chính","level":2},{"id":"cach-tinh-diem","text":"Cách tính điểm","level":2},{"id":"lien-quan-toi-kiip-va-topik","text":"Liên quan tới KIIP và TOPIK","level":2},{"id":"ho-so-can-chuan-bi","text":"Hồ sơ cần chuẩn bị","level":2},{"id":"le-phi-va-thoi-gian-xu-ly","text":"Lệ phí và thời gian xử lý","level":2},{"id":"cac-buoc-nop-ho-so","text":"Các bước nộp hồ sơ","level":2},{"id":"luu-y","text":"Lưu ý","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":9},{"slug":"d-10-tim-viec","title":"Visa D-10-1: ở lại Hàn tìm việc sau khi tốt nghiệp","summary":"Ai được đổi từ D-2 sang D-10-1, được ở bao lâu, được làm gì trong thời gian tìm việc, và KIIP giúp gì.","updated":"2026-09-25","facts":{"group":"Du học","code":"D-10"},"html":"<h2 id=\\"danh-cho-ai\\">Dành cho ai</h2>\\n<p>D-10 (구직, tìm việc) cho phép ở lại Hàn để tìm việc hoặc thực tập trước khi có việc chính thức. Loại phổ biến nhất là <strong>D-10-1 (일반구직, tìm việc thông thường)</strong>.</p>\\n<p>Việc bạn tìm phải thuộc nhóm visa chuyên môn E-1 đến E-7 (không tính E-6-2). Người vừa tốt nghiệp cao đẳng, đại học, cao học ở Hàn với visa D-2 là nhóm được ưu tiên nhất.</p>\\n<p>Nội dung bài theo sổ tay 체류민원 자격별 안내 매뉴얼 của Bộ Tư pháp, bản đăng trên HiKorea ngày 18/09/2026.</p>\\n<h2 id=\\"dieu-kien-chinh\\">Điều kiện chính</h2>\\n<p><strong>Mới tốt nghiệp ở Hàn, đổi D-10-1 lần đầu: không phải chấm điểm.</strong> Điều kiện:</p>\\n<ol>\\n<li>học ở trường đại học, cao đẳng chính quy của Hàn Quốc;</li>\\n<li>có visa D-2 và đã lấy bằng từ cao đẳng (전문학사) trở lên;</li>\\n<li>đây là lần đầu đổi sang D-10-1.</li>\\n</ol>\\n<p>Người đã về nước nhưng xin visa D-10 trong vòng 1 năm kể từ ngày tốt nghiệp cũng được miễn chấm điểm. Ai đã từng có D-10 thì không còn là &quot;lần đầu&quot;.</p>\\n<p><strong>Tốt nghiệp ở Hàn chưa quá 3 năm và giỏi tiếng Hàn: cũng được miễn chấm điểm.</strong> Cần TOPIK 4 trở lên còn hạn, hoặc đậu bài kiểm tra giữa kỳ KIIP giai đoạn 4 (중간평가), hoặc được xếp vào giai đoạn 5 ở bài đánh giá đầu vào KIIP (사전평가).</p>\\n<p><strong>Các trường hợp khác: chấm điểm.</strong> Phải đạt ít nhất <strong>60/190 điểm</strong>, trong đó phần cơ bản (tuổi + học vấn) ít nhất 20.</p>\\n<p>Bị loại nếu, ví dụ:</p>\\n<ul>\\n<li>bị kết án tù (금고 이상) trong 5 năm gần đây;</li>\\n<li>bị phạt tiền từ 3 triệu won trở lên trong 3 năm gần đây;</li>\\n<li>bị trục xuất hoặc lệnh xuất cảnh trong 5 năm gần đây.</li>\\n</ul>\\n<h2 id=\\"thang-diem-d-10-1\\">Thang điểm D-10-1</h2>\\n<p>Áp dụng khi không thuộc diện miễn, và khi gia hạn sau năm đầu.</p>\\n<p><strong>Cơ bản</strong> (tối đa 50):</p>\\n<ul>\\n<li>Tuổi: 20–24: 10 · 25–29: 15 · 30–34: 20 · 35–39: 15 · 40–49: 5.</li>\\n<li>Học vấn: cao đẳng Hàn Quốc 15 · cử nhân 15 · thạc sĩ 20 · tiến sĩ 30. Chỉ nhận bằng (학위증), không nhận giấy hoàn thành khoá học.</li>\\n</ul>\\n<p><strong>Tuỳ chọn</strong> (tối đa 70):</p>\\n<ul>\\n<li>Du học ở Hàn từ 2 năm: tốt nghiệp chưa quá 3 năm được <strong>30</strong>. Quá 3 năm: cao đẳng 5, cử nhân 10, thạc sĩ 15, tiến sĩ 20.</li>\\n<li>Kinh nghiệm làm việc đúng chuyên ngành trong 10 năm gần đây: tối đa 15.</li>\\n<li>Học tiếng D-4-1 từ 12 tháng: 3.</li>\\n<li>Tiếng Hàn (TOPIK hoặc KIIP):<ul>\\n<li>TOPIK 5 / hoàn thành KIIP giai đoạn 5: 20</li>\\n<li>TOPIK 4 / KIIP giai đoạn 4 hoặc 사전평가 từ 81 điểm: 15</li>\\n<li>TOPIK 3 / KIIP giai đoạn 3 hoặc từ 61 điểm: 10</li>\\n<li>TOPIK 2 / KIIP giai đoạn 2 hoặc từ 41 điểm: 5</li>\\n</ul>\\n</li>\\n</ul>\\n<p><strong>Điểm cộng</strong>: ví dụ bằng cử nhân khối kỹ thuật – tự nhiên (이공계) +5.</p>\\n<p><strong>Điểm trừ</strong>: bị phạt vì vi phạm luật xuất nhập cảnh hoặc luật hình sự trong 5 năm: trừ 5 đến 30 điểm tuỳ số tiền.</p>\\n<h2 id=\\"thoi-han-duoc-o\\">Thời hạn được ở</h2>\\n<p>Từ 29/10/2025, D-10 được ở tối đa <strong>3 năm</strong>, mỗi lần cấp tối đa 1 năm (trước đó là 2 năm, mỗi lần 6 tháng).</p>\\n<ul>\\n<li>Đổi D-10-1 lần đầu sau khi tốt nghiệp: được cấp <strong>1 năm</strong>. Gia hạn thì phải chấm điểm.</li>\\n<li>Từ 80 điểm, hoặc thuộc diện &quot;giỏi tiếng Hàn, tốt nghiệp chưa quá 3 năm&quot;: tối đa 3 năm, mỗi lần 1 năm.</li>\\n<li>60–79 điểm: tối đa <strong>1 năm</strong>, mỗi lần 6 tháng.</li>\\n</ul>\\n<p>Thời gian cộng dồn trong lúc ở Hàn. Rời Hàn hẳn rồi xin visa mới thì tính lại từ đầu.</p>\\n<h2 id=\\"duoc-va-khong-duoc-lam-gi\\">Được và không được làm gì</h2>\\n<p><strong>Thực tập (인턴):</strong> được thực tập có nhận phụ cấp ở công ty thuộc lĩnh vực E-1 đến E-7.</p>\\n<ul>\\n<li>Ở một công ty, mỗi lần tối đa <strong>1 năm</strong>. Không còn giới hạn tổng thời gian thực tập.</li>\\n<li>Phải <strong>báo trong 15 ngày</strong> kể từ ngày bắt đầu thực tập hoặc đổi nơi thực tập, tại cơ quan xuất nhập cảnh quản lý nơi bạn ở.</li>\\n</ul>\\n<p><strong>Làm thêm (시간제 취업):</strong> phải xin phép trước (체류자격외 활동허가). Điều kiện:</p>\\n<ul>\\n<li>tốt nghiệp cao đẳng trở lên ở Hàn, chưa quá 3 năm;</li>\\n<li>hoàn thành KIIP giai đoạn 4 trở lên, hoặc TOPIK 4 trở lên;</li>\\n<li>chưa từng ở Hàn bằng visa E-1 đến E-7.</li>\\n</ul>\\n<p>Chỉ được làm ở các ngành mà du học sinh được phép làm thêm. Riêng <strong>nhà máy (제조업)</strong>: bắt buộc hoàn thành KIIP giai đoạn 4, TOPIK không được tính. Ngày thường tối đa 25 giờ/tuần, cuối tuần và ngày lễ không giới hạn. Hoàn thành KIIP giai đoạn 5 thì ngày thường được 30 giờ. Phí xin phép: 120.000 won.</p>\\n<p><strong>Đi làm chính thức:</strong> phải đổi sang visa lao động (ví dụ E-7) trước khi bắt đầu.</p>\\n<h2 id=\\"ho-so-can-chuan-bi\\">Hồ sơ cần chuẩn bị</h2>\\n<p>Hồ sơ đổi D-2 sang D-10-1 lần đầu sau khi tốt nghiệp:</p>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"dglvxr\\"><span>Đơn xin (통합신청서, mẫu số 34)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"5w66z8\\"><span>Ảnh thẻ</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1gtdz22\\"><span>Hộ chiếu và bản sao</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"fm8wp5\\"><span>외국인등록증 (thẻ người nước ngoài)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1gg35ig\\"><span>Kế hoạch tìm việc (구직활동계획서)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"gx6xp0\\"><span>Bằng cao đẳng trở lên hoặc giấy chứng nhận tốt nghiệp của trường Hàn Quốc</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"dyf6ga\\"><span>Giấy tờ chứng minh chỗ ở (체류지 입증서류), ví dụ hợp đồng thuê nhà</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"376op6\\"><span>Phí</span></label></li>\\n</ul>\\n<p>Diện này <strong>không phải chứng minh tài chính</strong>. Diện &quot;giỏi tiếng Hàn&quot; nộp thêm bảng điểm TOPIK hoặc giấy đậu 중간평가 / bảng điểm 사전평가 KIIP.</p>\\n<p>Khi gia hạn theo thang điểm thì phải nộp thêm giấy xác nhận số dư ngân hàng. Mức tối thiểu tính bằng &quot;mức trợ cấp nhà ở cho hộ 1 người của năm đó × số tháng xin ở&quot;. Hỏi 1345 để biết con số năm hiện tại.</p>\\n<h2 id=\\"le-phi-va-thoi-gian-xu-ly\\">Lệ phí và thời gian xử lý</h2>\\n<p>Theo biểu phí trong sổ tay (2026):</p>\\n<ul>\\n<li>Đổi tư cách lưu trú: <strong>100.000 won</strong>.</li>\\n<li>Xin phép làm thêm: <strong>120.000 won</strong>.</li>\\n<li>Gia hạn: <strong>60.000 won</strong>.</li>\\n<li>Nếu được cấp thẻ người nước ngoài mới: <strong>35.000 won</strong>.</li>\\n</ul>\\n<p>Sổ tay không ghi thời gian xử lý cố định.</p>\\n<h2 id=\\"cac-buoc-nop-ho-so\\">Các bước nộp hồ sơ</h2>\\n<ol>\\n<li>Nộp ngay khi tình trạng thay đổi hoặc sắp thay đổi. Không để D-2 hết hạn.</li>\\n<li>Chuẩn bị kế hoạch tìm việc, bằng hoặc giấy tốt nghiệp.</li>\\n<li>Đặt lịch trên HiKorea (hikorea.go.kr), đến cơ quan xuất nhập cảnh quản lý nơi bạn ở. Hỏi phòng quốc tế của trường xem có hỗ trợ không.</li>\\n<li>Khi bắt đầu thực tập: báo trong 15 ngày.</li>\\n<li>Có việc: xin đổi sang visa lao động phù hợp.</li>\\n</ol>\\n<h2 id=\\"lien-quan-toi-kiip-va-topik\\">Liên quan tới KIIP và TOPIK</h2>\\n<ul>\\n<li><strong>KIIP giai đoạn 4</strong> (hoặc TOPIK 4) + tốt nghiệp chưa quá 3 năm: miễn chấm điểm, được ở tới 3 năm.</li>\\n<li>Muốn <strong>làm thêm ở nhà máy</strong> khi đang D-10: chỉ KIIP giai đoạn 4 mới được, TOPIK không thay được.</li>\\n<li><strong>KIIP giai đoạn 5</strong>: 20 điểm tiếng Hàn và được làm thêm 30 giờ ngày thường.</li>\\n<li>Khi chấm điểm, KIIP và TOPIK được tính ngang nhau. Bảng điểm 사전평가 chỉ có hạn 2 năm. Giấy hoàn thành giai đoạn KIIP và giấy đậu 중간평가 không hết hạn.</li>\\n</ul>\\n<h2 id=\\"luu-y\\">Lưu ý</h2>\\n<ul>\\n<li>Người học thạc sĩ ở Hàn: thời gian D-2 và D-10 được cộng lại để tính điều kiện 3 năm khi xin F-2-7. Xem bài F-2-7.</li>\\n<li>Gia hạn phải nộp trước ngày hết hạn. Xem bài đăng ký và gia hạn lưu trú.</li>\\n<li>Sổ tay nói rõ cơ quan xuất nhập cảnh có thể yêu cầu thêm hoặc bớt giấy tờ.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://www.hikorea.go.kr/board/BoardNtcDetailR.pt?BBS_SEQ=1&amp;BBS_GB_CD=BS10&amp;NTCCTT_SEQ=1062&amp;page=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">HiKorea — 체류민원 자격별 안내 매뉴얼, mục 구직(D-10), bản 18/09/2026 (file .hwp đính kèm)</a> <span class=\\"source-domain\\">hikorea.go.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/bbs/immigration/214/486421/download.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 — Thông cáo báo chí 27/10/2025: D-10 tăng lên tối đa 3 năm, thực tập mỗi công ty tối đa 1 năm (áp dụng từ 29/10/2025)</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n<li><a href=\\"https://www.hikorea.go.kr/info/InfoDatail.pt?CAT_SEQ=174&amp;PARENT_ID=19\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">HiKorea — Bảng lệ phí thủ tục lưu trú</a> <span class=\\"source-domain\\">hikorea.go.kr</span></li>\\n<li><a href=\\"https://www.law.go.kr/%EB%B2%95%EB%A0%B9/%EC%B6%9C%EC%9E%85%EA%B5%AD%EA%B4%80%EB%A6%AC%EB%B2%95%EC%8B%9C%ED%96%89%EA%B7%9C%EC%B9%99\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국가법령정보센터 — 출입국관리법 시행규칙, Điều 72 (lệ phí)</a> <span class=\\"source-domain\\">law.go.kr</span></li>\\n</ul>","headings":[{"id":"danh-cho-ai","text":"Dành cho ai","level":2},{"id":"dieu-kien-chinh","text":"Điều kiện chính","level":2},{"id":"thang-diem-d-10-1","text":"Thang điểm D-10-1","level":2},{"id":"thoi-han-duoc-o","text":"Thời hạn được ở","level":2},{"id":"duoc-va-khong-duoc-lam-gi","text":"Được và không được làm gì","level":2},{"id":"ho-so-can-chuan-bi","text":"Hồ sơ cần chuẩn bị","level":2},{"id":"le-phi-va-thoi-gian-xu-ly","text":"Lệ phí và thời gian xử lý","level":2},{"id":"cac-buoc-nop-ho-so","text":"Các bước nộp hồ sơ","level":2},{"id":"lien-quan-toi-kiip-va-topik","text":"Liên quan tới KIIP và TOPIK","level":2},{"id":"luu-y","text":"Lưu ý","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":8},{"slug":"e-7-4-lao-dong-lanh-nghe","title":"Visa E-7-4: từ E-9 lên lao động lành nghề","summary":"Điều kiện, cách tính điểm K-point E74 và cách nộp để chuyển từ E-9 sang E-7-4, kèm số điểm KIIP và TOPIK mang lại.","updated":"2026-09-25","facts":{"group":"Làm việc","code":"E-7-4"},"html":"<h2 id=\\"danh-cho-ai\\">Dành cho ai</h2>\\n<p>E-7-4 (숙련기능인력, lao động lành nghề) dành cho người đã làm lâu năm ở Hàn bằng visa <strong>E-9</strong> (lao động phổ thông EPS), <strong>E-10</strong> (thuyền viên) hoặc <strong>H-2</strong> (thăm thân làm việc). Bộ Tư pháp chấm điểm theo hệ thống <strong>K-point E74</strong>. Đủ điểm thì được đổi sang visa E-7-4 ngay tại Hàn.</p>\\n<p>Theo Bộ Tư pháp, E-7-4 được gia hạn và được đưa gia đình sang, nhằm khuyến khích ở lâu dài (điều kiện đưa gia đình: xem phần KIIP và TOPIK).</p>\\n<p>E-7-4 chỉ đổi tại Hàn, không xin mới từ nước ngoài. Mỗi lần được cấp tối đa <strong>2 năm</strong> (trong thời hạn hợp đồng), gia hạn được.</p>\\n<p>Số liệu theo sổ tay 체류민원 자격별 안내 매뉴얼 bản 18/09/2026 trên HiKorea (phần E-7-4 áp dụng từ 31/08/2026). Điều kiện và điểm có thể thay đổi.</p>\\n<h2 id=\\"dieu-kien-chinh\\">Điều kiện chính</h2>\\n<p>Phải đủ <strong>cả 4 điều kiện</strong>:</p>\\n<ol>\\n<li><strong>Thời gian ở Hàn:</strong> trong 10 năm gần đây, đã ở Hàn <strong>từ 4 năm</strong> bằng E-9, E-10 hoặc H-2. Hiện đang có thẻ người nước ngoài và làm việc hợp pháp ở nơi hiện tại. Ngoại lệ: ở vùng ngoài Seoul, Gyeonggi, Incheon từ 3 năm và được chính quyền tỉnh/thành phố (광역지자체) đề cử.</li>\\n<li><strong>Hợp đồng:</strong> hợp đồng E-7-4 với nơi đang làm, <strong>từ 2 năm</strong>, lương năm từ <strong>26 triệu won</strong>. Nông nghiệp, chăn nuôi, ngư nghiệp, tàu nội địa: từ 25,89 triệu won. Lương năm tính tổng tiền được trả (lương cơ bản cộng phụ cấp).</li>\\n<li><strong>Công ty đề cử:</strong> được giám đốc nơi bạn <strong>đang làm từ 1 năm</strong> đề cử.</li>\\n<li><strong>Điểm:</strong> từ <strong>200 điểm</strong> (tính cả điểm cộng). Riêng mục thu nhập và mục tiếng Hàn mỗi mục phải đạt ít nhất 50 điểm.</li>\\n</ol>\\n<p><strong>Bị loại</strong> nếu: bị phạt tiền từ 3 triệu won, còn nợ thuế (nộp đủ thì được nộp lại), vi phạm luật xuất nhập cảnh từ 4 lần, từng cư trú bất hợp pháp từ 3 tháng. Các mục về phạt tiền, vi phạm và cư trú bất hợp pháp chỉ tính trong 10 năm gần đây.</p>\\n<p><strong>Đổi chỗ làm không phải lỗi của bạn</strong> (công ty đóng cửa, nợ lương, bạo hành…): có giấy tờ chứng minh thì thời gian ở công ty cũ được cộng vào để tính &quot;làm từ 1 năm&quot; (áp dụng từ tháng 6/2026).</p>\\n<h2 id=\\"cach-tinh-diem\\">Cách tính điểm</h2>\\n<p>Tối đa 300 điểm cơ bản, cộng thêm điểm thưởng.</p>\\n<p><strong>Thu nhập</strong> (trung bình 2 năm gần nhất, theo 소득금액증명 của sở thuế), tối đa 120:</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Thu nhập năm</th>\\n<th>Điểm</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>25–30 triệu won</td>\\n<td>50</td>\\n</tr>\\n<tr>\\n<td>30–35 triệu</td>\\n<td>65</td>\\n</tr>\\n<tr>\\n<td>35–40 triệu</td>\\n<td>80</td>\\n</tr>\\n<tr>\\n<td>40–45 triệu</td>\\n<td>95</td>\\n</tr>\\n<tr>\\n<td>45–50 triệu</td>\\n<td>110</td>\\n</tr>\\n<tr>\\n<td>từ 50 triệu</td>\\n<td>120</td>\\n</tr>\\n</tbody></table></div>\\n<p>Thu nhập trung bình phải từ 25,89 triệu won. Nông, chăn nuôi, ngư nghiệp, tàu nội địa: từ 24 triệu won.</p>\\n<p><strong>Tiếng Hàn</strong>, tối đa 120:</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Mức</th>\\n<th>Điểm</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>TOPIK 2 / hoàn thành KIIP giai đoạn 2 / 사전평가 41–60 điểm</td>\\n<td>50</td>\\n</tr>\\n<tr>\\n<td>TOPIK 3 / KIIP giai đoạn 3 / 사전평가 61–80 điểm</td>\\n<td>80</td>\\n</tr>\\n<tr>\\n<td>TOPIK 4 trở lên / KIIP giai đoạn 4 trở lên / 사전평가 từ 81 điểm</td>\\n<td>120</td>\\n</tr>\\n</tbody></table></div>\\n<p><strong>Tuổi</strong>, tối đa 60: 19–26: 40 · 27–33: 60 · 34–40: 30 · từ 41: 10.</p>\\n<p><strong>Điểm cộng</strong> (cộng dồn được):</p>\\n<ul>\\n<li>Công ty đang làm đề cử: <strong>+50</strong></li>\\n<li>Bộ ngành trung ương hoặc tỉnh/thành phố đề cử: +30 (có cả hai chỉ tính một)</li>\\n<li>Làm ở nơi hiện tại từ 3 năm: +20</li>\\n<li>Làm ở vùng giảm dân số hoặc xã/thị trấn (읍·면) từ 3 năm: +20</li>\\n<li>Chứng chỉ nghề Hàn Quốc đúng ngành (기사, 산업기사, 기능사) hoặc bằng cao đẳng trở lên của trường Hàn: +20</li>\\n<li>Bằng lái xe Hàn Quốc từ hạng 2 thường (2종 보통): +10</li>\\n</ul>\\n<p><strong>Điểm trừ</strong> (tối đa 50, trong 10 năm): bị phạt tiền, bị hạn chế lưu trú vì nợ thuế, bị xử lý vì vi phạm luật xuất nhập cảnh. 1 lần: −5, 2 lần: −10, từ 3 lần: −15 hoặc −20 tuỳ mục.</p>\\n<p><strong>Ví dụ:</strong> 30 tuổi (60), thu nhập trung bình 32 triệu won (65), hoàn thành KIIP giai đoạn 3 (80), công ty đề cử (50): 60 + 65 + 80 + 50 = <strong>255 điểm</strong>.</p>\\n<h2 id=\\"han-ngach-nam-2026\\">Hạn ngạch năm 2026</h2>\\n<p>Năm 2026 Bộ Tư pháp tuyển <strong>33.000 người</strong>:</p>\\n<ul>\\n<li>12.000: &quot;đường cá nhân&quot; chỉ cần công ty đề cử, không cần bộ ngành hay tỉnh đề cử;</li>\\n<li>6.300: 7 bộ ngành đề cử theo ngành (ví dụ Bộ Lao động 2.000 cho ngành sản xuất);</li>\\n<li>8.500: 17 tỉnh/thành phố đề cử;</li>\\n<li>6.200: hạn ngạch linh hoạt, phân bổ sau.</li>\\n</ul>\\n<p>Nhận hồ sơ quanh năm, tới khi hết hạn ngạch.</p>\\n<h2 id=\\"ho-so-can-chuan-bi\\">Hồ sơ cần chuẩn bị</h2>\\n<p><strong>Người lao động:</strong></p>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1qrjn4c\\"><span>Đơn xin (통합신청서, mẫu 34) và bản sao trang thông tin hộ chiếu</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"t06bfc\\"><span>Bảng tự chấm điểm (점수제 자체 심사표)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"18t3h8j\\"><span>Bản tự khai lý lịch (신상 기술서)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"12i5rds\\"><span>Hợp đồng lao động E-7-4 (từ 2 năm, lương năm từ 26 triệu won)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"m3lext\\"><span>Giấy xác nhận thu nhập của sở thuế (소득금액증명원) 2 năm gần nhất</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"dkfa1f\\"><span>Bảng điểm TOPIK (dùng KIIP thì không cần nộp)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"12om3qd\\"><span>Giấy bảo lãnh nhân thân (신원보증서, mẫu 129), chủ sử dụng đứng bảo lãnh</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"qsqosf\\"><span>Nếu có: chứng chỉ nghề, bằng cấp Hàn Quốc, bằng lái xe (để lấy điểm cộng)</span></label></li>\\n</ul>\\n<p><strong>Công ty:</strong></p>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"g9ildl\\"><span>Bản sao giấy đăng ký kinh doanh (hoặc giấy đăng ký cơ sở nông nghiệp)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"130xhzb\\"><span>Giấy xác nhận đã nộp thuế quốc gia và thuế địa phương</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1hqqolc\\"><span>Danh sách người tham gia bảo hiểm xã hội của cơ sở</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1765gb0\\"><span>Thư đề cử của công ty và bản sao giấy tờ tùy thân của người đề cử</span></label></li>\\n</ul>\\n<h2 id=\\"le-phi-va-thoi-gian-xu-ly\\">Lệ phí và thời gian xử lý</h2>\\n<ul>\\n<li>Phí đổi tư cách lưu trú: <strong>100.000 won</strong> (biểu phí 2026). Sổ tay ghi nộp online qua HiKorea được áp dụng mức giảm phí của thủ tục online.</li>\\n<li>Sổ tay không ghi thời gian xử lý cố định.</li>\\n</ul>\\n<h2 id=\\"cac-buoc-nop-ho-so\\">Các bước nộp hồ sơ</h2>\\n<ol>\\n<li><p>Tự chấm điểm. Thiếu điểm tiếng Hàn thì học KIIP hoặc thi TOPIK trước.</p>\\n</li>\\n<li><p>Nói chuyện với chủ sử dụng: cần thư đề cử, hợp đồng E-7-4 và giấy bảo lãnh nhân thân.</p>\\n</li>\\n<li><p>Muốn thêm điểm đề cử của bộ ngành: công ty xin đề cử theo thông báo của bộ đó. Ví dụ năm 2026, Bộ Lao động nhận đề cử ngành sản xuất tại văn phòng lao động địa phương.</p>\\n</li>\\n<li><p>Nộp <strong>online</strong> qua HiKorea (전자민원). Ngày nộp theo số cuối năm sinh:</p>\\n<ul>\\n<li>thứ Hai: 1, 6</li>\\n<li>thứ Ba: 2, 7</li>\\n<li>thứ Tư: 3, 8</li>\\n<li>thứ Năm: 4, 9</li>\\n<li>thứ Sáu: 5, 0</li>\\n</ul>\\n<p>Chỉ nộp trực tiếp khi cơ quan xuất nhập cảnh cho phép (người cao tuổi, ở vùng xa…). File đính kèm tối đa 2 MB mỗi file.</p>\\n</li>\\n</ol>\\n<h2 id=\\"lien-quan-toi-kiip-va-topik\\">Liên quan tới KIIP và TOPIK</h2>\\n<p>Tiếng Hàn là mục <strong>bắt buộc</strong> và nặng điểm nhất cùng với thu nhập:</p>\\n<ul>\\n<li>Hoàn thành <strong>KIIP giai đoạn 2</strong> hoặc TOPIK 2 là mức tối thiểu (50 điểm).</li>\\n<li>Giai đoạn 3 được 80, giai đoạn 4 trở lên được <strong>120</strong>. Từ giai đoạn 2 lên 4 là thêm 70 điểm.</li>\\n<li>Dùng KIIP thì không phải nộp giấy.</li>\\n<li>Bảng điểm 사전평가 chỉ có hạn <strong>2 năm</strong>. Đạt từ 41 điểm nhưng điểm nói dưới 3 nên bị xếp giai đoạn 0 thì không được tính.</li>\\n</ul>\\n<p><strong>Tạm hoãn yêu cầu tiếng Hàn tới 31/12/2026:</strong> nếu chưa có tiếng Hàn nhưng các mục khác đạt từ 150 điểm, vẫn được đổi. Điều kiện là phải bổ sung tiếng Hàn trước lần gia hạn đầu (2 năm). Chưa bổ sung thì không được đưa gia đình sang, chỉ được gia hạn 6 tháng; hết 6 tháng vẫn chưa đủ thì không được gia hạn và bị huỷ tư cách lưu trú.</p>\\n<h2 id=\\"luu-y\\">Lưu ý</h2>\\n<ul>\\n<li>Hợp đồng E-7-4 phải là làm tiếp ít nhất 2 năm ở chính nơi đang làm lúc nộp.</li>\\n<li>Công ty vi phạm (nợ lương, bạo hành, thuê người bất hợp pháp) mất quyền đề cử ngay và không được đề cử trong 5 năm.</li>\\n<li>Mỗi công ty chỉ được thuê số người E-7-4 giới hạn: thường tới 30% số lao động người Hàn. Vùng giảm dân số, ngành công nghiệp gốc, nông – ngư nghiệp: tới 50%.</li>\\n<li>E-7-4 không được tính vào điều kiện xin F-2-7. Xem bài F-2-7.</li>\\n<li>Bộ Tư pháp cho biết sẽ công bố &quot;phương án thúc đẩy E-7-4&quot; (제도 활성화 방안) trong nửa cuối năm 2026. Kiểm tra thông báo mới trên HiKorea trước khi nộp.</li>\\n<li>Hỏi thêm: tổng đài <strong>1345</strong>.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://www.hikorea.go.kr/board/BoardNtcDetailR.pt?BBS_SEQ=1&amp;BBS_GB_CD=BS10&amp;NTCCTT_SEQ=1062&amp;page=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">HiKorea — 체류민원 자격별 안내 매뉴얼, phần 숙련기능인력(E-7-4), bản 18/09/2026 (file .hwp đính kèm)</a> <span class=\\"source-domain\\">hikorea.go.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/bbs/immigration/214/495389/download.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 — Thông cáo báo chí 01/06/2026: cải tiến E-7-4, kèm bảng điểm và hạn ngạch 33.000 người năm 2026</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n<li><a href=\\"https://www.moel.go.kr/local/seoul/common/downloadFile.do?file_seq=20260300886&amp;bbs_seq=20260300490&amp;bbs_id=LOCAL1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">고용노동부 — Hướng dẫn xin đề cử E-7-4 năm 2026 (ngành sản xuất) và bảng phân bổ hạn ngạch K-point E74</a> <span class=\\"source-domain\\">moel.go.kr</span></li>\\n<li><a href=\\"https://www.hikorea.go.kr/info/InfoDatail.pt?CAT_SEQ=174&amp;PARENT_ID=19\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">HiKorea — Bảng lệ phí thủ tục lưu trú</a> <span class=\\"source-domain\\">hikorea.go.kr</span></li>\\n</ul>","headings":[{"id":"danh-cho-ai","text":"Dành cho ai","level":2},{"id":"dieu-kien-chinh","text":"Điều kiện chính","level":2},{"id":"cach-tinh-diem","text":"Cách tính điểm","level":2},{"id":"han-ngach-nam-2026","text":"Hạn ngạch năm 2026","level":2},{"id":"ho-so-can-chuan-bi","text":"Hồ sơ cần chuẩn bị","level":2},{"id":"le-phi-va-thoi-gian-xu-ly","text":"Lệ phí và thời gian xử lý","level":2},{"id":"cac-buoc-nop-ho-so","text":"Các bước nộp hồ sơ","level":2},{"id":"lien-quan-toi-kiip-va-topik","text":"Liên quan tới KIIP và TOPIK","level":2},{"id":"luu-y","text":"Lưu ý","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":12},{"slug":"dang-ky-va-gia-han-luu-tru","title":"Đăng ký người nước ngoài, gia hạn lưu trú và báo đổi địa chỉ","summary":"Các hạn phải nhớ sau khi sang Hàn: làm thẻ 외국인등록증 trong 90 ngày, gia hạn trước khi hết hạn, báo chuyển nhà trong 15 ngày, và mức phạt nếu trễ.","updated":"2026-09-25","facts":{"group":"Thủ tục chung","code":"Thủ tục"},"html":"<h2 id=\\"danh-cho-ai\\">Dành cho ai</h2>\\n<p>Mọi người nước ngoài ở Hàn <strong>quá 90 ngày</strong>: du học (D-2, D-4), lao động (E-9, E-7…), kết hôn (F-6)… Bài này gom các thủ tục chung, không phụ thuộc loại visa. Giấy tờ riêng của từng visa thì xem bài của visa đó.</p>\\n<h2 id=\\"dieu-kien-chinh-cac-han-phai-nho\\">Điều kiện chính: các hạn phải nhớ</h2>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Việc</th>\\n<th>Hạn</th>\\n<th>Căn cứ</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>Đăng ký người nước ngoài (외국인등록)</td>\\n<td>trong <strong>90 ngày</strong> kể từ ngày nhập cảnh</td>\\n<td>Luật Xuất nhập cảnh, Điều 31</td>\\n</tr>\\n<tr>\\n<td>Gia hạn lưu trú (체류기간 연장)</td>\\n<td><strong>trước ngày hết hạn</strong> lưu trú</td>\\n<td>Điều 25</td>\\n</tr>\\n<tr>\\n<td>Báo đổi nơi ở (체류지 변경신고)</td>\\n<td>trong <strong>15 ngày</strong> kể từ ngày chuyển đến</td>\\n<td>Điều 36</td>\\n</tr>\\n<tr>\\n<td>Báo đổi thông tin đăng ký (tên, quốc tịch, hộ chiếu…)</td>\\n<td>trong <strong>15 ngày</strong></td>\\n<td>Điều 35</td>\\n</tr>\\n</tbody></table></div>\\n<p>Đổi tư cách lưu trú ngay tại Hàn mà sẽ ở quá 90 ngày thì đăng ký luôn lúc được đổi.</p>\\n<h2 id=\\"dang-ky-nguoi-nuoc-ngoai-va-the\\">Đăng ký người nước ngoài và thẻ 외국인등록증</h2>\\n<p>Đăng ký xong, bạn có <strong>số đăng ký người nước ngoài</strong> (외국인등록번호) và <strong>외국인등록증</strong> (thẻ người nước ngoài). Người dưới 17 tuổi có thể không được cấp thẻ; đủ 17 tuổi thì phải xin thẻ trong 90 ngày.</p>\\n<p>Nộp ở cơ quan xuất nhập cảnh (출입국·외국인관서) quản lý nơi bạn ở, <strong>phải đặt lịch trước</strong> trên HiKorea.</p>\\n<h2 id=\\"ho-so-can-chuan-bi\\">Hồ sơ cần chuẩn bị</h2>\\n<h3 id=\\"dang-ky-lan-dau\\">Đăng ký lần đầu</h3>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"dglvxr\\"><span>Đơn xin (통합신청서, mẫu số 34)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1mmzxfy\\"><span>Hộ chiếu</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"16nweg\\"><span>1 ảnh 3,5 × 4,5 cm, chụp trong 6 tháng gần nhất</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"eqb8zh\\"><span>Giấy tờ chứng minh chỗ ở (체류지 입증서류): hợp đồng thuê nhà, xác nhận ký túc xá…</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"3w2bes\\"><span>Phí 35.000 won</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"bn3yd1\\"><span>Giấy tờ riêng theo visa, ví dụ D-2, D-4: giấy xác nhận đang học (재학증명서)</span></label></li>\\n</ul>\\n<p>Người Việt Nam thuộc diện nước có nguy cơ lao cao. Nếu nhập cảnh bằng visa điện tử, hoặc nhập cảnh bằng visa dài hạn nhiều lần khi đã quá 6 tháng kể từ ngày cấp visa, thì phải nộp thêm <strong>giấy khám lao</strong> khi đăng ký.</p>\\n<h3 id=\\"gia-han-luu-tru\\">Gia hạn lưu trú</h3>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1gncuon\\"><span>Đơn xin gia hạn (통합신청서, mẫu số 34)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1b5njmw\\"><span>Hộ chiếu còn hạn</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"azes2u\\"><span>외국인등록증 đang dùng</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1y41526\\"><span>Giấy tờ chứng minh chỗ ở hiện tại</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1mqrnaa\\"><span>Phí 60.000 won</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1f1y38q\\"><span>Giấy tờ riêng theo visa (xem sổ tay 체류자격별 안내매뉴얼 trên HiKorea hoặc hỏi 1345)</span></label></li>\\n</ul>\\n<p>Người Việt Nam, nếu trong 1 năm trước ngày nộp đã ở Việt Nam (hoặc nước có nguy cơ lao cao khác) liên tục <strong>từ 6 tháng</strong>, thì phải nộp thêm giấy khám lao.</p>\\n<h3 id=\\"bao-doi-noi-o\\">Báo đổi nơi ở</h3>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1929cok\\"><span>Đơn báo đổi nơi ở (통합신청서)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"163t6rk\\"><span>Hộ chiếu (mang theo khi báo)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1lw9h9o\\"><span>외국인등록증 (để ghi địa chỉ mới)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1one7ez\\"><span>Giấy tờ chứng minh chỗ ở mới</span></label></li>\\n</ul>\\n<h2 id=\\"le-phi-va-thoi-gian-xu-ly\\">Lệ phí và thời gian xử lý</h2>\\n<p>Theo biểu phí trong sổ tay của Bộ Tư pháp (bản 09/2026):</p>\\n<ul>\\n<li>Cấp hoặc cấp lại thẻ người nước ngoài: <strong>35.000 won</strong></li>\\n<li>Gia hạn lưu trú: <strong>60.000 won</strong> (F-6: 30.000 won)</li>\\n<li>Đổi tư cách lưu trú: <strong>100.000 won</strong></li>\\n<li>Báo đổi thông tin đăng ký (hộ chiếu, tên…): không mất phí</li>\\n</ul>\\n<p>Phí là phí thẩm tra: hồ sơ đã được tiếp nhận thì không trả lại phí. Tài liệu năm 2022 của Bộ Tư pháp ghi nộp online qua HiKorea được giảm 20% phí.</p>\\n<h2 id=\\"cac-buoc-nop-ho-so\\">Các bước nộp hồ sơ</h2>\\n<p><strong>Đặt lịch HiKorea (방문예약):</strong> muốn đến cơ quan xuất nhập cảnh để đăng ký, gia hạn, đổi tư cách… thì phải đặt lịch online trước. Phụ nữ mang thai, người khuyết tật, người từ 70 tuổi và một số trường hợp đặc biệt được miễn đặt lịch.</p>\\n<ol>\\n<li>Vào hikorea.go.kr, chọn đặt lịch (방문예약), chọn cơ quan quản lý nơi bạn ở, ngày giờ và việc cần làm.</li>\\n<li>Chuẩn bị giấy tờ trước. Giấy tờ cấp ở Hàn phải cấp trong vòng 3 tháng. Giấy tờ cấp ở nước ngoài cần Apostille hoặc hợp pháp hoá lãnh sự.</li>\\n<li>Đến đúng giờ, nộp hồ sơ, lấy dấu vân tay nếu được yêu cầu.</li>\\n</ol>\\n<p><strong>Gia hạn:</strong> nộp <strong>từ 4 tháng trước</strong> ngày hết hạn, chậm nhất là <strong>ngày hết hạn</strong>. Nộp online thì chậm nhất là ngày trước đó. Nhiều loại visa gia hạn được online qua HiKorea (전자민원), không cần đến cơ quan.</p>\\n<p><strong>Báo đổi nơi ở:</strong> báo tại ủy ban phường/xã (주민센터, 시·군·구청), tại cơ quan xuất nhập cảnh, hoặc online trên HiKorea.</p>\\n<h2 id=\\"phat-khi-qua-han\\">Phạt khi quá hạn</h2>\\n<p>Theo Luật Xuất nhập cảnh (bản có hiệu lực từ 23/01/2026), mức phạt <strong>tối đa</strong>:</p>\\n<ul>\\n<li><strong>Không đăng ký</strong> người nước ngoài: tù tới 1 năm hoặc phạt tiền tới <strong>10 triệu won</strong> (Điều 95).</li>\\n<li><strong>Ở quá hạn</strong> mà không xin gia hạn: tù tới 3 năm hoặc phạt tiền tới <strong>30 triệu won</strong> (Điều 94).</li>\\n<li><strong>Không báo đổi nơi ở</strong>: phạt tiền tới <strong>1 triệu won</strong> (Điều 98).</li>\\n<li><strong>Không báo đổi thông tin đăng ký</strong>: phạt hành chính tới <strong>1 triệu won</strong> (Điều 100).</li>\\n</ul>\\n<p>Mức thực tế tuỳ từng vụ. Vi phạm luật xuất nhập cảnh còn có thể làm bạn bị hạn chế khi xin gia hạn, đổi visa, hoặc bị buộc xuất cảnh.</p>\\n<h2 id=\\"lien-quan-toi-kiip-va-topik\\">Liên quan tới KIIP và TOPIK</h2>\\n<p>Thủ tục đăng ký không yêu cầu TOPIK hay KIIP. Nhưng tài liệu năm 2022 của Bộ Tư pháp cho biết: học <strong>chương trình thích nghi sớm</strong> (조기적응 프로그램, có tiếng Việt) được tính <strong>2 giờ</strong> vào thời gian học KIIP. Đăng ký trên socinet.go.kr.</p>\\n<h2 id=\\"luu-y\\">Lưu ý</h2>\\n<ul>\\n<li><strong>Thời hạn lưu trú không vượt quá hạn hộ chiếu.</strong> Hộ chiếu sắp hết hạn thì làm hộ chiếu mới trước khi gia hạn, rồi báo đổi hộ chiếu trong 15 ngày.</li>\\n<li><strong>Phải đang ở Hàn khi nộp.</strong> Nộp xong mà xuất cảnh thì có thể bị từ chối.</li>\\n<li><strong>Mỗi người phải tự báo đổi nơi ở.</strong> Chủ hộ người Hàn chuyển nhà không tự động cập nhật địa chỉ cho vợ/chồng người nước ngoài.</li>\\n<li>Nợ thuế hoặc nợ bảo hiểm y tế có thể bị hạn chế thời gian lưu trú.</li>\\n<li>Tổng đài <strong>1345</strong> (không cần mã vùng): trả lời 24 giờ, 20 thứ tiếng. Sau 18 giờ ngày thường và cuối tuần, ngày lễ chỉ có tiếng Hàn, Anh, Trung.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://www.law.go.kr/%EB%B2%95%EB%A0%B9/%EC%B6%9C%EC%9E%85%EA%B5%AD%EA%B4%80%EB%A6%AC%EB%B2%95\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국가법령정보센터 — 출입국관리법 (Điều 25, 31, 33, 35, 36, 94, 95, 98, 100; hiệu lực từ 23/01/2026)</a> <span class=\\"source-domain\\">law.go.kr</span></li>\\n<li><a href=\\"https://www.law.go.kr/%EB%B2%95%EB%A0%B9/%EC%B6%9C%EC%9E%85%EA%B5%AD%EA%B4%80%EB%A6%AC%EB%B2%95%EC%8B%9C%ED%96%89%EB%A0%B9\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국가법령정보센터 — 출입국관리법 시행령 (Điều 31, 34의2 đặt lịch online, 45)</a> <span class=\\"source-domain\\">law.go.kr</span></li>\\n<li><a href=\\"https://www.law.go.kr/%EB%B2%95%EB%A0%B9/%EC%B6%9C%EC%9E%85%EA%B5%AD%EA%B4%80%EB%A6%AC%EB%B2%95%EC%8B%9C%ED%96%89%EA%B7%9C%EC%B9%99\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국가법령정보센터 — 출입국관리법 시행규칙 (Điều 72, lệ phí)</a> <span class=\\"source-domain\\">law.go.kr</span></li>\\n<li><a href=\\"https://www.hikorea.go.kr/board/BoardNtcDetailR.pt?BBS_SEQ=1&amp;BBS_GB_CD=BS10&amp;NTCCTT_SEQ=1062&amp;page=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">HiKorea — 체류민원 자격별 안내 매뉴얼, bản 18/09/2026 (biểu phí, giấy khám lao, hạn hộ chiếu)</a> <span class=\\"source-domain\\">hikorea.go.kr</span></li>\\n<li><a href=\\"https://www.hikorea.go.kr/info/InfoDatail.pt?CAT_SEQ=174&amp;PARENT_ID=19\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">HiKorea — Bảng lệ phí thủ tục lưu trú</a> <span class=\\"source-domain\\">hikorea.go.kr</span></li>\\n<li><a href=\\"https://www.hikorea.go.kr/info/InfoDatail.pt?CAT_SEQ=180&amp;PARENT_ID=139\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">HiKorea — Báo đổi thông tin đăng ký người nước ngoài</a> <span class=\\"source-domain\\">hikorea.go.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/bbs/immigration/47/426385/download.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">서울출입국·외국인청 — Tài liệu &quot;알기 쉽고 편리한 출입국 민원 안내&quot; (đặt lịch, gia hạn từ 4 tháng trước, tổng đài 1345)</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/bbs/immigration_eng/230/454086/download.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 — 비자 내비게이터 (Visa Navigator), bản 12/2022</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n</ul>","headings":[{"id":"danh-cho-ai","text":"Dành cho ai","level":2},{"id":"dieu-kien-chinh-cac-han-phai-nho","text":"Điều kiện chính: các hạn phải nhớ","level":2},{"id":"dang-ky-nguoi-nuoc-ngoai-va-the","text":"Đăng ký người nước ngoài và thẻ 외국인등록증","level":2},{"id":"ho-so-can-chuan-bi","text":"Hồ sơ cần chuẩn bị","level":2},{"id":"dang-ky-lan-dau","text":"Đăng ký lần đầu","level":3},{"id":"gia-han-luu-tru","text":"Gia hạn lưu trú","level":3},{"id":"bao-doi-noi-o","text":"Báo đổi nơi ở","level":3},{"id":"le-phi-va-thoi-gian-xu-ly","text":"Lệ phí và thời gian xử lý","level":2},{"id":"cac-buoc-nop-ho-so","text":"Các bước nộp hồ sơ","level":2},{"id":"phat-khi-qua-han","text":"Phạt khi quá hạn","level":2},{"id":"lien-quan-toi-kiip-va-topik","text":"Liên quan tới KIIP và TOPIK","level":2},{"id":"luu-y","text":"Lưu ý","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":16},{"slug":"f-6-ket-hon","title":"Visa F-6: kết hôn với người Hàn Quốc","summary":"Điều kiện, hồ sơ xin visa F-6-1 từ Việt Nam năm 2026, và đường đi tiếp lên vĩnh trú F-5-2 hoặc nhập tịch.","updated":"2026-09-25","facts":{"group":"Gia đình và định cư","code":"F-6"},"html":"<h2 id=\\"danh-cho-ai\\">Dành cho ai</h2>\\n<p>F-6 (결혼이민) là visa cho người nước ngoài kết hôn với công dân Hàn Quốc. Có ba loại:</p>\\n<ul>\\n<li><strong>F-6-1</strong>: đã đăng ký kết hôn hợp lệ ở cả hai nước, sang Hàn để sống chung với vợ/chồng người Hàn. Bài này chủ yếu nói về loại này.</li>\\n<li><strong>F-6-2</strong>: sau khi hôn nhân chấm dứt, đang nuôi hoặc sẽ nuôi con chưa thành niên có với người Hàn.</li>\\n<li><strong>F-6-3</strong>: hôn nhân không duy trì được vì vợ/chồng người Hàn mất, mất tích, hoặc vì lý do không do lỗi của mình.</li>\\n</ul>\\n<p>Người có F-6 được đi làm, không bị giới hạn ngành nghề như các visa lao động. Mỗi lần được cấp thời hạn lưu trú tối đa <strong>3 năm</strong>.</p>\\n<h2 id=\\"dieu-kien-chinh\\">Điều kiện chính</h2>\\n<p>Phía Hàn Quốc gọi người Hàn là <strong>초청인</strong> (người mời), người Việt là <strong>피초청인</strong> (người được mời).</p>\\n<p><strong>1. Thu nhập của người Hàn (năm 2026).</strong> Thu nhập trước thuế trong 1 năm gần nhất tính tới ngày nộp phải đạt mức sau (법무부고시 제2025-534호, áp dụng từ 02/01/2026):</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Số người trong hộ</th>\\n<th>Thu nhập năm tối thiểu</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>2 người</td>\\n<td>25.195.752 won</td>\\n</tr>\\n<tr>\\n<td>3 người</td>\\n<td>32.154.216 won</td>\\n</tr>\\n<tr>\\n<td>4 người</td>\\n<td>38.968.428 won</td>\\n</tr>\\n<tr>\\n<td>5 người</td>\\n<td>45.340.314 won</td>\\n</tr>\\n<tr>\\n<td>6 người</td>\\n<td>51.335.712 won</td>\\n</tr>\\n<tr>\\n<td>7 người</td>\\n<td>57.090.900 won</td>\\n</tr>\\n</tbody></table></div>\\n<ul>\\n<li>Từ 8 người: mỗi người thêm cộng <strong>5.755.188 won</strong>.</li>\\n<li>Hộ 2 người là người Hàn và vợ/chồng người Việt. Người thân trực hệ (bố mẹ, ông bà, con) cùng sổ hộ khẩu (주민등록표) với người Hàn thì tính thêm vào số người. Anh chị em không tính.</li>\\n<li>Không đủ thì được bù bằng thu nhập hoặc tài sản của người thân trực hệ cùng sổ hộ khẩu. Tiền gửi, bảo hiểm, chứng khoán chỉ được tính nếu từ 1 triệu won trở lên và đã giữ từ 6 tháng.</li>\\n<li><strong>Được miễn</strong> điều kiện thu nhập nếu: hai người đã có con chung; hai vợ chồng đã sống chung ở nước ngoài từ 1 năm nên người Hàn không có thu nhập ở Hàn; hoặc người Việt từng ở Hàn với F-6 của chính cuộc hôn nhân này mà không bị gián đoạn.</li>\\n</ul>\\n<p><strong>2. Giao tiếp tiếng Hàn của người Việt.</strong> Nộp một trong các giấy:</p>\\n<ul>\\n<li>TOPIK <strong>cấp 1 trở lên</strong> (kể cả TOPIK IBT);</li>\\n<li>chứng nhận hoàn thành khoá tiếng Hàn <strong>từ 120 giờ</strong> ở 세종학당 (sơ cấp 1A+1B) hoặc 한국교육원;</li>\\n<li>bằng đại học hoặc sau đại học ngành liên quan tới tiếng Hàn;</li>\\n<li>giấy tờ chứng minh người Việt đã ở Hàn <strong>liên tục từ 1 năm</strong>.</li>\\n</ul>\\n<p>Được miễn giấy tờ này nếu hai người đã có con chung, hoặc người Việt từng ở Hàn với F-6 của chính cuộc hôn nhân này. Nếu vợ chồng không dùng tiếng Hàn thì có thể chứng minh giao tiếp bằng tiếng Việt hoặc ngôn ngữ khác (ví dụ người Hàn đã sống ở Việt Nam từ 1 năm). Không có giấy nào thì cơ quan ngoại giao sẽ tự kiểm tra.</p>\\n<p><strong>3. Nhà ở.</strong> Phải có chỗ ở bình thường để hai vợ chồng sống lâu dài, đứng tên sở hữu hoặc thuê của người Hàn hoặc người nhà. 고시원, nhà nghỉ (모텔), nhà ni lông (비닐하우스) không được tính. Nhà ở công ty cấp có thể được chấp nhận. Địa chỉ phải trùng với sổ hộ khẩu.</p>\\n<p><strong>4. Chương trình hướng dẫn kết hôn quốc tế (국제결혼 안내프로그램).</strong> Người Hàn muốn mời vợ/chồng quốc tịch <strong>Việt Nam</strong> (cùng Trung Quốc, Philippines, Campuchia, Mông Cổ, Uzbekistan, Thái Lan) phải học chương trình này và nộp giấy hoàn thành. Đăng ký qua socinet.go.kr, giấy có hiệu lực <strong>5 năm</strong>. Được miễn nếu người Hàn đã sống ở Việt Nam (hoặc nước thứ ba bằng visa dài hạn) từ 6 tháng và quen nhau ở đó, hoặc người Việt đã ở Hàn hợp pháp bằng visa dài hạn từ 91 ngày và quen nhau lúc đó, hoặc có thai, sinh con.</p>\\n<h2 id=\\"ho-so-can-chuan-bi\\">Hồ sơ cần chuẩn bị</h2>\\n<p>Theo danh sách của Đại sứ quán Hàn Quốc tại Hà Nội (bản 10/11/2025). Giấy chứng nhận phải cấp trong vòng <strong>3 tháng</strong>, giấy khám sức khoẻ trong vòng 6 tháng.</p>\\n<p><strong>Người Việt chuẩn bị:</strong></p>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1wbvd0v\\"><span>Hộ chiếu còn hạn từ 6 tháng</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"x7okmr\\"><span>Đơn xin cấp visa (사증발급신청서), 1 ảnh 3,5 × 4,5 cm nền trắng</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1p65vmp\\"><span>Ảnh cưới, ảnh hai người khi quen nhau (in màu)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1c0ob6l\\"><span>Giấy khai sinh bản sao (BAN SAO)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"w7o42t\\"><span>Giấy xác nhận thông tin cư trú CT07, dịch công chứng sang tiếng Hàn hoặc tiếng Anh</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"ro4sk8\\"><span>Bản tường trình hoàn cảnh kết hôn (결혼배경 진술서, mẫu của Đại sứ quán)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"lzdt0t\\"><span>Bản kể quá trình quen nhau (교제경위서), kèm bản dịch</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"3pvh1k\\"><span>Phiếu lý lịch tư pháp số 2</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"dr5zl3\\"><span>Giấy khám sức khoẻ (có tâm thần, HIV, giang mai)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1bfhgb7\\"><span>Giấy khám lao ở bệnh viện Đại sứ quán chỉ định</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"794oo8\\"><span>Giấy chứng minh tiếng Hàn (xem trên)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1u0ersu\\"><span>Lịch sử nhắn tin, gọi điện (KakaoTalk, Messenger, Zalo…)</span></label></li>\\n</ul>\\n<p><strong>Người Hàn chuẩn bị:</strong></p>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"x553hp\\"><span>기본증명서, 혼인관계증명서, 가족관계증명서 (bản chi tiết 상세)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"67gc63\\"><span>주민등록표 등본 (sổ hộ khẩu)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1f9pdtg\\"><span>Thư mời vợ/chồng (초청장) và 교제경위서, đóng dấu 인감</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"4rhna\\"><span>소득금액증명 và giấy tờ việc làm (재직증명서, 건강보험 자격득실확인서…)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"85za03\\"><span>신용정보조회서 (tra tại credit4u.or.kr)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1ayz5fa\\"><span>Giấy tờ nhà: 등기부등본, hợp đồng thuê nếu thuê</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"170v04j\\"><span>신원보증서 (bảo lãnh tối thiểu 2 năm từ ngày nhập cảnh)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1ncozja\\"><span>인감증명서 hoặc 본인서명사실확인서</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1c7sn0e\\"><span>Giấy khám sức khoẻ của bệnh viện Hàn Quốc</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1xtbfkr\\"><span>Giấy hoàn thành 국제결혼 안내프로그램</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"b40x3x\\"><span>Bản sao CCCD Hàn và hộ chiếu</span></label></li>\\n</ul>\\n<p>Qua công ty môi giới hoặc người quen giới thiệu thì nộp thêm bản tường trình của người giới thiệu. Có thai từ 20 tuần hoặc đã có con chung thì dùng danh sách rút gọn riêng.</p>\\n<h2 id=\\"le-phi-va-thoi-gian-xu-ly\\">Lệ phí và thời gian xử lý</h2>\\n<ul>\\n<li>Tại Hà Nội: <strong>30 USD</strong>, cộng phí trung tâm tiếp nhận <strong>390.000 đồng</strong> (Đại sứ quán, 11/2025).</li>\\n<li>Xét trong <strong>31 ngày làm việc</strong>, có thể lâu hơn nếu cần phỏng vấn hoặc kiểm tra thực tế.</li>\\n<li>Visa cấp là visa 1 lần, hiệu lực 3 tháng. Vào Hàn phải đăng ký người nước ngoài và gia hạn trong 90 ngày.</li>\\n<li>Tại Hàn (bảng phí HiKorea): gia hạn F-6 <strong>30.000 won</strong>, đổi sang F-6 <strong>100.000 won</strong>.</li>\\n</ul>\\n<h2 id=\\"cac-buoc-nop-ho-so\\">Các bước nộp hồ sơ</h2>\\n<ol>\\n<li>Đăng ký kết hôn hợp lệ ở cả Việt Nam và Hàn Quốc.</li>\\n<li>Người Hàn học 국제결혼 안내프로그램 (nếu không được miễn).</li>\\n<li>Người Việt tự đến <strong>Trung tâm tiếp nhận visa Hà Nội (KVAC)</strong>, tầng 12 Discovery Complex, 302 Cầu Giấy. Không nhận qua bưu điện hay người nộp hộ. Tổng Lãnh sự quán tại TP.HCM có danh sách hồ sơ riêng.</li>\\n<li>Xem kết quả trên 대한민국 비자포털 (visa.go.kr).</li>\\n</ol>\\n<h2 id=\\"lien-quan-toi-kiip-va-topik\\">Liên quan tới KIIP và TOPIK</h2>\\n<ul>\\n<li><strong>Trước khi xin visa:</strong> TOPIK 1 là cách chứng minh tiếng Hàn đơn giản nhất. Theo 찾기쉬운 생활법령정보, hoàn thành KIIP từ giai đoạn 2 (사회통합프로그램 2단계 이상 교육 과정 이수) cũng được, nhưng quá 2 năm từ ngày hoàn thành thì phải qua bài kiểm tra trực tiếp của lãnh sự. Lựa chọn này chỉ hợp với người đang ở Hàn.</li>\\n<li><strong>Lên vĩnh trú F-5-2:</strong> ở Hàn với F-6 từ <strong>2 năm</strong>, và phải có &quot;năng lực hòa nhập&quot;: hoàn thành KIIP (영주 hoặc 귀화적격과정) hoặc thi 종합평가 đạt từ <strong>60/100</strong>. Xem bài F-5.</li>\\n<li><strong>Nhập tịch (간이귀화):</strong> kết hôn và có địa chỉ ở Hàn liên tục từ 2 năm; hoặc kết hôn đã 3 năm và có địa chỉ ở Hàn từ 1 năm. Người hoàn thành KIIP, hoặc đạt từ 60 điểm 종합평가 trong 3 năm gần nhất, được miễn bài thi 종합시험 khi xét nhập tịch.</li>\\n</ul>\\n<h2 id=\\"luu-y\\">Lưu ý</h2>\\n<ul>\\n<li>Khai quá trình quen nhau sơ sài hoặc giấy thu nhập thiếu có thể bị từ chối mà không được bổ sung.</li>\\n<li>Nộp giấy tờ giả: bị từ chối và Đại sứ quán sẽ đề nghị cơ quan Việt Nam điều tra.</li>\\n<li>Người đang ở Hàn bằng visa ngắn hạn (miễn visa, du lịch, C-3…) về nguyên tắc không đổi được sang F-6 tại Hàn, phải về nước xin visa. Có ngoại lệ khi mang thai, sinh con.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://overseas.mofa.go.kr/vn-ko/brd/m_2198/view.do?seq=1343476\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Đại sứ quán Hàn Quốc tại Việt Nam — Hướng dẫn visa F-6-1 và danh sách hồ sơ (2025.12.25)</a> <span class=\\"source-domain\\">overseas.mofa.go.kr</span></li>\\n<li><a href=\\"https://overseas.mofa.go.kr/vn-ko/brd/m_2197/view.do?seq=1345316&amp;page=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Đại sứ quán Hàn Quốc tại Việt Nam — Mức thu nhập F-6 năm 2026 (법무부고시 제2025-534호)</a> <span class=\\"source-domain\\">overseas.mofa.go.kr</span></li>\\n<li><a href=\\"https://overseas.mofa.go.kr/vn-ko/brd/m_2197/view.do?seq=1345296&amp;page=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Đại sứ quán Hàn Quốc tại Việt Nam — Giấy tờ chứng minh tiếng Hàn cho F-6</a> <span class=\\"source-domain\\">overseas.mofa.go.kr</span></li>\\n<li><a href=\\"https://www.hikorea.go.kr/board/BoardNtcDetailR.pt?BBS_SEQ=1&amp;BBS_GB_CD=BS10&amp;NTCCTT_SEQ=1062&amp;page=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">HiKorea — 체류자격별 안내 매뉴얼 (bản 18/09/2026), mục 결혼이민(F-6)</a> <span class=\\"source-domain\\">hikorea.go.kr</span></li>\\n<li><a href=\\"https://www.hikorea.go.kr/info/InfoDatail.pt?CAT_SEQ=174&amp;PARENT_ID=19\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">HiKorea — Bảng lệ phí thủ tục lưu trú</a> <span class=\\"source-domain\\">hikorea.go.kr</span></li>\\n<li><a href=\\"https://www.easylaw.go.kr/CSP/CnpClsMain.laf?csmSeq=47&amp;ccfNo=2&amp;cciNo=1&amp;cnpClsNo=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — Tư cách lưu trú do kết hôn</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://www.easylaw.go.kr/CSP/CnpClsMain.laf?csmSeq=47&amp;ccfNo=2&amp;cciNo=2&amp;cnpClsNo=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — Nhập tịch giản lược cho người kết hôn</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://www.gov.kr/portal/service/serviceInfo/SD0000012655\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">정부24 — 국제결혼 안내프로그램</a> <span class=\\"source-domain\\">gov.kr</span></li>\\n</ul>","headings":[{"id":"danh-cho-ai","text":"Dành cho ai","level":2},{"id":"dieu-kien-chinh","text":"Điều kiện chính","level":2},{"id":"ho-so-can-chuan-bi","text":"Hồ sơ cần chuẩn bị","level":2},{"id":"le-phi-va-thoi-gian-xu-ly","text":"Lệ phí và thời gian xử lý","level":2},{"id":"cac-buoc-nop-ho-so","text":"Các bước nộp hồ sơ","level":2},{"id":"lien-quan-toi-kiip-va-topik","text":"Liên quan tới KIIP và TOPIK","level":2},{"id":"luu-y","text":"Lưu ý","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":23},{"slug":"f-5-vinh-tru","title":"Visa F-5: vĩnh trú","summary":"Các diện vĩnh trú người Việt hay xin, điều kiện thu nhập, lý lịch, và vì sao phải hoàn thành KIIP giai đoạn 5 hoặc thi 영주용 종합평가.","updated":"2026-09-25","facts":{"group":"Gia đình và định cư","code":"F-5"},"html":"<h2 id=\\"danh-cho-ai\\">Dành cho ai</h2>\\n<p>F-5 (영주) là tư cách vĩnh trú. Không phải gia hạn visa, chỉ đổi thẻ vĩnh trú (영주증) <strong>10 năm một lần</strong>. Ra nước ngoài dưới 2 năm thì không cần xin giấy tái nhập cảnh.</p>\\n<p>F-5 có gần 30 mã. Các diện người Việt hay gặp:</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Mã</th>\\n<th>Dành cho</th>\\n<th>Thời gian ở Hàn</th>\\n<th>Thu nhập năm trước</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>F-5-2</td>\\n<td>Vợ/chồng người Hàn</td>\\n<td>Từ 2 năm với F-6</td>\\n<td>Từ 1 lần GNI</td>\\n</tr>\\n<tr>\\n<td>F-5-1</td>\\n<td>Người đi làm với D-7 đến E-7, hoặc F-2</td>\\n<td>Từ 5 năm liên tục</td>\\n<td>Từ 2 lần GNI</td>\\n</tr>\\n<tr>\\n<td>F-5-10</td>\\n<td>Có bằng hoặc chứng chỉ theo quy định, đang làm chính thức</td>\\n<td>Từ 3 năm</td>\\n<td>Từ 1 lần GNI</td>\\n</tr>\\n<tr>\\n<td>F-5-16</td>\\n<td>Người có F-2-7 (cư trú theo điểm)</td>\\n<td>Từ 3 năm với F-2-7</td>\\n<td>Từ 2 lần GNI</td>\\n</tr>\\n</tbody></table></div>\\n<p>GNI là thu nhập quốc dân bình quân đầu người. Theo Ngân hàng Trung ương Hàn Quốc (công bố 10/3/2026, số tạm tính), GNI năm 2025 là <strong>52.416.000 won</strong>.</p>\\n<h2 id=\\"dieu-kien-chinh\\">Điều kiện chính</h2>\\n<p>Bốn diện trên đều xét ba nhóm điều kiện (Luật Xuất nhập cảnh, điều 10-3).</p>\\n<p><strong>1. Lý lịch trong sạch (품행 단정).</strong> Một số trường hợp bị loại theo tiêu chí chung:</p>\\n<ul>\\n<li>bị phạt tù (kể cả án treo) chưa qua 5 năm;</li>\\n<li>bị phạt tiền chưa qua 3 năm kể từ ngày nộp phạt;</li>\\n<li>vi phạm Luật Xuất nhập cảnh từ 3 lần trong 5 năm gần nhất (không tính phạt hành chính 과태료);</li>\\n<li>bị trục xuất chưa qua 7 năm.</li>\\n</ul>\\n<p>Phải nộp <strong>lý lịch tư pháp của Việt Nam</strong>. Được miễn nếu, ví dụ, đã ở Hàn hợp pháp liên tục từ 10 năm, hoặc đã từng nộp khi xin visa và từ đó không ở nước ngoài quá 6 tháng liên tục. Có vi phạm luật trong 10 năm gần nhất thì phải học lớp 준법시민교육 (3 giờ) trước khi được cấp.</p>\\n<p><strong>2. Tự lo được cuộc sống (생계유지).</strong></p>\\n<ul>\\n<li>Thu nhập tính theo <strong>năm dương lịch trước năm nộp</strong>, chỉ tính khoản đã đóng thuế thu nhập. Ví dụ nộp năm 2026 thì xét thu nhập năm 2025.</li>\\n<li>Được cộng thu nhập của người nhà sống chung. Riêng F-5-10 chỉ tính thu nhập của chính người nộp.</li>\\n<li>Không đủ thu nhập thì một số diện được xét bằng tài sản ròng (F-5-2: từ mức trung vị; F-5-1, F-5-16: từ 1,5 lần mức bình quân). Không được cộng thu nhập với tài sản.</li>\\n<li>Còn nợ thuế, nợ bảo hiểm y tế, hoặc có thu nhập từ công việc mà visa của mình không cho phép thì bị đánh giá không đạt.</li>\\n</ul>\\n<p><strong>3. Năng lực hòa nhập (기본소양).</strong> Chứng minh bằng một trong hai cách:</p>\\n<ul>\\n<li>hoàn thành <strong>KIIP giai đoạn 5</strong> (사회통합프로그램 5단계 이수);</li>\\n<li>thi <strong>종합평가</strong> (영주용 hoặc 귀화용) đạt <strong>từ 60/100 điểm</strong>.</li>\\n</ul>\\n<p>TOPIK không còn được dùng cho mục này (TOPIK 4 chỉ áp dụng với hồ sơ nộp tới 31/3/2019). Xem thêm mục KIIP bên dưới.</p>\\n<p><strong>Riêng từng diện:</strong></p>\\n<ul>\\n<li><strong>F-5-2:</strong> đang duy trì hôn nhân hợp pháp, bình thường với người Hàn. Người nuôi con chung sau ly hôn, hoặc hôn nhân tan vỡ không do lỗi của mình, cũng xin được nếu ở với F-6 từ 2 năm.</li>\\n<li><strong>F-5-1:</strong> E-9, E-10, H-2 <strong>không</strong> nằm trong nhóm D-7 đến E-7. Người có E-7 phải có bằng cử nhân trở lên.</li>\\n<li><strong>F-5-10:</strong> có một trong các bằng: cử nhân ngành công nghệ cao, cử nhân khối kỹ thuật – tự nhiên của trường Hàn, <strong>thạc sĩ ngành bất kỳ của trường Hàn</strong>; hoặc chứng chỉ 기술사. Làm việc từ 3 năm sau khi có bằng, đang làm <strong>chính thức toàn thời gian từ 1 năm</strong> tại công ty Hàn.</li>\\n<li><strong>F-5-16:</strong> ở liên tục với F-2-7 trong 3 năm trước ngày nộp.</li>\\n</ul>\\n<h2 id=\\"ho-so-can-chuan-bi\\">Hồ sơ cần chuẩn bị</h2>\\n<h3 id=\\"dien-f-5-2-ket-hon\\">Diện F-5-2 (kết hôn)</h3>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"14ui5a0\\"><span>Đơn 통합신청서, 1 ảnh tiêu chuẩn, lệ phí</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1mmzxfy\\"><span>Hộ chiếu</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"fm8wp5\\"><span>외국인등록증 (thẻ người nước ngoài)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1lrv9lz\\"><span>Giấy tờ nơi ở: hợp đồng thuê nhà hoặc 등기부사항전부증명서</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"kpfs83\\"><span>Giấy tờ của vợ/chồng người Hàn: 기본증명서, 혼인관계증명서, 가족관계증명서, 주민등록표 등본</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"nsbcmk\\"><span>가족관계증명서 của con (nếu có con)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"b6v3yp\\"><span><strong>Từ 3 ảnh</strong> vợ chồng chụp chung (lễ tết, du lịch, sinh hoạt…)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"wmrwna\\"><span>Lý lịch tư pháp Việt Nam, cấp trong vòng 6 tháng</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"16zb6zt\\"><span>소득금액증명 của mình hoặc người nhà sống chung; hoặc giấy tờ tài sản kèm 신용정보조회서</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"12v0xq\\"><span>Giấy hoàn thành KIIP (한국이민영주적격과정 hoặc 한국이민귀화적격과정), hoặc giấy đạt 종합평가 (KIPRAT hoặc KINAT)</span></label></li>\\n</ul>\\n<h3 id=\\"dien-f-5-1-f-5-10-f-5-16\\">Diện F-5-1, F-5-10, F-5-16</h3>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1s06dp7\\"><span>Đơn 통합신청서, kèm tem lệ phí (수입인지)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1mmzxfy\\"><span>Hộ chiếu</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"fm8wp5\\"><span>외국인등록증 (thẻ người nước ngoài)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1lrv9lz\\"><span>Giấy tờ nơi ở: hợp đồng thuê nhà hoặc 등기부사항전부증명서</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"biquvm\\"><span>Lý lịch tư pháp Việt Nam (nếu không được miễn)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"w2c7h6\\"><span>신원보증서 (giấy bảo lãnh)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1bxpzww\\"><span>Giấy chứng nhận đã nộp đủ thuế (납세증명서)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"xeolwm\\"><span>소득금액증명 của sở thuế</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"vafloo\\"><span>Giấy hoàn thành KIIP hoặc giấy đạt 종합평가 (như trên)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1k6m4uh\\"><span>Bản khai thông tin người xin vĩnh trú (영주자격 신청자 기본정보)</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1e5xhx9\\"><span>F-5-1 có E-7: bằng tốt nghiệp, hợp đồng lao động</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"3ec9q7\\"><span>F-5-10: bằng hoặc chứng chỉ, 재직증명서, hợp đồng lao động, đăng ký kinh doanh của công ty, danh sách đóng 4 loại bảo hiểm</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1tapk8m\\"><span>F-5-16: 재직증명서, hợp đồng lao động, đăng ký kinh doanh của công ty</span></label></li>\\n</ul>\\n<h2 id=\\"le-phi-va-thoi-gian-xu-ly\\">Lệ phí và thời gian xử lý</h2>\\n<ul>\\n<li>Đổi sang F-5: <strong>200.000 won</strong> (bảng phí HiKorea), cộng phí cấp thẻ 영주증.</li>\\n<li>Cơ quan xuất nhập cảnh có thể kiểm tra thực tế trước khi quyết định.</li>\\n</ul>\\n<h2 id=\\"cac-buoc-nop-ho-so\\">Các bước nộp hồ sơ</h2>\\n<ol>\\n<li>Kiểm tra diện của mình, thời gian ở Hàn, thu nhập năm trước.</li>\\n<li>Hoàn thành KIIP giai đoạn 5 hoặc thi đạt 종합평가.</li>\\n<li>Chuẩn bị lý lịch tư pháp Việt Nam (nếu không được miễn).</li>\\n<li>Đặt lịch trên HiKorea (hikorea.go.kr), nộp tại cơ quan xuất nhập cảnh quản lý nơi ở.</li>\\n<li>Hỏi thêm qua tổng đài 1345.</li>\\n</ol>\\n<h2 id=\\"lien-quan-toi-kiip-va-topik\\">Liên quan tới KIIP và TOPIK</h2>\\n<p>Với F-5, KIIP gần như là bắt buộc.</p>\\n<ul>\\n<li><strong>Hoàn thành KIIP giai đoạn 5</strong> là cách phổ biến nhất. Giấy hoàn thành KIIP và giấy đạt 종합평가 không có hạn.</li>\\n<li><strong>영주용 종합평가</strong> (한국이민영주적격시험, KIPRAT) là bài thi cuối dành cho người xin vĩnh trú. Nội dung gồm tiếng Hàn và văn hoá Hàn (giai đoạn 1–4) và phần Hiểu biết xã hội Hàn Quốc cơ bản (giai đoạn 5). Đạt từ 60 điểm là đủ điều kiện năng lực hòa nhập.</li>\\n<li>Người học xong 5단계 기본과정 thì thi được 영주용. Người chưa học nhưng đạt <strong>từ 85 điểm</strong> bài kiểm tra đầu vào (사전평가) thì được thi thẳng trong 2 năm, nhưng không được công nhận &quot;hoàn thành KIIP&quot; (theo tài liệu hướng dẫn của Seoul).</li>\\n<li><strong>귀화용 종합평가</strong> có thêm phần 한국사회이해 심화, cũng được chấp nhận cho F-5. Nếu định nhập tịch sau này, học đủ 5단계 cả 기본 và 심화 sẽ dùng được cho cả hai.</li>\\n<li>Người dưới 15 tuổi được miễn. F-5-2 có thể được giảm hoặc miễn điều kiện thu nhập, năng lực hòa nhập theo 고시 riêng, hỏi 1345 để biết mình có thuộc diện đó không.</li>\\n</ul>\\n<h2 id=\\"luu-y\\">Lưu ý</h2>\\n<ul>\\n<li>Có thể bị huỷ F-5 nếu: gian dối khi xin; bị án tù từ 2 năm trở lên vì một số tội nặng; trong 5 năm bị án tù tổng cộng từ 3 năm.</li>\\n<li>Không được có quốc tịch Hàn song song. Không được làm hoặc điều hành ngành giải trí trái thuần phong mỹ tục (유흥서비스) trong thời gian xét.</li>\\n<li>Khai sai trong bản khai thông tin, phát hiện sau khi được cấp, có thể bị huỷ vĩnh trú.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://www.hikorea.go.kr/board/BoardNtcDetailR.pt?BBS_SEQ=1&amp;BBS_GB_CD=BS10&amp;NTCCTT_SEQ=1062&amp;page=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">HiKorea — 체류자격별 안내 매뉴얼 (bản 18/09/2026), mục 영주(F-5)</a> <span class=\\"source-domain\\">hikorea.go.kr</span></li>\\n<li><a href=\\"https://www.hikorea.go.kr/info/InfoDatail.pt?CAT_SEQ=174&amp;PARENT_ID=19\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">HiKorea — Bảng lệ phí thủ tục lưu trú</a> <span class=\\"source-domain\\">hikorea.go.kr</span></li>\\n<li><a href=\\"https://www.easylaw.go.kr/CSP/CnpClsMain.laf?csmSeq=47&amp;ccfNo=2&amp;cciNo=1&amp;cnpClsNo=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — Tư cách lưu trú do kết hôn (F-6, F-5)</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://eiec.kdi.re.kr/policy/materialView.do?num=277800\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">KDI 경제교육·정보센터 — 한국은행 &quot;2025년 4/4분기 및 연간 국민소득(잠정)&quot;</a> <span class=\\"source-domain\\">eiec.kdi.re.kr</span></li>\\n<li><a href=\\"https://global.seoul.go.kr/contents/bdmg/cont//1675297921384.pdf\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">서울외국인포털 — 사회통합프로그램 단계별 이수 기준, 종합평가 안내</a> <span class=\\"source-domain\\">global.seoul.go.kr</span></li>\\n<li><a href=\\"https://www.socinet.go.kr\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">사회통합정보망 (socinet)</a> <span class=\\"source-domain\\">socinet.go.kr</span></li>\\n</ul>","headings":[{"id":"danh-cho-ai","text":"Dành cho ai","level":2},{"id":"dieu-kien-chinh","text":"Điều kiện chính","level":2},{"id":"ho-so-can-chuan-bi","text":"Hồ sơ cần chuẩn bị","level":2},{"id":"dien-f-5-2-ket-hon","text":"Diện F-5-2 (kết hôn)","level":3},{"id":"dien-f-5-1-f-5-10-f-5-16","text":"Diện F-5-1, F-5-10, F-5-16","level":3},{"id":"le-phi-va-thoi-gian-xu-ly","text":"Lệ phí và thời gian xử lý","level":2},{"id":"cac-buoc-nop-ho-so","text":"Các bước nộp hồ sơ","level":2},{"id":"lien-quan-toi-kiip-va-topik","text":"Liên quan tới KIIP và TOPIK","level":2},{"id":"luu-y","text":"Lưu ý","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":23}],"truong":[{"slug":"dai-hoc-ajou","title":"Đại học Ajou (아주대학교)","summary":"Điều kiện tiếng, lịch tuyển sinh kỳ 3/2027, học phí, học bổng, ký túc xá và trường tiếng của Đại học Ajou cho sinh viên quốc tế hệ đại học.","updated":"2026-09-25","facts":{"nameKo":"아주대학교","city":"Suwon (Gyeonggi)","kind":"Tư thục","certified":"Có","topik":"Cấp 3 (chương trình tiếng Anh: không yêu cầu TOPIK)","tuition":"4,1–5,4 triệu won/học kỳ (năm 2026)","languageSchool":"Có","website":"https://www.ajou.ac.kr/iadmissions"},"html":"<h2 id=\\"tong-quan\\">Tổng quan</h2>\\n<p>Đại học tư thục ở quận Yeongtong, thành phố Suwon, tỉnh Gyeonggi.</p>\\n<p>Theo số liệu của Viện Phát triển Giáo dục Hàn Quốc (KEDI) ngày 1/4/2025, Ajou có 1.938 du học sinh Đông Nam Á, đứng thứ 4 cả nước. Trong số du học sinh Đông Nam Á ở Hàn, 83,5% là người Việt.</p>\\n<p>Trường đạt chứng nhận 교육국제화역량 인증제 (chứng nhận năng lực quốc tế hoá) năm 2025 cho cả hệ đại học và hệ học tiếng. Trường cũng nằm trong 39 trường &quot;우수 인증대학&quot; (chứng nhận xuất sắc). Danh sách do 교육부 và 법무부 công bố ngày 12/2/2026.</p>\\n<p>Hướng dẫn tuyển sinh kỳ 3/2027 có bản tiếng Việt trên trang tuyển sinh quốc tế của trường.</p>\\n<h2 id=\\"tuyen-sinh-sinh-vien-quoc-te\\">Tuyển sinh sinh viên quốc tế</h2>\\n<p>Diện dành cho người nước ngoài: 순수외국인 특별전형. Thí sinh và bố mẹ đều phải là người nước ngoài. Không nhận người hai quốc tịch có quốc tịch Hàn. GED, học tại nhà, học online không được tính.</p>\\n<p>Lịch kỳ nhập học 3/2027:</p>\\n<ul>\\n<li>Nộp hồ sơ online và gửi giấy tờ: 28/9/2026 (9:00) – 20/11/2026 (17:00). Gửi bưu điện thì hồ sơ phải đến trước 20/11/2026.</li>\\n<li>Công bố kết quả: 31/12/2026, 18:00.</li>\\n<li>Nộp bằng tốt nghiệp (nếu chưa tốt nghiệp) và giấy xác nhận số dư: hạn 22/1/2027.</li>\\n</ul>\\n<p>Lệ phí xét tuyển: 150.000 won. Học viên đang học ở 국제교육센터 của trường nộp sớm trước 15/10/2026 và mang hồ sơ đến trực tiếp thì được miễn lệ phí.</p>\\n<p>Xét tuyển 100% bằng hồ sơ. Riêng 국제경영학과 (Kinh doanh quốc tế) chương trình tiếng Anh có thêm phỏng vấn.</p>\\n<p>Chương trình tiếng Hàn nhận MỘT trong các giấy tờ sau:</p>\\n<ul>\\n<li>TOPIK 3 trở lên (PBT hoặc IBT).</li>\\n<li>Hoàn thành cấp 3 trở lên ở trường tiếng của một đại học chính quy tại Hàn.</li>\\n<li>Hoàn thành lớp 중급-3B ở 세종학당 (Học viện King Sejong). Khoá online và khoá tiếng Hàn thực dụng không được tính.</li>\\n<li>Đỗ bài thi tiếng Hàn của Ajou.</li>\\n</ul>\\n<p>Ai nộp khi đang chờ điểm phải bổ sung giấy tờ tiếng trước 16:00 ngày 23/12/2026. Không nộp kịp là trượt.</p>\\n<p>Chương trình tiếng Anh (chỉ ngành 국제경영학과 với hệ năm nhất) cần TOEFL iBT 71, IELTS 5.5 hoặc NEW TEPS 326.</p>\\n<p>Điều kiện tốt nghiệp: chương trình tiếng Hàn cần TOPIK 4. Chương trình tiếng Anh cần IELTS 5.5 hoặc TOEFL iBT 71.</p>\\n<p>Người đỗ nộp giấy xác nhận số dư từ 20 triệu won, cấp trong vòng 30 ngày tính đến ngày xin 사증발급인정서 (giấy chứng nhận đủ điều kiện cấp visa). Người học xong khoá tiếng Hàn ở 국제교육센터 của trường chỉ cần 10 triệu won.</p>\\n<h2 id=\\"hoc-phi-va-hoc-bong\\">Học phí và học bổng</h2>\\n<p>Học phí học kỳ đầu (năm 2026, năm 2027 có thể đổi):</p>\\n<ul>\\n<li>Nhân văn, khoa học xã hội: 4.134.000 won.</li>\\n<li>Kinh doanh quốc tế, chương trình tiếng Hàn: 4.452.000 won.</li>\\n<li>Kinh doanh quốc tế, chương trình tiếng Anh: 4.684.000 won.</li>\\n<li>Khoa học tự nhiên: 4.768.000 won.</li>\\n<li>Kỹ thuật, ICT, phần mềm: 5.366.000 won.</li>\\n</ul>\\n<p>Học bổng đầu vào theo TOPIK, chỉ áp dụng học kỳ đầu:</p>\\n<ul>\\n<li>TOPIK 6: giảm 100% học phí.</li>\\n<li>TOPIK 5: giảm 70%.</li>\\n<li>TOPIK 4: giảm 50%.</li>\\n<li>TOPIK 3: giảm 30%.</li>\\n<li>Điểm cao trong bài thi tiếng Hàn của Ajou: giảm 30% hoặc 20%.</li>\\n</ul>\\n<p>Trường còn có học bổng đặc biệt từ 1 học kỳ đến 4 năm, do hội đồng tuyển sinh tự chọn.</p>\\n<p>Có điểm TOPIK cao hơn sau khi nộp hồ sơ thì nộp bổ sung từ 23/12/2026 đến 19/2/2027. Phần chênh lệch được trả bằng tiền mặt sau khi nhập học.</p>\\n<p>Từ học kỳ 2, học bổng xét theo thứ hạng. Điều kiện chung: học từ 12 tín chỉ, GPA từ 2.0, có TOPIK 4:</p>\\n<ul>\\n<li>Top 5%: giảm 100%.</li>\\n<li>Trên 5% đến 15%: giảm 50%.</li>\\n<li>Trên 15% đến 30%: giảm 30%.</li>\\n</ul>\\n<p>Học bổng sinh hoạt CHEER UP: 1 triệu won. Năm nhất cần TOPIK 3, từ năm hai cần TOPIK 4, và xếp hạng trong top 50%. Người đã nhận học bổng theo thứ hạng thì không được nhận. Đạt TOPIK 4 trong 2 học kỳ đầu: nhận 300.000 won, một lần.</p>\\n<h2 id=\\"ky-tuc-xa\\">Ký túc xá</h2>\\n<p>Phí mỗi học kỳ (năm 2026):</p>\\n<ul>\\n<li>국제학사, phòng 2 người: 1.644.000 won.</li>\\n<li>화홍관, phòng 2 người: 1.258.000 won. Phòng 4 người: 853.000 won.</li>\\n<li>남제관, phòng 4 người: 762.000 won.</li>\\n</ul>\\n<h2 id=\\"truong-tieng\\">Trường tiếng (어학당)</h2>\\n<p>Trường có 국제교육센터 (Trung tâm giáo dục quốc tế).</p>\\n<ul>\\n<li>Mỗi kỳ 10 tuần, 200 giờ. Học thứ Hai đến thứ Sáu, 4 giờ/ngày.</li>\\n<li>6 cấp (1–6), lớp khoảng 18 người.</li>\\n<li>Học phí: 1.500.000 won/kỳ, 3.000.000 won/2 kỳ.</li>\\n<li>Lệ phí hồ sơ: 100.000 won, chỉ nộp kỳ đầu.</li>\\n<li>Hồ sơ visa D-4 cần giấy xác nhận số dư từ 10 triệu won.</li>\\n<li>Phải đi học từ 80% số giờ trở lên.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://www.ajou.ac.kr/iadmissions/undergraduate/guideline.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Ajou — Hướng dẫn tuyển sinh và nộp hồ sơ kỳ 3/2027</a> <span class=\\"source-domain\\">ajou.ac.kr</span></li>\\n<li><a href=\\"https://drive.google.com/file/d/19VdVHYoN_Vbh6zeIleCz5GqgLMNkBwrE/view\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Ajou — 2027학년도 1학기 순수외국인특별전형 모집요강 (tiếng Hàn, PDF)</a> <span class=\\"source-domain\\">drive.google.com</span></li>\\n<li><a href=\\"https://www.ajou.ac.kr/iadmissions/undergraduate/schedule.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Ajou — Lịch tuyển sinh kỳ 3/2027</a> <span class=\\"source-domain\\">ajou.ac.kr</span></li>\\n<li><a href=\\"https://cie.ajou.ac.kr/cie/korean/regular.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Ajou 국제교육센터 — Khoá tiếng Hàn chính quy</a> <span class=\\"source-domain\\">cie.ajou.ac.kr</span></li>\\n<li><a href=\\"https://cie.ajou.ac.kr/cie/admission/admission.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Ajou 국제교육센터 — Tuyển sinh, học phí</a> <span class=\\"source-domain\\">cie.ajou.ac.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/bbs/immigration/214/490761/download.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 — Thông cáo báo chí kết quả chứng nhận năng lực quốc tế hoá 2025 (12/2/2026, PDF)</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n<li><a href=\\"https://www.asiatoday.co.kr/kn/view.php?key=20260405010001321\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Asia Today — Du học sinh 300.000: từ Trung Quốc sang Đông Nam Á, người Việt tăng mạnh (5/4/2026)</a> <span class=\\"source-domain\\">asiatoday.co.kr</span></li>\\n</ul>","headings":[{"id":"tong-quan","text":"Tổng quan","level":2},{"id":"tuyen-sinh-sinh-vien-quoc-te","text":"Tuyển sinh sinh viên quốc tế","level":2},{"id":"hoc-phi-va-hoc-bong","text":"Học phí và học bổng","level":2},{"id":"ky-tuc-xa","text":"Ký túc xá","level":2},{"id":"truong-tieng","text":"Trường tiếng (어학당)","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":0},{"slug":"dai-hoc-dong-a","title":"Đại học Dong-A (동아대학교)","summary":"Điều kiện tiếng, học phí, học bổng, ký túc xá và trường tiếng của Đại học Dong-A ở Busan cho sinh viên quốc tế hệ đại học.","updated":"2026-09-25","facts":{"nameKo":"동아대학교","city":"Busan","kind":"Tư thục","certified":"Có","topik":"Cấp 2 (phải học thêm tiếng Hàn năm đầu; chuyển tiếp: cấp 3)","tuition":"3,3–4,7 triệu won/học kỳ (năm 2026)","languageSchool":"Có","website":"https://www.donga.ac.kr"},"html":"<h2 id=\\"tong-quan\\">Tổng quan</h2>\\n<p>Đại học tư thục ở Busan, có 3 cơ sở:</p>\\n<ul>\\n<li>승학캠퍼스 (Seunghak): phần lớn các trường thành viên.</li>\\n<li>부민캠퍼스 (Bumin): khối xã hội, kinh doanh, phòng quốc tế và trường tiếng.</li>\\n<li>구덕캠퍼스 (Gudeok): trường y.</li>\\n</ul>\\n<p>Theo số liệu của Viện Phát triển Giáo dục Hàn Quốc (KEDI) ngày 1/4/2025, Dong-A có 1.452 du học sinh Đông Nam Á, đứng thứ 8 cả nước. Phần lớn du học sinh Đông Nam Á ở Hàn là người Việt.</p>\\n<p>Trường đạt chứng nhận 교육국제화역량 인증제 (chứng nhận năng lực quốc tế hoá) năm 2025 cho cả hệ đại học và hệ học tiếng. Danh sách do 교육부 và 법무부 công bố ngày 12/2/2026.</p>\\n<h2 id=\\"tuyen-sinh-sinh-vien-quoc-te\\">Tuyển sinh sinh viên quốc tế</h2>\\n<p>Thông tin dưới đây lấy từ hướng dẫn tuyển sinh kỳ 9/2026 (2026학년도 후기). Hướng dẫn kỳ 3/2027 chưa thấy công bố khi cập nhật bài này. Kỳ 3/2026 năm ngoái nhận hồ sơ 2 đợt: 24/9 – 28/10/2025 và 9/12 – 17/12/2025.</p>\\n<p>Kỳ 9/2026 có 3 đợt nộp hồ sơ online: 1/4 – 14/4, 15/6 – 21/6 và 23/7 – 29/7/2026. Đợt 3 chỉ nhận người đang ở Hàn. Lệ phí xét tuyển chương trình tiếng Hàn: 40.000 won.</p>\\n<p>Điều kiện tiếng Hàn (chương trình tiếng Hàn):</p>\\n<ul>\\n<li>Năm nhất: TOPIK 2 trở lên, hoặc hoàn thành 중급1 (trung cấp 1) ở trường tiếng của Dong-A, hoặc kết quả tương đương (kỳ thi tiếng Hàn của Dong-A cấp 2, 사회통합프로그램 (KIIP) hoàn thành bậc 2 hoặc thi đầu vào từ 41 điểm).</li>\\n<li>Người vào bằng mức TOPIK 2 phải học thêm tiếng Hàn trong 1 năm đầu (trừ khối nghệ thuật, thể thao).</li>\\n<li>Chuyển tiếp (편입학): TOPIK 3 trở lên.</li>\\n<li>Chứng chỉ phải còn trong 2 năm tính đến hạn nộp hồ sơ.</li>\\n</ul>\\n<p>Chương trình tiếng Hàn xét tuyển bằng hồ sơ. Các ngành học bằng tiếng Anh (융합경영학과, 글로벌첨단융합공학부) cần IELTS 5.5 hoặc tương đương, xét hồ sơ và phỏng vấn.</p>\\n<p>Chứng minh tài chính: số dư từ 16.000.000 won, giấy cấp trong khoảng 1 tháng quanh ngày nộp online. Người học tiếp từ trường tiếng hoặc chương trình khác của Dong-A chỉ cần từ 8.000.000 won trong ngân hàng Hàn Quốc.</p>\\n<h2 id=\\"hoc-phi-va-hoc-bong\\">Học phí và học bổng</h2>\\n<p>Học phí năm 2026 (năm 2027 có thể tăng):</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Khối</th>\\n<th>Học kỳ 1</th>\\n<th>Từ học kỳ 2</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>Nhân văn, xã hội</td>\\n<td>3.476.700 won</td>\\n<td>3.318.500 won</td>\\n</tr>\\n<tr>\\n<td>미디어커뮤니케이션학과 (Truyền thông)</td>\\n<td>3.653.500 won</td>\\n<td>3.495.300 won</td>\\n</tr>\\n<tr>\\n<td>Toán</td>\\n<td>3.780.900 won</td>\\n<td>3.622.700 won</td>\\n</tr>\\n<tr>\\n<td>Tự nhiên, thể dục</td>\\n<td>4.085.200 won</td>\\n<td>3.927.000 won</td>\\n</tr>\\n<tr>\\n<td>Kỹ thuật</td>\\n<td>4.608.800 won</td>\\n<td>4.450.600 won</td>\\n</tr>\\n<tr>\\n<td>Nghệ thuật</td>\\n<td>4.690.300 won</td>\\n<td>4.532.100 won</td>\\n</tr>\\n</tbody></table></div>\\n<p>Học bổng đầu vào, chỉ áp dụng học kỳ 1 (chương trình tiếng Hàn):</p>\\n<ul>\\n<li>TOPIK 5 trở lên: miễn 100% học phí.</li>\\n<li>TOPIK 4: giảm 60%.</li>\\n<li>TOPIK 3: giảm 50%.</li>\\n<li>Kỳ thi tiếng Hàn của Dong-A cấp 3 trở lên: giảm 40%.</li>\\n<li>Các trường hợp đủ điều kiện nhập học khác: giảm 30%.</li>\\n</ul>\\n<p>Người đã hoàn thành từ 2 kỳ ở trường tiếng Dong-A, chuyên cần 2 kỳ cuối từ 80%, được xét mức cao hơn: TOPIK 5 miễn 100%, TOPIK 4 giảm 70%, TOPIK 3 giảm 60%, còn lại giảm 50%.</p>\\n<p>Học bổng cho sinh viên đang học, xét theo xếp hạng điểm kỳ trước: top 10% miễn 100%, top 40% giảm 70%, top 60% giảm 40%, top 80% giảm 20%.</p>\\n<h2 id=\\"ky-tuc-xa\\">Ký túc xá</h2>\\n<p>Phí một học kỳ (kỳ 1/2026, không gồm kỳ nghỉ):</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Toà</th>\\n<th>Sức chứa</th>\\n<th>Phí</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>승학1관 (nữ)</td>\\n<td>1.050 chỗ</td>\\n<td>939.000 won</td>\\n</tr>\\n<tr>\\n<td>승학2관 (nam)</td>\\n<td>588 chỗ</td>\\n<td>1.070.000 won</td>\\n</tr>\\n<tr>\\n<td>부민관</td>\\n<td>420 chỗ</td>\\n<td>1.194.000 won</td>\\n</tr>\\n<tr>\\n<td>구덕관</td>\\n<td>156 chỗ</td>\\n<td>999.000 won</td>\\n</tr>\\n</tbody></table></div>\\n<p>Tiền ăn tính riêng: gói 100 bữa 550.000 won, gói 70 bữa 420.000 won. Chỉ có bữa sáng và tối ngày thường. Cuối tuần, ngày lễ nhà ăn đóng cửa.</p>\\n<p>Ngoài ra có 석당 글로벌하우스, ký túc xá riêng cho du học sinh gần cơ sở Bumin: phòng 2 người, tối đa 184 chỗ, có bếp nấu ăn.</p>\\n<h2 id=\\"truong-tieng\\">Trường tiếng (어학당)</h2>\\n<p>Trường có 동아한국어학당.</p>\\n<ul>\\n<li>4 kỳ/năm, mỗi kỳ 10 tuần, 200 giờ. Học 5 ngày/tuần, 4 giờ/ngày. Lớp khoảng 15 người.</li>\\n<li>Học phí: 1.300.000 won/kỳ. Phí xét tuyển 50.000 won, chỉ nộp lần đầu. Giáo trình tính riêng.</li>\\n<li>Người nộp từ nước ngoài cần số dư từ 8.000.000 won.</li>\\n<li>Hướng dẫn tuyển sinh của trường tiếng ghi: không nhận người từ Hà Tĩnh, Nghệ An. Người tốt nghiệp trường nghề cần điểm từ 80.</li>\\n<li>Người mới nhập cảnh phải ở ký túc xá 3 tháng.</li>\\n<li>Kỳ tháng 3/2027: học 2/3 – 7/5/2027, nhận hồ sơ 16/11/2026 – 1/1/2027.</li>\\n</ul>\\n<p>Hoàn thành 중급1 ở trường tiếng được tính tương đương TOPIK 2 khi nộp vào đại học của Dong-A.</p>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://global.donga.ac.kr/global/CMS/Board/Board.do?mCode=MN066&amp;mode=view&amp;board_seq=8422214\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Dong-A — Tuyển sinh chương trình tiếng Hàn kỳ 9/2026 (thông báo và file hướng dẫn)</a> <span class=\\"source-domain\\">global.donga.ac.kr</span></li>\\n<li><a href=\\"https://global.donga.ac.kr/global/CMS/Board/Board.do?mCode=MN066&amp;mode=view&amp;board_seq=8422227\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Dong-A — Tuyển sinh chương trình tiếng Anh kỳ 9/2026</a> <span class=\\"source-domain\\">global.donga.ac.kr</span></li>\\n<li><a href=\\"https://global.donga.ac.kr/global/CMS/Board/Board.do?mCode=MN038&amp;mode=view&amp;mgr_seq=731&amp;board_seq=8401522\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Dong-A — Tuyển sinh kỳ 3/2026</a> <span class=\\"source-domain\\">global.donga.ac.kr</span></li>\\n<li><a href=\\"https://hanlim.donga.ac.kr/hanlim/CMS/Contents/Contents.do?mCode=MN018\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Dong-A — Ký túc xá: phí và tiền ăn</a> <span class=\\"source-domain\\">hanlim.donga.ac.kr</span></li>\\n<li><a href=\\"https://hanlim.donga.ac.kr/hanlim/CMS/Contents/Contents.do?mCode=MN012\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Dong-A — Ký túc xá: sức chứa</a> <span class=\\"source-domain\\">hanlim.donga.ac.kr</span></li>\\n<li><a href=\\"https://global.donga.ac.kr/global/CMS/Contents/Contents.do?mCode=MN062\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Dong-A — 석당 글로벌하우스</a> <span class=\\"source-domain\\">global.donga.ac.kr</span></li>\\n<li><a href=\\"https://global.donga.ac.kr/global/CMS/Contents/Contents.do?mCode=MN029\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">동아한국어학당 — Giới thiệu khoá học</a> <span class=\\"source-domain\\">global.donga.ac.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/bbs/immigration/214/490761/download.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 — Thông cáo báo chí kết quả chứng nhận năng lực quốc tế hoá 2025 (12/2/2026, PDF)</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n<li><a href=\\"https://www.asiatoday.co.kr/kn/view.php?key=20260405010001321\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Asia Today — Du học sinh 300.000: từ Trung Quốc sang Đông Nam Á, người Việt tăng mạnh (5/4/2026)</a> <span class=\\"source-domain\\">asiatoday.co.kr</span></li>\\n</ul>","headings":[{"id":"tong-quan","text":"Tổng quan","level":2},{"id":"tuyen-sinh-sinh-vien-quoc-te","text":"Tuyển sinh sinh viên quốc tế","level":2},{"id":"hoc-phi-va-hoc-bong","text":"Học phí và học bổng","level":2},{"id":"ky-tuc-xa","text":"Ký túc xá","level":2},{"id":"truong-tieng","text":"Trường tiếng (어학당)","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":0},{"slug":"dai-hoc-gachon","title":"Đại học Gachon (가천대학교)","summary":"Điều kiện tiếng, học phí, học bổng theo TOPIK và trường tiếng của Đại học Gachon cho sinh viên quốc tế hệ đại học.","updated":"2026-09-25","facts":{"nameKo":"가천대학교","city":"Seongnam (Gyeonggi)","kind":"Tư thục","certified":"Có","topik":"Không bắt buộc (một số ngành cần cấp 4)","tuition":"4,4–5,9 triệu won/học kỳ (năm 2026)","languageSchool":"Có","website":"https://www.gachon.ac.kr"},"html":"<h2 id=\\"tong-quan\\">Tổng quan</h2>\\n<p>Đại học tư thục. Cơ sở chính là 글로벌캠퍼스 (cơ sở Global) ở Seongnam, tỉnh Gyeonggi, sát ranh giới Seoul. Các ngành y tế học ở 메디컬캠퍼스 (cơ sở Medical) ở Incheon.</p>\\n<p>Theo số liệu của Viện Phát triển Giáo dục Hàn Quốc (KEDI) ngày 1/4/2025, Gachon là trường có nhiều du học sinh Đông Nam Á nhất cả nước: 3.278 người. Phần lớn du học sinh Đông Nam Á ở Hàn là người Việt.</p>\\n<p>Trường đạt chứng nhận 교육국제화역량 인증제 (chứng nhận năng lực quốc tế hoá) năm 2025 cho cả hệ đại học và hệ học tiếng. Danh sách do 교육부 và 법무부 công bố ngày 12/2/2026.</p>\\n<h2 id=\\"tuyen-sinh-sinh-vien-quoc-te\\">Tuyển sinh sinh viên quốc tế</h2>\\n<p>Thông tin dưới đây lấy từ hướng dẫn tuyển sinh kỳ 9/2026 (2026학년도 2학기). Hướng dẫn kỳ 3/2027 chưa thấy công bố khi cập nhật bài này.</p>\\n<p>Cả thí sinh và bố mẹ đều phải không có quốc tịch Hàn. Không nhận người hai quốc tịch có quốc tịch Hàn. Kỳ 9/2026 tuyển 3 đợt, nộp hồ sơ từ tháng 4 đến đầu tháng 7/2026. Lệ phí xét tuyển: 150.000 won.</p>\\n<p>Chương trình tiếng Hàn (한국어트랙) nhận một trong các giấy tờ sau:</p>\\n<ul>\\n<li>TOPIK 3 trở lên (không nhận điểm thi thử TOPIK iBT).</li>\\n<li>Hoàn thành cấp 3 trở lên khoá chính quy ở trường tiếng của một đại học Hàn Quốc.</li>\\n<li>Đỗ kỳ thi tiếng Hàn do Gachon tổ chức.</li>\\n<li>세종학당 (Học viện King Sejong) trung cấp 1 trở lên. Khoá online không được chấp nhận.</li>\\n<li>사회통합프로그램 (KIIP) cấp 3 trở lên, hoặc bài đánh giá đầu vào từ 61 điểm.</li>\\n</ul>\\n<p>Hướng dẫn tuyển sinh cũng cho phép nộp hồ sơ khi chưa có chứng chỉ tiếng Hàn. Ngoại lệ là một số ngành yêu cầu TOPIK 4, ví dụ 경영학과 (Quản trị kinh doanh), 관광경영학과 (Quản trị du lịch) và các ngành y tế ở cơ sở Medical như 물리치료학과 (Vật lý trị liệu), 치위생학과 (Nha khoa dự phòng).</p>\\n<p>Chương trình tiếng Anh (영어트랙) cần IELTS 5.5, TOEFL iBT 59 hoặc CEFR B2 trở lên.</p>\\n<p>Học tiếng bắt buộc sau khi nhập học:</p>\\n<ul>\\n<li>TOPIK 4 trở lên: không bắt buộc.</li>\\n<li>TOPIK 3 trở xuống, tân sinh viên: học tiếng bắt buộc 2 học kỳ.</li>\\n</ul>\\n<p>Điều kiện tốt nghiệp chương trình tiếng Hàn: có TOPIK 4. Chưa đạt thì phải học chương trình thay thế của trường, tự trả phí.</p>\\n<p>Người đỗ nộp giấy xác nhận số dư tài khoản từ 20.000.000 won (hoặc 16.000 USD).</p>\\n<p>Trường có 국제대학 (Đại học Quốc tế), dành riêng cho sinh viên nước ngoài. Sinh viên vào 국제대학 không được chuyển sang trường thành viên khác.</p>\\n<h2 id=\\"hoc-phi-va-hoc-bong\\">Học phí và học bổng</h2>\\n<p>Học phí mỗi học kỳ (kỳ 2 năm 2026, có thể tăng):</p>\\n<ul>\\n<li>Nhân văn, xã hội: 4.373.800 won.</li>\\n<li>Khoa học tự nhiên, thể dục: 5.119.800 won.</li>\\n<li>Kỹ thuật: 5.718.800 won.</li>\\n<li>Nghệ thuật: 5.939.800 won.</li>\\n</ul>\\n<p>Học bổng đầu vào cho chương trình tiếng Hàn, chỉ áp dụng học kỳ đầu:</p>\\n<ul>\\n<li>TOPIK 6: giảm 90% học phí.</li>\\n<li>TOPIK 5: giảm 80%.</li>\\n<li>TOPIK 4: giảm 60%.</li>\\n<li>TOPIK 3: giảm 40%.</li>\\n<li>Dưới TOPIK 3 hoặc chưa có điểm: giảm 30%.</li>\\n</ul>\\n<p>Được giới thiệu bởi cơ sở đối tác của trường hoặc 한국어교육센터 của trường: giảm thêm 10%.</p>\\n<p>Từ học kỳ 2, học bổng xét theo cấp TOPIK và GPA kỳ trước, từ 10% đến 100% học phí. Phải học ít nhất 12 tín chỉ ở kỳ trước (năm 4: 9 tín chỉ). Ai đạt TOPIK 4 trong năm đầu được thêm 300.000 won, một lần.</p>\\n<h2 id=\\"ky-tuc-xa\\">Ký túc xá</h2>\\n<p>Trường có 글로벌 학생생활관 (ký túc xá cơ sở Global). Hướng dẫn tuyển sinh không ghi phí ký túc xá cho sinh viên hệ đại học. Xem thông báo tại trang ký túc xá của trường.</p>\\n<h2 id=\\"truong-tieng\\">Trường tiếng (어학당)</h2>\\n<p>Trường có 한국어교육센터 (Trung tâm giáo dục tiếng Hàn), trực thuộc 국제교류처. Trung tâm cũng là nơi tổ chức thi TOPIK.</p>\\n<ul>\\n<li>Lớp tối đa 20 người, chia theo trình độ từ sơ cấp đến cao cấp.</li>\\n<li>Có TOPIK 3 trở lên: giảm 300.000 won học phí, một lần.</li>\\n<li>Mỗi kỳ, 2 học viên giỏi nhất mỗi trình độ nhận học bổng 500.000 hoặc 300.000 won.</li>\\n</ul>\\n<p>Học viên đang học ở trung tâm (visa D-4) khi nộp vào đại học chỉ cần giấy xác nhận số dư từ 10.000.000 won.</p>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://www.gachon.ac.kr/bbs/intl/1948/124242/artclView.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Gachon — 2026학년도 2학기 학부과정 외국인 신·편입학 특별전형 (thông báo và file hướng dẫn)</a> <span class=\\"source-domain\\">gachon.ac.kr</span></li>\\n<li><a href=\\"https://www.gachon.ac.kr/intl/11797/subview.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Gachon — 한국어교육센터</a> <span class=\\"source-domain\\">gachon.ac.kr</span></li>\\n<li><a href=\\"https://www.gachon.ac.kr/sites/dormitory/index.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Gachon — 학생생활관 (ký túc xá)</a> <span class=\\"source-domain\\">gachon.ac.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/bbs/immigration/214/490761/download.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 — Thông cáo báo chí kết quả chứng nhận năng lực quốc tế hoá 2025 (12/2/2026, PDF)</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n<li><a href=\\"https://www.asiatoday.co.kr/kn/view.php?key=20260405010001321\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Asia Today — Du học sinh 300.000: từ Trung Quốc sang Đông Nam Á, người Việt tăng mạnh (5/4/2026)</a> <span class=\\"source-domain\\">asiatoday.co.kr</span></li>\\n</ul>","headings":[{"id":"tong-quan","text":"Tổng quan","level":2},{"id":"tuyen-sinh-sinh-vien-quoc-te","text":"Tuyển sinh sinh viên quốc tế","level":2},{"id":"hoc-phi-va-hoc-bong","text":"Học phí và học bổng","level":2},{"id":"ky-tuc-xa","text":"Ký túc xá","level":2},{"id":"truong-tieng","text":"Trường tiếng (어학당)","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":0},{"slug":"dai-hoc-hannam","title":"Đại học Hannam (한남대학교)","summary":"Lịch nộp hồ sơ kỳ 3/2027, điều kiện tiếng, học phí, học bổng, ký túc xá và trường tiếng của Đại học Hannam ở Daejeon cho sinh viên quốc tế hệ đại học.","updated":"2026-09-25","facts":{"nameKo":"한남대학교","city":"Daejeon","kind":"Tư thục","certified":"Có","topik":"Cấp 3 (cấp 2 nếu học thêm 300 giờ tiếng Hàn ở trường trong năm đầu)","tuition":"3,6–4,6 triệu won/học kỳ (năm 2026)","languageSchool":"Có","website":"https://www.hannam.ac.kr"},"html":"<h2 id=\\"tong-quan\\">Tổng quan</h2>\\n<p>Đại học tư thục ở Daejeon.</p>\\n<p>Theo số liệu của Viện Phát triển Giáo dục Hàn Quốc (KEDI) ngày 1/4/2025, Hannam có 1.668 du học sinh Đông Nam Á, đứng thứ 6 cả nước. Phần lớn du học sinh Đông Nam Á ở Hàn là người Việt. Tài liệu tuyển sinh của trường ghi tổng số du học sinh là 2.042 người (tháng 4/2026).</p>\\n<p>Trường đạt chứng nhận 교육국제화역량 인증제 (chứng nhận năng lực quốc tế hoá) năm 2025 cho cả hệ đại học và hệ học tiếng. Danh sách do 교육부 và 법무부 công bố ngày 12/2/2026.</p>\\n<h2 id=\\"tuyen-sinh-sinh-vien-quoc-te\\">Tuyển sinh sinh viên quốc tế</h2>\\n<p>Lịch kỳ nhập học tháng 3/2027 (2027학년도 전기), khai giảng 2/3/2027:</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th></th>\\n<th>Đợt 1</th>\\n<th>Đợt 2</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>Nộp hồ sơ online và giấy tờ</td>\\n<td>12/10 – 23/10/2026</td>\\n<td>21/12 – 31/12/2026</td>\\n</tr>\\n<tr>\\n<td>Công bố kết quả</td>\\n<td>từ 16/11/2026</td>\\n<td>từ 18/1/2027</td>\\n</tr>\\n<tr>\\n<td>Đóng học phí</td>\\n<td>16/11 – 20/11/2026</td>\\n<td>18/1 – 22/1/2027</td>\\n</tr>\\n<tr>\\n<td>Nhận giấy nhập học (표준입학허가서)</td>\\n<td>từ 23/11/2026</td>\\n<td>từ 1/2/2027</td>\\n</tr>\\n</tbody></table></div>\\n<p>Đơn đăng ký chỉ nộp online tại ibsi.hannam.ac.kr. Giấy tờ nộp trực tiếp ở 입학관리실 (phòng tuyển sinh) hoặc gửi bưu điện. Lệ phí: 85.000 won. Hướng dẫn có bản tiếng Việt.</p>\\n<p>Cả bố và mẹ phải là người nước ngoài. Không nhận vào 사범대학 (6 ngành sư phạm) và ngành điều dưỡng. Xét tuyển 100% bằng hồ sơ.</p>\\n<p>Điều kiện tiếng (các ngành học bằng tiếng Hàn), nộp MỘT trong các giấy:</p>\\n<ul>\\n<li>TOPIK 3 trở lên (bản giấy hoặc TOPIK IBT).</li>\\n<li>Giấy đỗ kỳ thi tiếng Hàn do 한국어교육원 (trường tiếng) của Hannam tổ chức, mức tương đương TOPIK 3.</li>\\n<li>Giấy hoàn thành cấp 3 trở lên ở trường tiếng của Hannam.</li>\\n<li>TOPIK 2, kèm điều kiện: trong 1 năm sau nhập học phải học 300 giờ tiếng Hàn ở trường tiếng của Hannam.</li>\\n</ul>\\n<p>Người học từ 3 năm ở trường cấp 2, cấp 3 của Hàn (trừ trường quốc tế) nộp học bạ thay cho TOPIK.</p>\\n<p>린튼글로벌스쿨 (Linton Global School) học bằng tiếng Anh. Người từ nước không nói tiếng Anh cần một trong: TOEIC 850, TOEFL iBT 80, IELTS 5.5 hoặc NEW TEPS 385. Không có chứng chỉ thì có thể phỏng vấn thay.</p>\\n<p>Chứng minh tài chính: khi xin visa, nộp sổ tiết kiệm từ 18.000 USD, cấp trong tháng xin visa, tên người học hoặc gia đình.</p>\\n<h2 id=\\"hoc-phi-va-hoc-bong\\">Học phí và học bổng</h2>\\n<p>Học phí mỗi học kỳ, theo mức học kỳ 1/2026 (có thể đổi):</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Khối</th>\\n<th>Học phí</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>Nhân văn, xã hội</td>\\n<td>3.636.160 won</td>\\n</tr>\\n<tr>\\n<td>Toán</td>\\n<td>4.220.830 won</td>\\n</tr>\\n<tr>\\n<td>Tự nhiên, thể dục</td>\\n<td>4.239.720 won</td>\\n</tr>\\n<tr>\\n<td>Kỹ thuật, nghệ thuật</td>\\n<td>4.646.790 won</td>\\n</tr>\\n<tr>\\n<td>글로벌 (Linton)</td>\\n<td>4.148.390 won</td>\\n</tr>\\n</tbody></table></div>\\n<p>Học bổng đầu vào (các ngành tiếng Hàn):</p>\\n<ul>\\n<li>TOPIK 3, hoặc đỗ kỳ thi tiếng của trường mức cấp 3, hoặc học xong cấp 3 ở trường tiếng: giảm 40%.</li>\\n<li>TOPIK 4: giảm 50%.</li>\\n<li>TOPIK 5 trở lên: miễn 100%.</li>\\n</ul>\\n<p>Linton: giảm 40%, có TOEFL iBT 71 hoặc IELTS 5.5 trở lên thì giảm 50%.</p>\\n<p>Người đã học xong ở trường tiếng của Hannam được thêm học bổng 글로벌브리지 trong học kỳ đầu: khối nhân văn, xã hội 20%, khối tự nhiên, kỹ thuật 30%.</p>\\n<p>Học bổng cho sinh viên đang học, theo điểm trung bình (GPA):</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>GPA</th>\\n<th>Có TOPIK 4 trở lên</th>\\n<th>Chưa có</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>2,50 – dưới 3,50</td>\\n<td>30%</td>\\n<td>15%</td>\\n</tr>\\n<tr>\\n<td>3,50 – dưới 4,00</td>\\n<td>50%</td>\\n<td>25%</td>\\n</tr>\\n<tr>\\n<td>4,00 – dưới 4,30</td>\\n<td>80%</td>\\n<td>40%</td>\\n</tr>\\n<tr>\\n<td>Từ 4,30</td>\\n<td>100%</td>\\n<td>50%</td>\\n</tr>\\n</tbody></table></div>\\n<p>Sinh viên Linton cần TOEFL iBT 71 hoặc IELTS 5.5 thay cho TOPIK 4.</p>\\n<h2 id=\\"ky-tuc-xa\\">Ký túc xá</h2>\\n<p>Du học sinh ở 시빌리하우스 (Sibley House). Hệ đại học được ưu tiên xếp phòng. Phí kỳ 1/2026, phòng 3 người, chưa gồm tiền ăn:</p>\\n<ul>\\n<li>Sibley House 1 (nam): 590.000 won/học kỳ.</li>\\n<li>Sibley House 2 (nữ): 700.000 won/học kỳ.</li>\\n</ul>\\n<p>Đặt cọc chìa khoá 20.000 won. Trường không phát chăn, đồ dùng cá nhân. Ở trong kỳ nghỉ có thể tốn thêm.</p>\\n<h2 id=\\"truong-tieng\\">Trường tiếng (어학당)</h2>\\n<p>Trường có 한국어교육원 (trường tiếng).</p>\\n<ul>\\n<li>4 kỳ/năm, bắt đầu đầu tháng 3, 6, 9 và 12. Mỗi kỳ 10 tuần, 200 giờ.</li>\\n<li>Học phí: 1.400.000 won/kỳ. Phí xét tuyển 70.000 won, nộp một lần, không hoàn.</li>\\n<li>Hồ sơ cần giấy số dư ngân hàng từ 10.000 USD và giấy chứng minh thu nhập, cấp trong vòng 1 tháng.</li>\\n<li>Sinh viên hệ đại học của Hannam được giảm 50% học phí kỳ hè, kỳ đông và miễn phí xét tuyển.</li>\\n</ul>\\n<p>Hoàn thành cấp 3 ở trường tiếng được tính đủ điều kiện tiếng khi nộp vào đại học của Hannam.</p>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://ibsi.hannam.ac.kr/adms5/foreigner/4_1.asp\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Hannam — Hướng dẫn tuyển sinh người nước ngoài (danh sách file)</a> <span class=\\"source-domain\\">ibsi.hannam.ac.kr</span></li>\\n<li><a href=\\"https://ibsi.hannam.ac.kr/upload/GUIDES/20260921172318001.pdf\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Hannam — 2027학년도 전기 외국인 신입학 모집요강 (tiếng Hàn, PDF)</a> <span class=\\"source-domain\\">ibsi.hannam.ac.kr</span></li>\\n<li><a href=\\"https://ibsi.hannam.ac.kr/upload/GUIDES/20260921172403001.pdf\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Hannam — 2027 Spring Admission Guideline (tiếng Anh, PDF)</a> <span class=\\"source-domain\\">ibsi.hannam.ac.kr</span></li>\\n<li><a href=\\"https://ibsi.hannam.ac.kr/upload/GUIDES/20260529180909001.pdf\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Hannam — Tài liệu tuyển sinh 2027 (PDF)</a> <span class=\\"source-domain\\">ibsi.hannam.ac.kr</span></li>\\n<li><a href=\\"https://cir.hannam.ac.kr/kor/community/community_01.html?pPostNo=197999&amp;isGongjiPostList=N\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Hannam — Thông báo ký túc xá du học sinh kỳ 1/2026</a> <span class=\\"source-domain\\">cir.hannam.ac.kr</span></li>\\n<li><a href=\\"http://cklks.hnu.kr/kor/admission/admission_01.html\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Hannam 한국어교육원 — Tuyển sinh</a> <span class=\\"source-domain\\">cklks.hnu.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/bbs/immigration/214/490761/download.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 — Thông cáo báo chí kết quả chứng nhận năng lực quốc tế hoá 2025 (12/2/2026, PDF)</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n<li><a href=\\"https://www.asiatoday.co.kr/kn/view.php?key=20260405010001321\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Asia Today — Du học sinh 300.000: từ Trung Quốc sang Đông Nam Á, người Việt tăng mạnh (5/4/2026)</a> <span class=\\"source-domain\\">asiatoday.co.kr</span></li>\\n</ul>","headings":[{"id":"tong-quan","text":"Tổng quan","level":2},{"id":"tuyen-sinh-sinh-vien-quoc-te","text":"Tuyển sinh sinh viên quốc tế","level":2},{"id":"hoc-phi-va-hoc-bong","text":"Học phí và học bổng","level":2},{"id":"ky-tuc-xa","text":"Ký túc xá","level":2},{"id":"truong-tieng","text":"Trường tiếng (어학당)","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":0},{"slug":"dai-hoc-hanyang","title":"Đại học Hanyang (한양대학교)","summary":"Điều kiện tiếng, lịch tuyển sinh, học phí, học bổng và trường tiếng của Đại học Hanyang (cơ sở Seoul) cho sinh viên quốc tế hệ đại học.","updated":"2026-09-25","facts":{"nameKo":"한양대학교","city":"Seoul","kind":"Tư thục","certified":"Có","topik":"Cấp 4 để vào chuyên ngành (chưa có vẫn nộp được, học đủ cấp 4 ở trường; chương trình tiếng Anh: không yêu cầu)","tuition":"5,3–7,8 triệu won/học kỳ (kỳ 2 năm 2026)","languageSchool":"Có","website":"https://oia.hanyang.ac.kr"},"html":"<h2 id=\\"tong-quan\\">Tổng quan</h2>\\n<p>Đại học tư thục ở quận Seongdong, Seoul. Thuộc nhóm trường top của Hàn Quốc.</p>\\n<p>Theo báo cáo của 한국대학교육협의회 (Hội đồng Giáo dục Đại học Hàn Quốc) với số liệu năm 2023, Hanyang là trường có nhiều du học sinh nhất cả nước: 6.612 người. Trường không công bố riêng số sinh viên Việt Nam.</p>\\n<p>Trường đạt chứng nhận 교육국제화역량 인증제 (chứng nhận năng lực quốc tế hoá) năm 2025 cho cả hệ đại học và hệ học tiếng. Trường cũng nằm trong 39 trường &quot;우수 인증대학&quot; (chứng nhận xuất sắc). Danh sách do 교육부 và 법무부 công bố ngày 12/2/2026.</p>\\n<p>Bài này nói về cơ sở Seoul. Cơ sở ERICA ở Ansan (tỉnh Gyeonggi) tuyển sinh riêng. Đỗ cả hai thì chỉ được chọn một.</p>\\n<h2 id=\\"tuyen-sinh-sinh-vien-quoc-te\\">Tuyển sinh sinh viên quốc tế</h2>\\n<p>Thí sinh và bố mẹ đều phải là người nước ngoài. Không nhận người hai quốc tịch có quốc tịch Hàn. Học tại nhà, học online, giáo dục thường xuyên, GED không được tính.</p>\\n<p>Lịch kỳ nhập học 3/2027:</p>\\n<ul>\\n<li>Nộp hồ sơ online: 1/9 – 18/9/2026 (đã hết hạn).</li>\\n<li>Gửi hồ sơ qua bưu điện: hạn 30/9/2026. Không nhận nộp trực tiếp.</li>\\n<li>Công bố kết quả: 18/12/2026.</li>\\n<li>Khai giảng: 2/3/2027.</li>\\n</ul>\\n<p>Lệ phí xét tuyển: 142.000 won. Được đăng ký thêm nguyện vọng 2, trả thêm 27.000 won.</p>\\n<p>Phần lớn các ngành xét 100% bằng hồ sơ. Các ngành âm nhạc, múa, sân khấu điện ảnh, thiết kế nội thất xét thêm tác phẩm. 국제학부 (Khoa Quốc tế) và 데이터사이언스학부 (Khoa học dữ liệu) chương trình tiếng Anh có phỏng vấn tiếng Anh.</p>\\n<p>Hanyang xét năng lực học tập trước, không xét điều kiện tiếng. Nhưng muốn bắt đầu học chuyên ngành phải đạt MỘT trong hai:</p>\\n<ul>\\n<li>TOPIK 4 trở lên (kể cả TOPIK IBT).</li>\\n<li>Hoàn thành cấp 4 ở 국제교육원 (Viện Giáo dục Quốc tế) của trường.</li>\\n</ul>\\n<p>Người đỗ mà chưa đạt thì vẫn đóng học phí, làm thủ tục bảo lưu và đi học tiếng. Đạt chuẩn thì xin quay lại học. Thời gian bảo lưu tối đa theo quy định của trường.</p>\\n<p>Chương trình tiếng Anh không cần TOPIK. 국제학부 cần TOEFL iBT 89 hoặc IELTS 6.5. 데이터사이언스학부 và 경영학부 chương trình tiếng Anh cần TOEFL iBT 80 hoặc IELTS 6.0.</p>\\n<p>Giấy tờ bằng tiếng khác tiếng Hàn và tiếng Anh phải dịch công chứng. Bằng tốt nghiệp và học bạ phải hợp pháp hoá lãnh sự hoặc có Apostille. Hướng dẫn tuyển sinh ghi giấy tờ quan hệ gia đình của người Việt là giấy khai sinh.</p>\\n<h2 id=\\"hoc-phi-va-hoc-bong\\">Học phí và học bổng</h2>\\n<p>Học phí mỗi học kỳ (kỳ 2 năm 2026, có thể thay đổi):</p>\\n<ul>\\n<li>Nhân văn, xã hội, kinh tế, kinh doanh, quốc tế, chính sách: 5.279.000 won.</li>\\n<li>Khoa học tự nhiên, khoa học đời sống, thể thao: 6.150.000 won.</li>\\n<li>Kỹ thuật: 6.960.000 won.</li>\\n<li>Sân khấu điện ảnh, múa: 6.976.000 won.</li>\\n<li>Âm nhạc: 7.820.000 won.</li>\\n</ul>\\n<p>Học bổng đầu vào, xét tự động, không cộng dồn:</p>\\n<ul>\\n<li>HISP: giảm 100%, 70% hoặc 50% học phí suốt 8 học kỳ. Chọn theo điểm hồ sơ. Mỗi kỳ phải giữ GPA từ 2.5.</li>\\n<li>TOPIK 6: giảm 100% học phí học kỳ đầu. TOPIK 5: giảm 50%.</li>\\n<li>Hoàn thành cấp 6 ở 국제교육원: giảm 100% học kỳ đầu. Cấp 5: giảm 50%.</li>\\n<li>TOEFL iBT 90 hoặc IELTS 6.5: giảm 30% học kỳ đầu.</li>\\n</ul>\\n<p>Chỉ giấy tờ nộp trong hạn nộp hồ sơ mới được xét học bổng.</p>\\n<p>Khi đang học: học bổng HIEA cho người có GPA kỳ trước từ 3.0. Có học bổng cho người đạt TOPIK 5 hoặc 6 sau khi nhập học.</p>\\n<h2 id=\\"ky-tuc-xa\\">Ký túc xá</h2>\\n<p>Ký túc xá cơ sở Seoul do 학생생활관 quản lý. Phí và lịch đăng ký xem tại trang ký túc xá của trường. Hướng dẫn tuyển sinh không ghi phí ký túc xá cho sinh viên hệ đại học.</p>\\n<h2 id=\\"truong-tieng\\">Trường tiếng (어학당)</h2>\\n<p>Trường có 한양대학교 국제교육원 (Viện Giáo dục Quốc tế).</p>\\n<ul>\\n<li>4 kỳ/năm, mỗi kỳ 10 tuần, 200 giờ. Học thứ Hai đến thứ Sáu, ca sáng (9:00–13:00) hoặc ca chiều (14:00–18:00).</li>\\n<li>Cấp 1–6, lớp tối đa 15 người. Cấp 7: 150 giờ, tối đa 10 người.</li>\\n<li>Hồ sơ visa D-4 cần giấy xác nhận số dư từ 10 triệu won.</li>\\n<li>Học phí tăng từ kỳ thu 2026. Xem mức mới trên trang của 국제교육원.</li>\\n</ul>\\n<p>Ký túc xá cho học viên mới, phòng 2 người, cách trường khoảng 15 phút đi bộ:</p>\\n<ul>\\n<li>제6학생생활관 (nữ): 1.880.000 won/kỳ.</li>\\n<li>제7학생생활관 (nam): 1.627.000 won/kỳ.</li>\\n</ul>\\n<p>Chỉ đăng ký được tối đa 2 kỳ. Ký túc xá không có bếp.</p>\\n<p>Hoàn thành cấp 4 ở 국제교육원 là đủ chuẩn tiếng để bắt đầu học đại học.</p>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://oia.hanyang.ac.kr/admission\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Hanyang OIA — Regular Admission Guide (hướng dẫn tuyển sinh)</a> <span class=\\"source-domain\\">oia.hanyang.ac.kr</span></li>\\n<li><a href=\\"https://oia.hanyang.ac.kr/files/attach/filebox/2026/08/24/b95395d7bfde7ab0ed0392027f7c1ff7.pdf\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Hanyang — 2027학년도 1학기 외국인 모집요강 (tiếng Hàn, PDF)</a> <span class=\\"source-domain\\">oia.hanyang.ac.kr</span></li>\\n<li><a href=\\"https://iie.hanyang.ac.kr/front/regular/introduce/process\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">한양대학교 국제교육원 — Khoá chính quy</a> <span class=\\"source-domain\\">iie.hanyang.ac.kr</span></li>\\n<li><a href=\\"https://iie.hanyang.ac.kr/front/regular/dormitory\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">한양대학교 국제교육원 — Ký túc xá</a> <span class=\\"source-domain\\">iie.hanyang.ac.kr</span></li>\\n<li><a href=\\"https://iie.hanyang.ac.kr/front/regular/admission/application\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">한양대학교 국제교육원 — Hồ sơ đăng ký</a> <span class=\\"source-domain\\">iie.hanyang.ac.kr</span></li>\\n<li><a href=\\"https://dormitory.hanyang.ac.kr/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">한양대학교 학생생활관 (ký túc xá)</a> <span class=\\"source-domain\\">dormitory.hanyang.ac.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/bbs/immigration/214/490761/download.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 — Thông cáo báo chí kết quả chứng nhận năng lực quốc tế hoá 2025 (12/2/2026, PDF)</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n<li><a href=\\"https://www.etoday.co.kr/news/view/2373103\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">이투데이 — Trường nhiều du học sinh nhất: Hanyang, Kyung Hee, Sungkyunkwan (dẫn báo cáo của 대교협)</a> <span class=\\"source-domain\\">etoday.co.kr</span></li>\\n</ul>","headings":[{"id":"tong-quan","text":"Tổng quan","level":2},{"id":"tuyen-sinh-sinh-vien-quoc-te","text":"Tuyển sinh sinh viên quốc tế","level":2},{"id":"hoc-phi-va-hoc-bong","text":"Học phí và học bổng","level":2},{"id":"ky-tuc-xa","text":"Ký túc xá","level":2},{"id":"truong-tieng","text":"Trường tiếng (어학당)","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":0},{"slug":"dai-hoc-keimyung","title":"Đại học Keimyung (계명대학교)","summary":"Điều kiện tiếng, học phí, học bổng, ký túc xá và trường tiếng của Đại học Keimyung ở Daegu cho sinh viên quốc tế hệ đại học.","updated":"2026-09-25","facts":{"nameKo":"계명대학교","city":"Daegu","kind":"Tư thục","certified":"Có","topik":"Cấp 3 (ngành thể thao, nghệ thuật: cấp 2)","tuition":"3,3–5,1 triệu won/học kỳ (năm 2026)","languageSchool":"Có","website":"https://www.kmu.ac.kr"},"html":"<h2 id=\\"tong-quan\\">Tổng quan</h2>\\n<p>Đại học tư thục ở Daegu. Ký túc xá nằm ở 성서캠퍼스 (cơ sở Seongseo).</p>\\n<p>Theo báo Financial News (17/4/2026), trường có 2.162 du học sinh Việt Nam.</p>\\n<p>Trường đạt chứng nhận 교육국제화역량 인증제 (chứng nhận năng lực quốc tế hoá) năm 2025 cho cả hệ đại học và hệ học tiếng. Trường cũng nằm trong 39 trường &quot;우수 인증대학&quot; (chứng nhận xuất sắc). Danh sách do 교육부 và 법무부 công bố ngày 12/2/2026.</p>\\n<h2 id=\\"tuyen-sinh-sinh-vien-quoc-te\\">Tuyển sinh sinh viên quốc tế</h2>\\n<p>Lịch kỳ nhập học tháng 3/2027 (2027학년도 1학기):</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th></th>\\n<th>Đợt 1</th>\\n<th>Đợt 2</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>Nộp hồ sơ online</td>\\n<td>21/9 – 23/10/2026</td>\\n<td>30/11/2026 – 4/1/2027</td>\\n</tr>\\n<tr>\\n<td>Thi tiếng Hàn của trường (KKPT)</td>\\n<td>30/10/2026</td>\\n<td>7/1/2027</td>\\n</tr>\\n<tr>\\n<td>Phỏng vấn, thi năng khiếu (chỉ diện phỏng vấn)</td>\\n<td>6/11/2026</td>\\n<td>14–16/1/2027</td>\\n</tr>\\n<tr>\\n<td>Công bố kết quả</td>\\n<td>trước 13/11/2026</td>\\n<td>trước 21/1/2027</td>\\n</tr>\\n</tbody></table></div>\\n<p>Nộp hồ sơ qua <a href=\\"http://www.uwayapply.com\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">www.uwayapply.com</a>. Điểm TOPIK phải nộp trước hạn cuối nộp giấy tờ thì mới được tính cho điều kiện và học bổng.</p>\\n<p>Điều kiện tiếng, đáp ứng MỘT trong các mục:</p>\\n<ul>\\n<li>Phần lớn các ngành (nhân văn, kinh doanh, xã hội, tự nhiên, kỹ thuật, dược): TOPIK 3 trở lên.</li>\\n<li>Thể dục, âm nhạc – biểu diễn, mỹ thuật: TOPIK 2 trở lên.</li>\\n<li>Hoặc đỗ KKPT (계명대 한국어능력시험, kỳ thi tiếng Hàn của trường).</li>\\n<li>Hoặc hoàn thành cấp 3 trở lên tại 한국어학당 (trường tiếng) của Keimyung.</li>\\n<li>Hoặc đã học xong cấp 3 hay đại học bằng tiếng Hàn.</li>\\n</ul>\\n<p>Các ngành 국제경영학과 và 국제관계학과 thuộc Keimyung Adams College học bằng tiếng Anh. Điều kiện: TOEFL iBT 80 hoặc IELTS 5.5 trở lên.</p>\\n<p>Có hai diện xét tuyển:</p>\\n<ul>\\n<li>Diện phỏng vấn: phần lớn các ngành phỏng vấn bằng tiếng Hàn. Ngành học bằng tiếng Anh phỏng vấn bằng tiếng Anh. Ngành nghệ thuật, thể dục thi năng khiếu. Người ở nước ngoài được phỏng vấn online.</li>\\n<li>Diện xét hồ sơ: 100% hồ sơ, mở cho mọi ngành.</li>\\n</ul>\\n<p>Giấy chứng minh tài chính: số dư từ 16.000.000 won, duy trì trên 1 tháng. Người học xong khoá tiếng của Keimyung chỉ cần từ 8.000.000 won.</p>\\n<h2 id=\\"hoc-phi-va-hoc-bong\\">Học phí và học bổng</h2>\\n<p>Học phí năm 2026 (năm 2027 có thể đổi):</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Khối</th>\\n<th>Học kỳ 1</th>\\n<th>Từ học kỳ 2</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>Nhân văn, xã hội</td>\\n<td>3.460.000 won</td>\\n<td>3.320.000 won</td>\\n</tr>\\n<tr>\\n<td>Tự nhiên, thể dục</td>\\n<td>4.417.000 won</td>\\n<td>4.277.000 won</td>\\n</tr>\\n<tr>\\n<td>혁신신약학과 (Phát triển thuốc mới)</td>\\n<td>4.627.000 won</td>\\n<td>4.487.000 won</td>\\n</tr>\\n<tr>\\n<td>Kỹ thuật</td>\\n<td>4.740.000 won</td>\\n<td>4.600.000 won</td>\\n</tr>\\n<tr>\\n<td>Nghệ thuật, âm nhạc</td>\\n<td>5.066.000 won</td>\\n<td>4.926.000 won</td>\\n</tr>\\n<tr>\\n<td>Keimyung Adams College</td>\\n<td>5.001.000 won</td>\\n<td>4.861.000 won</td>\\n</tr>\\n</tbody></table></div>\\n<p>Học bổng đầu vào, chỉ áp dụng học kỳ 1:</p>\\n<ul>\\n<li>Loại A, TOPIK 5 trở lên: miễn 100% học phí.</li>\\n<li>Loại B, TOPIK 4: giảm 70% học phí.</li>\\n<li>Loại C, TOPIK 3: giảm 50% học phí. Với Keimyung Adams College: TOEFL iBT 80 hoặc IELTS 5.5 trở lên.</li>\\n</ul>\\n<p>Keimyung Adams College chỉ được xét loại C.</p>\\n<p>Học bổng cho sinh viên đang học, xét theo kết quả kỳ trước:</p>\\n<ul>\\n<li>진리 (Jinri): GPA từ 4.2, không có điểm F, từ 14 tín chỉ: miễn 100%.</li>\\n<li>정의 (Jeongeui): GPA từ 3.0, không có điểm F, từ 14 tín chỉ: giảm 50%.</li>\\n<li>사랑 (Sarang): GPA từ 2.0, không có điểm F, từ 3 tín chỉ: giảm 30%.</li>\\n<li>Đạt TOPIK 4 sau khi nhập học (ngành nghệ thuật, âm nhạc, thể dục: TOPIK 3): thưởng 500.000 won, một lần.</li>\\n</ul>\\n<h2 id=\\"ky-tuc-xa\\">Ký túc xá</h2>\\n<p>Sức chứa 2.932 chỗ. Sinh viên quốc tế được ưu tiên. Ký túc xá ở cơ sở Seongseo. Phải nộp giấy kết quả khám lao ngày nhận phòng.</p>\\n<p>Phí quản lý mỗi học kỳ (kỳ xuân 2026, không gồm kỳ nghỉ):</p>\\n<ul>\\n<li>Toà General: 651.000 won.</li>\\n<li>Toà Sarang: 763.000 won.</li>\\n<li>Toà Bangsa (nam), Hyupryuk (nữ): 1.269.000 won.</li>\\n<li>Toà Shinchuk: 1.357.000 won.</li>\\n</ul>\\n<p>Toà General và Sarang dùng chung phòng tắm, nhà vệ sinh. Các toà còn lại có phòng tắm trong phòng.</p>\\n<h2 id=\\"truong-tieng\\">Trường tiếng (어학당)</h2>\\n<p>Trường có 계명대학교 한국어학당.</p>\\n<ul>\\n<li>Khoá chính quy: 4 kỳ/năm, mỗi kỳ 10 tuần, 200 giờ. Học 5 ngày/tuần, 4 giờ/ngày.</li>\\n<li>6 cấp (1–6), mỗi lớp khoảng 15 người.</li>\\n<li>Phí nhập học: 100.000 won (không hoàn lại). Học phí: 1.300.000 won/kỳ.</li>\\n<li>Mỗi kỳ có học bổng cho 4–5 học viên có điểm và chuyên cần tốt.</li>\\n</ul>\\n<p>Hoàn thành cấp 3 trở lên ở 한국어학당 được tính là đủ điều kiện tiếng khi nộp vào đại học của trường.</p>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://inco.kmu.ac.kr/asiacenter/9951/subview.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Keimyung — Tuyển sinh hệ đại học cho người nước ngoài (lịch, file hướng dẫn)</a> <span class=\\"source-domain\\">inco.kmu.ac.kr</span></li>\\n<li><a href=\\"https://inco.kmu.ac.kr/sites/asiacenter/download/2027englishspring.pdf\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Keimyung — 2027 Spring Undergraduate Admission Guideline (tiếng Anh, PDF)</a> <span class=\\"source-domain\\">inco.kmu.ac.kr</span></li>\\n<li><a href=\\"https://inco.kmu.ac.kr/sites/asiacenter/download/2027koreanspring.pdf\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Keimyung — 2027학년도 1학기 외국인 특별전형 모집요강 (tiếng Hàn, PDF)</a> <span class=\\"source-domain\\">inco.kmu.ac.kr</span></li>\\n<li><a href=\\"https://kintlcenter.kmu.ac.kr/kintlcenter/9811/subview.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">계명대학교 한국어학당 — 과정소개</a> <span class=\\"source-domain\\">kintlcenter.kmu.ac.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/bbs/immigration/214/490761/download.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 — Thông cáo báo chí kết quả chứng nhận năng lực quốc tế hoá 2025 (12/2/2026, PDF)</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n<li><a href=\\"https://www.fnnews.com/news/202604171455201401\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Financial News — 계명대, trung tâm hợp tác Việt Nam (17/4/2026)</a> <span class=\\"source-domain\\">fnnews.com</span></li>\\n</ul>","headings":[{"id":"tong-quan","text":"Tổng quan","level":2},{"id":"tuyen-sinh-sinh-vien-quoc-te","text":"Tuyển sinh sinh viên quốc tế","level":2},{"id":"hoc-phi-va-hoc-bong","text":"Học phí và học bổng","level":2},{"id":"ky-tuc-xa","text":"Ký túc xá","level":2},{"id":"truong-tieng","text":"Trường tiếng (어학당)","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":0},{"slug":"dai-hoc-korea","title":"Đại học Korea (고려대학교)","summary":"Điều kiện tiếng, học phí, học bổng và trường tiếng của Đại học Korea cho sinh viên quốc tế hệ đại học.","updated":"2026-09-25","facts":{"nameKo":"고려대학교","city":"Seoul","kind":"Tư thục","certified":"Có","tuition":"5,8–7,8 triệu won/học kỳ (năm 2026)","languageSchool":"Có","website":"https://oia.korea.ac.kr"},"html":"<h2 id=\\"tong-quan\\">Tổng quan</h2>\\n<p>Đại học tư thục ở quận Seongbuk, Seoul (cơ sở Anam). Thuộc nhóm trường top của Hàn Quốc.</p>\\n<p>Trường đạt chứng nhận 교육국제화역량 인증제 (chứng nhận năng lực quốc tế hoá) năm 2025 cho cả hệ đại học và hệ học tiếng. Trường cũng nằm trong 39 trường &quot;우수 인증대학&quot; (chứng nhận xuất sắc). Danh sách do 교육부 và 법무부 công bố ngày 12/2/2026.</p>\\n<p>Bài này nói về cơ sở Seoul. Cơ sở Sejong (고려대학교(세종)) tuyển sinh riêng.</p>\\n<h2 id=\\"tuyen-sinh-sinh-vien-quoc-te\\">Tuyển sinh sinh viên quốc tế</h2>\\n<p>Diện dành cho người nước ngoài: 외국인 특별전형. Cả thí sinh và bố mẹ đều phải không có quốc tịch Hàn. Thí sinh phải học đủ 12 năm phổ thông chính quy. GED, học tại nhà, học online không được tính.</p>\\n<p>Lịch kỳ nhập học mùa xuân 2027:</p>\\n<ul>\\n<li>Nộp hồ sơ online: 3/8 – 31/8/2026.</li>\\n<li>Gửi hồ sơ gốc qua bưu điện: hạn 7/9/2026.</li>\\n<li>Công bố kết quả: 27/11/2026.</li>\\n</ul>\\n<p>Xét tuyển 100% bằng hồ sơ. Lệ phí xét tuyển (전형료): 150.000 won, riêng khối nghệ thuật 200.000 won.</p>\\n<p>Điều kiện ngôn ngữ: nộp MỘT trong các giấy tờ sau, trong hạn 2 năm:</p>\\n<ul>\\n<li>Bảng điểm TOPIK (kể cả TOPIK iBT chính thức).</li>\\n<li>Chứng nhận hoàn thành khoá chính quy tại 한국어센터 (Trung tâm tiếng Hàn) của trường, hoặc tại trường tiếng của trường đại học khác đạt chứng nhận quốc tế hoá.</li>\\n<li>Chứng nhận trung cấp của 세종학당 (Học viện King Sejong) hoặc điểm trung cấp SKA. Khoá online không được chấp nhận.</li>\\n<li>TOEFL iBT hoặc IELTS Academic.</li>\\n</ul>\\n<p>Hướng dẫn tuyển sinh không ghi mức TOPIK tối thiểu. Báo JoongAng Daily (8/2026) đưa tin trường yêu cầu tối thiểu TOPIK 3.</p>\\n<p>Từ kỳ mùa xuân 2027, trường bỏ bài kiểm tra tiếng Hàn online. Không có một trong các giấy tờ trên thì không nộp được hồ sơ.</p>\\n<p>Sau khi nhập học, mức tiếng quyết định việc học:</p>\\n<ul>\\n<li>TOPIK 5 trở lên: không học tiếng bắt buộc, học chuyên ngành tự do.</li>\\n<li>TOPIK 4: học tiếng bắt buộc 1 học kỳ. Mỗi kỳ chỉ được học tối đa 6 tín chỉ chuyên ngành.</li>\\n<li>TOPIK 3 trở xuống: học tiếng bắt buộc 2 học kỳ. Chưa được học môn chuyên ngành.</li>\\n</ul>\\n<p>Khi xin visa D-2, người đỗ phải nộp giấy chứng minh số dư tài khoản từ 20 triệu won trở lên.</p>\\n<h2 id=\\"hoc-phi-va-hoc-bong\\">Học phí và học bổng</h2>\\n<p>Học phí mỗi học kỳ (năm 2026):</p>\\n<ul>\\n<li>Nhân văn, xã hội: khoảng 5.800.000 won.</li>\\n<li>Khoa học tự nhiên: khoảng 6.700.000 won.</li>\\n<li>Kỹ thuật: khoảng 7.700.000 won.</li>\\n<li>Nghệ thuật: khoảng 7.800.000 won.</li>\\n</ul>\\n<p>Học bổng đầu vào xét theo kết quả tuyển sinh, không cần nộp đơn riêng:</p>\\n<ul>\\n<li>Anam Global: 100% học phí, 8 học kỳ. Mỗi khối lấy 1 người điểm cao nhất.</li>\\n<li>KU STEM Global Leader A: 100% học phí, 4 học kỳ. Dành cho thí sinh xuất sắc khối STEM.</li>\\n<li>Global Leader B: 50% học phí, 4 học kỳ.</li>\\n<li>Challenge C: dành cho người học xong khoá chính quy ở 한국어센터 của trường. Cấp 6 được 500.000 won, cấp 5 được 300.000 won. Chỉ cấp một lần ở học kỳ 1.</li>\\n</ul>\\n<p>Để giữ học bổng nhiều kỳ, mỗi kỳ phải học ít nhất 12 tín chỉ và đạt GPA tối thiểu 3.0 hoặc 3.5, tuỳ loại.</p>\\n<h2 id=\\"ky-tuc-xa\\">Ký túc xá</h2>\\n<p>Khu ký túc xá 안암학사 có ba toà dành cho sinh viên quốc tế hệ đại học: CJ I-House, Anam I-House và Global House. Các toà quốc tế CJ và Anam I-House là phòng đơn, dùng chung phòng tắm.</p>\\n<p>Phí và lịch đăng ký xem tại trang ký túc xá dorm.korea.ac.kr.</p>\\n<h2 id=\\"truong-tieng\\">Trường tiếng (어학당)</h2>\\n<p>Trường có 고려대학교 한국어센터 (KLC).</p>\\n<ul>\\n<li>Khoá chính quy: 4 kỳ/năm, mỗi kỳ 10 tuần, 200 giờ. Học 5 ngày/tuần, 4 giờ/ngày.</li>\\n<li>6 cấp (1–6), mỗi lớp tối đa 14 người.</li>\\n<li>Phí: 120.000 won phí nộp hồ sơ, 1.800.000 won/kỳ học phí.</li>\\n<li>Hồ sơ cần giấy chứng minh số dư từ 10 triệu won.</li>\\n<li>Học viên mới kỳ đầu có thể xin ở ký túc xá: phòng 2 người, 1.450.000 won/kỳ.</li>\\n</ul>\\n<p>Học xong khoá chính quy ở KLC được tính là đủ điều kiện tiếng khi nộp vào đại học.</p>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://oia.korea.ac.kr/oia2026/Admission-Guide.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Korea University OIA — Admission Guide (kỳ mùa xuân 2027)</a> <span class=\\"source-domain\\">oia.korea.ac.kr</span></li>\\n<li><a href=\\"https://oia.korea.ac.kr/_attach/file/2026/08/cPWRwqxnzxVGZbkkUvWL.pdf\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Korea University — 2027학년도 외국인 학부 특별전형 모집요강 (tiếng Hàn, PDF)</a> <span class=\\"source-domain\\">oia.korea.ac.kr</span></li>\\n<li><a href=\\"https://oia.korea.ac.kr/oia2026/Tuition.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Korea University OIA — Tuition</a> <span class=\\"source-domain\\">oia.korea.ac.kr</span></li>\\n<li><a href=\\"https://dorm.korea.ac.kr/front/main?lang=en\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Korea University — Anam Dormitory</a> <span class=\\"source-domain\\">dorm.korea.ac.kr</span></li>\\n<li><a href=\\"https://klc.korea.ac.kr/klckor/course/regular_guide.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">고려대학교 한국어센터 — 정규과정 등록안내</a> <span class=\\"source-domain\\">klc.korea.ac.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/bbs/immigration/214/490761/download.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 — Thông cáo báo chí kết quả chứng nhận năng lực quốc tế hoá 2025 (12/2/2026, PDF)</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n<li><a href=\\"https://www.koreajoongangdaily.com/korea/spring-2027-admissions-for-international-students-open-at-korean-universities/12788168\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Korea JoongAng Daily — Spring 2027 admissions for international students open at Korean universities</a> <span class=\\"source-domain\\">koreajoongangdaily.com</span></li>\\n</ul>","headings":[{"id":"tong-quan","text":"Tổng quan","level":2},{"id":"tuyen-sinh-sinh-vien-quoc-te","text":"Tuyển sinh sinh viên quốc tế","level":2},{"id":"hoc-phi-va-hoc-bong","text":"Học phí và học bổng","level":2},{"id":"ky-tuc-xa","text":"Ký túc xá","level":2},{"id":"truong-tieng","text":"Trường tiếng (어학당)","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":0},{"slug":"dai-hoc-quoc-gia-kyungpook","title":"Đại học Quốc gia Kyungpook (경북대학교)","summary":"Lịch nộp hồ sơ kỳ 3/2027, điều kiện tiếng theo ngành, học phí quốc lập, học bổng, ký túc xá và trường tiếng của Đại học Quốc gia Kyungpook ở Daegu.","updated":"2026-09-25","facts":{"nameKo":"경북대학교","city":"Daegu","kind":"Quốc lập","certified":"Có","topik":"Cấp 3 (một số ngành: cấp 4, ngành 미디어커뮤니케이션: cấp 5)","tuition":"1,9–2,7 triệu won/học kỳ (năm 2026)","languageSchool":"Có","website":"https://www.knu.ac.kr"},"html":"<h2 id=\\"tong-quan\\">Tổng quan</h2>\\n<p>Đại học quốc lập, cơ sở chính ở Daegu, thêm một cơ sở ở Sangju (tỉnh Gyeongbuk). Là trường quốc lập nên học phí thấp hơn hẳn các trường tư.</p>\\n<p>Theo số liệu 법무부 ngày 31/12/2025 (K-Study Times tổng hợp), trường có 746 du học sinh Việt Nam trên tổng 2.304 du học sinh.</p>\\n<p>Trường đạt chứng nhận 교육국제화역량 인증제 (chứng nhận năng lực quốc tế hoá) năm 2025 cho cả hệ đại học và hệ học tiếng. Trường cũng nằm trong 39 trường &quot;우수 인증대학&quot; (chứng nhận xuất sắc). Danh sách do 교육부 và 법무부 công bố ngày 12/2/2026.</p>\\n<h2 id=\\"tuyen-sinh-sinh-vien-quoc-te\\">Tuyển sinh sinh viên quốc tế</h2>\\n<p>Lịch kỳ nhập học tháng 3/2027 (2027학년도 1학기):</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Bước</th>\\n<th>Thời gian</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>Nộp hồ sơ online</td>\\n<td>12/10 – 30/10/2026</td>\\n</tr>\\n<tr>\\n<td>Phỏng vấn</td>\\n<td>18/11 – 27/11/2026</td>\\n</tr>\\n<tr>\\n<td>Nộp chứng minh tài chính</td>\\n<td>đến 18/12/2026</td>\\n</tr>\\n<tr>\\n<td>Nộp bổ sung điểm TOPIK (nếu nộp bằng phiếu dự thi)</td>\\n<td>đến 13:00 ngày 21/12/2026</td>\\n</tr>\\n<tr>\\n<td>Công bố kết quả</td>\\n<td>dự kiến 6/1/2027, báo qua email</td>\\n</tr>\\n<tr>\\n<td>Nộp bản gốc giấy tờ</td>\\n<td>đến 19/2/2027</td>\\n</tr>\\n</tbody></table></div>\\n<p>Kỳ tháng 9/2027 nhận hồ sơ 12/4 – 30/4/2027. Nộp qua <a href=\\"http://www.uwayapply.com\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">www.uwayapply.com</a>. Lệ phí: 80.000 won.</p>\\n<p>Phỏng vấn online qua video, đánh giá tiếng Hàn và kiến thức nền của ngành. Khối nghệ thuật thi năng khiếu. Ngành thiết kế, mỹ thuật, âm nhạc chỉ nhận nhập học tháng 3. Phần lớn môn học dạy bằng tiếng Hàn.</p>\\n<p>Điều kiện tiếng khác nhau theo ngành:</p>\\n<ul>\\n<li>TOPIK 3: địa lý, mỹ thuật, trẻ em, may mặc, dinh dưỡng, hành chính.</li>\\n<li>TOPIK 4: các ngành ngôn ngữ, triết học, công tác xã hội, điện, điện tử, tâm lý, chính trị ngoại giao, xã hội học, vật lý, sinh học, máy tính, 인공지능시스템학과. Kinh doanh, kinh tế thương mại, cơ khí cũng cần TOPIK 4 và không nhận phiếu dự thi.</li>\\n<li>TOPIK 5: 미디어커뮤니케이션학과 (truyền thông), không nhận phiếu dự thi.</li>\\n</ul>\\n<p>Các ngành còn lại đáp ứng MỘT trong các mục:</p>\\n<ul>\\n<li>TOPIK 3 trở lên.</li>\\n<li>Hoàn thành cấp 3 ở trường tiếng thuộc một đại học Hàn Quốc.</li>\\n<li>TOEFL iBT 59, IELTS 5.5, CEFR B2 hoặc NEW TEPS 202.</li>\\n<li>사회통합프로그램 (KIIP) hoàn thành bậc 3 hoặc thi đầu vào từ 61 điểm.</li>\\n<li>Giấy hoàn thành trung cấp 1 ở 세종학당 (King Sejong Institute) ngoài Hàn Quốc, không tính học online.</li>\\n</ul>\\n<p>Sinh viên năm nhất phải đạt TOPIK 4 trước khi tốt nghiệp.</p>\\n<p>Chứng minh tài chính: số dư tương đương 16.000.000 won, tên người học hoặc bố mẹ, cấp trong vòng 30 ngày. Dùng tài khoản của bố mẹ thì nộp thêm giấy xác nhận công việc hoặc đăng ký kinh doanh của bố mẹ. Người đang ở Hàn chỉ được dùng tài khoản ngân hàng Hàn đứng tên mình.</p>\\n<h2 id=\\"hoc-phi-va-hoc-bong\\">Học phí và học bổng</h2>\\n<p>Học phí mỗi học kỳ năm 2026, cơ sở Daegu:</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Khối</th>\\n<th>Học phí</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>Kinh doanh, hành chính</td>\\n<td>1.954.000 won</td>\\n</tr>\\n<tr>\\n<td>Nhân văn, sư phạm</td>\\n<td>1.981.000 won</td>\\n</tr>\\n<tr>\\n<td>Khoa học xã hội</td>\\n<td>2.019.000 won</td>\\n</tr>\\n<tr>\\n<td>Tự nhiên, đời sống, nông nghiệp</td>\\n<td>2.379.000 won</td>\\n</tr>\\n<tr>\\n<td>Kỹ thuật, IT</td>\\n<td>2.531.000 won</td>\\n</tr>\\n<tr>\\n<td>Nghệ thuật</td>\\n<td>2.610.000 won (mỹ thuật 2.670.000 won)</td>\\n</tr>\\n</tbody></table></div>\\n<p>Học bổng đầu vào, chỉ học kỳ 1:</p>\\n<ul>\\n<li>TOPIK 3: miễn phần 수업료1, khoảng 20% học phí.</li>\\n<li>TOPIK 4: miễn nửa phần 수업료2, khoảng 40%.</li>\\n<li>TOPIK 5: miễn toàn bộ 수업료2, khoảng 80%.</li>\\n<li>TOPIK 6: miễn 100%.</li>\\n<li>Học xong từ 2 kỳ ở trường tiếng của trường: khoảng 20%. Không cộng với học bổng TOPIK.</li>\\n</ul>\\n<p>Học bổng ký túc xá: kỳ đầu được hỗ trợ phí quản lý, không gồm tiền ăn. Số người được vào ký túc xá tuỳ ngân sách của trường.</p>\\n<p>Sinh viên đang học:</p>\\n<ul>\\n<li>Top 7% du học sinh của trường thành viên (theo điểm kỳ trước): khoảng 80% học phí.</li>\\n<li>Top 8–37%: khoảng 20%.</li>\\n<li>Vào trường với TOPIK 3 trở xuống, đạt TOPIK 4 trong 3 học kỳ đầu: thưởng 500.000 won, một lần.</li>\\n</ul>\\n<h2 id=\\"ky-tuc-xa\\">Ký túc xá</h2>\\n<p>Phí mỗi học kỳ (kỳ 2/2026), phòng 2 người:</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Toà</th>\\n<th>Phí quản lý</th>\\n<th>Tiền ăn (3 bữa/ngày)</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>봉사관, 화목관 (Daegu)</td>\\n<td>635.500 won</td>\\n<td>1.043.200 won</td>\\n</tr>\\n<tr>\\n<td>첨성관 (Daegu)</td>\\n<td>713.400 won</td>\\n<td>1.043.200 won</td>\\n</tr>\\n<tr>\\n<td>청운관, 노악관 (Sangju)</td>\\n<td>693.100 won</td>\\n<td>1.111.800 won</td>\\n</tr>\\n</tbody></table></div>\\n<p>Được chọn số bữa: Daegu 0–3 bữa/ngày, Sangju 1–3 bữa/ngày. Du học sinh năm nhất được ưu tiên xếp phòng nhưng không được bảo đảm chỗ.</p>\\n<h2 id=\\"truong-tieng\\">Trường tiếng (어학당)</h2>\\n<p>Trường có 한국어연수과정 (khoá tiếng Hàn) thuộc 언어교육센터.</p>\\n<ul>\\n<li>4 kỳ/năm, mỗi kỳ 10 tuần, 200 giờ. Học 5 ngày/tuần, 4 giờ/ngày.</li>\\n<li>6 cấp, tối đa 15 người/lớp.</li>\\n<li>Phí xét tuyển: 70.000 won. Học phí: 1.400.000 won/kỳ từ năm 2026. Giáo trình, bảo hiểm tính riêng.</li>\\n<li>Người Việt có đợt nhận hồ sơ riêng, xem lịch trên lang.knu.ac.kr.</li>\\n</ul>\\n<p>Hoàn thành cấp 3 được tính đủ điều kiện tiếng cho phần lớn các ngành. Học viên đang học phải xong cấp 3 trước 13/11/2026 để nộp kỳ tháng 3/2027.</p>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://home.knu.ac.kr/HOME/old_data/download/global/2027%20%EB%8C%80%ED%95%99%20%EC%99%B8%EA%B5%AD%EC%9D%B8%20%ED%8A%B9%EB%B3%84%EC%A0%84%ED%98%95%20%EB%AA%A8%EC%A7%91%EC%9A%94%EA%B0%95%20-%20%EA%B5%AD%EB%AC%B8(%EC%9B%B9%EC%9A%A9).pdf\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Kyungpook — 2027학년도 대학 외국인 특별전형 모집요강 (tiếng Hàn, PDF)</a> <span class=\\"source-domain\\">home.knu.ac.kr</span></li>\\n<li><a href=\\"https://home.knu.ac.kr/HOME/global/sub.htm?nav_code=glo1738646172\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Kyungpook — Tuyển sinh hệ đại học cho người nước ngoài (các bản ngôn ngữ, có tiếng Việt)</a> <span class=\\"source-domain\\">home.knu.ac.kr</span></li>\\n<li><a href=\\"https://home.knu.ac.kr/HOME/global/sub.htm?nav_code=glo1730012177\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Kyungpook — Học bổng hệ đại học</a> <span class=\\"source-domain\\">home.knu.ac.kr</span></li>\\n<li><a href=\\"https://dorm.knu.ac.kr\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Kyungpook — Ký túc xá cơ sở Daegu</a> <span class=\\"source-domain\\">dorm.knu.ac.kr</span></li>\\n<li><a href=\\"https://en.knu.ac.kr/admission/korean01.htm\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Kyungpook — Korean Language Program</a> <span class=\\"source-domain\\">en.knu.ac.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/bbs/immigration/214/490761/download.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 — Thông cáo báo chí kết quả chứng nhận năng lực quốc tế hoá 2025 (12/2/2026, PDF)</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n<li><a href=\\"https://kstudytimes.kr/universities/kyungpook-national/foreign-students\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">K-Study Times — Du học sinh tại Đại học Kyungpook (số liệu 법무부, 31/12/2025)</a> <span class=\\"source-domain\\">kstudytimes.kr</span></li>\\n</ul>","headings":[{"id":"tong-quan","text":"Tổng quan","level":2},{"id":"tuyen-sinh-sinh-vien-quoc-te","text":"Tuyển sinh sinh viên quốc tế","level":2},{"id":"hoc-phi-va-hoc-bong","text":"Học phí và học bổng","level":2},{"id":"ky-tuc-xa","text":"Ký túc xá","level":2},{"id":"truong-tieng","text":"Trường tiếng (어학당)","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":0},{"slug":"dai-hoc-soongsil","title":"Đại học Soongsil (숭실대학교)","summary":"Điều kiện tiếng, lịch tuyển sinh kỳ 3/2027, học phí, học bổng theo TOPIK và trường tiếng của Đại học Soongsil cho sinh viên quốc tế hệ đại học.","updated":"2026-09-25","facts":{"nameKo":"숭실대학교","city":"Seoul","kind":"Tư thục","certified":"Có","topik":"Cấp 3 (chuyên ngành 영화예술: cấp 4)","tuition":"4,9–7,1 triệu won/học kỳ (kỳ 3/2027)","languageSchool":"Có","website":"https://iphak.ssu.ac.kr"},"html":"<h2 id=\\"tong-quan\\">Tổng quan</h2>\\n<p>Đại học tư thục ở quận Dongjak, Seoul. Trường thành lập trên nền tảng Cơ đốc giáo. Mọi sinh viên phải học các môn Cơ đốc giáo và dự chapel theo quy định.</p>\\n<p>Theo số liệu của Viện Phát triển Giáo dục Hàn Quốc (KEDI) ngày 1/4/2025, Soongsil có 1.892 du học sinh Đông Nam Á, đứng thứ 5 cả nước và nhiều nhất trong các trường ở Seoul. Trong số du học sinh Đông Nam Á ở Hàn, 83,5% là người Việt.</p>\\n<p>Trường đạt chứng nhận 교육국제화역량 인증제 (chứng nhận năng lực quốc tế hoá) năm 2025 cho cả hệ đại học và hệ học tiếng. Danh sách do 교육부 và 법무부 công bố ngày 12/2/2026.</p>\\n<h2 id=\\"tuyen-sinh-sinh-vien-quoc-te\\">Tuyển sinh sinh viên quốc tế</h2>\\n<p>Diện dành cho người nước ngoài: 순수외국인 특별전형. Thí sinh và bố mẹ đều phải là người nước ngoài. Không nhận người hai quốc tịch có quốc tịch Hàn. Không nhận học tại nhà, GED, học online.</p>\\n<p>Kỳ nhập học 3/2027 chia 3 đợt:</p>\\n<ul>\\n<li>Đợt 1: nộp online 12–16/10/2026, gửi hồ sơ đến hạn 23/10/2026, kết quả 19/11/2026.</li>\\n<li>Đợt 2: nộp online 23–27/11/2026, gửi hồ sơ đến hạn 4/12/2026, kết quả 4/1/2027.</li>\\n<li>Đợt 3: nộp online 28–30/12/2026, gửi hồ sơ đến hạn 4/1/2027, kết quả 21/1/2027.</li>\\n</ul>\\n<p>Hồ sơ phải đến trường trước hạn, trễ là trượt. Lệ phí xét tuyển: 90.000 won. Xét 100% bằng hồ sơ. Riêng chuyên ngành 영화예술 (Nghệ thuật điện ảnh) xét 40% hồ sơ và 60% phỏng vấn.</p>\\n<p>Điều kiện tiếng: có MỘT trong các giấy tờ sau.</p>\\n<ul>\\n<li>TOPIK 3 trở lên.</li>\\n<li>Hoàn thành cấp 3 khoá chính quy ở 한국어교육원 (Trung tâm tiếng Hàn) của trường.</li>\\n<li>Hoàn thành trung cấp 1 ở 세종학당 (Học viện King Sejong) tại nước ngoài. Khoá online không được tính.</li>\\n<li>Đỗ 숭실 한국어능력시험 (bài thi tiếng Hàn của trường): từ 60/100 điểm.</li>\\n</ul>\\n<p>Chuyên ngành 영화예술 cần TOPIK 4. Chứng nhận của trường tiếng phải là khoá học xong trong vòng 2 năm.</p>\\n<p>Bài thi tiếng Hàn của trường là thi nói online. Lệ phí 40.000 won. Đợt 1 đăng ký 28/9–1/10/2026, thi 7/10/2026. Đợt 2 thi 17/11/2026, đợt 3 thi 22/12/2026. Điểm chỉ dùng để nộp vào Soongsil.</p>\\n<p>Sau khi nhập học, mọi sinh viên quốc tế phải học các môn tiếng Hàn bắt buộc. Muốn tốt nghiệp phải có TOPIK 4.</p>\\n<p>Người đỗ nộp giấy xác nhận số dư từ 20 triệu won. Học viên D-4 ở 한국어교육원 của trường chuyển sang D-2 chỉ cần 10 triệu won.</p>\\n<h2 id=\\"hoc-phi-va-hoc-bong\\">Học phí và học bổng</h2>\\n<p>Học phí học kỳ nhập học 3/2027 (có thể thay đổi):</p>\\n<ul>\\n<li>Phần lớn ngành nhân văn, luật, xã hội, kinh tế, quản trị kinh doanh: 4.892.000 won.</li>\\n<li>Toán, thống kê, kế toán, thông tin xã hội, báo chí: 5.501.000 won.</li>\\n<li>Vật lý, hoá học, hệ thống y sinh, thể thao: 5.878.000 won.</li>\\n<li>Kỹ thuật và IT: 6.393.000 won.</li>\\n<li>Tài chính, luật quốc tế, phần mềm AI: 6.509.000 won.</li>\\n<li>영화예술: 7.084.000 won.</li>\\n</ul>\\n<p>Chưa gồm bảo hiểm và phí hội sinh viên.</p>\\n<p>Học bổng đầu vào, chỉ áp dụng học kỳ đầu, không cộng dồn:</p>\\n<ul>\\n<li>TOPIK 6: giảm 100% học phí.</li>\\n<li>TOPIK 5: giảm 80%.</li>\\n<li>TOPIK 4: giảm 60%.</li>\\n<li>TOPIK 3: giảm 40%.</li>\\n<li>Điểm cao trong bài thi tiếng Hàn của trường: giảm 30%.</li>\\n<li>Hoàn thành cấp 4 trở lên ở 한국어교육원 của trường: giảm 40%.</li>\\n</ul>\\n<p>Có điểm TOPIK mới sau khi nộp hồ sơ thì nộp bổ sung 21–23/12/2026 để xét học bổng.</p>\\n<p>Từ học kỳ 2, học bổng xét theo GPA kỳ trước (học từ 12 tín chỉ). Phải có TOPIK 4 mới được xét:</p>\\n<ul>\\n<li>GPA từ 3.8: giảm 50%.</li>\\n<li>GPA 3.5 đến dưới 3.8: giảm 40%.</li>\\n<li>GPA 3.0 đến dưới 3.5: giảm 20%.</li>\\n</ul>\\n<p>Ai đạt TOPIK 5 trở lên khi đang học nhận thêm 200.000 won, một lần. Không áp dụng nếu đã nhận học bổng đầu vào nhờ TOPIK 5 trở lên.</p>\\n<h2 id=\\"ky-tuc-xa\\">Ký túc xá</h2>\\n<p>Theo hướng dẫn tuyển sinh kỳ 3/2027:</p>\\n<ul>\\n<li>레지던스홀 (trong trường), phòng 2 người: khoảng 1.400.000 won/16 tuần, khoảng 2.100.000 won/25 tuần.</li>\\n<li>세원빌라 (ngoài trường, chỉ cho nữ), nhà 4 người: khoảng 1.650.000 won/16 tuần.</li>\\n</ul>\\n<p>Lịch đăng ký thông báo khi có kết quả tuyển sinh.</p>\\n<h2 id=\\"truong-tieng\\">Trường tiếng (어학당)</h2>\\n<p>Trường có 숭실대학교 한국어교육원.</p>\\n<ul>\\n<li>Khoá chính quy: 4 kỳ/năm, mỗi kỳ 200 giờ.</li>\\n<li>Cấp 1–2 học chiều (13:30–17:30), cấp 3–6 học sáng (9:00–13:00), thứ Hai đến thứ Sáu.</li>\\n<li>Lớp khoảng 15 người.</li>\\n<li>Học phí: 1.600.000 won/kỳ.</li>\\n<li>Kỳ đông 2026: học 7/12/2026–18/2/2027, nhận hồ sơ 1–20/10/2026.</li>\\n<li>Kỳ xuân 2027: học 8/3–18/5/2027, nhận hồ sơ 1–20/1/2027.</li>\\n</ul>\\n<p>Học xong cấp 3 ở đây là đủ điều kiện tiếng khi nộp vào đại học.</p>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://iphak.ssu.ac.kr/upload/SSU(1)_26090184026.pdf\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Soongsil — 2027학년도 1학기 순수외국인 특별전형 신·편입학 모집요강 (tiếng Hàn, PDF)</a> <span class=\\"source-domain\\">iphak.ssu.ac.kr</span></li>\\n<li><a href=\\"https://iphak.ssu.ac.kr/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Soongsil 입학처 — Trang tuyển sinh</a> <span class=\\"source-domain\\">iphak.ssu.ac.kr</span></li>\\n<li><a href=\\"https://language.ssu.ac.kr/app/html/dep_02/2100.php\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">숭실대학교 한국어교육원 — Khoá chính quy</a> <span class=\\"source-domain\\">language.ssu.ac.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/bbs/immigration/214/490761/download.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 — Thông cáo báo chí kết quả chứng nhận năng lực quốc tế hoá 2025 (12/2/2026, PDF)</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n<li><a href=\\"https://www.asiatoday.co.kr/kn/view.php?key=20260405010001321\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Asia Today — Du học sinh 300.000: từ Trung Quốc sang Đông Nam Á, người Việt tăng mạnh (5/4/2026)</a> <span class=\\"source-domain\\">asiatoday.co.kr</span></li>\\n</ul>","headings":[{"id":"tong-quan","text":"Tổng quan","level":2},{"id":"tuyen-sinh-sinh-vien-quoc-te","text":"Tuyển sinh sinh viên quốc tế","level":2},{"id":"hoc-phi-va-hoc-bong","text":"Học phí và học bổng","level":2},{"id":"ky-tuc-xa","text":"Ký túc xá","level":2},{"id":"truong-tieng","text":"Trường tiếng (어학당)","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":0}],"viec-lam":[{"slug":"lao-dong-eps-e-9","title":"Đi làm theo chương trình EPS (visa E-9)","summary":"Quy trình đi Hàn làm việc theo 고용허가제 từ Việt Nam, thời hạn làm việc và điều kiện đổi nơi làm.","updated":"2026-09-25","facts":{"group":"Trước khi sang Hàn"},"html":"<h2 id=\\"eps-la-gi\\">EPS là gì</h2>\\n<p>EPS (고용허가제, Chế độ cấp phép việc làm) là chương trình của Chính phủ Hàn Quốc tuyển lao động phổ thông nước ngoài. Người đi theo EPS nhận visa E-9 (비전문취업, lao động không chuyên môn).</p>\\n<p>Ở Việt Nam, chương trình do <strong>Trung tâm Lao động ngoài nước</strong> (thuộc Bộ Nội vụ) phối hợp với 한국산업인력공단 (HRD Korea, Cơ quan phát triển nguồn nhân lực Hàn Quốc) thực hiện. Đây là đơn vị duy nhất được giao làm EPS. Không có công ty môi giới nào &quot;lo&quot; được suất EPS.</p>\\n<h2 id=\\"cac-nganh-duoc-tuyen\\">Các ngành được tuyển</h2>\\n<p>Theo hệ thống EPS, các ngành được nhận lao động E-9 gồm: sản xuất (제조업), xây dựng (건설업), nông nghiệp – chăn nuôi (농축산업), ngư nghiệp (어업), dịch vụ (서비스업), lâm nghiệp (임업), khai khoáng (광업).</p>\\n<p>Năm 2026 không phải năm nào ngành nào cũng mở tuyển cho Việt Nam. Theo thông báo của Trung tâm Lao động ngoài nước, kế hoạch năm 2026 tuyển <strong>4.200 người</strong>:</p>\\n<ul>\\n<li>Sản xuất: 3.000</li>\\n<li>Ngư nghiệp: 1.000</li>\\n<li>Lâm nghiệp: 150</li>\\n<li>Dịch vụ: 50</li>\\n</ul>\\n<p>Tổng hạn ngạch E-9 của Hàn Quốc năm 2026 là 80.000 người, giảm so với 130.000 người năm 2025.</p>\\n<h2 id=\\"dieu-kien-du-tuyen-nam-2026\\">Điều kiện dự tuyển (năm 2026)</h2>\\n<p>Theo thông báo tuyển chọn năm 2026:</p>\\n<ul>\\n<li>Tuổi từ 18 đến 39.</li>\\n<li>Không có tiền án bị phạt tù hoặc hình phạt nặng hơn.</li>\\n<li>Chưa từng bị trục xuất khỏi Hàn Quốc.</li>\\n<li>Nếu từng ở Hàn bằng visa E-9 hoặc E-10 thì tổng thời gian dưới 5 năm.</li>\\n<li>Không bị cấm xuất cảnh Việt Nam.</li>\\n<li>Không có người thân (theo quy định) đang cư trú bất hợp pháp tại Hàn.</li>\\n<li>Đủ sức khỏe, không mù màu, không dị tật cột sống nặng.</li>\\n</ul>\\n<p>Một số ngành có điều kiện thêm:</p>\\n<ul>\\n<li><strong>Ngư nghiệp</strong>: sống ở vùng ven biển và có kinh nghiệm đi biển, hoặc có chứng chỉ đào tạo nghề cá/nuôi trồng thủy sản, hoặc đã từng làm ngư nghiệp theo EPS.</li>\\n<li><strong>Lâm nghiệp, dịch vụ</strong>: thường trú tại thôn, xã thuộc vùng đồng bào dân tộc thiểu số và miền núi.</li>\\n</ul>\\n<p>Những năm trước, một số huyện có nhiều người lao động bỏ trốn, ở lại trái phép bị tạm dừng tuyển. Thông báo năm 2026 trên trang Trung tâm Lao động ngoài nước không nêu danh sách địa phương bị dừng. Trước mỗi đợt, hãy đọc thông báo chính thức mới nhất để chắc địa phương mình được đăng ký.</p>\\n<h2 id=\\"quy-trinh-tu-viet-nam\\">Quy trình từ Việt Nam</h2>\\n<ol>\\n<li><strong>Theo dõi thông báo</strong> trên trang Trung tâm Lao động ngoài nước (colab.gov.vn). Thông báo cũng gửi về Sở Nội vụ các tỉnh.</li>\\n<li><strong>Đăng ký dự thi</strong> trực tiếp tại địa điểm tiếp nhận ghi trong thông báo. Hồ sơ gồm bản sao căn cước, 2 ảnh 3,5×4,5 cm, phiếu đăng ký. Lệ phí thi năm 2026: tương đương 28 USD.</li>\\n<li><strong>Vòng 1 – thi tiếng Hàn EPS-TOPIK</strong> trên máy tính: nghe và đọc, 40 câu, 50 phút, tối đa 200 điểm.</li>\\n<li><strong>Vòng 2 – kiểm tra tay nghề</strong> (bắt buộc) và đánh giá năng lực (tùy chọn). Chỉ người đạt vòng 1 mới vào vòng 2.</li>\\n<li><strong>Nộp hồ sơ dự tuyển</strong>. Người đạt cả hai vòng được đưa vào danh sách để chủ sử dụng Hàn Quốc chọn. Đạt thi <strong>không</strong> có nghĩa chắc chắn được chọn.</li>\\n<li><strong>Ký hợp đồng lao động</strong> (근로계약) khi được chủ chọn, sau đó làm thủ tục visa và học định hướng trước khi đi.</li>\\n<li><strong>Nhập cảnh và học 취업교육</strong> (đào tạo đầu vào) tại Hàn trước khi về công ty.</li>\\n</ol>\\n<p>Lịch năm 2026 (theo thông báo): ngành ngư nghiệp, lâm nghiệp, dịch vụ đăng ký 23–27/3/2026; ngành sản xuất đăng ký 22/6–21/8/2026, thi vòng 1 từ 12–16/10/2026.</p>\\n<h2 id=\\"thoi-han-lam-viec\\">Thời hạn làm việc</h2>\\n<ul>\\n<li>Thời hạn làm việc ban đầu (취업활동 기간): <strong>3 năm</strong>.</li>\\n<li>Nếu chủ sử dụng xin 재고용 허가 (cấp phép tuyển dụng lại) và được Bộ Việc làm và Lao động Hàn Quốc chấp thuận: làm thêm <strong>1 năm 10 tháng</strong>.</li>\\n<li>Tổng tối đa một lần sang: <strong>4 năm 10 tháng</strong>.</li>\\n</ul>\\n<p>Người làm liên tục ở một nơi đến hết hạn có thể được xét 성실근로자 재입국 (tái nhập cảnh cho lao động chuyên cần): về nước một thời gian rồi quay lại làm cho chủ cũ. Điều kiện và thời gian phải ở ngoài Hàn đã được sửa nhiều lần. Hỏi 1577-0071 hoặc trung tâm việc làm (고용센터) trước khi về.</p>\\n<h2 id=\\"doi-noi-lam-viec\\">Đổi nơi làm việc</h2>\\n<p>E-9 không được tự ý nghỉ để sang chỗ khác. Chỉ được đổi (사업장 변경) khi có lý do theo luật, ví dụ:</p>\\n<ul>\\n<li>Chủ chấm dứt hợp đồng hoặc không gia hạn vì lý do chính đáng.</li>\\n<li>Công ty đóng cửa, bị thu hồi giấy phép tuyển lao động nước ngoài, hoặc chủ vi phạm điều kiện lao động.</li>\\n<li>Bị bệnh, chấn thương không làm tiếp được ở nơi cũ nhưng vẫn làm được nơi khác.</li>\\n</ul>\\n<p>Số lần đổi:</p>\\n<ul>\\n<li>Trong 3 năm đầu: tối đa <strong>3 lần</strong>.</li>\\n<li>Trong 1 năm 10 tháng tái tuyển dụng: tối đa <strong>2 lần</strong>.</li>\\n<li>Đổi vì lỗi của chủ thì không tính vào số lần.</li>\\n</ul>\\n<p>Hạn phải nhớ:</p>\\n<ul>\\n<li>Nộp đơn xin đổi tại 고용센터 trong <strong>1 tháng</strong> kể từ ngày hết hợp đồng.</li>\\n<li>Phải được phép đổi nơi làm (근무처 변경 허가) trong <strong>3 tháng</strong> kể từ khi nộp đơn.</li>\\n<li>Trễ một trong hai hạn: phải xuất cảnh.</li>\\n</ul>\\n<p>Theo chính sách công bố tháng 7/2023, việc đổi nơi làm chỉ được trong cùng khu vực (권역) và cùng ngành. Hỏi 고용센터 nơi mình ở để biết phạm vi cụ thể.</p>\\n<h2 id=\\"luu-y\\">Lưu ý</h2>\\n<ul>\\n<li>Chỉ tin thông báo từ Trung tâm Lao động ngoài nước và cơ quan nhà nước. Cơ quan này đã nhiều lần cảnh báo việc giả mạo Trung tâm để thu tiền.</li>\\n<li>Tư vấn cho lao động EPS tại Hàn: 외국인력상담센터 <strong>1577-0071</strong>, có tiếng Việt, 9:00–18:00.</li>\\n<li>Trung tâm Lao động ngoài nước: 024.7303.0199.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://colab.moha.gov.vn/tin-tuc/5396/THONG-BAO-KE-HOACH-TUYEN-CHON-NGUOI-LAO-DONG-DI-LAM-VIEC-TAI-HAN-QUOC-THEO-CHUONG-TRINH-EPS-NAM-2026.aspx\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Trung tâm Lao động ngoài nước — Thông báo kế hoạch tuyển chọn EPS năm 2026</a> <span class=\\"source-domain\\">colab.moha.gov.vn</span></li>\\n<li><a href=\\"https://colab.moha.gov.vn/tin-tuc/5353/MOT-SO-THONG-TIN-VE-CHUONG-TRINH-EPS-NAM-2026.aspx\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Trung tâm Lao động ngoài nước — Một số thông tin về chương trình EPS năm 2026</a> <span class=\\"source-domain\\">colab.moha.gov.vn</span></li>\\n<li><a href=\\"https://www.eps.go.kr/eo/EmployPerSystem.eo\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">EPS — Hệ thống quản lý tuyển dụng lao động nước ngoài</a> <span class=\\"source-domain\\">eps.go.kr</span></li>\\n<li><a href=\\"https://www.moel.go.kr/policyitrd/policyItrdView.do?policy_itrd_sn=248\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">고용노동부 — 외국인근로자 사업장 변경제도</a> <span class=\\"source-domain\\">moel.go.kr</span></li>\\n<li><a href=\\"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&amp;csmSeq=2042&amp;ccfNo=3&amp;cciNo=2&amp;cnpClsNo=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — 근무처(사업 또는 사업장) 변경</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://www.easylaw.go.kr/CSP/OnhunqueansInfoRetrieve.laf?onhunqnaAstSeq=82&amp;onhunqueSeq=6511&amp;search_put=\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — 취업활동 기간 연장(재고용)</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://www.korea.kr/news/policyNewsView.do?newsId=148917291\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">대한민국 정책브리핑 — 외국인근로자 사업장 변경, 일정 권역·업종 내에서만 허용</a> <span class=\\"source-domain\\">korea.kr</span></li>\\n<li><a href=\\"https://www.hrdkorea.or.kr/1/3/3/4\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">한국산업인력공단 — 외국인력상담센터</a> <span class=\\"source-domain\\">hrdkorea.or.kr</span></li>\\n</ul>","headings":[{"id":"eps-la-gi","text":"EPS là gì","level":2},{"id":"cac-nganh-duoc-tuyen","text":"Các ngành được tuyển","level":2},{"id":"dieu-kien-du-tuyen-nam-2026","text":"Điều kiện dự tuyển (năm 2026)","level":2},{"id":"quy-trinh-tu-viet-nam","text":"Quy trình từ Việt Nam","level":2},{"id":"thoi-han-lam-viec","text":"Thời hạn làm việc","level":2},{"id":"doi-noi-lam-viec","text":"Đổi nơi làm việc","level":2},{"id":"luu-y","text":"Lưu ý","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":0},{"slug":"quyen-loi-nguoi-lao-dong","title":"Quyền lợi cơ bản của lao động nước ngoài","summary":"Lương tối thiểu, giờ làm, bảo hiểm, trợ cấp thôi việc và cách đòi lương bị nợ khi làm việc ở Hàn Quốc.","updated":"2026-09-25","facts":{"group":"Đang làm việc"},"html":"<h2 id=\\"nguyen-tac-chung\\">Nguyên tắc chung</h2>\\n<p>Luật lao động Hàn Quốc (근로기준법, Luật Tiêu chuẩn lao động) áp dụng như nhau cho người Hàn và người nước ngoài. Quốc tịch hay loại visa không làm mất quyền được trả lương cho phần việc đã làm.</p>\\n<h2 id=\\"luong-toi-thieu\\">Lương tối thiểu (최저임금)</h2>\\n<ul>\\n<li><strong>Năm 2026</strong>: 10.320 won/giờ. Quy ra tháng (209 giờ, đã gồm ngày nghỉ có lương hằng tuần): 2.156.880 won.</li>\\n<li><strong>Năm 2027</strong> (đã công bố ngày 5/8/2026, áp dụng từ 1/1/2027): 10.700 won/giờ, tháng 2.236.300 won.</li>\\n<li>Mức này áp dụng chung cho mọi ngành, mọi loại công ty.</li>\\n</ul>\\n<p>Lương ghi trong hợp đồng thấp hơn mức này thì phần thấp hơn vô hiệu. Giữ lại hợp đồng lao động (근로계약서) và bảng lương (임금명세서) hằng tháng.</p>\\n<h2 id=\\"gio-lam-va-lam-them\\">Giờ làm và làm thêm</h2>\\n<p>Theo 근로기준법:</p>\\n<ul>\\n<li>Giờ làm chuẩn: tối đa 8 giờ/ngày, 40 giờ/tuần.</li>\\n<li>Làm thêm (연장근로): tối đa 12 giờ/tuần nếu hai bên đồng ý.</li>\\n<li>Làm thêm, làm đêm (22:00–06:00), làm ngày nghỉ: được trả thêm ít nhất 50% lương.</li>\\n<li>Nghỉ giữa giờ: làm 4 giờ được nghỉ ít nhất 30 phút; làm 8 giờ được nghỉ ít nhất 1 giờ.</li>\\n</ul>\\n<p>Hai ngoại lệ quan trọng với lao động E-9:</p>\\n<ul>\\n<li><strong>Nông nghiệp, chăn nuôi, thủy sản</strong>: các quy định về giờ làm, nghỉ giữa giờ, ngày nghỉ <strong>không áp dụng</strong> (근로기준법 제63조). Giờ làm phụ thuộc hợp đồng. Đọc kỹ hợp đồng trước khi ký.</li>\\n<li><strong>Nơi dưới 5 người</strong> làm thường xuyên: chủ không bắt buộc trả thêm 50% cho giờ làm thêm, làm đêm, làm ngày nghỉ. Lương tối thiểu và trợ cấp thôi việc vẫn phải trả.</li>\\n</ul>\\n<h2 id=\\"bon-loai-bao-hiem-xa-hoi-4\\">Bốn loại bảo hiểm xã hội (4대보험)</h2>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Bảo hiểm</th>\\n<th>Với lao động E-9</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>건강보험 (bảo hiểm y tế)</td>\\n<td>Tham gia qua công ty</td>\\n</tr>\\n<tr>\\n<td>산재보험 (bảo hiểm tai nạn lao động)</td>\\n<td>Chủ đóng, chi trả khi bị tai nạn, bệnh nghề nghiệp</td>\\n</tr>\\n<tr>\\n<td>고용보험 (bảo hiểm việc làm)</td>\\n<td>Bắt buộc với E-9, H-2 từ năm 2021–2023 (theo quy mô công ty). Phần trợ cấp thất nghiệp phải đăng ký riêng mới được hưởng</td>\\n</tr>\\n<tr>\\n<td>국민연금 (lương hưu quốc gia)</td>\\n<td>Đóng qua công ty, có thể xin nhận lại một lần khi về nước</td>\\n</tr>\\n</tbody></table></div>\\n<p>Bị tai nạn khi làm việc: đi khám, báo công ty và yêu cầu làm hồ sơ 산재. Công ty không làm thì liên hệ 근로복지공단 (Cơ quan phúc lợi lao động) hoặc gọi 1350.</p>\\n<h2 id=\\"bon-loai-bao-hiem-rieng-cho-lao-dong-e-9-h-2\\">Bốn loại bảo hiểm riêng cho lao động E-9, H-2</h2>\\n<p>Theo luật tuyển dụng lao động nước ngoài:</p>\\n<ul>\\n<li><strong>출국만기보험</strong> (bảo hiểm hết hạn xuất cảnh): chủ đóng hằng tháng 8,3% lương thông thường. Dùng để trả trợ cấp thôi việc.</li>\\n<li><strong>임금체불 보증보험</strong> (bảo hiểm bảo lãnh nợ lương): chủ đóng. Chi trả phần lương bị nợ trong hạn mức.</li>\\n<li><strong>귀국비용보험</strong> (bảo hiểm chi phí về nước): người lao động đóng trong 3 tháng đầu, 400.000–600.000 won tùy nước. Nhận lại khi về nước.</li>\\n<li><strong>상해보험</strong> (bảo hiểm thương tật): người lao động đóng trong 15 ngày đầu. Chi trả khi chết hoặc thương tật không do công việc.</li>\\n</ul>\\n<p>Hai loại người lao động đóng thường được hướng dẫn làm ngay trong buổi đào tạo đầu vào (취업교육).</p>\\n<h2 id=\\"tro-cap-thoi-viec\\">Trợ cấp thôi việc (퇴직금)</h2>\\n<ul>\\n<li>Điều kiện: làm liên tục từ <strong>1 năm</strong> trở lên, trung bình từ 15 giờ/tuần trở lên.</li>\\n<li>Mức: mỗi năm làm việc ít nhất <strong>30 ngày lương bình quân</strong> (lương bình quân tính trên 3 tháng trước khi nghỉ).</li>\\n<li>Hạn trả: trong <strong>14 ngày</strong> kể từ ngày nghỉ việc.</li>\\n</ul>\\n<p>Với lao động E-9, H-2:</p>\\n<ul>\\n<li>Tiền 출국만기보험 được trả trong <strong>14 ngày sau khi xuất cảnh</strong> (không phải lúc nghỉ việc). Quy định này để hạn chế việc nhận tiền rồi ở lại trái phép.</li>\\n<li>Bảo hiểm tính theo lương thông thường, nên có thể thấp hơn 퇴직금 thật. Chủ phải trả <strong>phần chênh lệch</strong>.</li>\\n</ul>\\n<h2 id=\\"bi-no-luong-thi-lam-gi\\">Bị nợ lương thì làm gì</h2>\\n<ol>\\n<li><strong>Ghi lại bằng chứng</strong>: hợp đồng, bảng lương, sổ ngân hàng, bảng chấm công, ảnh chụp tin nhắn với chủ.</li>\\n<li><strong>Gọi tư vấn</strong>: 1350 (Bộ Việc làm và Lao động) hoặc 1577-0071 (có tiếng Việt).</li>\\n<li><strong>Nộp đơn khiếu nại</strong> (임금체불 진정): trực tuyến trên 노동포털 (labor.moel.go.kr) hoặc trực tiếp tại văn phòng lao động (지방고용노동관서) nơi công ty đặt trụ sở.</li>\\n<li><strong>Xin 대지급금</strong> (tiền Nhà nước trả thay): nếu chủ không trả, 근로복지공단 có thể trả thay một phần trong hạn mức luật định, sau đó đòi lại chủ.</li>\\n</ol>\\n<p>Nợ lương là lý do được đổi nơi làm việc mà không tính vào số lần đổi (xem bài EPS).</p>\\n<h2 id=\\"so-dien-thoai-can-luu\\">Số điện thoại cần lưu</h2>\\n<ul>\\n<li><strong>1350</strong>: Trung tâm tư vấn của Bộ Việc làm và Lao động (고용노동부 고객상담센터).</li>\\n<li><strong>1577-0071</strong>: 외국인력상담센터 (Trung tâm tư vấn nhân lực nước ngoài), 18 ngôn ngữ gồm tiếng Việt, 9:00–18:00, cả ngày nghỉ.</li>\\n<li><strong>1345</strong>: Tổng đài xuất nhập cảnh (visa, lưu trú).</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://www.moel.go.kr/news/enews/report/enewsView.do?news_seq=18144\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">고용노동부 — 2026년 적용 최저임금 시간급 10,320원</a> <span class=\\"source-domain\\">moel.go.kr</span></li>\\n<li><a href=\\"https://www.moel.go.kr/news/enews/report/enewsView.do?news_seq=19744\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">고용노동부 — 2027년도 적용 최저임금 시간급 10,700원</a> <span class=\\"source-domain\\">moel.go.kr</span></li>\\n<li><a href=\\"https://www.minimumwage.go.kr/customer/notice/view.do?bultnId=4657\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">최저임금위원회 — 2026년 적용 최저임금 고시</a> <span class=\\"source-domain\\">minimumwage.go.kr</span></li>\\n<li><a href=\\"https://www.law.go.kr/lsLawLinkInfo.do?lsJoLnkSeq=1012317909&amp;chrClsCd=010202&amp;ancYnChk=0\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국가법령정보센터 — 근로기준법 제63조 (적용의 제외)</a> <span class=\\"source-domain\\">law.go.kr</span></li>\\n<li><a href=\\"https://1350.moel.go.kr/rtmview.do?id=1000000868\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">고용노동부 1350 — 5인 미만 사업장 적용 규정</a> <span class=\\"source-domain\\">1350.moel.go.kr</span></li>\\n<li><a href=\\"https://www.moel.go.kr/local/tongyeong/news/notice/noticeView.do?bbs_seq=20201200983\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">고용노동부 — 고용보험법 개정에 따른 외국인 근로자(E-9, H-2) 고용보험 적용 안내</a> <span class=\\"source-domain\\">moel.go.kr</span></li>\\n<li><a href=\\"https://eps.hrdkorea.or.kr/e9/user/intro/intro.do?method=epsInsurances\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">HRD Korea EPS — 고용허가제 4대 보험안내</a> <span class=\\"source-domain\\">eps.hrdkorea.or.kr</span></li>\\n<li><a href=\\"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&amp;csmSeq=2042&amp;ccfNo=3&amp;cciNo=1&amp;cnpClsNo=3\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — 외국인근로자 전용보험</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&amp;csmSeq=999&amp;ccfNo=3&amp;cciNo=2&amp;cnpClsNo=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — 퇴직금 지급</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://www.korea.kr/news/policyNewsView.do?newsId=148781107\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">대한민국 정책브리핑 — 외국인근로자 출국만기보험 지급시기</a> <span class=\\"source-domain\\">korea.kr</span></li>\\n<li><a href=\\"https://labor.moel.go.kr/minwonSysInfo/wagesolway.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">고용노동부 노동포털 — 체불임금 해결 방법</a> <span class=\\"source-domain\\">labor.moel.go.kr</span></li>\\n<li><a href=\\"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&amp;csmSeq=1694&amp;ccfNo=3&amp;cciNo=3&amp;cnpClsNo=2\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — 대지급금의 청구 및 지급</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://www.hrdkorea.or.kr/1/3/3/4\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">한국산업인력공단 — 외국인력상담센터</a> <span class=\\"source-domain\\">hrdkorea.or.kr</span></li>\\n</ul>","headings":[{"id":"nguyen-tac-chung","text":"Nguyên tắc chung","level":2},{"id":"luong-toi-thieu","text":"Lương tối thiểu (최저임금)","level":2},{"id":"gio-lam-va-lam-them","text":"Giờ làm và làm thêm","level":2},{"id":"bon-loai-bao-hiem-xa-hoi-4","text":"Bốn loại bảo hiểm xã hội (4대보험)","level":2},{"id":"bon-loai-bao-hiem-rieng-cho-lao-dong-e-9-h-2","text":"Bốn loại bảo hiểm riêng cho lao động E-9, H-2","level":2},{"id":"tro-cap-thoi-viec","text":"Trợ cấp thôi việc (퇴직금)","level":2},{"id":"bi-no-luong-thi-lam-gi","text":"Bị nợ lương thì làm gì","level":2},{"id":"so-dien-thoai-can-luu","text":"Số điện thoại cần lưu","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":0},{"slug":"tim-viec-an-toan","title":"Tìm việc an toàn ở Hàn Quốc","summary":"Biết visa của mình được làm việc gì, tìm việc qua kênh chính thức và tránh bẫy môi giới, làm việc trái phép.","updated":"2026-09-25","facts":{"group":"Trước khi sang Hàn"},"html":"<h2 id=\\"visa-quyet-dinh-ban-duoc-lam-gi\\">Visa quyết định bạn được làm gì</h2>\\n<p>Ở Hàn Quốc, người nước ngoài chỉ được đi làm khi visa (체류자격, tư cách lưu trú) cho phép. Làm sai loại việc so với visa cũng là làm việc trái phép, dù có hợp đồng.</p>\\n<p>Các visa người Việt hay gặp:</p>\\n<ul>\\n<li><strong>E-9</strong> (비전문취업, lao động phổ thông theo EPS): chỉ làm ở nơi đã được cấp phép, đúng ngành. Muốn đổi nơi làm phải qua 고용센터 (trung tâm việc làm). Xem bài về EPS.</li>\\n<li><strong>D-2</strong> (du học) và <strong>D-4</strong> (học tiếng): về nguyên tắc không được đi làm. Muốn làm thêm (아르바이트) phải xin <strong>phép trước</strong> tại cơ quan xuất nhập cảnh (체류자격외 활동허가, giấy phép hoạt động ngoài tư cách lưu trú). Năm 2026: sinh viên đại học đạt mức tiếng Hàn được làm tối đa 25 giờ/tuần ngày thường, thạc sĩ, tiến sĩ 30 giờ; D-4 tối đa 20 giờ/tuần. Chi tiết và ngoại lệ: xem bài Làm thêm hợp pháp cho du học sinh.</li>\\n<li><strong>D-10</strong> (구직, tìm việc): dành cho người tìm việc chuyên môn (nhóm E-1 đến E-7). Được tìm việc và thực tập ngắn hạn. Làm thêm cũng phải xin phép như trên.</li>\\n<li><strong>E-7</strong> (특정활동, hoạt động đặc định): việc chuyên môn, kỹ thuật cho đúng công ty và đúng nghề đã được cấp. Đổi công ty phải xin phép trước.</li>\\n<li><strong>F-2</strong> (거주, cư trú), <strong>F-5</strong> (영주, vĩnh trú), <strong>F-6</strong> (결혼이민, kết hôn): theo 출입국관리법 시행령 (Nghị định thi hành Luật Xuất nhập cảnh), F-5 và F-6 không bị giới hạn ngành nghề. F-2 phần lớn cũng vậy nhưng tùy loại F-2 cụ thể.</li>\\n</ul>\\n<p>Không chắc visa mình được làm gì: gọi <strong>1345</strong> (có tiếng Việt) hoặc xem hikorea.go.kr.</p>\\n<h2 id=\\"kenh-tim-viec-chinh-thuc\\">Kênh tìm việc chính thức</h2>\\n<ul>\\n<li><strong>Lao động E-9 từ Việt Nam</strong>: chỉ qua Trung tâm Lao động ngoài nước (colab.gov.vn). Đây là đơn vị duy nhất được giao làm chương trình EPS ở Việt Nam.</li>\\n<li><strong>Đang ở Hàn, có E-9 và cần đổi nơi làm</strong>: qua 고용센터 và hệ thống EPS (eps.go.kr). Hỗ trợ tiếng Việt: 1577-0071.</li>\\n<li><strong>고용24</strong> (work24.go.kr): cổng việc làm của Chính phủ Hàn Quốc. Từ năm 2024, 워크넷 (WorkNet) và các dịch vụ việc làm cũ đã gộp vào đây.</li>\\n<li><strong>Du học sinh</strong>: phòng hỗ trợ sinh viên quốc tế và trung tâm việc làm của trường.</li>\\n</ul>\\n<p>Việc có thật vẫn cần kiểm tra: tên công ty, địa chỉ, hợp đồng bằng văn bản ghi rõ lương, giờ làm, nơi làm.</p>\\n<h2 id=\\"dau-hieu-lua-dao-moi-gioi\\">Dấu hiệu lừa đảo môi giới</h2>\\n<p>Cẩn thận khi gặp các dấu hiệu sau:</p>\\n<ul>\\n<li>Hứa &quot;bao đậu&quot;, &quot;đi nhanh không cần thi&quot; cho chương trình EPS. EPS bắt buộc thi tiếng Hàn và kiểm tra tay nghề, không ai lo được suất.</li>\\n<li>Tự xưng là Trung tâm Lao động ngoài nước hoặc &quot;liên kết&quot; với Trung tâm qua Facebook, Zalo. Trung tâm đã nhiều lần cảnh báo việc giả mạo này.</li>\\n<li>Thu tiền đặt cọc, &quot;phí giữ chỗ&quot; trước khi có hợp đồng.</li>\\n<li>Đòi giữ hộ chiếu, thẻ người nước ngoài (외국인등록증).</li>\\n<li>Việc &quot;lương cao, không cần visa lao động&quot;, hoặc bảo bạn sang bằng visa du lịch, visa học rồi đi làm.</li>\\n<li>Không có hợp đồng, hoặc hợp đồng khác với lời hứa.</li>\\n<li>Chỉ liên lạc qua mạng xã hội, không có địa chỉ, không có giấy phép.</li>\\n</ul>\\n<p>Nghi ngờ: gọi Trung tâm Lao động ngoài nước (024.7303.0199) để hỏi trước khi nộp tiền. Ở Hàn thì gọi 1345 hoặc 1577-0071.</p>\\n<h2 id=\\"hau-qua-khi-lam-viec-trai-phep\\">Hậu quả khi làm việc trái phép</h2>\\n<p>Theo 출입국관리법 (Luật Quản lý xuất nhập cảnh):</p>\\n<ul>\\n<li>Làm việc khi visa không cho phép: có thể bị <strong>phạt tù đến 3 năm hoặc phạt tiền đến 30 triệu won</strong>.</li>\\n<li>Có thể bị trục xuất (강제퇴거) và bị cấm nhập cảnh lại một thời gian.</li>\\n<li>Chủ thuê người không có tư cách lao động cũng bị xử phạt.</li>\\n</ul>\\n<p>Hệ quả thực tế:</p>\\n<ul>\\n<li>Du học sinh làm thêm không phép có thể mất visa, không được gia hạn.</li>\\n<li>Lao động E-9 bỏ trốn khỏi nơi làm thành cư trú bất hợp pháp. Theo quy định tuyển chọn EPS năm 2026, người có người thân cư trú bất hợp pháp tại Hàn không được dự tuyển. Người bỏ trốn làm hại cả gia đình và địa phương mình.</li>\\n</ul>\\n<p>Dù làm trái phép, bạn vẫn có quyền đòi lương cho phần việc đã làm (xem bài quyền lợi người lao động).</p>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://www.law.go.kr/LSW/lsLinkCommonInfo.do?lspttninfSeq=82621&amp;chrClsCd=010202\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국가법령정보센터 — 출입국관리법 시행령</a> <span class=\\"source-domain\\">law.go.kr</span></li>\\n<li><a href=\\"http://www.law.go.kr/lsLawLinkInfo.do?lsJoLnkSeq=900535470&amp;chrClsCd=010202\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국가법령정보센터 — 출입국관리법 제18조 관련 조문</a> <span class=\\"source-domain\\">law.go.kr</span></li>\\n<li><a href=\\"https://www.hikorea.go.kr\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">HiKorea — Cổng dịch vụ xuất nhập cảnh</a> <span class=\\"source-domain\\">hikorea.go.kr</span></li>\\n<li><a href=\\"https://www.easylaw.go.kr/CSP/CnpClsMain.laf?csmSeq=47&amp;ccfNo=2&amp;cciNo=1&amp;cnpClsNo=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — 결혼에 따른 체류자격</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://www.easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&amp;csmSeq=508&amp;ccfNo=3&amp;cciNo=7&amp;cnpClsNo=1&amp;menuType=qna\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — 외국인유학생 아르바이트: 시간제 근로</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&amp;csmSeq=2853&amp;ccfNo=3&amp;cciNo=6&amp;cnpClsNo=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — 외국인유학생 시간제 취업 (sổ tay 법무부 bản 7/8/2026)</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://www.keis.or.kr/keis/ko/conts/101/web.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">한국고용정보원 — 디지털 고용서비스 고용24</a> <span class=\\"source-domain\\">keis.or.kr</span></li>\\n<li><a href=\\"https://m.work.go.kr/worknetServiceNotice.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">워크넷 — 서비스 종료 안내</a> <span class=\\"source-domain\\">m.work.go.kr</span></li>\\n<li><a href=\\"https://www.eps.go.kr/eo/EmployPerSystem.eo\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">EPS — Hệ thống quản lý tuyển dụng lao động nước ngoài</a> <span class=\\"source-domain\\">eps.go.kr</span></li>\\n<li><a href=\\"https://colab.moha.gov.vn/tin-tuc/5396/THONG-BAO-KE-HOACH-TUYEN-CHON-NGUOI-LAO-DONG-DI-LAM-VIEC-TAI-HAN-QUOC-THEO-CHUONG-TRINH-EPS-NAM-2026.aspx\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Trung tâm Lao động ngoài nước — Thông báo kế hoạch tuyển chọn EPS năm 2026</a> <span class=\\"source-domain\\">colab.moha.gov.vn</span></li>\\n<li><a href=\\"https://vieclam.camau.gov.vn/tin-tuc/canh-bao-lua-dao-dua-lao-dong-di-lam-viec-tai-han-quoc-theo-chuong-trinh-eps\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Cổng thông tin việc làm tỉnh Cà Mau — Cảnh báo lừa đảo đưa lao động đi làm việc tại Hàn Quốc theo Chương trình EPS</a> <span class=\\"source-domain\\">vieclam.camau.gov.vn</span></li>\\n</ul>","headings":[{"id":"visa-quyet-dinh-ban-duoc-lam-gi","text":"Visa quyết định bạn được làm gì","level":2},{"id":"kenh-tim-viec-chinh-thuc","text":"Kênh tìm việc chính thức","level":2},{"id":"dau-hieu-lua-dao-moi-gioi","text":"Dấu hiệu lừa đảo môi giới","level":2},{"id":"hau-qua-khi-lam-viec-trai-phep","text":"Hậu quả khi làm việc trái phép","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":0},{"slug":"lam-them-cho-du-hoc-sinh","title":"Làm thêm hợp pháp cho du học sinh (D-2, D-4)","summary":"Điều kiện, số giờ được làm mỗi tuần theo bậc học, ngành nghề bị cấm và cách xin giấy phép làm thêm (시간제취업 허가) trước khi đi làm.","updated":"2026-09-25","facts":{"group":"Đang làm việc"},"html":"<h2 id=\\"nguyen-tac\\">Nguyên tắc</h2>\\n<p>Du học sinh visa D-2 (du học) và D-4 (học tiếng) về nguyên tắc không được đi làm. Muốn làm thêm (아르바이트) phải có <strong>체류자격외 활동허가</strong> (giấy phép hoạt động ngoài tư cách lưu trú) do cơ quan xuất nhập cảnh cấp.</p>\\n<ul>\\n<li>Chỉ được bắt đầu làm <strong>sau khi có giấy phép</strong>. Đang chờ duyệt mà đi làm vẫn là làm việc không phép.</li>\\n<li>Mỗi lần đổi chủ (đổi nơi làm) phải xin phép lại trước khi làm ở chỗ mới.</li>\\n</ul>\\n<p>Số giờ và điều kiện dưới đây theo 『체류자격별 통합 안내 매뉴얼』 (sổ tay hướng dẫn theo tư cách lưu trú) của Bộ Tư pháp Hàn Quốc, bản ngày 7/8/2026. Bảng giờ làm áp dụng từ tháng 7/2023 và vẫn là quy định hiện hành.</p>\\n<h2 id=\\"ai-duoc-xin-phep\\">Ai được xin phép</h2>\\n<ul>\\n<li><strong>D-2</strong> hệ cao đẳng (전문학사), đại học, thạc sĩ, tiến sĩ (D-2-1 đến D-2-4, D-2-6, D-2-7): xin được ngay.</li>\\n<li><strong>D-4 học tiếng</strong> (D-4-1, D-4-7) và <strong>sinh viên trao đổi</strong> (D-2-8): phải ở Hàn đủ <strong>6 tháng</strong> tính từ ngày nhập cảnh hoặc ngày đổi sang tư cách này.</li>\\n<li>Đã hết thời gian học chuẩn (2 năm cao đẳng, 4 năm đại học) mà chưa tốt nghiệp vì thiếu tín chỉ: không được xin.</li>\\n</ul>\\n<p>Điều kiện chung (theo hướng dẫn của các trường):</p>\\n<ul>\\n<li>D-2: điểm trung bình học kỳ trước từ <strong>C (2.0)</strong> trở lên. Học kỳ đầu chưa có bảng điểm thì chưa xét điều kiện này.</li>\\n<li>D-4: tỉ lệ chuyên cần trung bình từ <strong>90%</strong> trở lên.</li>\\n<li>Có xác nhận của cán bộ phụ trách du học sinh ở trường.</li>\\n</ul>\\n<h2 id=\\"muc-tieng-han-can-co\\">Mức tiếng Hàn cần có</h2>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Bậc học</th>\\n<th>TOPIK</th>\\n<th>Hoặc KIIP (사회통합프로그램)</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>Học tiếng (D-4)</td>\\n<td>Cấp 2</td>\\n<td>Hoàn thành cấp 2, hoặc thi đầu vào từ 41 điểm</td>\\n</tr>\\n<tr>\\n<td>Cao đẳng, đại học năm 1–2</td>\\n<td>Cấp 3</td>\\n<td>Hoàn thành cấp 3, hoặc thi đầu vào từ 61 điểm</td>\\n</tr>\\n<tr>\\n<td>Đại học năm 3–4, thạc sĩ, tiến sĩ</td>\\n<td>Cấp 4</td>\\n<td>Hoàn thành cấp 4, hoặc thi đầu vào từ 81 điểm</td>\\n</tr>\\n</tbody></table></div>\\n<p>Chưa đạt mức này vẫn được xin, nhưng số giờ bị giới hạn thấp hơn (xem bảng dưới).</p>\\n<h2 id=\\"duoc-lam-bao-nhieu-gio-moi-tuan\\">Được làm bao nhiêu giờ mỗi tuần</h2>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Bậc học</th>\\n<th>Chưa đạt mức tiếng Hàn</th>\\n<th>Đã đạt: ngày thường</th>\\n<th>Đã đạt: cuối tuần, ngày lễ, kỳ nghỉ</th>\\n<th>Diện ưu đãi (ngày thường)</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>Học tiếng (D-4)</td>\\n<td>10 giờ</td>\\n<td>20 giờ</td>\\n<td>Tính chung trong 20 giờ</td>\\n<td>25 giờ</td>\\n</tr>\\n<tr>\\n<td>Cao đẳng, đại học</td>\\n<td>10 giờ</td>\\n<td>25 giờ</td>\\n<td>Không giới hạn</td>\\n<td>30 giờ</td>\\n</tr>\\n<tr>\\n<td>Thạc sĩ, tiến sĩ</td>\\n<td>15 giờ</td>\\n<td>30 giờ</td>\\n<td>Không giới hạn</td>\\n<td>35 giờ</td>\\n</tr>\\n</tbody></table></div>\\n<p>Cách hiểu bảng:</p>\\n<ul>\\n<li><strong>Chưa đạt mức tiếng Hàn</strong>: giới hạn tính cho cả tuần, gồm cả cuối tuần.</li>\\n<li><strong>D-4</strong>: không có quy định &quot;không giới hạn&quot; vào cuối tuần hay kỳ nghỉ.</li>\\n<li><strong>Diện ưu đãi</strong>: học ở trường được chứng nhận (인증대학), hoặc có thành tích học tập, tiếng Hàn tốt theo tiêu chí của Bộ Tư pháp. Hỏi trường xem mình có thuộc diện này không.</li>\\n<li>Làm nhiều nơi thì <strong>cộng giờ tất cả các nơi</strong> lại.</li>\\n<li>Người đang viết luận văn sau khi học xong thạc sĩ, tiến sĩ: tối đa 30 giờ/tuần, không có &quot;không giới hạn&quot; cuối tuần, kỳ nghỉ.</li>\\n</ul>\\n<p>Từ năm 2026, sinh viên 16 khoa &quot;육성형 전문기술학과&quot; (khoa kỹ thuật đào tạo nhân lực) được Bộ Tư pháp chỉ định thí điểm ở các trường cao đẳng, nếu có TOPIK cấp 3 trở lên, được làm đến 35 giờ/tuần thay vì 30 giờ.</p>\\n<p>Tháng 8/2026, Bộ Tư pháp nói đang xem xét nới lỏng quy định cho du học sinh giỏi tiếng Hàn. Đây mới là kế hoạch, chưa áp dụng.</p>\\n<h2 id=\\"viec-bi-cam\\">Việc bị cấm</h2>\\n<ul>\\n<li>Việc trái thuần phong mỹ tục, trật tự xã hội.</li>\\n<li>Việc chuyên môn thuộc nhóm E-1 đến E-7, ví dụ dạy hội thoại ngoại ngữ cho học sinh nhỏ tuổi.</li>\\n<li><strong>Xây dựng</strong>. <strong>Sản xuất</strong> (nhà máy) chỉ được làm nếu có tiếng Hàn từ cấp 4.</li>\\n<li>Việc làm như người lao động đặc thù: giao hàng, tài xế giao đồ ăn (배달대행), lái thay (대리기사), tư vấn bảo hiểm, bán hàng tận nhà.</li>\\n<li>Làm qua công ty phái cử, nhận thầu lại, môi giới. Người thuê bạn phải là chủ trực tiếp ký hợp đồng.</li>\\n<li>Nơi làm quá xa nơi ở, trường học. Theo hướng dẫn của các trường, khoảng cách hợp lý là trong 1 tiếng đi lại.</li>\\n<li>Chủ từng bị phạt vì thuê người trái phép.</li>\\n</ul>\\n<p>Một số việc không cần xin phép, ví dụ trợ giảng, làm ở thư viện trường theo diện 근로장학생 (sinh viên vừa học vừa làm) do trường trả tiền.</p>\\n<h2 id=\\"cach-xin-phep\\">Cách xin phép</h2>\\n<ol>\\n<li>Thỏa thuận với chủ, ký <strong>hợp đồng lao động chuẩn</strong> (표준근로계약서) ghi lương theo giờ, giờ làm, việc làm.</li>\\n<li>Mang giấy tờ đến phòng hỗ trợ du học sinh của trường để lấy <strong>외국인 유학생 시간제취업 확인서</strong> (giấy xác nhận làm thêm, có dấu của trường).</li>\\n<li>Nộp trực tuyến trên <strong>hikorea.go.kr</strong> (mục 전자민원) hoặc đặt lịch đến cơ quan xuất nhập cảnh.</li>\\n<li>Chờ có giấy phép rồi mới đi làm.</li>\\n</ol>\\n<p>Giấy tờ thường cần: đơn (통합신청서), hộ chiếu, 외국인등록증, bảng điểm, chứng nhận tiếng Hàn, giấy xác nhận của trường, bản sao hợp đồng, 사업자등록증 (đăng ký kinh doanh) và giấy tờ tùy thân của chủ.</p>\\n<p>Theo hướng dẫn các trường, giấy phép cho D-2 có hạn trong thời hạn lưu trú, tối đa 1 năm, tối đa 2 nơi làm. D-4 tối đa 6 tháng, 1 nơi làm.</p>\\n<h2 id=\\"lam-khong-phep-thi-sao\\">Làm không phép thì sao</h2>\\n<p>Theo 출입국관리법, làm việc ngoài tư cách lưu trú mà không có phép có thể bị <strong>phạt tù đến 3 năm hoặc phạt tiền đến 30 triệu won</strong>, bị khuyến cáo tự xuất cảnh hoặc bị trục xuất.</p>\\n<p>Theo hướng dẫn trường Đại học Kwangwoon học kỳ 1/2026:</p>\\n<ul>\\n<li>Lần 1: nộp tiền phạt và <strong>1 năm</strong> không được xin làm thêm.</li>\\n<li>Lần 2: hủy tư cách du học, phải xuất cảnh.</li>\\n<li>Làm ở <strong>công trường xây dựng</strong>: bị lệnh xuất cảnh ngay từ lần đầu.</li>\\n</ul>\\n<p>Có phép nhưng làm quá giờ, sai nơi cũng bị xử lý. Làm không phép vẫn được đòi lương cho phần đã làm (xem bài Quyền lợi người lao động). Không chắc việc mình định làm có được phép không: gọi <strong>1345</strong> (có tiếng Việt).</p>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&amp;csmSeq=2853&amp;ccfNo=3&amp;cciNo=6&amp;cnpClsNo=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — Du học sinh: làm thêm (trích sổ tay 법무부 bản 7/8/2026)</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://www.cju.ac.kr/intl/contents.do?key=8518\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">청주대학교 국제교류처 — 시간제 취업 (bảng giờ, D-4, giấy tờ, xử lý vi phạm)</a> <span class=\\"source-domain\\">cju.ac.kr</span></li>\\n<li><a href=\\"https://m.kw.ac.kr/ko/life/notice.jsp?BoardMode=view&amp;DUID=51943&amp;searchKey=1&amp;searchVal=&amp;srCategoryId=&amp;tpage=19\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">광운대학교 — 2026-1학기 외국인 유학생 시간제취업 허가 관련 안내</a> <span class=\\"source-domain\\">m.kw.ac.kr</span></li>\\n<li><a href=\\"https://www.corrections.go.kr/bbs/moj/182/490464/download.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 보도자료 — 전문대학 내 「육성형 전문기술학과」 16개 시범지정 (5/2/2026)</a> <span class=\\"source-domain\\">corrections.go.kr</span></li>\\n<li><a href=\\"https://www.etoday.co.kr/news/view/2618320\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">이투데이 — &quot;유학생 알바 규제 푼다&quot; (8/2026)</a> <span class=\\"source-domain\\">etoday.co.kr</span></li>\\n<li><a href=\\"https://www.hikorea.go.kr\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">HiKorea — Cổng dịch vụ xuất nhập cảnh</a> <span class=\\"source-domain\\">hikorea.go.kr</span></li>\\n</ul>","headings":[{"id":"nguyen-tac","text":"Nguyên tắc","level":2},{"id":"ai-duoc-xin-phep","text":"Ai được xin phép","level":2},{"id":"muc-tieng-han-can-co","text":"Mức tiếng Hàn cần có","level":2},{"id":"duoc-lam-bao-nhieu-gio-moi-tuan","text":"Được làm bao nhiêu giờ mỗi tuần","level":2},{"id":"viec-bi-cam","text":"Việc bị cấm","level":2},{"id":"cach-xin-phep","text":"Cách xin phép","level":2},{"id":"lam-khong-phep-thi-sao","text":"Làm không phép thì sao","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":0},{"slug":"phieu-luong-thue-va-quyet-toan","title":"Phiếu lương, thuế thu nhập và quyết toán thuế cuối năm","summary":"Đọc từng dòng trên phiếu lương, biết mình bị trừ bao nhiêu cho bảo hiểm và thuế, và làm quyết toán thuế (연말정산) để không mất tiền hoàn thuế.","updated":"2026-09-25","facts":{"group":"Đang làm việc"},"html":"<h2 id=\\"phieu-luong-la-quyen-cua-ban\\">Phiếu lương là quyền của bạn</h2>\\n<p>Từ ngày 19/11/2021, chủ phải đưa <strong>임금명세서</strong> (phiếu lương, còn gọi 급여명세서) mỗi lần trả lương (근로기준법 제48조). Có thể là giấy hoặc bản điện tử.</p>\\n<p>Phiếu lương phải ghi:</p>\\n<ul>\\n<li>Họ tên, ngày sinh hoặc mã nhân viên.</li>\\n<li>Ngày trả lương, tổng lương.</li>\\n<li>Số tiền từng khoản: lương cơ bản, phụ cấp, thưởng…</li>\\n<li>Cách tính các khoản thay đổi theo ngày công, giờ làm. Có làm thêm, làm đêm, làm ngày nghỉ thì phải ghi <strong>số giờ</strong>.</li>\\n<li>Từng khoản bị trừ và tổng số bị trừ.</li>\\n</ul>\\n<p>Chủ không đưa, hoặc ghi thiếu, ghi sai: bị phạt hành chính đến 5 triệu won.</p>\\n<h2 id=\\"phan-tien-duoc-nhan\\">Phần tiền được nhận (지급 내역)</h2>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Mục trên phiếu</th>\\n<th>Nghĩa</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>기본급</td>\\n<td>Lương cơ bản</td>\\n</tr>\\n<tr>\\n<td>연장근로수당</td>\\n<td>Tiền làm thêm giờ (quá 8 giờ/ngày, 40 giờ/tuần)</td>\\n</tr>\\n<tr>\\n<td>야간근로수당</td>\\n<td>Tiền làm đêm (22:00–06:00)</td>\\n</tr>\\n<tr>\\n<td>휴일근로수당</td>\\n<td>Tiền làm ngày nghỉ</td>\\n</tr>\\n<tr>\\n<td>주휴수당</td>\\n<td>Tiền ngày nghỉ có lương hằng tuần</td>\\n</tr>\\n<tr>\\n<td>상여금</td>\\n<td>Thưởng</td>\\n</tr>\\n<tr>\\n<td>식대</td>\\n<td>Tiền ăn</td>\\n</tr>\\n</tbody></table></div>\\n<p>Mức cộng thêm cho làm thêm, làm đêm, làm ngày nghỉ và các ngoại lệ (nông nghiệp, nơi dưới 5 người): xem bài Quyền lợi người lao động.</p>\\n<p>Tự kiểm tra: lấy số giờ trên phiếu nhân với mức lương giờ trong hợp đồng, so với số tiền ghi. Lệch mà chủ không giải thích được thì giữ phiếu lại làm bằng chứng.</p>\\n<h2 id=\\"phan-bi-tru\\">Phần bị trừ (공제 내역)</h2>\\n<p>Tỉ lệ phần người lao động đóng (năm 2026), tính trên lương tháng:</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Mục trên phiếu</th>\\n<th>Nghĩa</th>\\n<th>Người lao động đóng</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>국민연금</td>\\n<td>Lương hưu quốc gia</td>\\n<td>4,75% (tổng 9,5%, chủ đóng một nửa)</td>\\n</tr>\\n<tr>\\n<td>건강보험</td>\\n<td>Bảo hiểm y tế</td>\\n<td>3,595% (tổng 7,19%, chủ đóng một nửa)</td>\\n</tr>\\n<tr>\\n<td>장기요양보험</td>\\n<td>Bảo hiểm chăm sóc dài hạn</td>\\n<td>Tính bằng 13,14% số tiền 건강보험</td>\\n</tr>\\n<tr>\\n<td>고용보험</td>\\n<td>Bảo hiểm việc làm</td>\\n<td>0,9% (phần trợ cấp thất nghiệp)</td>\\n</tr>\\n<tr>\\n<td>소득세</td>\\n<td>Thuế thu nhập</td>\\n<td>Theo bảng khấu trừ của Cục Thuế</td>\\n</tr>\\n<tr>\\n<td>지방소득세</td>\\n<td>Thuế thu nhập địa phương</td>\\n<td>10% của số 소득세</td>\\n</tr>\\n</tbody></table></div>\\n<p>Không có dòng 산재보험 (bảo hiểm tai nạn lao động) vì chủ đóng toàn bộ.</p>\\n<p>Lưu ý:</p>\\n<ul>\\n<li>Tỉ lệ 국민연금 tăng 0,5 điểm % mỗi năm từ 2026 đến khi đạt 13% vào năm 2033.</li>\\n<li>Lao động <strong>E-9, H-2</strong> (và D-3) có thể xin <strong>không tham gia 장기요양보험</strong>: điền đơn 외국인근로자 장기요양보험 가입제외 신청서, đưa cho chủ nộp lên 국민건강보험공단. Nộp trong 14 ngày kể từ khi được đăng ký bảo hiểm y tế thì được miễn từ đầu.</li>\\n<li>Người Việt đi làm ở công ty tham gia 국민연금 phải đóng từ ngày 1/1/2022. Khoản này có thể được nhận lại khi về nước tùy loại visa (xem bài Trước khi về nước: nhận đủ các khoản tiền).</li>\\n</ul>\\n<h2 id=\\"thue-thu-nhap-hang-thang\\">Thuế thu nhập hằng tháng</h2>\\n<p>Mỗi tháng, công ty trừ trước 소득세 theo <strong>근로소득 간이세액표</strong> (bảng khấu trừ thuế tạm tính) và nộp thay bạn. Số này chỉ là tạm tính. Số thuế thật của cả năm được tính lại khi quyết toán.</p>\\n<h3 id=\\"chon-thue-suat-co-dinh-19\\">Chọn thuế suất cố định 19%</h3>\\n<p>Theo 조세특례제한법 제18조의2, lao động nước ngoài có thể chọn nộp thuế <strong>19% trên toàn bộ tiền lương</strong> thay cho cách tính thông thường:</p>\\n<ul>\\n<li>Áp dụng cho người <strong>bắt đầu làm việc ở Hàn lần đầu không muộn hơn ngày 31/12/2026</strong>, trong tối đa 20 năm kể từ ngày bắt đầu làm.</li>\\n<li>Không áp dụng cho lao động làm theo ngày (일용근로자).</li>\\n<li>Chọn 19% thì <strong>không được hưởng khoản miễn thuế, giảm trừ nào</strong>.</li>\\n<li>Muốn chọn thì nộp 외국인근로자 단일세율적용신청서 cho công ty khi quyết toán, hoặc cho cơ quan thuế khi tự khai thuế.</li>\\n</ul>\\n<p>Vì mất hết khoản giảm trừ, hãy nhờ phòng kế toán tính thử cả hai cách trước khi chọn.</p>\\n<h2 id=\\"quyet-toan-thue-cuoi-nam\\">Quyết toán thuế cuối năm (연말정산)</h2>\\n<p>Quyết toán là tính lại thuế của cả năm trước. Đã bị trừ nhiều hơn số phải nộp thì được <strong>hoàn lại</strong>. Bị trừ ít hơn thì <strong>nộp thêm</strong>. Lao động nước ngoài làm theo lịch giống người Hàn.</p>\\n<p>Các bước (theo lịch quyết toán năm 2025, làm vào đầu năm 2026):</p>\\n<ol>\\n<li>Từ ngày 15/1, vào <strong>홈택스</strong> (hometax.go.kr), mục 연말정산 간소화, tải dữ liệu các khoản được giảm trừ. Công ty đăng ký dịch vụ tải hộ thì có thể tải thay cho người lao động đã đồng ý.</li>\\n<li>Nộp dữ liệu và tờ khai cho công ty theo hạn công ty báo.</li>\\n<li>Công ty tính lại, rồi hoàn tiền hoặc trừ thêm qua lương. Xem kết quả trên phiếu lương.</li>\\n</ol>\\n<p>Người bị xác định là 비거주자 (người không cư trú theo luật thuế) vẫn phải quyết toán nhưng mất nhiều khoản giảm trừ, như giảm trừ cho người phụ thuộc.</p>\\n<h3 id=\\"nghi-viec-giua-nam-quen-khai\\">Nghỉ việc giữa năm, quên khai</h3>\\n<ul>\\n<li>Nghỉ việc giữa năm: công ty tính lại thuế khi trả lương tháng cuối.</li>\\n<li>Bỏ sót khoản giảm trừ, hoặc làm hai nơi mà chưa cộng lương: tự khai <strong>종합소득세</strong> (thuế thu nhập tổng hợp) trong tháng 5 năm sau trên 홈택스.</li>\\n<li>Người phải khai 종합소득세 mà rời Hàn hẳn thì phải khai <strong>trước ngày xuất cảnh</strong> (소득세법 제74조).</li>\\n</ul>\\n<h3 id=\\"ho-tro\\">Hỗ trợ</h3>\\n<ul>\\n<li>Cục Thuế Hàn Quốc có tài liệu quyết toán bằng tiếng Việt trên trang tiếng Anh của Cục Thuế (nts.go.kr).</li>\\n<li>Tổng đài tư vấn thuế cho người nước ngoài: <strong>1588-0560</strong> (tiếng Anh), 9:00–18:00, nghỉ trưa 11:30–13:00.</li>\\n<li>Tổng đài thuế chung: <strong>126</strong>.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&amp;csmSeq=1694&amp;ccfNo=2&amp;cciNo=3&amp;cnpClsNo=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — 임금대장 작성 및 임금명세서 교부</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://www.moel.go.kr/local/seoulseobu/news/notice/noticeView.do?bbs_seq=20211101223\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">고용노동부 — 임금명세서 교부 의무화 안내</a> <span class=\\"source-domain\\">moel.go.kr</span></li>\\n<li><a href=\\"https://www.korea.kr/news/policyNewsView.do?newsId=148957270\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">대한민국 정책브리핑 — 내년부터 달라지는 국민연금 (보험료율 9,5%)</a> <span class=\\"source-domain\\">korea.kr</span></li>\\n<li><a href=\\"https://www.mohw.go.kr/board.es?mid=a10503010100&amp;bid=0027&amp;act=view&amp;list_no=1487279&amp;tag=&amp;nPage=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">보건복지부 — 2026년 건강보험료율 7.19%로 결정</a> <span class=\\"source-domain\\">mohw.go.kr</span></li>\\n<li><a href=\\"https://www.mohw.go.kr/board.es?mid=a10503010100&amp;bid=0027&amp;act=view&amp;list_no=1487817&amp;tag=&amp;nPage=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">보건복지부 — 2026년도 장기요양보험료율 0.9448%</a> <span class=\\"source-domain\\">mohw.go.kr</span></li>\\n<li><a href=\\"https://www.comwel.or.kr/comwel/paym/paym/tari.jsp\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">근로복지공단 — 보험료율</a> <span class=\\"source-domain\\">comwel.or.kr</span></li>\\n<li><a href=\\"https://www.nhis.or.kr/nhis/policy/wbhada05900m01.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국민건강보험 — 외국인 근로자 장기요양보험 가입제외 신청안내</a> <span class=\\"source-domain\\">nhis.or.kr</span></li>\\n<li><a href=\\"https://www.nps.or.kr/html/download/easy/national_join_202603.pdf\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국민연금공단 — 국가별 가입대상 여부 (19/3/2026)</a> <span class=\\"source-domain\\">nps.or.kr</span></li>\\n<li><a href=\\"https://www.law.go.kr/LSW//lsLawLinkInfo.do?lsJoLnkSeq=1000226093&amp;lsId=001649&amp;chrClsCd=010202&amp;print=print\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국가법령정보센터 — 지방세법 제103조의13</a> <span class=\\"source-domain\\">law.go.kr</span></li>\\n<li><a href=\\"https://www.law.go.kr/LSW/lsLawLinkInfo.do?lsJoLnkSeq=1001022467&amp;chrClsCd=010202\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국가법령정보센터 — 조세특례제한법 제18조의2 (외국인근로자에 대한 과세특례)</a> <span class=\\"source-domain\\">law.go.kr</span></li>\\n<li><a href=\\"https://eiec.kdi.re.kr/policy/materialView.do?num=275705\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">KDI 경제교육·정보센터 — 외국인 근로자 연말정산, 국세청과 함께라면 어렵지 않아요 (7/1/2026)</a> <span class=\\"source-domain\\">eiec.kdi.re.kr</span></li>\\n<li><a href=\\"https://www.korea.kr/news/policyNewsView.do?newsId=148957765\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">대한민국 정책브리핑 — 외국인 근로자 국세청 연말정산 안내 서비스</a> <span class=\\"source-domain\\">korea.kr</span></li>\\n<li><a href=\\"https://www.korea.kr/news/policyNewsView.do?newsId=148928889\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">대한민국 정책브리핑 — 연말정산 때 놓친 공제, 5월 종소세 신고 때 신청 가능</a> <span class=\\"source-domain\\">korea.kr</span></li>\\n<li><a href=\\"https://www.law.go.kr/%EB%B2%95%EB%A0%B9/%EC%86%8C%EB%93%9D%EC%84%B8%EB%B2%95/(20230701,19196,20221231)/%EC%A0%9C74%EC%A1%B0\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국가법령정보센터 — 소득세법 제74조 (과세표준확정신고의 특례)</a> <span class=\\"source-domain\\">law.go.kr</span></li>\\n</ul>","headings":[{"id":"phieu-luong-la-quyen-cua-ban","text":"Phiếu lương là quyền của bạn","level":2},{"id":"phan-tien-duoc-nhan","text":"Phần tiền được nhận (지급 내역)","level":2},{"id":"phan-bi-tru","text":"Phần bị trừ (공제 내역)","level":2},{"id":"thue-thu-nhap-hang-thang","text":"Thuế thu nhập hằng tháng","level":2},{"id":"chon-thue-suat-co-dinh-19","text":"Chọn thuế suất cố định 19%","level":3},{"id":"quyet-toan-thue-cuoi-nam","text":"Quyết toán thuế cuối năm (연말정산)","level":2},{"id":"nghi-viec-giua-nam-quen-khai","text":"Nghỉ việc giữa năm, quên khai","level":3},{"id":"ho-tro","text":"Hỗ trợ","level":3},{"id":"nguon","text":"Nguồn","level":2}],"checks":0},{"slug":"tai-nan-lao-dong","title":"Bị tai nạn lao động, bệnh nghề nghiệp","summary":"Bảo hiểm tai nạn lao động (산재보험) bảo vệ cả lao động nước ngoài; biết mình được nhận gì, tự nộp đơn ra sao khi chủ không hợp tác.","updated":"2026-09-25","facts":{"group":"Đang làm việc"},"html":"<h2 id=\\"la-gi\\">산재보험 là gì</h2>\\n<p>산재보험 (산업재해보상보험, bảo hiểm bồi thường tai nạn lao động) chi trả khi người lao động bị thương, bị bệnh hoặc chết <strong>vì công việc</strong>. Chủ đóng toàn bộ phí. Người lao động không bị trừ lương cho khoản này.</p>\\n<ul>\\n<li>Mọi nơi thuê từ 1 người lao động trở lên đều phải tham gia.</li>\\n<li>Ngoại lệ: hộ nông nghiệp, lâm nghiệp (trừ khai thác gỗ), ngư nghiệp không phải pháp nhân và dưới 5 người thường xuyên.</li>\\n<li>Nơi thuê lao động <strong>E-9, H-2</strong> thì đương nhiên phải tham gia 산재보험.</li>\\n</ul>\\n<h2 id=\\"lao-dong-nuoc-ngoai-co-duoc-khong\\">Lao động nước ngoài có được không</h2>\\n<p><strong>Có.</strong> Luật 산재보험 không có điều nào loại người nước ngoài ra.</p>\\n<p><strong>Không có giấy tờ, làm sai visa cũng được.</strong> Tòa án tối cao Hàn Quốc (대법원 1995. 9. 15. 선고 94누12067) đã xử: người nước ngoài không có tư cách làm việc, nhưng thực tế làm việc và bị thương khi làm, vẫn là người lao động theo 근로기준법. Họ được hưởng 산재 như người Hàn. Việc cấm thuê người không có tư cách lưu trú chỉ để xử phạt, không làm hợp đồng lao động mất hiệu lực.</p>\\n<p><strong>Công ty chưa đăng ký 산재보험 cũng được.</strong> 근로복지공단 (Cơ quan phúc lợi lao động) vẫn bồi thường thay chủ cho người lao động.</p>\\n<h2 id=\\"duoc-nhan-nhung-gi\\">Được nhận những gì</h2>\\n<p>Theo 산업재해보상보험법, có các loại quyền lợi:</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Quyền lợi</th>\\n<th>Nội dung</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>요양급여</td>\\n<td>Chi phí điều trị tại cơ sở y tế được chỉ định cho 산재</td>\\n</tr>\\n<tr>\\n<td>휴업급여</td>\\n<td>Tiền thay lương những ngày không làm được vì điều trị: <strong>70% lương bình quân một ngày</strong></td>\\n</tr>\\n<tr>\\n<td>장해급여</td>\\n<td>Khi còn lại thương tật sau điều trị</td>\\n</tr>\\n<tr>\\n<td>간병급여</td>\\n<td>Chi phí người chăm sóc khi cần</td>\\n</tr>\\n<tr>\\n<td>상병보상연금</td>\\n<td>Khi điều trị lâu dài, bệnh nặng</td>\\n</tr>\\n<tr>\\n<td>유족급여, 장례비</td>\\n<td>Cho gia đình khi người lao động chết; chi phí mai táng</td>\\n</tr>\\n<tr>\\n<td>직업재활급여</td>\\n<td>Hỗ trợ học nghề, quay lại làm việc</td>\\n</tr>\\n</tbody></table></div>\\n<p>Lưu ý:</p>\\n<ul>\\n<li>Chỉ điều trị khỏi trong <strong>3 ngày trở xuống</strong> thì 산재 không trả 요양급여. Nghỉ việc 3 ngày trở xuống thì không có 휴업급여.</li>\\n<li>Quyền nhận 요양급여, 휴업급여 <strong>không mất khi bạn nghỉ việc</strong>.</li>\\n<li>Trong lúc chờ 근로복지공단 quyết định, có thể khám bằng bảo hiểm y tế (건강보험). Được công nhận 산재 thì xin lại phần tiền mình đã tự trả.</li>\\n</ul>\\n<h2 id=\\"nop-don-the-nao\\">Nộp đơn thế nào</h2>\\n<ol>\\n<li><strong>Đi khám ngay.</strong> Nói rõ với bác sĩ là bị thương hoặc bị bệnh khi làm việc. Xin <strong>소견서</strong> (giấy nhận xét của bác sĩ).</li>\\n<li><strong>Ghi lại bằng chứng</strong>: ảnh nơi xảy ra tai nạn, tên người chứng kiến, tin nhắn báo cho chủ, bảng chấm công.</li>\\n<li><strong>Nộp 요양급여신청서</strong> (đơn xin trợ cấp điều trị) kèm 소견서 tới chi nhánh 근로복지공단 nơi công ty đặt trụ sở. Có thể:<ul>\\n<li>Nộp trực tiếp tại chi nhánh.</li>\\n<li>Nộp trực tuyến trên <strong>고용·산재보험 토탈서비스</strong> (total.comwel.or.kr).</li>\\n<li>Ký giấy đồng ý để <strong>bệnh viện nộp thay</strong> (bệnh viện thuộc diện 산재).</li>\\n</ul>\\n</li>\\n<li><strong>Chờ kết quả.</strong> 근로복지공단 báo cho chủ và hỏi ý kiến chủ. Trường hợp rõ ràng, phải quyết định trong <strong>7 ngày</strong>. Cần điều tra, hội đồng xét bệnh nghề nghiệp… thì lâu hơn.</li>\\n<li><strong>Xin 휴업급여</strong> riêng bằng 휴업급여청구서, cũng nộp tại 근로복지공단 hoặc trực tuyến.</li>\\n</ol>\\n<p>Hạn: quyền xin 요양급여, 휴업급여 mất sau <strong>3 năm</strong> (tính từ ngày hôm sau ngày điều trị hoặc nghỉ việc). Đừng chờ lâu.</p>\\n<p>Không đồng ý với quyết định không công nhận: được khiếu nại (심사청구) hoặc kiện trong <strong>90 ngày</strong> kể từ khi biết quyết định.</p>\\n<h2 id=\\"chu-khong-khai-bao-khong-ky-thi-lam-gi\\">Chủ không khai báo, không ký thì làm gì</h2>\\n<p>Bạn <strong>không cần chủ đồng ý</strong> mới nộp đơn.</p>\\n<ul>\\n<li>Theo Bộ Việc làm và Lao động Hàn Quốc: chủ không hợp tác thì người lao động tự nộp đơn tới chi nhánh 근로복지공단 nơi công ty đặt trụ sở. 근로복지공단 tự điều tra và quyết định có phải tai nạn lao động hay không.</li>\\n<li>Chủ gây sức ép, đòi bạn không nộp đơn: gọi 1350 hoặc 1577-0071 để được tư vấn trước khi ký bất cứ giấy gì.</li>\\n</ul>\\n<p>Lao động E-9 bị thương, bị bệnh không làm tiếp được ở nơi cũ nhưng làm được nơi khác thì có thể xin đổi nơi làm (xem bài EPS).</p>\\n<h2 id=\\"noi-ho-tro\\">Nơi hỗ trợ</h2>\\n<ul>\\n<li><strong>근로복지공단</strong>: 1588-0075, total.comwel.or.kr.</li>\\n<li><strong>1350</strong>: Trung tâm tư vấn của Bộ Việc làm và Lao động.</li>\\n<li><strong>1577-0071</strong>: 외국인력상담센터 (Trung tâm tư vấn nhân lực nước ngoài), có tiếng Việt.</li>\\n<li><strong>1345</strong>: Tổng đài xuất nhập cảnh, có tiếng Việt (hỏi về visa trong lúc điều trị).</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&amp;csmSeq=575&amp;ccfNo=2&amp;cciNo=2&amp;cnpClsNo=2\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — 요양급여의 신청 및 지급</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&amp;csmSeq=575&amp;ccfNo=3&amp;cciNo=1&amp;cnpClsNo=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — 휴업급여</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&amp;csmSeq=2042&amp;ccfNo=3&amp;cciNo=1&amp;cnpClsNo=2\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — 외국인근로자 4대 보험</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://easylaw.go.kr/CSP/OnhunqueansInfoRetrieve.laf?onhunqnaAstSeq=82&amp;targetRow=81&amp;sortType=RECOM&amp;pagingType=default&amp;onhunqueSeq=1787\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — 산업재해보상보험 가입 및 보험료 징수 (문답)</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://www.law.go.kr/LSW/precInfoP.do?evtNo=94%EB%88%8412067\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국가법령정보센터 — 대법원 94누12067 요양불승인처분취소</a> <span class=\\"source-domain\\">law.go.kr</span></li>\\n<li><a href=\\"https://www.law.go.kr/LSW/precInfoP.do?precSeq=119759\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국가법령정보센터 — 서울고법 93구16774 (외국인 불법취업자 요양급여)</a> <span class=\\"source-domain\\">law.go.kr</span></li>\\n<li><a href=\\"https://law.go.kr/LSW/lsInfoP.do?lsiSeq=96714\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국가법령정보센터 — 산업재해보상보험법</a> <span class=\\"source-domain\\">law.go.kr</span></li>\\n<li><a href=\\"https://www.comwel.or.kr/comwel/comp/recu/appl01.jsp\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">근로복지공단 — 산재신청 방법</a> <span class=\\"source-domain\\">comwel.or.kr</span></li>\\n<li><a href=\\"https://www.moel.go.kr/faq/faqView.do?seqRepeat=207\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">고용노동부 — 사업주의 산재처리 거부시 처리방법</a> <span class=\\"source-domain\\">moel.go.kr</span></li>\\n<li><a href=\\"https://www.korea.kr/news/policyNewsView.do?newsId=148809649\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">대한민국 정책브리핑 — 우리 회사, 고용·산재보험은 가입돼 있나요?</a> <span class=\\"source-domain\\">korea.kr</span></li>\\n<li><a href=\\"https://www.moel.go.kr/policyitrd/policyItrdView.do?policy_itrd_sn=248\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">고용노동부 — 외국인근로자 사업장 변경제도</a> <span class=\\"source-domain\\">moel.go.kr</span></li>\\n<li><a href=\\"https://www.hrdkorea.or.kr/1/3/3/4\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">한국산업인력공단 — 외국인력상담센터</a> <span class=\\"source-domain\\">hrdkorea.or.kr</span></li>\\n</ul>","headings":[{"id":"la-gi","text":"산재보험 là gì","level":2},{"id":"lao-dong-nuoc-ngoai-co-duoc-khong","text":"Lao động nước ngoài có được không","level":2},{"id":"duoc-nhan-nhung-gi","text":"Được nhận những gì","level":2},{"id":"nop-don-the-nao","text":"Nộp đơn thế nào","level":2},{"id":"chu-khong-khai-bao-khong-ky-thi-lam-gi","text":"Chủ không khai báo, không ký thì làm gì","level":2},{"id":"noi-ho-tro","text":"Nơi hỗ trợ","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":0},{"slug":"ve-nuoc-nhan-tien","title":"Trước khi về nước: nhận đủ các khoản tiền","summary":"Danh sách các khoản tiền lao động E-9 được nhận khi về nước (퇴직금, 출국만기보험, 귀국비용보험, 국민연금 반환일시금), thủ tục trước khi bay và cách nhận khi đã về Việt Nam.","updated":"2026-09-25","facts":{"group":"Khi về nước"},"html":"<h2 id=\\"cac-khoan-tien-co-the-nhan\\">Các khoản tiền có thể nhận</h2>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Khoản</th>\\n<th>Ai trả</th>\\n<th>Điều kiện chính</th>\\n<th>Khi nào nhận</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>퇴직금 (trợ cấp thôi việc) phần chênh lệch</td>\\n<td>Chủ</td>\\n<td>Làm từ 1 năm trở lên</td>\\n<td>Khi nghỉ việc</td>\\n</tr>\\n<tr>\\n<td>출국만기보험 (bảo hiểm hết hạn xuất cảnh)</td>\\n<td>Công ty bảo hiểm (삼성화재)</td>\\n<td>E-9, H-2, làm <strong>cùng một nơi từ 1 năm</strong> trở lên</td>\\n<td>Sau khi xuất cảnh</td>\\n</tr>\\n<tr>\\n<td>귀국비용보험 (bảo hiểm chi phí về nước)</td>\\n<td>Công ty bảo hiểm (삼성화재)</td>\\n<td>E-9, H-2 đã đóng phí</td>\\n<td>Trước ngày xuất cảnh</td>\\n</tr>\\n<tr>\\n<td>국민연금 반환일시금 (hoàn trả lương hưu một lần)</td>\\n<td>국민연금공단 (NPS)</td>\\n<td>Đóng 국민연금 bằng visa E-9, H-2</td>\\n<td>Sau khi xuất cảnh, hoặc tại sân bay</td>\\n</tr>\\n<tr>\\n<td>Lương tháng cuối</td>\\n<td>Chủ</td>\\n<td>Mọi người lao động</td>\\n<td>Theo hợp đồng</td>\\n</tr>\\n</tbody></table></div>\\n<p>Quy định chung về 퇴직금 (cách tính, hạn trả 14 ngày): xem bài Quyền lợi người lao động.</p>\\n<h2 id=\\"muc-va\\">퇴직금 và 출국만기보험</h2>\\n<p>Với E-9, H-2, tiền trợ cấp thôi việc chia làm hai phần:</p>\\n<ul>\\n<li><strong>출국만기보험</strong>: chủ đóng hằng tháng 8,3% lương thông thường cho công ty bảo hiểm. Làm cùng một nơi từ 1 năm trở lên thì tiền này trả cho <strong>bạn</strong>. Dưới 1 năm thì trả về cho chủ.</li>\\n<li><strong>Phần chênh lệch (차액)</strong>: nếu 퇴직금 theo luật cao hơn số tiền bảo hiểm (khi thu nhập thực tế cao hơn lương thông thường dùng để tính phí), chủ phải trả thêm phần thiếu.</li>\\n</ul>\\n<p>Có thể gọi công ty bảo hiểm hỏi số tiền 출국만기보험 dự kiến để tính phần chênh lệch.</p>\\n<p>Tiền 출국만기보험 được trả <strong>trong 14 ngày sau khi xuất cảnh</strong>, vào tài khoản ở Hàn hoặc ở nước ngoài. Theo công ty bảo hiểm, khi về nước hẳn còn có thể nhận trực tiếp tại sân bay.</p>\\n<h2 id=\\"muc\\">귀국비용보험</h2>\\n<ul>\\n<li>Người lao động tự đóng trong 3 tháng đầu. Mức cho người Việt Nam: <strong>400.000 won</strong>.</li>\\n<li>Được trả lại khi về nước do hết hạn lưu trú, về vì việc riêng (không tính về tạm thời), kể cả khi tự nguyện xuất cảnh hoặc bị trục xuất.</li>\\n<li>Số tiền nhận: đúng tiền gốc nếu dưới 1 năm; từ 1 năm trở lên được thêm một ít (ví dụ từ 4 năm: 106% tiền gốc).</li>\\n<li>Công ty bảo hiểm kiểm tra việc xuất cảnh rồi trả vào tài khoản của bạn <strong>trước ngày xuất cảnh dự kiến</strong>.</li>\\n<li>Đang ở Hàn thì không được nhờ người khác xin thay.</li>\\n</ul>\\n<h2 id=\\"muc-2\\">국민연금 반환일시금</h2>\\n<p>Người Việt đi làm ở công ty tham gia 국민연금 phải đóng từ 1/1/2022. Có nhận lại khi về nước hay không tùy loại visa:</p>\\n<ul>\\n<li><strong>E-9, H-2</strong> (và E-8 연수취업): <strong>được nhận</strong>, không phụ thuộc quốc tịch. Riêng E-8 계절근로 (lao động thời vụ) thì không.</li>\\n<li><strong>Visa khác</strong> (ví dụ E-7): theo danh sách của NPS (tháng 5/2026), Việt Nam <strong>không</strong> thuộc nhóm nước được hoàn một lần theo hiệp định hay theo nguyên tắc tương đương. Hiệp định an sinh xã hội Hàn–Việt (hiệu lực 1/1/2024) chủ yếu miễn đóng trùng và cộng thời gian đóng. Người thuộc diện này nên hỏi <strong>1355</strong> trước khi về.</li>\\n</ul>\\n<p>Số tiền: phần bạn đã đóng cộng lãi theo lãi suất tiền gửi kỳ hạn 3 năm (năm 2026: 2,2%).</p>\\n<p>Cách nhận:</p>\\n<ul>\\n<li><strong>Tại sân bay Incheon</strong>: trong vòng 1 tháng trước ngày bay, đến chi nhánh NPS nộp đơn xin 반환일시금 và đăng ký nhận ở sân bay. Mang hộ chiếu, 외국인등록증, vé máy bay, bản sao tài khoản dự phòng. Ngày bay đến quầy NPS ở nhà ga số 1 lấy giấy, rồi nhận ngoại tệ tại quầy ngân hàng trong sân bay.<ul>\\n<li>Công ty phải báo bạn nghỉ việc (상실신고) <strong>trước ngày bay</strong>, nếu không sẽ không nhận ở sân bay được.</li>\\n<li>Không nhận ở sân bay nếu bay vào thứ Bảy, Chủ nhật, ngày lễ, ngày làm việc cuối cùng của tháng 12.</li>\\n<li>Không trả bằng tiền won.</li>\\n<li>Giờ máy bay cất cánh phải nằm trong khung giờ NPS quy định cho từng nhà ga. Hỏi khi nộp đơn.</li>\\n</ul>\\n</li>\\n<li><strong>Chuyển khoản</strong>: NPS chỉ trả khi đã xác nhận bạn xuất cảnh. Có vé bay trong vòng 1 tháng thì nộp đơn trước được.</li>\\n<li><strong>Đã về Việt Nam</strong>: tự gửi đơn qua bưu điện, hoặc cử người đại diện ở Hàn đến chi nhánh NPS.</li>\\n</ul>\\n<p>Hạn: phải xin trong <strong>5 năm</strong> kể từ khi phát sinh quyền nhận. Gọi từ Việt Nam: +82-63-713-6900.</p>\\n<h2 id=\\"thu-tuc-truoc-khi-bay-e-9\\">Thủ tục trước khi bay (E-9)</h2>\\n<ol>\\n<li><strong>Báo công ty</strong> ngày nghỉ, thống nhất ngày chấm dứt hợp đồng. Báo sớm để kịp nhận lương và phần chênh lệch 퇴직금.</li>\\n<li><strong>Khai báo dự định xuất cảnh</strong> (출국예정신고서) ở 고용센터. Chỉ khai được trong vòng <strong>1 tháng trước ngày bay</strong>. Nhận <strong>출국예정사실 확인서</strong> (giấy xác nhận dự định xuất cảnh).</li>\\n<li><strong>Nộp đơn xin 출국만기보험 và 귀국비용보험</strong> cho công ty bảo hiểm, kèm giấy xác nhận trên, bản sao tài khoản đứng tên mình và giấy tờ tùy thân. Nộp qua tổng đài bảo hiểm cho lao động nước ngoài, app bảo hiểm cho lao động nước ngoài, hoặc văn phòng khu vực của 삼성화재.</li>\\n<li><strong>Nộp đơn 반환일시금</strong> ở chi nhánh NPS (xem mục trên).</li>\\n<li><strong>Quyết toán thuế</strong>: công ty tính lại thuế khi trả lương tháng cuối (xem bài Phiếu lương, thuế và quyết toán).</li>\\n<li><strong>Giữ tài khoản ngân hàng ở Hàn</strong> cho đến khi nhận đủ tiền. Tiền 출국만기보험 về sau khi đã bay.</li>\\n<li><strong>Trả 외국인등록증</strong> cho nhân viên xuất nhập cảnh tại sân bay.</li>\\n</ol>\\n<h2 id=\\"da-ve-nuoc-ma-chua-nhan\\">Đã về nước mà chưa nhận</h2>\\n<ul>\\n<li><strong>출국만기보험, 귀국비용보험</strong>: quyền đòi mất sau <strong>3 năm</strong> kể từ khi phát sinh. Quá hạn, tiền chuyển sang 한국산업인력공단 (HRD Korea) làm <strong>휴면보험금</strong> (tiền bảo hiểm chưa nhận) và vẫn có thể xin lại.</li>\\n<li>Người Việt tra tên trên trang Trung tâm Lao động ngoài nước (colab.gov.vn), mục &quot;Tra cứu danh sách người lao động chưa nhận tiền bảo hiểm&quot;. Hồ sơ gồm: đơn đăng ký nhận tiền, bản sao hộ chiếu (trang ảnh, trang dấu xuất cảnh Hàn Quốc), giấy xác nhận tài khoản ngân hàng ở Việt Nam có mã SWIFT. Gửi tới <strong>Trung tâm EPS tại Việt Nam</strong> (024.3773.7273). Tiền về tài khoản khoảng 2–3 tháng sau khi hồ sơ đủ.</li>\\n<li>Hỏi thêm: Trung tâm Lao động ngoài nước 024.7303.0199.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://www.eps.go.kr/eo/EmployPerSystem.eo?tabGb=06\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">EPS — Các loại bảo hiểm và quyền lợi (출국만기보험, 귀국비용보험)</a> <span class=\\"source-domain\\">eps.go.kr</span></li>\\n<li><a href=\\"https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&amp;csmSeq=2042&amp;ccfNo=3&amp;cciNo=1&amp;cnpClsNo=3\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">찾기쉬운 생활법령정보 — 외국인근로자 전용보험</a> <span class=\\"source-domain\\">easylaw.go.kr</span></li>\\n<li><a href=\\"https://www.korea.kr/news/policyNewsView.do?newsId=148781107\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">대한민국 정책브리핑 — 외국인근로자 출국만기보험 지급시기</a> <span class=\\"source-domain\\">korea.kr</span></li>\\n<li><a href=\\"https://foreign-worker.sfmi.co.kr/faq\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">삼성화재 외국인근로자 전용보험 — Câu hỏi thường gặp</a> <span class=\\"source-domain\\">foreign-worker.sfmi.co.kr</span></li>\\n<li><a href=\\"https://www.nps.or.kr/pnsinfo/ntpsklg/getOHAF0084M0.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국민연금공단 — 외국인에 대한 반환일시금, 공항지급서비스</a> <span class=\\"source-domain\\">nps.or.kr</span></li>\\n<li><a href=\\"https://www.nps.or.kr/html/download/easy/national_join_202603.pdf\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국민연금공단 — 국가별 가입대상 여부 (19/3/2026)</a> <span class=\\"source-domain\\">nps.or.kr</span></li>\\n<li><a href=\\"https://mohw.go.kr/board.es?act=view&amp;bid=0027&amp;list_no=1479193&amp;mid=a10503010100&amp;nPage=1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">보건복지부 — 한국과 베트남, 연금보험료 이중납부 해소와 가입기간 합산</a> <span class=\\"source-domain\\">mohw.go.kr</span></li>\\n<li><a href=\\"https://colab.moha.gov.vn/tin-tuc/615/Thu-tuc-ve-nuoc.aspx\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Trung tâm Lao động ngoài nước — Thủ tục về nước</a> <span class=\\"source-domain\\">colab.moha.gov.vn</span></li>\\n<li><a href=\\"https://colab.moha.gov.vn/huong-dan-thu-tuc-nhan-tien-bao-hiem.aspx\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Trung tâm Lao động ngoài nước — Hướng dẫn thủ tục nhận tiền bảo hiểm</a> <span class=\\"source-domain\\">colab.moha.gov.vn</span></li>\\n</ul>","headings":[{"id":"cac-khoan-tien-co-the-nhan","text":"Các khoản tiền có thể nhận","level":2},{"id":"muc-va","text":"퇴직금 và 출국만기보험","level":2},{"id":"muc","text":"귀국비용보험","level":2},{"id":"muc-2","text":"국민연금 반환일시금","level":2},{"id":"thu-tuc-truoc-khi-bay-e-9","text":"Thủ tục trước khi bay (E-9)","level":2},{"id":"da-ve-nuoc-ma-chua-nhan","text":"Đã về nước mà chưa nhận","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":0}],"hoc-tap":[{"slug":"tu-kiem-tra-thay-vi-doc-lai","title":"Tự kiểm tra thay vì đọc lại","summary":"Vì sao tự nhớ lại bài (tự kiểm tra) giúp nhớ lâu hơn đọc lại, và cách làm khi học tiếng Hàn và lập trình.","updated":"2026-10-01","facts":{"group":"Nền tảng"},"html":"<p>Cách ôn phổ biến nhất là đọc lại bài, tô màu chỗ quan trọng, đọc thêm lần nữa trước khi thi. Đọc lại cho cảm giác đã thuộc, nhưng một tuần sau phần lớn đã quên. Bài này nói về một cách ôn khác có nhiều bằng chứng hơn: tự kiểm tra.</p>\\n<h2 id=\\"tu-kiem-tra-la-gi\\">Tự kiểm tra là gì</h2>\\n<p>Tự kiểm tra (tiếng Anh: retrieval practice) là cố nhớ lại kiến thức mà không nhìn tài liệu. Ví dụ: gấp sách lại rồi viết ra những gì vừa học, che nghĩa rồi tự nói từ, làm bài trắc nghiệm trước khi xem lại bài.</p>\\n<p>Điểm chính: bài kiểm tra không chỉ để đo xem bạn biết gì. Chính việc cố nhớ lại làm cho kiến thức bám lâu hơn. Hiện tượng này gọi là hiệu ứng kiểm tra (testing effect).</p>\\n<h2 id=\\"vi-sao-doc-lai-co-cam-giac-hieu-qua\\">Vì sao đọc lại có cảm giác hiệu quả</h2>\\n<p>Khi đọc lại một bài, câu chữ quen dần, đọc trôi hơn. Ta dễ nhầm cảm giác &quot;quen&quot; đó với &quot;nhớ được&quot;. Nhưng nhận ra một câu khi nó nằm trước mặt khác với tự nói ra câu đó khi không có gì để nhìn.</p>\\n<p>Roediger và Karpicke (2006) cho thấy rõ sự nhầm lẫn này. Sinh viên Đại học Washington ở St. Louis (Mỹ) học các đoạn văn ngắn lấy từ sách luyện thi TOEFL, về Mặt Trời và rái cá biển. Ở thí nghiệm 2, mỗi người học một đoạn văn qua bốn lượt liên tiếp, chia ba nhóm:</p>\\n<ul>\\n<li>Bốn lượt đọc (mỗi lượt 5 phút).</li>\\n<li>Ba lượt đọc, rồi một lượt tự viết lại bài.</li>\\n<li>Một lượt đọc, rồi ba lượt tự viết lại bài (không được xem đáp án).</li>\\n</ul>\\n<p>Kiểm tra sau 5 phút, nhóm chỉ đọc nhớ nhiều nhất (83% ý của bài, so với 78% và 71%). Kiểm tra sau 1 tuần, kết quả đảo ngược: nhóm tự viết lại 3 lần nhớ 61%, nhóm 1 lần 56%, nhóm chỉ đọc 40%.</p>\\n<p>Điều đáng chú ý: nhóm chỉ đọc lại tự tin nhất rằng mình sẽ nhớ bài sau một tuần. Họ tự tin nhất nhưng kết quả kém nhất, dù trong bốn lượt đó họ đã đọc hết bài khoảng 14 lần, còn nhóm tự viết lại ba lần chỉ đọc khoảng 3 lần.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — hiệu ứng kiểm tra đã được lặp lại trong rất nhiều thí nghiệm. Riêng các con số trên là của một nghiên cứu, trên sinh viên đại học Mỹ, học đoạn văn tiếng Anh trong phòng thí nghiệm.</p>\\n<h2 id=\\"tu-kiem-tra-tot-hon-ca-cach-hoc-chu-dong-khac\\">Tự kiểm tra tốt hơn cả cách học &quot;chủ động&quot; khác</h2>\\n<p>Có người nghĩ: chỉ cần học chủ động là được, không cần tự kiểm tra. Karpicke và Blunt (2011) so sánh tự kiểm tra với vẽ sơ đồ khái niệm (concept map) trong lúc vẫn nhìn bài, một cách học chủ động được dùng nhiều trong dạy khoa học. Thời gian học hai nhóm bằng nhau. Nhóm tự kiểm tra học bài một lần, viết lại những gì nhớ được, đọc lại bài, rồi viết lại lần nữa.</p>\\n<p>Kết quả sau 1 tuần:</p>\\n<ul>\\n<li>Thí nghiệm 1: nhóm tự kiểm tra làm đúng trung bình 67%, nhóm vẽ sơ đồ 45%. Ưu thế có cả ở câu hỏi suy luận, không chỉ câu hỏi nhớ nguyên văn.</li>\\n<li>Thí nghiệm 2: 101 trên 120 sinh viên (84%) làm bài tốt hơn sau khi tự kiểm tra. Ưu thế vẫn còn ngay cả khi bài thi cuối là vẽ sơ đồ khái niệm.</li>\\n<li>Trong khi đó, 90 trên 120 sinh viên (75%) đoán rằng vẽ sơ đồ hiệu quả bằng hoặc hơn tự kiểm tra.</li>\\n</ul>\\n<p>Bài học: cảm giác &quot;mình học tốt&quot; không phải thước đo đáng tin. Một cách học có thể cho cảm giác nặng nề hơn nhưng lại cho kết quả lâu dài tốt hơn.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — hai thí nghiệm trên sinh viên đại học với bài đọc khoa học. Chưa kiểm tra với học ngoại ngữ hay lập trình.</p>\\n<h2 id=\\"cac-nha-nghien-cuu-xep-hang-cach-hoc\\">Các nhà nghiên cứu xếp hạng cách học</h2>\\n<p>Dunlosky và cộng sự (2013) tổng hợp nghiên cứu về 10 cách học phổ biến, xét xem lợi ích có giữ được qua nhiều độ tuổi, trình độ, loại tài liệu và loại bài thi không.</p>\\n<ul>\\n<li><strong>Tự kiểm tra</strong> (practice testing) và học giãn cách được xếp &quot;hiệu quả cao&quot;, vì có lợi cho người học ở nhiều độ tuổi, trình độ và cả trong lớp học thật.</li>\\n<li><strong>Đọc lại</strong> và <strong>tô đậm, gạch chân</strong> bị xếp &quot;hiệu quả thấp&quot;, vì không giúp cải thiện kết quả một cách ổn định. Nhóm tác giả khuyên dùng tự kiểm tra thay cho đọc lại.</li>\\n</ul>\\n<p>Một phân tích gộp của Rowland (2014) còn cho thấy: kiểu kiểm tra bắt phải tự nhớ ra (viết, nói lại) cho lợi ích lớn hơn kiểu chỉ cần nhận ra đáp án đúng (chọn trong các phương án).</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — một bài tổng quan lớn và một phân tích gộp, gồm nghiên cứu trên người học nhiều độ tuổi và trình độ.</p>\\n<h2 id=\\"ap-dung-khi-hoc-tieng-han\\">Áp dụng khi học tiếng Hàn</h2>\\n<p><strong>Che nghĩa, tự nói câu tiếng Hàn.</strong> Viết câu tiếng Việt một bên, tiếng Hàn một bên. Che cột tiếng Hàn, nhìn tiếng Việt và tự nói hoặc viết câu tiếng Hàn. Sau đó mở ra so.</p>\\n<ul>\\n<li>&quot;Tôi đến từ Việt Nam.&quot; → 저는 베트남에서 왔어요.</li>\\n<li>&quot;Vì trời mưa nên tôi ở nhà.&quot; → 비가 와서 집에 있었어요.</li>\\n</ul>\\n<p>Nên luyện chiều từ tiếng Việt sang tiếng Hàn, vì đó là chiều bạn cần khi nói và viết.</p>\\n<p><strong>Làm bài kiểm tra trước, đọc lại sau.</strong> Khi ôn một bài KIIP cũ, đừng mở bài khoá ra đọc trước. Làm bài tập của bài trước, sai chỗ nào thì mới quay lại đọc đúng chỗ đó.</p>\\n<p><strong>Tự viết ví dụ ngữ pháp từ trí nhớ.</strong> Gấp sách, viết 2–3 câu dùng mẫu ngữ pháp vừa học. Ví dụ với -(으)ㄹ 수 있다 (có thể làm gì): 한국어를 읽을 수 있어요 (Tôi có thể đọc tiếng Hàn). Viết xong mới mở sách kiểm tra cách chia.</p>\\n<h2 id=\\"ap-dung-khi-hoc-lap-trinh\\">Áp dụng khi học lập trình</h2>\\n<p><strong>Viết lại hàm mà không nhìn.</strong> Sau khi học một bài, đóng ví dụ lại và tự viết lại hàm đó từ đầu bằng Java. Kẹt chỗ nào thì đó chính là chỗ bạn chưa hiểu. Xem lại đúng chỗ đó, rồi đóng lại và viết lần nữa.</p>\\n<p><strong>Đoán kết quả trước khi chạy.</strong> Trước khi bấm chạy, viết ra giấy chương trình sẽ in gì:</p>\\n<pre><code class=\\"language-java\\">List&lt;Integer&gt; list = new ArrayList&lt;&gt;(List.of(3, 1, 2));\\nCollections.sort(list);\\nlist.add(0);\\nSystem.out.println(list);\\n</code></pre>\\n<p>Bạn đoán in ra gì? Chạy thử để kiểm tra (đáp án: <code>[1, 2, 3, 0]</code>, vì <code>add</code> thêm vào cuối sau khi đã sắp xếp). Đoán sai không sao. Điều quan trọng là bạn đã phải tự suy ra trước khi nhìn kết quả.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — đây là áp dụng nguyên tắc chung. Các nghiên cứu nêu trong bài dùng bài đọc và từ vựng, chưa thử riêng với lập trình.</p>\\n<h2 id=\\"kiem-tra-dap-an-sau-khi-tu-kiem-tra\\">Kiểm tra đáp án sau khi tự kiểm tra</h2>\\n<p>Tự kiểm tra mà không biết mình đúng hay sai thì dễ nhớ luôn cả cái sai.</p>\\n<ul>\\n<li>Pashler và cộng sự (2005) cho 258 người học cặp từ tiếng Luganda (một ngôn ngữ ở Uganda) và tiếng Anh. Được xem đáp án đúng sau khi trả lời sai giúp nhớ tốt hơn nhiều ở bài kiểm tra 1 tuần sau. Xem đáp án sau khi đã trả lời đúng thì gần như không khác biệt.</li>\\n<li>Butler và Roediger (2008) cho thấy với bài trắc nghiệm, xem đáp án (ngay sau đó hoặc muộn hơn) giúp nhớ đúng nhiều hơn và giảm việc nhớ nhầm các phương án sai.</li>\\n</ul>\\n<p>Cách làm: tự kiểm tra xong thì so đáp án luôn. Ghi lại câu sai để lần sau kiểm tra lại câu đó.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — vài thí nghiệm trong phòng thí nghiệm, với từ vựng và đoạn văn.</p>\\n<h2 id=\\"ap-dung-ngay\\">Áp dụng ngay</h2>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"jlpku6\\"><span>Lần ôn tới, gấp sách và viết ra mọi thứ còn nhớ trước khi mở sách đọc lại.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1ocroqu\\"><span>Chọn 10 câu tiếng Hàn trong bài vừa học, che phần tiếng Hàn và tự nói lại từ nghĩa tiếng Việt.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"3kmi2h\\"><span>Làm bài kiểm tra của một bài KIIP cũ trước, chỉ đọc lại phần làm sai.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"j0u01j\\"><span>Viết lại từ đầu một hàm Java vừa học mà không nhìn ví dụ.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1ox451f\\"><span>Sau mỗi lần tự kiểm tra, so đáp án ngay và ghi lại câu sai.</span></label></li>\\n</ul>\\n<h2 id=\\"tren-haechivn\\">Trên HaechiVN</h2>\\n<ul>\\n<li><a href=\\"/books/step1/roadmap\\">Lộ trình KIIP</a>: Sơ cấp 1 có câu hỏi kiểm tra chấm tự động ngay trong trình đọc; giáo trình và sách bài tập các cấp có đáp án của sách để tự chấm.</li>\\n<li><a href=\\"/ngu-phap\\">Ngữ pháp</a>: xem lại cách dùng và ví dụ sau khi đã tự viết câu của mình.</li>\\n<li><a href=\\"/exam/topik-i\\">Luyện thi TOPIK I</a>: làm theo từng phần hoặc thi thử có giờ.</li>\\n<li><a href=\\"/java\\">Khoá Java</a> và <a href=\\"/it\\">Khoá C#</a>: nhiều bài học có câu hỏi kiểm tra cuối bài.</li>\\n<li><a href=\\"/my\\">Góc học tập</a>: gợi ý các điểm ngữ pháp nên ôn, dựa trên phần bạn tự chấm và câu hỏi kiểm tra của Sơ cấp 1.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://doi.org/10.1111/j.1467-9280.2006.01693.x\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Roediger &amp; Karpicke (2006). Test-enhanced learning: Taking memory tests improves long-term retention. Psychological Science</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1126/science.1199327\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Karpicke &amp; Blunt (2011). Retrieval practice produces more learning than elaborative studying with concept mapping. Science</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1177/1529100612453266\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Dunlosky, Rawson, Marsh, Nathan &amp; Willingham (2013). Improving students&#39; learning with effective learning techniques: Promising directions from cognitive and educational psychology. Psychological Science in the Public Interest</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1037/a0037559\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Rowland (2014). The effect of testing versus restudy on retention: A meta-analytic review of the testing effect. Psychological Bulletin</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1037/0278-7393.31.1.3\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Pashler, Cepeda, Wixted &amp; Rohrer (2005). When does feedback facilitate learning of words? Journal of Experimental Psychology: Learning, Memory, and Cognition</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.3758/MC.36.3.604\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Butler &amp; Roediger (2008). Feedback enhances the positive effects and reduces the negative effects of multiple-choice testing. Memory &amp; Cognition</a> <span class=\\"source-domain\\">doi.org</span></li>\\n</ul>","headings":[{"id":"tu-kiem-tra-la-gi","text":"Tự kiểm tra là gì","level":2},{"id":"vi-sao-doc-lai-co-cam-giac-hieu-qua","text":"Vì sao đọc lại có cảm giác hiệu quả","level":2},{"id":"tu-kiem-tra-tot-hon-ca-cach-hoc-chu-dong-khac","text":"Tự kiểm tra tốt hơn cả cách học \\"chủ động\\" khác","level":2},{"id":"cac-nha-nghien-cuu-xep-hang-cach-hoc","text":"Các nhà nghiên cứu xếp hạng cách học","level":2},{"id":"ap-dung-khi-hoc-tieng-han","text":"Áp dụng khi học tiếng Hàn","level":2},{"id":"ap-dung-khi-hoc-lap-trinh","text":"Áp dụng khi học lập trình","level":2},{"id":"kiem-tra-dap-an-sau-khi-tu-kiem-tra","text":"Kiểm tra đáp án sau khi tự kiểm tra","level":2},{"id":"ap-dung-ngay","text":"Áp dụng ngay","level":2},{"id":"tren-haechivn","text":"Trên HaechiVN","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":5},{"slug":"on-ngat-quang","title":"Ôn ngắt quãng thay vì học dồn","summary":"Chia việc ôn thành nhiều lần cách nhau vài ngày để nhớ từ vựng, ngữ pháp và kiến thức lập trình lâu hơn so với học dồn một buổi.","updated":"2026-10-01","facts":{"group":"Nền tảng"},"html":"<p>Nhiều người học dồn: tuần trước kỳ thi KIIP hay TOPIK thì ngồi cả tối đọc lại toàn bộ từ vựng. Học xong thấy nhớ, vài tuần sau quên gần hết. Cùng một lượng thời gian, chia ra nhiều buổi cách nhau thường giúp nhớ lâu hơn. Cách này gọi là ôn ngắt quãng (spaced practice, distributed practice).</p>\\n<h2 id=\\"tri-nho-giam-theo-thoi-gian\\">Trí nhớ giảm theo thời gian</h2>\\n<p>Cuối thế kỷ 19, Hermann Ebbinghaus tự học các danh sách âm tiết vô nghĩa rồi đo xem sau một khoảng thời gian thì học lại mất bao lâu. Ông thấy lượng nhớ giảm nhanh lúc đầu, rồi chậm dần. Đường giảm này gọi là đường cong quên.</p>\\n<p>Năm 2015, Murre và Dros lặp lại thí nghiệm: một người học các danh sách tổng cộng 70 giờ, rồi học lại sau 20 phút, 1 giờ, 9 giờ, 1 ngày, 2 ngày hoặc 31 ngày. Kết quả gần giống số liệu gốc của Ebbinghaus.</p>\\n<p>Cần nói rõ phạm vi: cả hai nghiên cứu chỉ có một người học, tài liệu là âm tiết vô nghĩa. Nó cho thấy ý chính là không ôn thì quên, không cho con số chính xác về việc bạn sẽ quên bao nhiêu từ tiếng Hàn sau một tuần.</p>\\n<h2 id=\\"on-cach-quang-nho-lau-hon-hoc-don\\">Ôn cách quãng nhớ lâu hơn học dồn</h2>\\n<p>Cepeda và cộng sự (2006) làm một phân tích gộp trên các nghiên cứu về ôn ngắt quãng với nhiệm vụ nhớ lại thông tin bằng lời (từ, câu, sự kiện). Họ tìm được 839 phép đo trong 317 thí nghiệm, từ 184 bài báo. Họ so sánh học dồn liền một lúc với học chia thành nhiều lần, và so sánh khoảng cách ngắn với khoảng cách dài hơn.</p>\\n<p>Năm 2013, Dunlosky và cộng sự đánh giá 10 kỹ thuật học phổ biến. Chỉ hai kỹ thuật được xếp mức &quot;hữu ích cao&quot;: tự kiểm tra (practice testing) và ôn ngắt quãng. Lý do: hai cách này có lợi cho người học ở nhiều độ tuổi, nhiều trình độ và nhiều loại nội dung. Đọc lại (rereading) và tô đậm, gạch chân bị xếp mức hữu ích thấp.</p>\\n<p>Việc nên làm: thay vì ôn một bài 60 phút trong một tối, chia thành ba lần 20 phút ở ba ngày khác nhau.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — phân tích gộp hàng trăm thí nghiệm và bài tổng quan lớn đều cùng kết luận. Phần lớn nghiên cứu là học thông tin bằng lời trong phòng thí nghiệm hoặc lớp học.</p>\\n<h2 id=\\"khoang-cach-bao-lau-la-hop-ly\\">Khoảng cách bao lâu là hợp lý</h2>\\n<p>Không có một khoảng cách đúng cho mọi trường hợp. Cepeda và cộng sự (2006) thấy khoảng cách giữa các lần học cho kết quả tốt nhất tăng lên khi thời điểm cần nhớ (ví dụ ngày thi) ở xa hơn.</p>\\n<p>Nghiên cứu năm 2008 của cùng nhóm kiểm tra điều này trên hơn 1.350 người. Họ học một bộ kiến thức sự kiện, ôn lại sau một khoảng từ ngay lập tức đến 3,5 tháng, rồi làm bài kiểm tra cuối sau thêm tối đa 1 năm. Kết quả: khi tăng khoảng cách ôn, điểm lúc đầu tăng rồi giảm dần. Bài kiểm tra càng xa thì khoảng cách ôn tốt nhất càng dài. Nhưng tính theo tỉ lệ, nó giảm dần: khoảng 20–40% thời gian đến bài kiểm tra nếu bài kiểm tra cách 1 tuần, còn khoảng 5–10% nếu cách 1 năm.</p>\\n<p>Áp dụng thô: còn khoảng một tháng nữa thi thì nên ôn lại sau vài ngày đến khoảng một tuần, thay vì ôn ngay hôm sau rồi bỏ. Muốn nhớ từ vựng cả năm thì cần ôn lại cách nhau vài tuần, không chỉ vài ngày.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — một nghiên cứu lớn, được phân tích gộp ủng hộ về hướng chung. Tài liệu là kiến thức sự kiện, chỉ có hai lần học, nên các tỉ lệ 20–40% và 5–10% là gần đúng, không phải công thức cho mọi môn.</p>\\n<h2 id=\\"mot-lich-on-thuong-dung\\">Một lịch ôn thường dùng</h2>\\n<p>Nhiều người và nhiều app thẻ ghi nhớ dùng lịch khoảng cách tăng dần, ví dụ:</p>\\n<ul>\\n<li>Học mới hôm nay.</li>\\n<li>Ôn lần 1 sau 1 ngày.</li>\\n<li>Lần 2 sau 3 ngày.</li>\\n<li>Lần 3 sau 1 tuần.</li>\\n<li>Lần 4 sau 2 tuần, lần 5 sau 1 tháng.</li>\\n</ul>\\n<p>Đây là quy ước thực hành, không phải công thức đã được nghiên cứu chứng minh. Phân tích gộp năm 2006 có xét khoảng cách tăng dần, nhưng điều chắc chắn hơn là phải có khoảng cách và khoảng cách nên dài ra khi bạn cần nhớ lâu hơn. Nhớ dễ thì giãn lịch ra, quên thì rút ngắn lại.</p>\\n<p>Các app thẻ ghi nhớ có lặp lại ngắt quãng (SRS) tự tính ngày ôn cho từng thẻ. Bạn không cần app riêng nào, sổ tay chia cột theo ngày cũng làm được việc này.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — lịch cụ thể như trên là quy ước thực hành, chưa được chứng minh tốt hơn các lịch khác; chỉ nguyên tắc có khoảng cách là có bằng chứng mạnh.</p>\\n<h2 id=\\"on-bang-cach-tu-kiem-tra\\">Ôn bằng cách tự kiểm tra</h2>\\n<p>Ôn ngắt quãng hiệu quả hơn khi mỗi lần ôn là tự kiểm tra thay vì chỉ đọc lại. Mỗi lần ôn, hãy tự hỏi và trả lời trước khi xem đáp án:</p>\\n<ul>\\n<li>Thẻ tiếng Hàn: mặt trước &quot;약속&quot;, mặt sau &quot;lời hẹn, cuộc hẹn&quot;. Che mặt sau, tự nói nghĩa rồi mới lật.</li>\\n<li>Ngữ pháp: tự đặt một câu với cấu trúc, rồi so với ví dụ trong sách.</li>\\n<li>Lập trình: tự trả lời &quot;Trong Java, so sánh nội dung hai <code>String</code> dùng <code>==</code> hay <code>.equals()</code>? Vì sao?&quot; trước khi mở lại bài.</li>\\n</ul>\\n<p>Dunlosky và cộng sự (2013) xếp cả tự kiểm tra và ôn ngắt quãng ở mức hữu ích cao. Ghép hai cách lại: đến hạn ôn thì làm bài kiểm tra nhỏ, không đọc lại.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — cả hai kỹ thuật đều được xếp mức hữu ích cao trong bài tổng quan năm 2013.</p>\\n<h2 id=\\"xen-ke-cac-muc-de-nham\\">Xen kẽ các mục dễ nhầm</h2>\\n<p>Ngữ pháp tiếng Hàn có nhiều cặp gần nghĩa. Ví dụ hai đuôi chỉ lý do:</p>\\n<ul>\\n<li><strong>-아서/어서</strong>: 비가 와서 늦었어요. (Vì trời mưa nên tôi đến muộn.) Không dùng với câu mệnh lệnh, rủ rê.</li>\\n<li><strong>-(으)니까</strong>: 비가 오니까 우산을 가져가세요. (Trời mưa nên hãy mang ô theo.) Dùng được với mệnh lệnh.</li>\\n</ul>\\n<p>Học xong -아서/어서 cả buổi rồi hôm sau học -(으)니까 cả buổi thì dễ thấy mình đã hiểu. Khi phải chọn giữa hai đuôi, nhiều người vẫn chọn sai. Cách khác là xen kẽ: trộn câu của cả hai đuôi vào cùng một bài luyện, mỗi câu phải tự quyết định dùng đuôi nào.</p>\\n<p>Kornell và Bjork (2008) cho người tham gia học tranh của nhiều hoạ sĩ, xếp liền theo từng hoạ sĩ hoặc xen kẽ giữa các hoạ sĩ. Nhóm xen kẽ nhận ra hoạ sĩ của tranh mới tốt hơn. Đáng chú ý: người tham gia lại đánh giá học liền theo khối là hiệu quả hơn, kể cả sau khi chính điểm của họ cho thấy điều ngược lại. Nghĩa là cảm giác &quot;học trơn tru&quot; không đáng tin.</p>\\n<p>Với lập trình cũng vậy: trộn bài tập về <code>interface</code> và <code>abstract class</code>, hoặc <code>ArrayList</code> và <code>LinkedList</code> trong Java, để phải chọn đúng thứ cho từng tình huống.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — Dunlosky và cộng sự (2013) xếp xen kẽ ở mức hữu ích trung bình vì bằng chứng còn hạn chế. Nghiên cứu của Kornell và Bjork dùng tranh vẽ, chưa phải ngữ pháp tiếng Hàn; áp dụng cho đuôi câu là suy rộng hợp lý, chưa được kiểm chứng trực tiếp.</p>\\n<h2 id=\\"ap-dung-ngay\\">Áp dụng ngay</h2>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"17zuvwy\\"><span>Chia buổi ôn tối nay thành các phần ngắn và đặt lịch ôn lại phần đó sau 1 ngày và sau 3 ngày.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"xbvk7d\\"><span>Biến 10 từ vựng mới thành thẻ hỏi đáp, ôn bằng cách che đáp án.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"76n80c\\"><span>Viết 6 câu trộn lẫn -아서/어서 và -(으)니까, che đuôi câu rồi tự điền.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"17w95p0\\"><span>Ghi ngày thi vào lịch; càng còn xa thì khoảng cách giữa các lần ôn càng dài.</span></label></li>\\n</ul>\\n<h2 id=\\"tren-haechivn\\">Trên HaechiVN</h2>\\n<ul>\\n<li><a href=\\"/my\\">Góc học tập</a>: xem thống kê học, mục tiêu tuần, chuỗi ngày học và mục &quot;điểm ngữ pháp nên ôn&quot;, gợi ý từ phần bạn tự chấm bài tập và câu hỏi kiểm tra của Sơ cấp 1.</li>\\n<li><a href=\\"/ngu-phap\\">Ngữ pháp</a>: tra lại từng cấu trúc khi đến ngày ôn.</li>\\n<li><a href=\\"/books/step1/roadmap\\">Lộ trình KIIP</a>: đánh dấu bài đã học, rồi ghi ngày ôn lại các bài đó vào lịch của bạn.</li>\\n<li><a href=\\"/java\\">Khoá Java</a> và <a href=\\"/it\\">Khoá C#</a>: với những bài có câu hỏi kiểm tra, làm lại câu hỏi của bài cũ thay vì chỉ đọc lại.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://doi.org/10.1371/journal.pone.0120644\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Murre &amp; Dros (2015). Replication and Analysis of Ebbinghaus&#39; Forgetting Curve. PLOS ONE</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1037/0033-2909.132.3.354\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Cepeda, Pashler, Vul, Wixted &amp; Rohrer (2006). Distributed practice in verbal recall tasks: A review and quantitative synthesis. Psychological Bulletin</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1111/j.1467-9280.2008.02209.x\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Cepeda, Vul, Rohrer, Wixted &amp; Pashler (2008). Spacing Effects in Learning: A Temporal Ridgeline of Optimal Retention. Psychological Science</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1177/1529100612453266\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Dunlosky, Rawson, Marsh, Nathan &amp; Willingham (2013). Improving Students&#39; Learning With Effective Learning Techniques. Psychological Science in the Public Interest</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1111/j.1467-9280.2008.02127.x\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Kornell &amp; Bjork (2008). Learning Concepts and Categories: Is Spacing the &quot;Enemy of Induction&quot;? Psychological Science</a> <span class=\\"source-domain\\">doi.org</span></li>\\n</ul>","headings":[{"id":"tri-nho-giam-theo-thoi-gian","text":"Trí nhớ giảm theo thời gian","level":2},{"id":"on-cach-quang-nho-lau-hon-hoc-don","text":"Ôn cách quãng nhớ lâu hơn học dồn","level":2},{"id":"khoang-cach-bao-lau-la-hop-ly","text":"Khoảng cách bao lâu là hợp lý","level":2},{"id":"mot-lich-on-thuong-dung","text":"Một lịch ôn thường dùng","level":2},{"id":"on-bang-cach-tu-kiem-tra","text":"Ôn bằng cách tự kiểm tra","level":2},{"id":"xen-ke-cac-muc-de-nham","text":"Xen kẽ các mục dễ nhầm","level":2},{"id":"ap-dung-ngay","text":"Áp dụng ngay","level":2},{"id":"tren-haechivn","text":"Trên HaechiVN","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":4},{"slug":"nam-lam-tuong-ve-viec-hoc","title":"Năm lầm tưởng phổ biến về việc học","summary":"Năm niềm tin quen thuộc về cách học, nghiên cứu nói gì về từng điều và nên làm gì thay thế.","updated":"2026-10-01","facts":{"group":"Nền tảng"},"html":"<p>Nhiều cách học được truyền tai nhau vì nghe hợp lý hoặc vì cảm giác lúc học rất tốt. Một số trong đó đã được kiểm tra kỹ và kết quả không như ta nghĩ. Bài này điểm qua năm điều hay gặp, nghiên cứu nói gì, và nên làm gì thay thế.</p>\\n<h2 id=\\"lam-tuong-1-phai-hoc-dung-phong-cach-cua-minh\\">Lầm tưởng 1: Phải học đúng &quot;phong cách&quot; của mình</h2>\\n<p>Nhiều người được làm bài trắc nghiệm rồi xếp mình vào nhóm &quot;học bằng mắt&quot;, &quot;học bằng tai&quot; hay &quot;học bằng vận động&quot;. Ý tưởng đi kèm là: dạy và học theo đúng nhóm đó thì sẽ học tốt hơn. Giới nghiên cứu gọi đây là giả thuyết khớp (meshing hypothesis).</p>\\n<p>Năm 2008, Pashler, McDaniel, Rohrer và Bjork xem lại các nghiên cứu về chủ đề này. Họ chỉ ra rằng muốn chứng minh giả thuyết khớp, cần một kiểu thí nghiệm cụ thể: chia người học theo phong cách, chia ngẫu nhiên vào các cách dạy khác nhau, rồi cho cùng một bài kiểm tra. Kết quả phải cho thấy mỗi nhóm học tốt nhất với cách dạy hợp với nhóm mình. Nhóm tác giả gần như không tìm thấy bằng chứng cho kiểu kết quả đó. Rất ít nghiên cứu dùng đúng thiết kế này, và trong số đó có vài nghiên cứu cho kết quả ngược với giả thuyết.</p>\\n<p>Điều có thật: người ta có sở thích về cách nhận thông tin, và có khác biệt về năng lực. Nhưng thích một cách không có nghĩa là học bằng cách đó hiệu quả hơn.</p>\\n<p><strong>Làm gì thay thế:</strong> chọn cách trình bày theo nội dung, không theo &quot;phong cách&quot;. Học phát âm tiếng Hàn thì phải nghe. Học bảng chữ 한글 (Hangul) thì nhìn mặt chữ và tự viết. Học vòng lặp <code>for</code> trong Java thì gõ code và chạy thử.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — bài tổng quan trên tạp chí Psychological Science in the Public Interest không tìm thấy bằng chứng đủ để áp dụng. Nhóm tác giả cũng nói nhiều phiên bản của lý thuyết này chưa từng được kiểm tra đúng cách, nên chưa thể kết luận cho tất cả.</p>\\n<h2 id=\\"lam-tuong-2-doc-nho-10-nghe-nho-20\\">Lầm tưởng 2: &quot;Đọc nhớ 10%, nghe nhớ 20%…&quot;</h2>\\n<p>Bạn có thể đã thấy hình kim tự tháp học tập (learning pyramid): đọc nhớ 10%, nghe nhớ 20%, dạy lại người khác nhớ 90%. Hình này thường được gắn tên Edgar Dale.</p>\\n<p>Letrud và Hernes (2018) truy tìm nguồn gốc các mô hình này trong thư viện số. Họ thấy các phiên bản của kim tự tháp đã xuất hiện trong tranh luận giáo dục hơn 160 năm, nên không thể bắt nguồn từ nghiên cứu thực nghiệm. Họ cũng cho rằng cách hiểu về trí nhớ trong mô hình này lệch xa hiểu biết hiện nay của tâm lý học nhận thức. Masters (2013) xem lại 43 bài báo giáo dục y khoa có dẫn kim tự tháp. Ông thấy nhiều bài dẫn sai nguồn, dẫn vòng, và các bài không thống nhất cả về con số phần trăm. Kết luận của ông là nên tránh dẫn kim tự tháp này.</p>\\n<p><strong>Làm gì thay thế:</strong> đừng chọn cách học theo con số phần trăm. Hỏi câu khác: cách này có bắt mình nhớ lại và dùng kiến thức không? Dạy lại cho bạn bè có thể có ích vì bạn phải tự nhớ và giải thích, không phải vì nó &quot;nhớ 90%&quot;.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — hai bài truy nguồn độc lập cho thấy các con số không có cơ sở nghiên cứu. Điều này không có nghĩa là mọi hoạt động trong hình đều vô ích; chỉ là thứ tự và con số không có căn cứ.</p>\\n<h2 id=\\"lam-tuong-3-doc-lai-va-to-dam-la-cach-on-tot\\">Lầm tưởng 3: Đọc lại và tô đậm là cách ôn tốt</h2>\\n<p>Đọc lại bài và tô màu câu quan trọng là cách rất nhiều người dùng. Lúc đọc lại, mọi thứ trông quen nên ta có cảm giác đã nhớ.</p>\\n<p>Dunlosky và cộng sự (2013) đánh giá mười kỹ thuật học. Họ chọn đọc lại và tô đậm một phần vì sinh viên cho biết dựa vào hai cách này rất nhiều. Cả hai bị xếp vào nhóm hiệu quả thấp: chúng không giúp cải thiện kết quả một cách ổn định. Hai kỹ thuật được xếp hiệu quả cao là tự kiểm tra (practice testing) và ôn ngắt quãng (distributed practice). Nhóm tác giả gợi ý cụ thể: tự kiểm tra thay cho đọc lại.</p>\\n<p><strong>Làm gì thay thế:</strong> sau khi đọc một bài ngữ pháp, gập sách và tự đặt câu. Ví dụ với <code>-(으)ㄹ 수 있다</code> (có thể làm gì), tự viết 3 câu như 한국어를 읽을 수 있어요 (Tôi đọc được tiếng Hàn), rồi mới mở sách so lại.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — bài tổng quan lớn, xét nhiều độ tuổi, loại tài liệu và kiểu bài kiểm tra.</p>\\n<h2 id=\\"lam-tuong-4-hoc-don-dem-truoc-la-du\\">Lầm tưởng 4: Học dồn đêm trước là đủ</h2>\\n<p>Học dồn sát giờ thi cho cảm giác bài còn &quot;nóng&quot; trong đầu. Vấn đề là ta thường cần nhớ lâu hơn một buổi thi: kiến thức của bài 3 KIIP sẽ cần lại ở bài 10, ở kỳ thi cuối khoá và khi nói chuyện thật.</p>\\n<p>Cepeda và cộng sự (2006) phân tích gộp 317 thí nghiệm về học ngắt quãng với nhiệm vụ nhớ lại từ ngữ. Họ thấy khoảng cách giữa các lần ôn và thời điểm kiểm tra cùng quyết định kết quả: muốn nhớ càng lâu thì khoảng cách tốt nhất giữa các lần ôn càng dài. Nói cách khác, học dồn sát giờ thi hợp với việc nhớ vài ngày, không hợp với việc nhớ vài tháng.</p>\\n<p>Giấc ngủ cũng liên quan. Bài tổng quan của Diekelmann và Born (2010) trên Nature Reviews Neuroscience kết luận rằng giấc ngủ giúp củng cố thông tin mới học vào trí nhớ, tùy điều kiện học và thời điểm ngủ. Thức trắng để học dồn là bỏ đi một phần quá trình đó.</p>\\n<p><strong>Làm gì thay thế:</strong> chia cùng số giờ học thành nhiều buổi ngắn trải ra nhiều ngày. Mỗi buổi ôn lại một ít bài cũ. Trước ngày thi, vẫn ngủ đủ.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — với học ngắt quãng (phân tích gộp, phần lớn là nhiệm vụ nhớ từ ngữ). Vừa — với vai trò của giấc ngủ trong việc học: bài tổng quan uy tín, nhưng chủ yếu là nghiên cứu trong phòng thí nghiệm và hiệu quả phụ thuộc điều kiện.</p>\\n<h2 id=\\"lam-tuong-5-vua-hoc-vua-tra-loi-tin-nhan-khong-sao\\">Lầm tưởng 5: Vừa học vừa trả lời tin nhắn không sao</h2>\\n<p>Nhiều người học với điện thoại bật thông báo, cho rằng liếc một chút không ảnh hưởng.</p>\\n<p>Stothart, Mitchum và Yehnert (2015) cho thấy chỉ riêng việc nhận thông báo điện thoại, dù người tham gia không cầm máy lên, cũng làm giảm rõ kết quả ở một nhiệm vụ đòi hỏi tập trung. Mức giảm tương đương mức mà các nghiên cứu khác ghi nhận khi người ta thật sự nghe gọi hoặc nhắn tin.</p>\\n<p>Về thói quen dùng nhiều phương tiện cùng lúc (media multitasking), Ophir, Nass và Wagner (2009) thấy người dùng nhiều dễ bị nhiễu bởi thông tin không liên quan hơn, và chuyển việc kém hơn. Nhưng chín năm sau, bài tổng quan của Uncapher và Wagner (2018), có cùng một tác giả, cho rằng nhìn chung người dùng nhiều có kết quả kém hơn ở một số nhiệm vụ nhận thức, nhưng kết quả chưa thống nhất (nhiều nghiên cứu không thấy khác biệt) và chưa xác định được quan hệ nhân quả.</p>\\n<p><strong>Làm gì thay thế:</strong> khi học, tắt thông báo hoặc để điện thoại ở phòng khác. Đặt một khoảng học cố định, độ dài tùy bạn, hết khoảng đó mới xem tin nhắn.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — với tác hại tức thời của thông báo (thí nghiệm trên một nhiệm vụ chú ý, chưa phải trên việc học ngôn ngữ). Còn tranh luận — với việc thói quen đa nhiệm lâu dài làm giảm khả năng tập trung.</p>\\n<h2 id=\\"ap-dung-ngay\\">Áp dụng ngay</h2>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"8ydtef\\"><span>Thôi chọn cách học theo &quot;phong cách&quot;; chọn theo nội dung cần học.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"545kc1\\"><span>Sau mỗi bài đọc, gập sách và tự viết lại 3 ý hoặc 3 câu ví dụ trước khi xem lại.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1qnuk9j\\"><span>Chia lịch ôn tuần này thành nhiều buổi ngắn, mỗi buổi ôn lại một ít bài cũ.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1xiw0ds\\"><span>Tắt thông báo điện thoại trong lúc học.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1xjann2\\"><span>Đêm trước ngày thi vẫn ngủ đủ thay vì thức trắng.</span></label></li>\\n</ul>\\n<h2 id=\\"tren-haechivn\\">Trên HaechiVN</h2>\\n<ul>\\n<li><a href=\\"/my\\">Góc học tập</a>: đặt mục tiêu tuần, theo dõi chuỗi ngày học và xem các điểm ngữ pháp được gợi ý ôn lại.</li>\\n<li><a href=\\"/books/step1/roadmap\\">Lộ trình KIIP</a>: làm bài tập rồi tự chấm bằng đáp án của sách, thay cho việc đọc lại. Sơ cấp 1 còn có câu hỏi chấm tự động trong trình đọc.</li>\\n<li><a href=\\"/exam/topik-i\\">Luyện thi TOPIK</a>: tự kiểm tra bằng đề luyện.</li>\\n<li><a href=\\"/cam-nang/hoc-tap\\">Học hiệu quả</a>: đọc thêm &quot;Tự kiểm tra thay vì đọc lại&quot; và &quot;Ôn ngắt quãng&quot;.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://doi.org/10.1111/j.1539-6053.2009.01038.x\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Pashler, McDaniel, Rohrer &amp; Bjork (2008). Learning Styles: Concepts and Evidence. Psychological Science in the Public Interest</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1080/2331186X.2018.1518638\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Letrud &amp; Hernes (2018). Excavating the origins of the learning pyramid myths. Cogent Education</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.3109/0142159X.2013.800636\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Masters (2013). Edgar Dale&#39;s Pyramid of Learning in medical education: A literature review. Medical Teacher</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1177/1529100612453266\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Dunlosky, Rawson, Marsh, Nathan &amp; Willingham (2013). Improving Students&#39; Learning With Effective Learning Techniques. Psychological Science in the Public Interest</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1037/0033-2909.132.3.354\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Cepeda, Pashler, Vul, Wixted &amp; Rohrer (2006). Distributed practice in verbal recall tasks: A review and quantitative synthesis. Psychological Bulletin</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1038/nrn2762\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Diekelmann &amp; Born (2010). The memory function of sleep. Nature Reviews Neuroscience</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1037/xhp0000100\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stothart, Mitchum &amp; Yehnert (2015). The attentional cost of receiving a cell phone notification. Journal of Experimental Psychology: Human Perception and Performance</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1073/pnas.0903620106\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Ophir, Nass &amp; Wagner (2009). Cognitive control in media multitaskers. PNAS</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1073/pnas.1611612115\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Uncapher &amp; Wagner (2018). Minds and brains of media multitaskers: Current findings and future directions. PNAS</a> <span class=\\"source-domain\\">doi.org</span></li>\\n</ul>","headings":[{"id":"lam-tuong-1-phai-hoc-dung-phong-cach-cua-minh","text":"Lầm tưởng 1: Phải học đúng \\"phong cách\\" của mình","level":2},{"id":"lam-tuong-2-doc-nho-10-nghe-nho-20","text":"Lầm tưởng 2: \\"Đọc nhớ 10%, nghe nhớ 20%…\\"","level":2},{"id":"lam-tuong-3-doc-lai-va-to-dam-la-cach-on-tot","text":"Lầm tưởng 3: Đọc lại và tô đậm là cách ôn tốt","level":2},{"id":"lam-tuong-4-hoc-don-dem-truoc-la-du","text":"Lầm tưởng 4: Học dồn đêm trước là đủ","level":2},{"id":"lam-tuong-5-vua-hoc-vua-tra-loi-tin-nhan-khong-sao","text":"Lầm tưởng 5: Vừa học vừa trả lời tin nhắn không sao","level":2},{"id":"ap-dung-ngay","text":"Áp dụng ngay","level":2},{"id":"tren-haechivn","text":"Trên HaechiVN","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":5},{"slug":"giu-nhip-hoc-deu","title":"Giữ nhịp học đều mỗi ngày","summary":"Dùng mục tiêu nhỏ, kế hoạch \\"nếu–thì\\" và việc ghi lại tiến độ để học tiếng Hàn hay lập trình đều đặn, kể cả khi lịch làm việc bận.","updated":"2026-10-01","facts":{"group":"Nền tảng"},"html":"<p>Nhiều người bắt đầu rất hăng: cuối tuần ngồi học ba tiếng, rồi cả tuần sau không mở sách. Người làm ca ở Hàn hay người học lập trình sau giờ làm thường gặp cảnh này, vì giờ giấc thay đổi và lúc rảnh thì đã mệt. Vấn đề thường không nằm ở quyết tâm mà ở chỗ chưa có cách biến ý định thành việc làm lặp lại.</p>\\n<h2 id=\\"muc-tieu-nho-moi-ngay-thay-vi-buoi-lon-that-thuong\\">Mục tiêu nhỏ mỗi ngày thay vì buổi lớn thất thường</h2>\\n<p>&quot;Tuần này học xong bài 5 KIIP&quot; là một mục tiêu lớn, dễ bị dời đến cuối tuần rồi bỏ. &quot;Mỗi ngày đọc một trang bài 5 và làm hai câu bài tập&quot; nhỏ hơn, làm được cả hôm mệt.</p>\\n<p>Có hai lý do để chọn cách nhỏ và đều. Thứ nhất, chia việc học thành nhiều lần cách nhau giúp nhớ lâu hơn học dồn (xem bài <a href=\\"/cam-nang/hoc-tap/on-ngat-quang\\">Ôn ngắt quãng thay vì học dồn</a>). Thứ hai, thói quen hình thành qua việc lặp lại cùng một hành động trong cùng một bối cảnh. Trong nghiên cứu của Lally và cộng sự (2010) nêu ở phần sau, người thực hiện hành vi đều đặn hơn thì đường tăng thói quen của họ khớp mô hình tốt hơn.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — lợi ích của việc chia nhỏ để nhớ lâu có bằng chứng mạnh. Việc &quot;nhỏ và đều thì dễ duy trì hơn lớn và thất thường&quot; là suy ra từ nghiên cứu về thói quen, chưa có thí nghiệm so sánh trực tiếp hai cách này trên người học ngoại ngữ.</p>\\n<h2 id=\\"ke-hoach-neu-thi\\">Kế hoạch &quot;nếu–thì&quot;</h2>\\n<p>Ý định chung như &quot;Tôi sẽ chăm học tiếng Hàn&quot; thường không đủ. Gollwitzer (1999) tổng kết về một dạng kế hoạch cụ thể do ông đề xuất, gọi là implementation intention (ý định thực hiện), có cấu trúc: &quot;Khi gặp tình huống X, tôi sẽ làm Y&quot;. Kế hoạch này gắn sẵn hành động với một tình huống, để khi tình huống đến thì không cần cân nhắc lại có học hay không.</p>\\n<p>Ví dụ:</p>\\n<ul>\\n<li>&quot;Sau bữa tối, tôi học 15 phút ngữ pháp.&quot;</li>\\n<li>&quot;Khi lên xe buýt về ký túc xá sau ca, tôi ôn 10 thẻ từ vựng.&quot;</li>\\n<li>&quot;Khi tắt máy tính công ty, tôi mở IDE và làm một bài tập Java trước khi về.&quot;</li>\\n</ul>\\n<p>Gollwitzer và Sheeran (2006) làm phân tích gộp trên 94 phép kiểm tra độc lập. Kết quả: người lập kế hoạch &quot;nếu–thì&quot; đạt mục tiêu tốt hơn, với mức ảnh hưởng trung bình đến lớn (d = 0,65).</p>\\n<p>Kế hoạch tốt cần tình huống cụ thể. &quot;Khi rảnh, tôi sẽ học&quot; quá mơ hồ vì lúc nào cũng có thể coi là chưa rảnh. &quot;Sau khi đánh răng buổi tối&quot; thì rõ ràng.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — phân tích gộp gần một trăm phép kiểm tra cho thấy hiệu quả ổn định. Các nghiên cứu này đo nhiều loại mục tiêu, không riêng việc học ngoại ngữ hay lập trình; áp dụng cho việc học là suy rộng hợp lý.</p>\\n<h2 id=\\"thoi-quen-can-thoi-gian-va-moi-nguoi-mot-khac\\">Thói quen cần thời gian, và mỗi người một khác</h2>\\n<p>Lally, van Jaarsveld, Potts và Wardle (2010) theo dõi 96 người tình nguyện, phần lớn là học viên sau đại học, tuổi trung bình 27. Mỗi người chọn một hành vi ăn uống hoặc vận động để làm hằng ngày trong cùng một bối cảnh, ví dụ &quot;sau bữa sáng&quot;, trong 12 tuần. Mỗi ngày họ tự chấm mức độ hành vi đó đã thành tự động.</p>\\n<p>Có 82 người đủ dữ liệu để phân tích, và mô hình khớp tốt với 39 người. Trong nhóm 39 người này, thời gian trung vị để mức tự động đạt 95% mức tối đa là 66 ngày. Khoảng dao động từ 18 đến 254 ngày. Con số 254 ngày là dự đoán từ mô hình, vì nghiên cứu chỉ kéo dài 84 ngày.</p>\\n<p>Ý chính cho người học: không có một con số cố định cho mọi người. Câu &quot;21 ngày là hình thành thói quen&quot; hay được nhắc trên mạng. Gardner, Lally và Wardle (2012) gọi đó là một quan niệm sai, có lẽ bắt nguồn từ quan sát giai thoại về bệnh nhân phẫu thuật thẩm mỹ, không phải từ nghiên cứu về thói quen. Nếu sau ba tuần việc học vẫn còn phải cố, đó là chuyện bình thường.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — một nghiên cứu theo dõi kỹ trong đời thực, nhưng mẫu nhỏ, phần lớn là sinh viên, hành vi là ăn uống và vận động đơn giản, mức tự động do người tham gia tự đánh giá. Việc học một bài ngữ pháp phức tạp hơn uống một cốc nước, nên thời gian có thể khác.</p>\\n<h2 id=\\"lo-mot-ngay-khong-lam-hong-ca-qua-trinh\\">Lỡ một ngày không làm hỏng cả quá trình</h2>\\n<p>Nhiều người bỏ hẳn sau khi lỡ vài hôm vì nghĩ &quot;chuỗi đã đứt rồi&quot;. Lally và cộng sự (2010) kiểm tra điều này. Ngay sau một lần bỏ lỡ, điểm tự động hôm sau thấp hơn một chút nhưng không có ý nghĩa thống kê, và không thấy ảnh hưởng lâu dài từ một lần bỏ lỡ đơn lẻ.</p>\\n<p>Với người làm ca ở Hàn theo diện EPS, những tuần tăng ca hay đổi ca đêm khó tránh. Hôm đó có thể bỏ, hoặc làm phiên bản tối thiểu, ví dụ đọc lại năm từ vựng. Điều quan trọng là quay lại kế hoạch &quot;nếu–thì&quot; vào ngày hôm sau.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — kết quả từ cùng một nghiên cứu ở trên, chỉ xét ảnh hưởng của một lần bỏ lỡ đơn lẻ. Nghiên cứu không cho biết bỏ nhiều ngày liền thì ảnh hưởng thế nào.</p>\\n<h2 id=\\"gan-viec-hoc-vao-thoi-quen-san-co\\">Gắn việc học vào thói quen sẵn có</h2>\\n<p>Trong nghiên cứu của Lally, mỗi người chọn một bối cảnh cố định đi kèm hành vi mới, như &quot;sau bữa sáng&quot;. Đây cũng là cách dễ nhất để chọn phần &quot;nếu&quot; trong kế hoạch: lấy một việc ngày nào cũng làm.</p>\\n<ul>\\n<li>Người làm ca: ca thay đổi nên giờ đồng hồ không ổn định. Thay vì &quot;học lúc 8 giờ tối&quot;, dùng mốc gắn với việc chắc chắn có: &quot;sau khi ăn cơm sau ca&quot;, &quot;trong 20 phút đi xe về&quot;. Ca ngày hay ca đêm thì mốc này vẫn còn.</li>\\n<li>Người học Java sau giờ làm: &quot;sau khi pha cà phê buổi tối, tôi mở bài học trong 20 phút&quot;. Nếu về nhà là không muốn mở máy, có thể chọn mốc ở công ty, ngay trước khi rời bàn.</li>\\n</ul>\\n<p><strong>Mức bằng chứng:</strong> vừa — gắn hành vi mới với một bối cảnh cố định là thiết kế của nghiên cứu Lally và đúng với định nghĩa kế hoạch &quot;nếu–thì&quot; của Gollwitzer, nhưng chưa có thí nghiệm riêng so sánh mốc thời gian với mốc thói quen cho việc học tiếng.</p>\\n<h2 id=\\"ghi-lai-tien-do\\">Ghi lại tiến độ</h2>\\n<p>Harkin và cộng sự (2016) làm phân tích gộp 138 nghiên cứu, tổng cộng 19.951 người tham gia. Các nghiên cứu này chia ngẫu nhiên người tham gia vào nhóm được khuyến khích theo dõi tiến độ và nhóm đối chứng. Kết quả: theo dõi tiến độ giúp đạt mục tiêu tốt hơn (d = 0,40). Hiệu quả lớn hơn khi tiến độ được ghi lại cụ thể (viết ra, ghi lại) và khi kết quả được báo cáo hoặc công khai với người khác.</p>\\n<p>Áp dụng: ghi số phút học mỗi ngày, đánh dấu bài đã xong, hoặc báo tiến độ hằng tuần cho một người bạn cùng học.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — phân tích gộp lớn với các thử nghiệm phân bổ ngẫu nhiên. Các nghiên cứu trong phân tích gộp đo nhiều loại mục tiêu, không riêng việc học, nên áp dụng cho việc học là suy rộng.</p>\\n<h2 id=\\"ap-dung-ngay\\">Áp dụng ngay</h2>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"nkepaa\\"><span>Viết một câu &quot;nếu–thì&quot; cho việc học, với phần &quot;nếu&quot; là một việc ngày nào cũng làm.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"gch101\\"><span>Đặt mục tiêu ngày nhỏ đến mức hôm mệt vẫn làm được, ví dụ 15 phút hoặc 10 thẻ từ vựng.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"svtabc\\"><span>Chuẩn bị sẵn một &quot;phiên bản tối thiểu&quot; cho hôm tăng ca, ví dụ đọc lại 5 từ.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"x9scoj\\"><span>Ghi số phút học mỗi ngày trong tuần này, cuối tuần xem lại.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1fb3sha\\"><span>Nếu lỡ một ngày, quay lại kế hoạch vào ngày hôm sau, không đợi đầu tuần.</span></label></li>\\n</ul>\\n<h2 id=\\"tren-haechivn\\">Trên HaechiVN</h2>\\n<ul>\\n<li><a href=\\"/my\\">Góc học tập</a>: xem số phút đã học, đặt mục tiêu số phút mỗi tuần, theo dõi chuỗi ngày học và đọc lời nhắn ngắn kèm một việc nên làm tiếp.</li>\\n<li><a href=\\"/books/step1/roadmap\\">Lộ trình KIIP</a>: đánh dấu từng bài KIIP đã học để thấy tiến độ.</li>\\n<li><a href=\\"/video\\">Phim có phụ đề Hàn–Việt</a>: một lựa chọn cho phiên bản tối thiểu hôm mệt.</li>\\n<li>Bài liên quan: <a href=\\"/cam-nang/hoc-tap/tu-kiem-tra-thay-vi-doc-lai\\">Tự kiểm tra thay vì đọc lại</a>, <a href=\\"/cam-nang/hoc-tap/on-ngat-quang\\">Ôn ngắt quãng thay vì học dồn</a>, <a href=\\"/cam-nang/hoc-tap/nam-lam-tuong-ve-viec-hoc\\">Năm lầm tưởng phổ biến về việc học</a>.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://doi.org/10.1037/0003-066X.54.7.493\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Gollwitzer (1999). Implementation intentions: Strong effects of simple plans. American Psychologist</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1016/S0065-2601(06)38002-1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Gollwitzer &amp; Sheeran (2006). Implementation intentions and goal achievement: A meta-analysis of effects and processes. Advances in Experimental Social Psychology</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1002/ejsp.674\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Lally, van Jaarsveld, Potts &amp; Wardle (2010). How are habits formed: Modelling habit formation in the real world. European Journal of Social Psychology</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.3399/bjgp12X659466\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Gardner, Lally &amp; Wardle (2012). Making health habitual: the psychology of &#39;habit-formation&#39; and general practice. British Journal of General Practice</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1037/bul0000025\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Harkin, Webb, Chang, Prestwich, Conner, Kellar, Benn &amp; Sheeran (2016). Does monitoring goal progress promote goal attainment? A meta-analysis of the experimental evidence. Psychological Bulletin</a> <span class=\\"source-domain\\">doi.org</span></li>\\n</ul>","headings":[{"id":"muc-tieu-nho-moi-ngay-thay-vi-buoi-lon-that-thuong","text":"Mục tiêu nhỏ mỗi ngày thay vì buổi lớn thất thường","level":2},{"id":"ke-hoach-neu-thi","text":"Kế hoạch \\"nếu–thì\\"","level":2},{"id":"thoi-quen-can-thoi-gian-va-moi-nguoi-mot-khac","text":"Thói quen cần thời gian, và mỗi người một khác","level":2},{"id":"lo-mot-ngay-khong-lam-hong-ca-qua-trinh","text":"Lỡ một ngày không làm hỏng cả quá trình","level":2},{"id":"gan-viec-hoc-vao-thoi-quen-san-co","text":"Gắn việc học vào thói quen sẵn có","level":2},{"id":"ghi-lai-tien-do","text":"Ghi lại tiến độ","level":2},{"id":"ap-dung-ngay","text":"Áp dụng ngay","level":2},{"id":"tren-haechivn","text":"Trên HaechiVN","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":5},{"slug":"di-het-lo-trinh-kiip","title":"Đi hết lộ trình KIIP từ 0단계 đến 5단계","summary":"Cấu trúc các giai đoạn KIIP theo nguồn chính thức của Bộ Tư pháp, cách bài đánh giá đầu vào xếp lớp, các bài thi cuối giai đoạn, và cách học từng giai đoạn cho chắc.","updated":"2026-10-01","facts":{"group":"Học tiếng"},"html":"<p>Nhiều người đăng ký KIIP (사회통합프로그램, chương trình hội nhập xã hội) mà không rõ mình phải học bao nhiêu giờ, thi những bài nào, và học xong thì dùng vào việc gì. Bài này tóm tắt lộ trình theo nguồn chính thức, rồi gợi ý cách học từng chặng.</p>\\n<h2 id=\\"cac-giai-doan-va-so-gio-hoc\\">Các giai đoạn và số giờ học</h2>\\n<p>KIIP gồm hai phần: 한국어와 한국문화 (tiếng Hàn và văn hoá Hàn, giai đoạn 0–4) và 한국사회이해 (hiểu biết xã hội Hàn Quốc, giai đoạn 5). Theo bảng tóm tắt trong thông báo của Bộ Tư pháp (법무부 공고 제2024-478호, ngày 15/11/2024):</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Giai đoạn</th>\\n<th>Khoá</th>\\n<th>Số giờ</th>\\n<th>Bài thi cuối</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>0단계</td>\\n<td>기초 (cơ bản)</td>\\n<td>15</td>\\n<td>Không có</td>\\n</tr>\\n<tr>\\n<td>1단계</td>\\n<td>초급1 (sơ cấp 1)</td>\\n<td>100</td>\\n<td>1단계평가</td>\\n</tr>\\n<tr>\\n<td>2단계</td>\\n<td>초급2 (sơ cấp 2)</td>\\n<td>100</td>\\n<td>2단계평가</td>\\n</tr>\\n<tr>\\n<td>3단계</td>\\n<td>중급1 (trung cấp 1)</td>\\n<td>100</td>\\n<td>3단계평가</td>\\n</tr>\\n<tr>\\n<td>4단계</td>\\n<td>중급2 (trung cấp 2)</td>\\n<td>100</td>\\n<td>중간평가 (thi giữa kỳ)</td>\\n</tr>\\n<tr>\\n<td>5단계 기본과정</td>\\n<td>Khoá cơ bản</td>\\n<td>70</td>\\n<td>영주용 종합평가 (thi tổng hợp cho vĩnh trú)</td>\\n</tr>\\n<tr>\\n<td>5단계 심화과정</td>\\n<td>Khoá nâng cao</td>\\n<td>30</td>\\n<td>귀화용 종합평가 (thi tổng hợp cho nhập tịch)</td>\\n</tr>\\n</tbody></table></div>\\n<p>Cùng thông báo đó ghi phần tiếng Hàn và văn hoá là &quot;từ miễn học đến tối đa 415 giờ&quot;, tùy giai đoạn được xếp. Giai đoạn 5 dạy những điều người nước ngoài cần biết để sống trong xã hội Hàn, theo các mảng xã hội, văn hoá, chính trị, kinh tế, lịch sử, pháp luật, địa lý. Trang KIIP của Bộ Tư pháp (xem năm 2026) cũng ghi: muốn lấy tư cách vĩnh trú cần học 70 giờ 한국사회이해, muốn nhập quốc tịch cần 100 giờ.</p>\\n<p>Giáo trình chính thức theo 사회통합정보망 (socinet, hệ thống thông tin hội nhập xã hội, xem năm 2026): giai đoạn 0 dùng &quot;한국어와 한국문화 기초&quot;, giai đoạn 1–4 lần lượt dùng 초급1, 초급2, 중급1, 중급2, giai đoạn 5 dùng &quot;한국사회 이해&quot; gồm hai cuốn 기본 và 심화.</p>\\n<h2 id=\\"bai-danh-gia-dau-vao-giup-bo-qua-giai-doan\\">Bài đánh giá đầu vào giúp bỏ qua giai đoạn</h2>\\n<p>Người đăng ký chọn một trong các cách xếp giai đoạn trên socinet: bắt đầu từ 0단계, thi 사전평가 (bài đánh giá đầu vào), hoặc xếp theo kết quả liên kết như TOPIK hay visa kết hôn (theo thông báo 법무부 tháng 11/2024). Người bắt đầu từ 0단계 thì không cần thi 사전평가 (theo trang 출입국·외국인정책본부, xem năm 2026).</p>\\n<p>Điểm 사전평가 quyết định giai đoạn được xếp (theo thông báo 법무부 tháng 11/2024):</p>\\n<ul>\\n<li>dưới 3 điểm: 0단계</li>\\n<li>3–20 điểm: 1단계</li>\\n<li>21–40 điểm: 2단계</li>\\n<li>41–60 điểm: 3단계</li>\\n<li>61–80 điểm: 4단계</li>\\n<li>81–100 điểm: 5단계</li>\\n</ul>\\n<p>Riêng người có điểm thi nói (구술) dưới 3 thì bị xếp 0단계, bất kể điểm viết. Kết quả 사전평가 có hiệu lực 2 năm kể từ ngày công bố (theo kiiptest.org, xem năm 2026).</p>\\n<p>Đăng ký 사전평가 trên trang thi kiiptest.org, lệ phí 38.000 won (theo trang KIIP của 법무부, xem năm 2026). Ngoài lệ phí thi, từ giai đoạn 1 trở đi người học nộp học phí (교육 수수료) trực tuyến khi kết thúc mỗi giai đoạn; giai đoạn 0 không thu (theo thông báo 법무부 tháng 11/2024). Thi đầu vào có thể bớt nhiều giờ học, nhưng xếp quá cao so với sức thật thì sẽ đuối ở giai đoạn đó, nên hãy làm bài bằng năng lực thật.</p>\\n<h2 id=\\"len-giai-doan-va-cac-bai-thi\\">Lên giai đoạn và các bài thi</h2>\\n<p>Nguyên tắc chung: học xong khoá và đạt bài thi thì mới lên giai đoạn tiếp theo (theo thông báo 법무부 tháng 11/2024). Bài thi giai đoạn 1–3 do cơ sở đào tạo tổ chức. 중간평가 sau giai đoạn 4 và hai bài 종합평가 sau giai đoạn 5 do Bộ Tư pháp tổ chức, đăng ký trên kiiptest.org.</p>\\n<p>Cần chú ý chuyện chuyên cần. Theo trang hướng dẫn thủ tục của socinet (xem năm 2026), tự ý nghỉ từ 30 ngày trở lên trong lúc học thì bị cho thôi học, và phần đã học ở giai đoạn đó bị huỷ toàn bộ. Nếu buộc phải nghỉ từ 30 ngày vì lý do bất khả kháng (sinh con, điều trị bệnh, việc gia đình), hãy xin tạm dừng (이수정지) trên socinet trong vòng 15 ngày để giữ số giờ đã học.</p>\\n<h2 id=\\"hoan-thanh-kiip-dung-vao-viec-gi\\">Hoàn thành KIIP dùng vào việc gì</h2>\\n<p>Thông báo 법무부 tháng 11/2024 nêu ba nhóm lợi ích, tùy giai đoạn đã hoàn thành: miễn bài thi nhập tịch khi xin nhập quốc tịch; được coi là đáp ứng điều kiện hiểu biết cơ bản khi xin vĩnh trú; được cộng điểm hoặc miễn chứng minh tiếng Hàn khi xin một số tư cách lưu trú khác. Chi tiết cho từng visa có trong các bài:</p>\\n<ul>\\n<li><a href=\\"/cam-nang/visa/f-2-7-cu-tru-theo-diem\\">F-2-7: cư trú theo điểm</a>: điểm tiếng Hàn theo giai đoạn KIIP và điểm cộng khi xong giai đoạn 5.</li>\\n<li><a href=\\"/cam-nang/visa/e-7-4-lao-dong-lanh-nghe\\">E-7-4: lao động lành nghề</a> và <a href=\\"/cam-nang/visa/d-10-tim-viec\\">D-10: tìm việc</a>: điểm theo giai đoạn 2–5.</li>\\n<li><a href=\\"/cam-nang/visa/f-5-vinh-tru\\">F-5: vĩnh trú</a>: giai đoạn 5 và 종합평가.</li>\\n</ul>\\n<h2 id=\\"on-lai-bai-cu-suot-lo-trinh\\">Ôn lại bài cũ suốt lộ trình</h2>\\n<p>Một lộ trình đầy đủ dài hơn 500 giờ, thường kéo dài nhiều học kỳ. Ngữ pháp sơ cấp vẫn xuất hiện trong bài trung cấp và trong bài thi 중간평가, 종합평가. Vì vậy, đừng coi một giai đoạn đã xong là có thể bỏ. Mỗi tuần dành một buổi ngắn ôn lại vài bài của giai đoạn trước, và giãn khoảng cách dần khi đã nhớ chắc. Cách làm chi tiết có trong bài <a href=\\"/cam-nang/hoc-tap/on-ngat-quang\\">Ôn ngắt quãng thay vì học dồn</a>.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — Dunlosky và cộng sự (2013) xếp ôn ngắt quãng ở mức hữu ích cao; phân tích gộp của Cepeda và cộng sự (2006) cùng hướng. Phần lớn nghiên cứu dùng thông tin bằng lời, chưa làm riêng trên người học KIIP.</p>\\n<p>Khi ôn, hãy che đáp án rồi tự trả lời, đừng chỉ đọc lại. Ví dụ: che phần tiếng Hàn của bài khoá, nhìn nghĩa tiếng Việt và tự nói lại câu tiếng Hàn. Xem bài <a href=\\"/cam-nang/hoc-tap/tu-kiem-tra-thay-vi-doc-lai\\">Tự kiểm tra thay vì đọc lại</a>.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — Dunlosky và cộng sự (2013) cũng xếp tự kiểm tra ở mức hữu ích cao; Roediger và Karpicke (2006) cho thấy làm bài kiểm tra giúp nhớ lâu hơn đọc lại, trên sinh viên học đoạn văn.</p>\\n<h2 id=\\"cach-hoc-tung-chang\\">Cách học từng chặng</h2>\\n<p>Các gợi ý dưới đây áp dụng những nguyên tắc ở trên (ôn ngắt quãng, tự kiểm tra, xen kẽ, từ cùng gốc) vào nội dung từng giai đoạn.</p>\\n<p><strong>Giai đoạn 0–1: chữ Hàn và phát âm.</strong> Giai đoạn 0 chỉ có 15 giờ, nên cần tự luyện thêm 한글 (chữ Hàn) cho đến khi đọc được không cần phiên âm. Nghe và nói theo từng câu ngắn để phân biệt các bộ ba phụ âm thường, bật hơi, căng như ㄱ/ㅋ/ㄲ, và 받침 (phụ âm cuối) ㄴ với ㅇ.</p>\\n<p><strong>Giai đoạn 2: chắc ngữ pháp nền.</strong> Lập một danh sách các đuôi câu và tiểu từ đã học, mỗi mục kèm một câu tự đặt. Trộn các cấu trúc dễ nhầm vào cùng một lần ôn để phải tự chọn, như bài <a href=\\"/cam-nang/hoc-tap/on-ngat-quang\\">Ôn ngắt quãng</a> mô tả.</p>\\n<p><strong>Giai đoạn 3–4: đọc bài dài hơn.</strong> Bài khoá trung cấp dài và nhiều từ Hán Hàn (한자어). Đọc trọn bài một lần để nắm ý, sau đó mới tra từ và đọc lại từng câu. Tập tóm tắt mỗi bài trong ba câu tiếng Hàn. Với từ Hán Hàn, thử đoán nghĩa qua âm Hán-Việt rồi tra lại, như trong bài <a href=\\"/cam-nang/hoc-tap/dung-han-viet-hoc-tu-han-han\\">Dùng âm Hán-Việt để học từ Hán Hàn</a>.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — sự tương ứng giữa từ Hán Hàn và Hán-Việt được mô tả trong nghiên cứu đối chiếu; lợi ích của việc học từ cùng gốc được ghi nhận chủ yếu trên ngôn ngữ châu Âu, chưa đo trực tiếp với người Việt học tiếng Hàn.</p>\\n<p><strong>Giai đoạn 5: nội dung xã hội và từ vựng chuyên đề.</strong> Đây là phần kiến thức, không chỉ là tiếng. Mỗi bài nên gom riêng từ vựng theo chủ đề: pháp luật (법, 권리, 의무), lịch sử (조선, 독립), chính trị (선거, 국회). Phần lớn là từ Hán Hàn nên âm Hán-Việt giúp được nhiều: 선거 là &quot;tuyển cử&quot;, 국회 là &quot;quốc hội&quot;. Sau mỗi bài, tự viết ra vài ý chính rồi mới so với sách.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — từng gợi ý dựa trên các nguyên tắc có nghiên cứu nêu trong bài và các bài liên quan; cách chia theo giai đoạn là đề xuất, chưa có nghiên cứu riêng về KIIP.</p>\\n<h2 id=\\"ap-dung-ngay\\">Áp dụng ngay</h2>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"191var\\"><span>Xem lại bảng điểm 사전평가 ở trên và quyết định nên thi đầu vào hay bắt đầu từ 0단계.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"r93del\\"><span>Đặt một buổi ôn cố định mỗi tuần cho bài của giai đoạn trước.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1a9gbzd\\"><span>Chọn một bài khoá đã học, che phần tiếng Hàn và tự nói lại từ nghĩa tiếng Việt.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"ublt6d\\"><span>Mở sổ từ vựng theo chủ đề (pháp luật, lịch sử, chính trị) nếu sắp học giai đoạn 5.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1ywcuge\\"><span>Ghi lịch các buổi học để không nghỉ liền nhiều tuần.</span></label></li>\\n</ul>\\n<h2 id=\\"tren-haechivn\\">Trên HaechiVN</h2>\\n<p>Bộ sách KIIP trên HaechiVN ứng với giáo trình chính thức như sau: Sơ cấp 1 là 초급1 (giai đoạn 1), Sơ cấp 2 là 초급2 (giai đoạn 2), Trung cấp 1 là 중급1 (giai đoạn 3), Trung cấp 2 là 중급2 (giai đoạn 4), Hiểu biết xã hội là 한국사회 이해 (giai đoạn 5). Site chưa có sách giai đoạn 0.</p>\\n<ul>\\n<li>Lộ trình theo từng giai đoạn: <a href=\\"/books/step1/roadmap\\">Sơ cấp 1</a>, <a href=\\"/books/step2/roadmap\\">Sơ cấp 2</a>, <a href=\\"/books/step3/roadmap\\">Trung cấp 1</a>, <a href=\\"/books/step4/roadmap\\">Trung cấp 2</a>, <a href=\\"/books/step5/roadmap\\">Hiểu biết xã hội</a>. Đánh dấu bài đã học để theo dõi tiến độ, rồi tự ghi lịch ôn lại các bài cũ.</li>\\n<li>Trình đọc có dịch tiếng Việt từng câu; luyện nói đuổi (shadowing) cho Sơ cấp 1 đến Trung cấp 2.</li>\\n<li>Mọi cấp đều có đáp án của sách để tự chấm; Sơ cấp 1 có thêm câu hỏi kiểm tra chấm tự động.</li>\\n<li><a href=\\"/ngu-phap\\">Ngữ pháp</a>: tra lại cấu trúc của giai đoạn trước khi ôn.</li>\\n<li><a href=\\"/tieng-han\\">Thư viện giáo trình tiếng Hàn</a>: thêm bài đọc cho giai đoạn 3–4.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://www.moj.go.kr/moj/369/subview.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 — 사회통합프로그램</a> <span class=\\"source-domain\\">moj.go.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/immigration/1571/subview.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">출입국·외국인정책본부 — 사회통합프로그램</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n<li><a href=\\"https://www.immigration.go.kr/bbs/moj/184/474732/download.do\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">법무부 공고 제2024-478호 — 이민자 사회통합프로그램 운영기관 모집 공고 (15/11/2024)</a> <span class=\\"source-domain\\">immigration.go.kr</span></li>\\n<li><a href=\\"https://www.socinet.go.kr/soci/contents/PgmApplStep.jsp?q_global_menu_id=S_SIP_SUB03\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">사회통합정보망 — 신청절차</a> <span class=\\"source-domain\\">socinet.go.kr</span></li>\\n<li><a href=\\"https://www.socinet.go.kr/soci/contents/PgmTecrBook.jsp?q_global_menu_id=S_SIP_SUB05\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">사회통합정보망 — 강사 및 교재</a> <span class=\\"source-domain\\">socinet.go.kr</span></li>\\n<li><a href=\\"https://doi.org/10.1177/1529100612453266\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Dunlosky, Rawson, Marsh, Nathan &amp; Willingham (2013). Improving Students&#39; Learning With Effective Learning Techniques. Psychological Science in the Public Interest</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1037/0033-2909.132.3.354\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Cepeda, Pashler, Vul, Wixted &amp; Rohrer (2006). Distributed practice in verbal recall tasks: A review and quantitative synthesis. Psychological Bulletin</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1111/0023-8333.00110\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">De Groot &amp; Keijzer (2000). What is hard to learn is easy to forget: The roles of word concreteness, cognate status, and word frequency in foreign-language vocabulary learning and forgetting. Language Learning</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://www.kiiptest.org/guide/pre-evaluation\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">kiiptest.org — 사전평가 안내</a> <span class=\\"source-domain\\">kiiptest.org</span></li>\\n<li><a href=\\"https://doi.org/10.1111/j.1467-9280.2006.01693.x\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Roediger &amp; Karpicke (2006). Test-enhanced learning: Taking memory tests improves long-term retention. Psychological Science</a> <span class=\\"source-domain\\">doi.org</span></li>\\n</ul>","headings":[{"id":"cac-giai-doan-va-so-gio-hoc","text":"Các giai đoạn và số giờ học","level":2},{"id":"bai-danh-gia-dau-vao-giup-bo-qua-giai-doan","text":"Bài đánh giá đầu vào giúp bỏ qua giai đoạn","level":2},{"id":"len-giai-doan-va-cac-bai-thi","text":"Lên giai đoạn và các bài thi","level":2},{"id":"hoan-thanh-kiip-dung-vao-viec-gi","text":"Hoàn thành KIIP dùng vào việc gì","level":2},{"id":"on-lai-bai-cu-suot-lo-trinh","text":"Ôn lại bài cũ suốt lộ trình","level":2},{"id":"cach-hoc-tung-chang","text":"Cách học từng chặng","level":2},{"id":"ap-dung-ngay","text":"Áp dụng ngay","level":2},{"id":"tren-haechivn","text":"Trên HaechiVN","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":5},{"slug":"chia-thoi-gian-hoc-theo-bon-mang","title":"Chia thời gian học theo bốn mảng","summary":"Dùng khung \\"bốn mảng\\" của Paul Nation để chia thời gian học tiếng Hàn giữa nghe đọc, nói viết, học ngữ pháp từ vựng và luyện độ trôi chảy, thay vì dồn hết vào học bài.","updated":"2026-10-01","facts":{"group":"Học tiếng"},"html":"<p>Nhiều người học tiếng Hàn dành gần hết thời gian để chép từ vựng, học thuộc ngữ pháp và làm bài tập điền chỗ trống, còn rất ít thời gian để nghe đọc cho hiểu hay nói viết để truyền đạt ý. Kết quả thường gặp: biết nhiều quy tắc nhưng nghe không kịp, nói chậm. Paul Nation đề xuất một cách kiểm tra sự cân bằng này: chia việc học thành bốn mảng (four strands).</p>\\n<h2 id=\\"bon-mang-la-gi\\">Bốn mảng là gì</h2>\\n<p>Trong bài &quot;The Four Strands&quot; (2007), Nation xếp mọi hoạt động của một khoá học ngôn ngữ vào bốn mảng:</p>\\n<ol>\\n<li><strong>Tiếp nhận tập trung vào nghĩa</strong> (meaning-focused input): nghe và đọc để hiểu nội dung.</li>\\n<li><strong>Diễn đạt tập trung vào nghĩa</strong> (meaning-focused output): nói và viết để truyền đạt ý cho người khác.</li>\\n<li><strong>Học tập trung vào ngôn ngữ</strong> (language-focused learning): học có chủ đích phát âm, chính tả, từ vựng, ngữ pháp.</li>\\n<li><strong>Phát triển độ trôi chảy</strong> (fluency development): dùng nhanh hơn, nhuần nhuyễn hơn những gì đã biết.</li>\\n</ol>\\n<p>Theo Nation, khoá học cân bằng dành thời gian gần bằng nhau cho bốn mảng, khoảng 25% mỗi mảng, và mảng 3 không nên vượt quá một phần tư.</p>\\n<p>Đây không phải kết quả của một thí nghiệm so sánh &quot;chia đều bốn mảng&quot; với cách chia khác. Nation tổng hợp nhiều hướng nghiên cứu (học qua đọc nhiều, vai trò của việc nói viết, dạy ngữ pháp có chủ đích, luyện tốc độ đọc và nói) thành một nguyên tắc thiết kế khoá học. Chính ông viết rằng chia đều thời gian là một quyết định tùy ý (arbitrary).</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — khung bốn mảng là đề xuất có cơ sở, dựa trên tổng hợp nghiên cứu, phần lớn nghiên cứu được dẫn là về người học tiếng Anh. Tỉ lệ 25% mỗi mảng là quy ước do tác giả tự nhận là tùy ý, chưa được thí nghiệm chứng minh là tỉ lệ tốt nhất.</p>\\n<h2 id=\\"mang-1-nghe-va-doc-tai-lieu-de-hieu\\">Mảng 1: nghe và đọc tài liệu dễ hiểu</h2>\\n<p>Mảng này chỉ có tác dụng khi phần lớn tài liệu đã quen. Nation đặt điều kiện: 95 đến 98% số từ trong bài đã biết, tức chỉ 5, tốt hơn là 1 đến 2 từ lạ trên mỗi trăm từ. Con số này lấy từ Hu và Nation (2000), nghiên cứu xem cần biết bao nhiêu phần trăm từ trong một văn bản truyện để hiểu đầy đủ khi tự đọc, không có trợ giúp.</p>\\n<p>Ngưỡng 98% có giới hạn. Kremmel và cộng sự (2023) chỉ ra nó dựa trên phân tích với 66 sinh viên đại học ở New Zealand. Họ làm lại với 104 người học trưởng thành ở Sri Lanka và không lặp lại được hoàn toàn kết quả gốc. Hãy xem 98% là mốc tham khảo, không phải ranh giới cứng.</p>\\n<p>Với tiếng Hàn: đọc bài khoá KIIP ở trình độ đã học xong, xem phim có phụ đề tiếng Hàn để theo dõi câu chuyện, nghe lại hội thoại trong sách khi đã hiểu gần hết. Nếu dòng nào cũng phải tra từ thì đó là đọc kỹ để học ngôn ngữ (mảng 3). Nation cũng nhấn mạnh mảng này cần lượng lớn, vì mỗi lần gặp một từ khi đọc chỉ học thêm được một chút.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — vai trò của lượng lớn đầu vào dễ hiểu được nhiều nhà nghiên cứu đồng thuận, nhưng ngưỡng 98% đến từ một mẫu 66 sinh viên và bản làm lại năm 2023 không xác nhận đầy đủ.</p>\\n<h2 id=\\"mang-2-noi-va-viet-de-truyen-dat\\">Mảng 2: nói và viết để truyền đạt</h2>\\n<p>Ở mảng này, mục tiêu chính là truyền ý cho người khác, chủ đề phần lớn đã quen, chỉ một phần nhỏ ngôn ngữ cần dùng là chưa vững. Nation dựa vào giả thuyết đầu ra (output hypothesis) của Swain: khi cố nói hoặc viết, người học nhận ra chỗ chưa biết cách diễn đạt, rồi để ý cách người khác nói điều đó.</p>\\n<p>Với tiếng Hàn: viết vài câu nhật ký như 오늘 회사에서 일이 많아서 피곤했어요. (Hôm nay ở công ty nhiều việc nên tôi mệt.), kể lại bài khoá vừa đọc rồi tự ghi âm, nhắn tin bằng tiếng Hàn với đồng nghiệp khi có dịp. Ý nào bí không biết nói thì ghi lại câu tiếng Việt đó làm nguyên liệu cho mảng 3.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — có nghiên cứu ủng hộ vai trò của việc nói viết trong học ngôn ngữ, nhưng Nation trình bày đây là lý lẽ tổng hợp, không đo hiệu quả của một tỉ lệ thời gian cụ thể.</p>\\n<h2 id=\\"mang-3-hoc-co-chu-dich-ngu-phap-va-tu-vung\\">Mảng 3: học có chủ đích ngữ pháp và từ vựng</h2>\\n<p>Đây là mảng quen thuộc nhất: học thẻ từ, học ngữ pháp, đọc kỹ từng câu, làm bài tập, nhận góp ý bài viết. Nation cho rằng cùng một lượng thời gian, học có chủ đích thường cho nhiều kiến thức mới hơn học ngẫu nhiên qua đọc. Điều kiện: xử lý sâu, ôn lặp lại cách quãng, và những gì học ở đây cần gặp lại trong ba mảng kia.</p>\\n<p>Ví dụ: học -(으)ㄹ 수 있다 (có thể làm gì) qua câu 한국어로 이야기할 수 있어요. (Tôi có thể nói chuyện bằng tiếng Hàn.), rồi tự đặt câu khác và tự kiểm tra thay vì đọc lại.</p>\\n<p>Vấn đề là khi mảng này chiếm gần hết thời gian. Nation viết các hoạt động này có ích nhưng chỉ nên là một phần nhỏ, không thành toàn bộ khoá học.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — hiệu quả của học từ vựng có chủ đích được nhiều nghiên cứu ủng hộ; giới hạn &quot;không quá một phần tư thời gian&quot; là đề xuất của Nation, không phải kết quả đo trực tiếp.</p>\\n<h2 id=\\"mang-4-luyen-troi-chay-voi-tai-lieu-de\\">Mảng 4: luyện trôi chảy với tài liệu dễ</h2>\\n<p>Nation nhận xét phần lớn khoá học không dành đủ thời gian cho mảng này, có lẽ vì nó không dạy điều gì mới nên trông như không tiến bộ. Ông đặt điều kiện: tài liệu đã quen, không có từ lạ; trọng tâm vẫn là nghĩa; có áp lực làm nhanh hơn bình thường. Thiếu một điều kiện thì không phải hoạt động trôi chảy.</p>\\n<p>Với tiếng Hàn:</p>\\n<ul>\\n<li>Đọc lại bài khoá KIIP đã học kỹ từ vài tuần trước, bấm giờ và cố đọc nhanh hơn lần trước.</li>\\n<li>Nói 4/3/2: giới thiệu công việc của bạn trong 4 phút, rồi nói lại cùng nội dung trong 3 phút, rồi 2 phút. Nation mô tả là nói với ba người nghe khác nhau; tự học thì có thể ghi âm từng lần.</li>\\n<li>Viết liên tục 10 phút về một chủ đề quen, không dừng lại tra từ.</li>\\n</ul>\\n<p><strong>Mức bằng chứng:</strong> vừa — Nation dẫn một số nghiên cứu cho thấy luyện có bấm giờ và nói lặp lại kiểu 4/3/2 làm tăng độ trôi chảy, nhưng số nghiên cứu được dẫn còn ít, phần lớn trên người học tiếng Anh. Áp dụng cho tiếng Hàn là suy rộng hợp lý.</p>\\n<h2 id=\\"mot-tuan-5-gio-chia-theo-bon-mang\\">Một tuần 5 giờ chia theo bốn mảng</h2>\\n<p>Bảng dưới đây chỉ là <strong>ví dụ minh hoạ</strong> cho người có khoảng 5 giờ (300 phút) mỗi tuần, chia đều khoảng 75 phút mỗi mảng. Không có nghiên cứu nào kiểm tra lịch cụ thể này.</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Ngày</th>\\n<th>Hoạt động</th>\\n<th>Mảng</th>\\n<th>Thời gian</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>Thứ 2</td>\\n<td>Học từ vựng và ngữ pháp bài mới, tự kiểm tra</td>\\n<td>3</td>\\n<td>40 phút</td>\\n</tr>\\n<tr>\\n<td>Thứ 3</td>\\n<td>Đọc bài khoá KIIP đã học, nghe lại hội thoại</td>\\n<td>1</td>\\n<td>40 phút</td>\\n</tr>\\n<tr>\\n<td>Thứ 4</td>\\n<td>Viết nhật ký 5–6 câu, kể lại bài khoá</td>\\n<td>2</td>\\n<td>40 phút</td>\\n</tr>\\n<tr>\\n<td>Thứ 5</td>\\n<td>Đọc nhanh bài cũ có bấm giờ, nói 4/3/2</td>\\n<td>4</td>\\n<td>40 phút</td>\\n</tr>\\n<tr>\\n<td>Thứ 6</td>\\n<td>Ôn ngữ pháp, chữa lỗi trong bài viết thứ 4</td>\\n<td>3</td>\\n<td>35 phút</td>\\n</tr>\\n<tr>\\n<td>Thứ 7</td>\\n<td>Xem phim có phụ đề tiếng Hàn</td>\\n<td>1</td>\\n<td>35 phút</td>\\n</tr>\\n<tr>\\n<td>Chủ nhật</td>\\n<td>Nói chuyện hoặc nhắn tin bằng tiếng Hàn (35 phút); kể lại một bài khoá đã học, cố nhanh hơn lần trước (35 phút)</td>\\n<td>2 và 4</td>\\n<td>70 phút</td>\\n</tr>\\n</tbody></table></div>\\n<p>Cộng lại, mỗi mảng 75 phút. Có thể đổi ngày hoặc gộp hai mảng vào một buổi, miễn sau một hai tuần tổng thời gian các mảng gần bằng nhau. Nation cũng gợi ý cách kiểm tra: ghi lại các hoạt động trong hai tuần đến một tháng, xếp mỗi hoạt động vào một mảng và cộng thời gian.</p>\\n<h2 id=\\"ap-dung-ngay\\">Áp dụng ngay</h2>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1ina5i8\\"><span>Ghi lại mọi hoạt động học tiếng Hàn trong 7 ngày tới, xếp mỗi hoạt động vào một trong bốn mảng và cộng số phút.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1xfm65j\\"><span>Nếu mảng 3 chiếm quá một phần tư tổng thời gian, chuyển bớt một buổi học ngữ pháp sang đọc bài khoá cũ hoặc luyện trôi chảy.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"vacw2m\\"><span>Chọn một bài khoá đã học kỹ, đọc lại có bấm giờ hôm nay và ghi số phút để lần sau so sánh.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"mmlqii\\"><span>Viết 5 câu tiếng Hàn kể về ngày hôm nay; câu nào bí thì ghi lại để tra sau.</span></label></li>\\n</ul>\\n<h2 id=\\"tren-haechivn\\">Trên HaechiVN</h2>\\n<ul>\\n<li><a href=\\"/books/step1/roadmap\\">Lộ trình KIIP</a>: bài khoá có dịch từng câu và giải thích, dùng cho mảng 1 (đọc bài đã học) và mảng 4 (đọc lại nhanh bài cũ).</li>\\n<li>Shadowing (nói đuổi) trong sách KIIP từ Sơ cấp 1 đến Trung cấp 2: nghe câu mẫu, ghi âm giọng của bạn rồi nghe lại, có thể chấm phát âm bằng AI. Chủ yếu luyện phát âm (mảng 3); chỉ tính vào mảng 4 khi dùng câu đã hiểu hết, tập trung vào nghĩa và cố theo kịp tốc độ.</li>\\n<li>Tự chấm bài tập sách giáo trình và sách bài tập mọi cấp KIIP theo đáp án của sách; Sơ cấp 1 có thêm trắc nghiệm chấm tự động. Dùng cho mảng 3.</li>\\n<li><a href=\\"/video\\">Video</a>: phim có phụ đề Hàn – Việt bật tắt được, có bản chép lời và shadowing từng dòng, dùng cho mảng 1 và luyện phát âm.</li>\\n<li><a href=\\"/ngu-phap\\">Ngữ pháp</a>: tra nghĩa tiếng Việt và ví dụ của từng cấu trúc khi học mảng 3.</li>\\n<li><a href=\\"/my\\">Góc học tập</a>: đặt mục tiêu số phút mỗi tuần và theo dõi chuỗi ngày học.</li>\\n<li>Bài liên quan: <a href=\\"/cam-nang/hoc-tap/tu-kiem-tra-thay-vi-doc-lai\\">Tự kiểm tra thay vì đọc lại</a> và <a href=\\"/cam-nang/hoc-tap/on-ngat-quang\\">Ôn ngắt quãng</a> cho mảng 3.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://doi.org/10.2167/illt039.0\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nation (2007). The Four Strands. Innovation in Language Learning and Teaching</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.64152/10125/66973\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Hu &amp; Nation (2000). Unknown vocabulary density and reading comprehension. Reading in a Foreign Language</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1111/lang.12622\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Kremmel, Indrarathne, Kormos &amp; Suzuki (2023). Unknown Vocabulary Density and Reading Comprehension: Replicating Hu and Nation (2000). Language Learning</a> <span class=\\"source-domain\\">doi.org</span></li>\\n</ul>","headings":[{"id":"bon-mang-la-gi","text":"Bốn mảng là gì","level":2},{"id":"mang-1-nghe-va-doc-tai-lieu-de-hieu","text":"Mảng 1: nghe và đọc tài liệu dễ hiểu","level":2},{"id":"mang-2-noi-va-viet-de-truyen-dat","text":"Mảng 2: nói và viết để truyền đạt","level":2},{"id":"mang-3-hoc-co-chu-dich-ngu-phap-va-tu-vung","text":"Mảng 3: học có chủ đích ngữ pháp và từ vựng","level":2},{"id":"mang-4-luyen-troi-chay-voi-tai-lieu-de","text":"Mảng 4: luyện trôi chảy với tài liệu dễ","level":2},{"id":"mot-tuan-5-gio-chia-theo-bon-mang","text":"Một tuần 5 giờ chia theo bốn mảng","level":2},{"id":"ap-dung-ngay","text":"Áp dụng ngay","level":2},{"id":"tren-haechivn","text":"Trên HaechiVN","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":4},{"slug":"luyen-nghe-va-shadowing","title":"Luyện nghe tiếng Hàn và shadowing","summary":"Chọn bài nghe vừa sức, nghe theo từng lượt có và không có phụ đề, nói đuổi theo băng (shadowing) và làm quen các quy tắc biến âm khiến người Việt nghe sót chữ.","updated":"2026-10-01","facts":{"group":"Học tiếng"},"html":"<p>Nhiều người học tiếng Hàn đọc hiểu được bài trong sách nhưng nghe băng thì chỉ bắt được vài từ rời. Lý do thường gặp: bài nghe quá khó so với vốn từ, chỉ nghe thụ động mà không luyện lại, và chữ viết khác xa âm thật vì các quy tắc biến âm. Bài này đi qua từng nguyên nhân và cách luyện tương ứng.</p>\\n<h2 id=\\"chon-bai-nghe-vua-suc\\">Chọn bài nghe vừa sức</h2>\\n<p>Độ phủ từ vựng (lexical coverage) là tỉ lệ từ trong bài mà người học đã biết. Với đọc, nhiều nghiên cứu cho rằng cần biết khoảng 98% số từ trong bài để hiểu đầy đủ. Con số này từng được dùng luôn cho kỹ năng nghe.</p>\\n<p>Van Zeeland và Schmitt (2013) kiểm tra trực tiếp với kỹ năng nghe. Họ cho 36 người bản ngữ và 40 người học tiếng Anh nghe bốn đoạn kể chuyện thân mật, trong đó tỉ lệ từ đã biết được điều chỉnh, rồi hỏi về thông tin trong bài. Kết quả: phần lớn người nghe hiểu đủ khi biết 90% số từ, nhưng người học ngoại ngữ chênh lệch nhau nhiều ở mức này. Ở mức 95%, người học hiểu khá tốt và ít chênh lệch hơn. Dựa trên mức 95%, các tác giả ước tính cần biết khoảng 2.000 đến 3.000 họ từ để nghe hiểu đủ, so với 6.000 đến 7.000 nếu tính theo mức 98%.</p>\\n<p>Áp dụng thô: 95% nghĩa là trung bình cứ 20 từ thì không quá 1 từ lạ. Nghe thử một đoạn ngắn. Nếu cứ vài từ lại vướng một từ chưa biết, bài đó đang quá khó để luyện nghe hiểu; nên lùi xuống bài dễ hơn hoặc học trước từ vựng của bài.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — một nghiên cứu được trích dẫn nhiều, nhưng làm với tiếng Anh, bài kể chuyện thân mật và câu hỏi về thông tin cụ thể. Tiếng Hàn chắp dính (một từ gắn nhiều tiểu từ, đuôi câu) nên cách đếm &quot;từ&quot; khác, con số 95% chỉ nên dùng làm mốc ước lượng.</p>\\n<h2 id=\\"nghe-theo-tung-luot-khong-phu-de-phu-de-han-phu-de-viet\\">Nghe theo từng lượt: không phụ đề, phụ đề Hàn, phụ đề Việt</h2>\\n<p>Một quy trình thực hành với một đoạn video hay bài nghe ngắn (1 đến 3 phút):</p>\\n<ol>\\n<li>Nghe lần đầu không phụ đề. Ghi lại ý chính đoán được.</li>\\n<li>Nghe lại với phụ đề tiếng Hàn. Dừng ở câu không nghe ra, so chữ với âm.</li>\\n<li>Xem phụ đề tiếng Việt cho những câu vẫn chưa hiểu nghĩa.</li>\\n<li>Nghe lại không phụ đề. Lần này kiểm tra xem bắt được bao nhiêu câu đã vướng ở lần 1.</li>\\n</ol>\\n<p>Phần có nghiên cứu là bước 2. Montero Perez, Van Den Noortgate và Desmet (2013) làm phân tích gộp về video có phụ đề cùng ngôn ngữ với lời thoại (caption, ví dụ phim tiếng Hàn kèm chữ tiếng Hàn). Kết luận: so với xem không phụ đề, xem có caption giúp người học hiểu nội dung nghe tốt hơn và học được nhiều từ vựng hơn. Trong bài giới thiệu một số chuyên đề về video và học ngoại ngữ năm 2019, Montero Perez và Rodgers cũng tóm tắt rằng xem video có caption có thể giúp hiểu bài và học từ.</p>\\n<p>Cần nói rõ: các nghiên cứu này đo việc hiểu khi đang có chữ trên màn hình. Thứ tự bốn lượt ở trên là quy ước thực hành, chưa có nghiên cứu nào so sánh nó với các cách khác. Bước 1 và bước 4 có mục đích riêng: buộc tai làm việc khi không có chữ đỡ, vì trong kỳ thi và ngoài đời không có phụ đề.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — phân tích gộp ủng hộ việc dùng caption để hiểu bài và học từ, nhưng không có kết quả riêng cho người Việt học tiếng Hàn và các nghiên cứu chủ yếu đo việc hiểu khi đang có chữ. Quy trình bốn lượt là cách sắp xếp hợp lý, chưa được kiểm chứng riêng.</p>\\n<h2 id=\\"shadowing-noi-duoi-theo-bang\\">Shadowing: nói đuổi theo băng</h2>\\n<p>Shadowing là nghe một câu và nói lặp lại gần như đồng thời, chỉ chậm hơn băng một chút, giống cái bóng đi theo người. Khác với nghe rồi nhắc lại sau khi băng dừng, shadowing buộc người học bám theo đúng tốc độ, ngữ điệu và chỗ nối âm của người nói.</p>\\n<p>Hamada (2016) kiểm tra hai nhận định phổ biến ở Nhật: shadowing giúp nghe phân biệt âm tốt hơn, và có lợi nhất cho người trình độ thấp. Người tham gia là 43 sinh viên Nhật học tiếng Anh ở một trường đại học, học chín buổi có shadowing theo giáo trình. Trước và sau đó, họ làm bài nghe trích từ kỳ thi chuẩn hoá của Nhật và bài nghe chép điền từ 20 câu. Kết quả: khả năng nhận biết âm tăng ở cả nhóm trình độ thấp và trung bình, nhưng chỉ nhóm trình độ thấp tăng điểm ở câu hỏi nghe mức trung học. Tác giả gợi ý dùng shadowing chủ yếu cho quá trình xử lý từ dưới lên: nhận ra âm, nhận ra từ.</p>\\n<p>Cách làm đơn giản:</p>\\n<ul>\\n<li>Chọn câu bạn đã hiểu nghĩa (sau lượt phụ đề ở trên), ngắn, tốc độ vừa.</li>\\n<li>Nghe vài lần, rồi nói đuổi theo. Lúc đầu có thể nhìn chữ, sau bỏ chữ.</li>\\n<li>Ghi âm giọng mình, nghe lại và so với câu mẫu ở chỗ nối âm, chỗ ngắt.</li>\\n</ul>\\n<p><strong>Mức bằng chứng:</strong> vừa — nghiên cứu của Hamada có 43 người, tóm tắt chỉ mô tả so sánh trước và sau khi luyện; chính bài này cho biết các kết luận phổ biến về shadowing đến từ nghiên cứu ở Nhật với người học tiếng Anh. Chưa có bằng chứng tương đương cho người Việt học tiếng Hàn; lợi ích rõ nhất là nhận ra âm, không phải hiểu ý cả bài.</p>\\n<h2 id=\\"bien-am-tieng-han-vi-sao-nghe-khong-khop-voi-chu\\">Biến âm tiếng Hàn: vì sao nghe không khớp với chữ</h2>\\n<p>Tiếng Việt viết sao đọc vậy theo từng âm tiết. Tiếng Hàn thì âm cuối (받침) thường dịch chuyển hoặc đổi khi gặp âm tiết sau. Người Việt quen tách từng chữ nên hay &quot;không nhận ra&quot; từ mình đã biết. Các quy tắc dưới đây lấy từ 표준 발음법 (Quy tắc phát âm chuẩn) của 국립국어원 (Viện Quốc ngữ Quốc gia Hàn Quốc).</p>\\n<p><strong>Nối âm (연음).</strong> Khi phía sau là tiểu từ, đuôi từ hoặc hậu tố bắt đầu bằng nguyên âm, phụ âm cuối chuyển sang làm âm đầu của âm tiết đó (ㅇ cuối thì không chuyển):</p>\\n<ul>\\n<li>한국어 (tiếng Hàn) → [한구거]</li>\\n<li>옷이 (cái áo + tiểu từ chủ ngữ) → [오시]</li>\\n<li>있어요 (có) → [이써요]</li>\\n<li>Với phụ âm cuối kép, chỉ phụ âm sau chuyển sang: 읽어요 (đọc) → [일거요].</li>\\n<li>Nếu phía sau là một từ có nghĩa riêng, phụ âm cuối đổi thành âm đại diện rồi mới nối: 옷 안 (bên trong áo) → [오단], không phải [오산].</li>\\n</ul>\\n<p><strong>Mất âm ㅎ.</strong> ㅎ (cả ㄶ, ㅀ) cuối âm tiết đứng trước đuôi từ hoặc hậu tố bắt đầu bằng nguyên âm thì không đọc: 좋아요 (tốt, thích) → [조아요].</p>\\n<p><strong>Mũi hoá (비음화).</strong> Âm cuối đọc là ㄱ, ㄷ, ㅂ (kể cả các phụ âm cuối khác đọc thành ba âm này, ví dụ ㅆ trong 있는 → [인는]) đứng trước ㄴ, ㅁ thì đọc thành [ㅇ, ㄴ, ㅁ]:</p>\\n<ul>\\n<li>합니다 (làm, đuôi trang trọng) → [함니다]</li>\\n<li>먹는 (ăn, dạng định ngữ) → [멍는]</li>\\n<li>국물 (nước canh) → [궁물]</li>\\n</ul>\\n<p><strong>Căng hoá (경음화).</strong> Sau âm cuối ㄱ, ㄷ, ㅂ, các phụ âm ㄱ, ㄷ, ㅂ, ㅅ, ㅈ đọc thành âm căng:</p>\\n<ul>\\n<li>학교 (trường học) → [학꾜]</li>\\n<li>식당 (quán ăn) → [식땅]</li>\\n</ul>\\n<p>Khi luyện nghe theo phụ đề tiếng Hàn, hãy đánh dấu chỗ âm nghe được khác chữ viết và tự gọi tên quy tắc. Khi shadowing, đọc theo âm trong ngoặc, không đọc theo từng chữ.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — nội dung quy tắc lấy từ chuẩn phát âm chính thức của 국립국어원. Việc học quy tắc giúp người Việt nghe tốt hơn bao nhiêu thì chưa có nghiên cứu riêng; đây là suy luận từ việc shadowing và caption giúp nhận ra âm.</p>\\n<h2 id=\\"ap-dung-ngay\\">Áp dụng ngay</h2>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"edt21q\\"><span>Chọn một đoạn nghe 1 đến 3 phút, đếm thử số từ lạ trong vài câu đầu; quá 1 từ lạ trên 20 từ thì đổi bài dễ hơn.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"xm3sdq\\"><span>Nghe đoạn đó theo bốn lượt: không phụ đề, phụ đề Hàn, phụ đề Việt, không phụ đề.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"198h25e\\"><span>Chọn 3 câu đã hiểu nghĩa, shadowing mỗi câu vài lần, ghi âm và nghe lại.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"6rfiyy\\"><span>Tìm trong đoạn nghe ít nhất hai chỗ nối âm, mũi hoá hoặc căng hoá, viết âm thật vào ngoặc.</span></label></li>\\n</ul>\\n<h2 id=\\"tren-haechivn\\">Trên HaechiVN</h2>\\n<ul>\\n<li><a href=\\"/books/step1/roadmap\\">Lộ trình KIIP</a>: từ Sơ cấp 1 đến Trung cấp 2 có audio và shadowing: nghe câu mẫu, ghi âm giọng mình, nghe lại, có thể bật chấm phát âm bằng AI.</li>\\n<li><a href=\\"/video\\">Video</a>: phim có phụ đề Hàn và Việt bật tắt được, có bản lời thoại, shadowing từng câu (nghe câu, đến lượt bạn, ghi âm) và chế độ tự chạy qua cả tập. Phù hợp với quy trình bốn lượt ở trên.</li>\\n<li><a href=\\"/exam/topik-i\\">TOPIK I</a> và <a href=\\"/exam/topik-ii\\">TOPIK II</a>: phần 듣기 (nghe) để kiểm tra lại khi không có phụ đề.</li>\\n<li>Bài liên quan: <a href=\\"/cam-nang/hoc-tap/on-ngat-quang\\">Ôn ngắt quãng</a>, <a href=\\"/cam-nang/hoc-tap/luyen-de-topik-thong-minh\\">Luyện đề TOPIK thông minh</a>, <a href=\\"/cam-nang/hoc-tap/chia-thoi-gian-hoc-theo-bon-mang\\">Chia thời gian học theo bốn mảng</a>.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://doi.org/10.1093/applin/ams074\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">van Zeeland &amp; Schmitt (2013). Lexical Coverage in L1 and L2 Listening Comprehension: The Same or Different from Reading Comprehension? Applied Linguistics</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1016/j.system.2013.07.013\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Montero Perez, Van Den Noortgate &amp; Desmet (2013). Captioned video for L2 listening and vocabulary learning: A meta-analysis. System</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1080/09571736.2019.1629099\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Montero Perez &amp; Rodgers (2019). Video and language learning. The Language Learning Journal</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1177/1362168815597504\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Hamada (2016). Shadowing: Who benefits and how? Uncovering a booming EFL teaching technique for listening comprehension. Language Teaching Research</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://www.korean.go.kr/front/page/pageView.do?page_id=P000102\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국립국어원 — 표준어 규정, 제2부 표준 발음법</a> <span class=\\"source-domain\\">korean.go.kr</span></li>\\n</ul>","headings":[{"id":"chon-bai-nghe-vua-suc","text":"Chọn bài nghe vừa sức","level":2},{"id":"nghe-theo-tung-luot-khong-phu-de-phu-de-han-phu-de-viet","text":"Nghe theo từng lượt: không phụ đề, phụ đề Hàn, phụ đề Việt","level":2},{"id":"shadowing-noi-duoi-theo-bang","text":"Shadowing: nói đuổi theo băng","level":2},{"id":"bien-am-tieng-han-vi-sao-nghe-khong-khop-voi-chu","text":"Biến âm tiếng Hàn: vì sao nghe không khớp với chữ","level":2},{"id":"ap-dung-ngay","text":"Áp dụng ngay","level":2},{"id":"tren-haechivn","text":"Trên HaechiVN","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":4},{"slug":"hoc-ngu-phap-qua-cau","title":"Học ngữ pháp tiếng Hàn qua câu","summary":"Học mỗi cấu trúc ngữ pháp qua giải thích ngắn, vài câu ví dụ, câu tự đặt, so sánh cặp dễ nhầm và sửa lỗi để dùng được trong bài thi và khi nói, viết.","updated":"2026-10-01","facts":{"group":"Học tiếng"},"html":"<p>Nhiều người học ngữ pháp tiếng Hàn bằng cách chép lại công thức, ví dụ &quot;V + -고 싶다 = muốn làm V&quot;, rồi chuyển sang bài mới. Làm bài trắc nghiệm thì đúng, nhưng khi tự viết câu lại dùng sai hoặc không nghĩ ra cấu trúc nào. Bài này tóm tắt nghiên cứu về dạy ngữ pháp ngoại ngữ và gợi ý một quy trình cho từng điểm ngữ pháp mới.</p>\\n<h2 id=\\"giai-thich-ngu-phap-ro-rang-co-ich\\">Giải thích ngữ pháp rõ ràng có ích</h2>\\n<p>Norris và Ortega (2000) làm phân tích gộp 49 nghiên cứu thực nghiệm về dạy ngoại ngữ, công bố từ 1980 đến 1998. Họ thấy việc dạy có trọng tâm vào hình thức ngôn ngữ giúp người học tiến bộ rõ ở đúng phần được dạy, và cách dạy tường minh (có giải thích quy tắc) hiệu quả hơn cách dạy ngầm (chỉ cho tiếp xúc với câu, không giải thích). Hiệu quả vẫn còn ở các bài kiểm tra sau một thời gian.</p>\\n<p>Giới hạn quan trọng: phần lớn nghiên cứu trong đó đo kết quả bằng bài kiểm tra có kiểm soát như chọn đáp án, điền chỗ trống, kiểu đo có lợi cho kiến thức tường minh. Norris và Ortega lưu ý cách đo có thể ảnh hưởng tới độ lớn của hiệu quả. Khi Ellis (2005) tổng hợp lại, chỉ khoảng 8 nghiên cứu đo bằng nói, viết tự do, và ở đó hiệu quả chưa bằng một nửa so với bài chọn đáp án.</p>\\n<p>Spada và Tomita (2010) phân tích gộp 41 nghiên cứu về ngữ pháp tiếng Anh, chia cấu trúc thành đơn giản và phức tạp. Dạy tường minh có hiệu quả lớn hơn dạy ngầm với cả hai loại, và có đóng góp cả vào kiến thức có kiểm soát lẫn việc dùng tự phát.</p>\\n<p>Việc nên làm: đọc kỹ phần giải thích nghĩa và cách chia, nhưng coi đó là bước đầu, chưa phải là đã dùng được.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — hai phân tích gộp trên tạp chí lớn cùng kết luận dạy tường minh có ích. Phần lớn bài kiểm tra thiên về kiến thức tường minh, nghiên cứu chủ yếu về tiếng Anh, chưa có phân tích gộp tương tự riêng cho tiếng Hàn.</p>\\n<h2 id=\\"hoc-qua-nhieu-cau-roi-tu-dat-cau\\">Học qua nhiều câu, rồi tự đặt câu</h2>\\n<p>Với mỗi cấu trúc mới, đọc ít nhất ba câu ví dụ ở các tình huống khác nhau. Sau đó che ví dụ lại và tự viết câu của mình về chuyện thật: công việc, gia đình, cuộc sống ở Hàn.</p>\\n<p>Tự đặt câu là một dạng tự kiểm tra: bạn phải tự lấy cấu trúc ra từ trí nhớ thay vì nhìn lại sách. Bằng chứng về tự kiểm tra được tóm tắt ở bài <a href=\\"/cam-nang/hoc-tap/tu-kiem-tra-thay-vi-doc-lai\\">Tự kiểm tra thay vì đọc lại</a>. Viết câu cũng làm lộ ra chỗ bạn chưa chắc, như cách chia với động từ có patchim.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — tự kiểm tra có bằng chứng mạnh với việc ghi nhớ thông tin. Việc áp dụng cho tự đặt câu ngữ pháp là suy rộng hợp lý, chưa có nghiên cứu kiểm chứng trực tiếp với người Việt học tiếng Hàn.</p>\\n<h2 id=\\"dat-cac-cap-de-nham-canh-nhau\\">Đặt các cặp dễ nhầm cạnh nhau</h2>\\n<p>Nhiều lỗi ngữ pháp đến từ việc chọn nhầm giữa hai cấu trúc gần nghĩa. Bài <a href=\\"/cam-nang/hoc-tap/on-ngat-quang\\">Ôn ngắt quãng</a> đã nói về việc trộn -아서/어서 và -(으)니까. Dưới đây là bốn cặp khác, ghi chú theo cách dùng cơ bản (đối chiếu với 표준국어대사전), không phải quy tắc tuyệt đối.</p>\\n<p><strong>은/는 và 이/가</strong></p>\\n<ul>\\n<li>저는 베트남 사람이에요. (Tôi là người Việt Nam.) 은/는 nêu chủ đề câu đang nói tới.</li>\\n<li>누가 왔어요? 민수 씨가 왔어요. (Ai đến vậy? Anh Minsu đến.) Từ để hỏi như 누가 đi với 이/가, câu trả lời cũng thường dùng 이/가 vì đó là thông tin mới.</li>\\n<li>사과는 좋아해요. 배는 안 좋아해요. (Táo thì tôi thích. Lê thì không thích.) 은/는 còn dùng để đối chiếu hai thứ.</li>\\n</ul>\\n<p><strong>-고 싶다 và -고 싶어 하다</strong></p>\\n<ul>\\n<li>저는 한국 요리를 배우고 싶어요. (Tôi muốn học nấu món Hàn.) -고 싶다 nói mong muốn của chính người nói, hoặc hỏi mong muốn của người nghe: 뭐 먹고 싶어요? (Bạn muốn ăn gì?)</li>\\n<li>동생은 한국에 가고 싶어 해요. (Em tôi muốn sang Hàn.) Kể mong muốn của người thứ ba thì dùng -고 싶어 하다. Câu &quot;동생은 한국에 가고 싶어요&quot; nghe không tự nhiên.</li>\\n</ul>\\n<p><strong>-(으)ㄹ 거예요 và -겠어요</strong></p>\\n<ul>\\n<li>다음 달에 고향에 갈 거예요. (Tháng sau tôi sẽ về quê.) -(으)ㄹ 거예요 thường nói kế hoạch, dự định. Kể kế hoạch của người khác cũng dùng cấu trúc này: 민수 씨는 내일 이사할 거예요. (Mai anh Minsu chuyển nhà.)</li>\\n<li>제가 다시 연락드리겠습니다. (Tôi sẽ liên lạc lại ạ.) Ở ngôi thứ nhất, -겠- thể hiện ý chí của người nói, hay gặp trong lời nói lịch sự, trang trọng.</li>\\n<li>구름이 많네요. 비가 오겠어요. (Mây nhiều quá. Chắc trời sắp mưa.) -겠- còn dùng để phỏng đoán, thường khi phản ứng với điều đang thấy, đang nghe: 맛있겠어요! (Trông ngon quá!)</li>\\n<li>-(으)ㄹ 거예요 cũng phỏng đoán được: 내일은 추울 거예요. (Mai chắc trời lạnh.) Ở nghĩa phỏng đoán, hai cấu trúc chồng lấn nhau, nên học qua tình huống cụ thể.</li>\\n</ul>\\n<p><strong>-지만 và -는데</strong></p>\\n<ul>\\n<li>이 식당은 비싸지만 맛있어요. (Quán này đắt nhưng ngon.) -지만 nối hai vế trái ngược.</li>\\n<li>비가 오는데 우산 있어요? (Trời đang mưa, bạn có ô không?) -는데 nêu trước một tình huống làm nền cho câu hỏi, lời đề nghị hay lời giải thích phía sau. Câu này không thay bằng -지만 được.</li>\\n<li>형은 키가 큰데 저는 작아요. (Anh tôi cao, còn tôi thì thấp.) -는데 cũng dùng để đối chiếu, đây là phần hai cấu trúc trùng nhau. Chú ý cách chia: động từ và 있다/없다 dùng -는데, tính từ dùng -(으)ㄴ데.</li>\\n</ul>\\n<p>Viết mỗi cặp trên cùng một trang, rồi luyện câu trộn lẫn: che phần ngữ pháp và tự chọn.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — Dunlosky và cộng sự (2013) xếp xen kẽ ở mức hữu ích trung bình, chủ yếu dựa trên tài liệu không phải ngữ pháp ngoại ngữ. Áp dụng cho các cặp ngữ pháp tiếng Hàn là suy rộng hợp lý, chưa được kiểm chứng trực tiếp.</p>\\n<h2 id=\\"nho-nguoi-sua-cau-cua-ban\\">Nhờ người sửa câu của bạn</h2>\\n<p>Lyster và Saito (2010) phân tích gộp 15 nghiên cứu trong lớp học (827 người học) về việc giáo viên sửa lỗi khi người học nói. Sửa lỗi có hiệu quả rõ và kéo dài. Hiệu quả lớn hơn khi người sửa gợi ý để người học tự sửa (prompt) so với khi người sửa chỉ nói lại câu đúng (recast). Hiệu quả thấy rõ nhất ở bài đo bằng nói, viết tự do. Người học nhỏ tuổi hưởng lợi nhiều hơn người lớn tuổi.</p>\\n<p>Li (2010) phân tích gộp 33 nghiên cứu về sửa lỗi. Kết quả: hiệu quả tổng thể ở mức trung bình và vẫn còn ở bài kiểm tra sau. Nghiên cứu trong phòng thí nghiệm cho hiệu quả lớn hơn nghiên cứu trong lớp học.</p>\\n<p>Phạm vi: đây là sửa lỗi do giáo viên hoặc nhà nghiên cứu đưa ra, không phải tự học một mình. Khi tự học, có thể so câu với ví dụ trong sách, hoặc nhờ giáo viên lớp KIIP, bạn người Hàn xem giúp, và nhờ họ chỉ chỗ sai để bạn tự sửa trước.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — hai phân tích gộp cùng thấy sửa lỗi có ích và hiệu quả còn lâu. Kết quả về loại sửa lỗi nào tốt hơn còn khác nhau giữa các nghiên cứu, và tự sửa lỗi khi học một mình chưa được kiểm chứng trực tiếp.</p>\\n<h2 id=\\"quy-trinh-cho-moi-diem-ngu-phap-moi\\">Quy trình cho mỗi điểm ngữ pháp mới</h2>\\n<ol>\\n<li>Đọc nghĩa và cách chia. Chú ý động từ, tính từ, có patchim hay không.</li>\\n<li>Đọc ba câu ví dụ, nói to từng câu.</li>\\n<li>Che ví dụ, viết ba câu của mình về chuyện thật.</li>\\n<li>Kiểm tra: so với ví dụ, với bảng cách chia, hoặc nhờ người xem. Sửa và ghi lại lỗi.</li>\\n<li>Vài ngày sau, viết lại vài câu trộn cấu trúc này với các cấu trúc cũ dễ nhầm.</li>\\n</ol>\\n<p><strong>Mức bằng chứng:</strong> vừa — từng bước dựa trên các nghiên cứu ở trên; cả quy trình chưa được thử nghiệm như một tổng thể.</p>\\n<h2 id=\\"ap-dung-ngay\\">Áp dụng ngay</h2>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"k3ji86\\"><span>Chọn điểm ngữ pháp mới nhất bạn học, viết ba câu của mình mà không nhìn sách.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"dimiqb\\"><span>Viết một trang so sánh 은/는 và 이/가, mỗi bên ba câu.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"ydvt20\\"><span>Viết lại hai câu về mong muốn: một câu của bạn (-고 싶다), một câu của người thân (-고 싶어 하다).</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1miyt8m\\"><span>Gửi năm câu tự viết cho giáo viên hoặc bạn người Hàn, nhờ họ chỉ chỗ sai trước khi đưa câu đúng.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"up0odw\\"><span>Đặt lịch ba ngày sau viết câu trộn cấu trúc mới với một cấu trúc cũ.</span></label></li>\\n</ul>\\n<h2 id=\\"tren-haechivn\\">Trên HaechiVN</h2>\\n<ul>\\n<li><a href=\\"/ngu-phap\\">Ngữ pháp</a>: các điểm ngữ pháp KIIP Sơ cấp 1 đến Trung cấp 2, có nghĩa tiếng Việt, ví dụ, bảng cách chia và link tới trang trong sách. Tìm được bằng tiếng Hàn hoặc tiếng Việt.</li>\\n<li><a href=\\"/my\\">Góc học tập</a>: gợi ý các điểm ngữ pháp nên ôn dựa trên phần bạn tự chấm bài tập trong sách bài tập và bài kiểm tra Sơ cấp 1.</li>\\n<li>Sách KIIP trên site có bản dịch từng câu: tìm thêm câu chứa cấu trúc đang học, tự hiểu trước rồi mới xem bản dịch.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://doi.org/10.1111/0023-8333.00136\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Norris &amp; Ortega (2000). Effectiveness of L2 Instruction: A Research Synthesis and Quantitative Meta-analysis. Language Learning</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1111/j.1467-9922.2010.00562.x\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Spada &amp; Tomita (2010). Interactions Between Type of Instruction and Type of Language Feature: A Meta-Analysis. Language Learning</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1017/S0272263109990520\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Lyster &amp; Saito (2010). Oral Feedback in Classroom SLA: A Meta-Analysis. Studies in Second Language Acquisition</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1111/j.1467-9922.2010.00561.x\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Li (2010). The Effectiveness of Corrective Feedback in SLA: A Meta-Analysis. Language Learning</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1177/1529100612453266\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Dunlosky, Rawson, Marsh, Nathan &amp; Willingham (2013). Improving Students&#39; Learning With Effective Learning Techniques. Psychological Science in the Public Interest</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://www-leland.stanford.edu/~hakuta/Courses/Ed388%20Website/Resources/Instructional%20Resources/Ellis%20Instructed-second-language%20-%20latest%20version.pdf\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Ellis (2005). Instructed Second Language Acquisition: A Literature Review. New Zealand Ministry of Education (bản lưu tại Stanford)</a> <span class=\\"source-domain\\">www-leland.stanford.edu</span></li>\\n<li><a href=\\"https://stdict.korean.go.kr/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국립국어원 표준국어대사전</a> <span class=\\"source-domain\\">stdict.korean.go.kr</span></li>\\n</ul>","headings":[{"id":"giai-thich-ngu-phap-ro-rang-co-ich","text":"Giải thích ngữ pháp rõ ràng có ích","level":2},{"id":"hoc-qua-nhieu-cau-roi-tu-dat-cau","text":"Học qua nhiều câu, rồi tự đặt câu","level":2},{"id":"dat-cac-cap-de-nham-canh-nhau","text":"Đặt các cặp dễ nhầm cạnh nhau","level":2},{"id":"nho-nguoi-sua-cau-cua-ban","text":"Nhờ người sửa câu của bạn","level":2},{"id":"quy-trinh-cho-moi-diem-ngu-phap-moi","text":"Quy trình cho mỗi điểm ngữ pháp mới","level":2},{"id":"ap-dung-ngay","text":"Áp dụng ngay","level":2},{"id":"tren-haechivn","text":"Trên HaechiVN","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":5},{"slug":"dung-han-viet-hoc-tu-han-han","title":"Dùng âm Hán-Việt để học từ Hán Hàn","summary":"Nhận ra quy luật âm giữa từ Hán Hàn (한자어) và âm Hán-Việt để đoán nghĩa, nhớ từ theo nhóm và tránh các cặp từ giống âm khác nghĩa.","updated":"2026-10-01","facts":{"group":"Học tiếng"},"html":"<p>Người Việt học tiếng Hàn thường học từng từ một như học từ hoàn toàn mới. Nhưng 학교, 경제, 준비 đọc lên nghe rất giống &quot;học hiệu&quot;, &quot;kinh tế&quot;, &quot;chuẩn bị&quot;. Đó không phải trùng hợp: cả tiếng Hàn và tiếng Việt đều mượn rất nhiều từ gốc Hán. Bài này chỉ cách tận dụng điều đó, và những chỗ nó dẫn bạn đi sai.</p>\\n<h2 id=\\"la-gi-va-chiem-bao-nhieu\\">한자어 là gì và chiếm bao nhiêu</h2>\\n<p>한자어 (từ Hán Hàn) là từ tiếng Hàn có gốc chữ Hán, viết bằng Hangeul nhưng mỗi âm tiết ứng với một chữ Hán (한자). Tiếng Hàn còn có 고유어 (từ thuần Hàn, như 사람, 물, 먹다), 외래어 (từ ngoại lai, như 버스, 컴퓨터) và 혼종어 (từ lai, ghép từ hai loại trở lên).</p>\\n<p>Theo ấn phẩm &quot;2022 숫자로 살펴보는 우리말&quot; của 국립국어원 (Viện Quốc ngữ Quốc gia Hàn Quốc), tính đến tháng 5/2022, 표준국어대사전 (Từ điển tiếng Hàn chuẩn) có 422.890 mục từ. Trong đó:</p>\\n<ul>\\n<li>한자어: 235.173 mục (55,6%)</li>\\n<li>혼종어: 88.378 mục (20,9%)</li>\\n<li>고유어: 75.520 mục (17,9%)</li>\\n<li>외래어: 23.819 mục (5,6%)</li>\\n</ul>\\n<p>Con số này đo <strong>tỉ lệ mục từ trong từ điển</strong>, không phải tỉ lệ từ bạn gặp trong một bài đọc hay cuộc nói chuyện. Từ điển chứa cả rất nhiều thuật ngữ chuyên ngành ít dùng hằng ngày. Ngược lại, trong lời nói hằng ngày, từ thuần Hàn như 있다, 하다, 이, 그 xuất hiện liên tục. Bài này không tìm được một tỉ lệ chính thức về 한자어 tính theo số lần xuất hiện trong văn bản thực tế, nên không đưa ra con số nào. Điều chắc chắn: trong từ vựng về hành chính, kinh tế, giáo dục, y tế (đúng mảng KIIP hay dùng), từ Hán rất phổ biến.</p>\\n<h2 id=\\"quy-luat-am-giua-tieng-han-va-han-viet\\">Quy luật âm giữa tiếng Hàn và Hán-Việt</h2>\\n<p>Vì cùng đọc một chữ Hán, âm Hàn và âm Hán-Việt thường tương ứng với nhau khá đều đặn. Biết một âm tiết, bạn đoán được nhiều từ.</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Tiếng Hàn</th>\\n<th>Hán tự</th>\\n<th>Âm Hán-Việt</th>\\n<th>Nghĩa</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>학교</td>\\n<td>學校</td>\\n<td>học hiệu</td>\\n<td>trường học</td>\\n</tr>\\n<tr>\\n<td>학생</td>\\n<td>學生</td>\\n<td>học sinh</td>\\n<td>học sinh</td>\\n</tr>\\n<tr>\\n<td>대학</td>\\n<td>大學</td>\\n<td>đại học</td>\\n<td>đại học</td>\\n</tr>\\n<tr>\\n<td>경제</td>\\n<td>經濟</td>\\n<td>kinh tế</td>\\n<td>kinh tế</td>\\n</tr>\\n<tr>\\n<td>준비</td>\\n<td>準備</td>\\n<td>chuẩn bị</td>\\n<td>chuẩn bị</td>\\n</tr>\\n<tr>\\n<td>문화</td>\\n<td>文化</td>\\n<td>văn hoá</td>\\n<td>văn hoá</td>\\n</tr>\\n<tr>\\n<td>사회</td>\\n<td>社會</td>\\n<td>xã hội</td>\\n<td>xã hội</td>\\n</tr>\\n<tr>\\n<td>시간</td>\\n<td>時間</td>\\n<td>thời gian</td>\\n<td>thời gian, giờ</td>\\n</tr>\\n<tr>\\n<td>가족</td>\\n<td>家族</td>\\n<td>gia tộc</td>\\n<td>gia đình</td>\\n</tr>\\n<tr>\\n<td>도서관</td>\\n<td>圖書館</td>\\n<td>đồ thư quán</td>\\n<td>thư viện</td>\\n</tr>\\n<tr>\\n<td>외국인</td>\\n<td>外國人</td>\\n<td>ngoại quốc nhân</td>\\n<td>người nước ngoài</td>\\n</tr>\\n<tr>\\n<td>대사관</td>\\n<td>大使館</td>\\n<td>đại sứ quán</td>\\n<td>đại sứ quán</td>\\n</tr>\\n<tr>\\n<td>결혼</td>\\n<td>結婚</td>\\n<td>kết hôn</td>\\n<td>kết hôn</td>\\n</tr>\\n<tr>\\n<td>생일</td>\\n<td>生日</td>\\n<td>sinh nhật</td>\\n<td>sinh nhật</td>\\n</tr>\\n<tr>\\n<td>병원</td>\\n<td>病院</td>\\n<td>bệnh viện</td>\\n<td>bệnh viện</td>\\n</tr>\\n<tr>\\n<td>은행</td>\\n<td>銀行</td>\\n<td>ngân hàng</td>\\n<td>ngân hàng</td>\\n</tr>\\n<tr>\\n<td>전화</td>\\n<td>電話</td>\\n<td>điện thoại</td>\\n<td>điện thoại</td>\\n</tr>\\n<tr>\\n<td>안전</td>\\n<td>安全</td>\\n<td>an toàn</td>\\n<td>an toàn</td>\\n</tr>\\n</tbody></table></div>\\n<p>Một số âm tiết gặp rất nhiều:</p>\\n<ul>\\n<li><strong>학 (學) ↔ học</strong>: 학교, 학생, 대학, 학습 (學習, học tập)</li>\\n<li><strong>국 (國) ↔ quốc</strong>: 한국 (韓國, Hàn Quốc), 외국인, 국적 (國籍, quốc tịch)</li>\\n<li><strong>대 (大) ↔ đại</strong>: 대학, 대사관</li>\\n<li><strong>생 (生) ↔ sinh</strong>: 학생, 생일, 생활 (生活, sinh hoạt; nghĩa tiếng Hàn là cuộc sống)</li>\\n<li><strong>관 (館) ↔ quán</strong>: 도서관, 대사관</li>\\n<li><strong>원 (院) ↔ viện</strong>: 병원</li>\\n</ul>\\n<p>Cũng có quy luật ở phụ âm cuối:</p>\\n<ul>\\n<li>Âm Hàn tận cùng <strong>ㄱ (-k)</strong> thường ứng với <strong>-c/-ch</strong>: 학/học, 국/quốc, 족/tộc, 적/tịch.</li>\\n<li>Âm Hàn tận cùng <strong>ㄹ (-l)</strong> thường ứng với <strong>-t</strong>: 일/nhật, 활/hoạt, 결/kết.</li>\\n<li>Âm Hàn tận cùng <strong>ㅂ (-p)</strong> thường ứng với <strong>-p</strong>: 습/tập.</li>\\n<li>Âm Hàn tận cùng <strong>ㅇ (-ng)</strong> thường ứng với <strong>-ng/-nh</strong>: 생/sinh, 행/hàng, 경/kinh.</li>\\n</ul>\\n<p>Hãy coi đây là gợi ý để đoán, không phải luật tuyệt đối.</p>\\n<p>Nghiên cứu của 박종갑 và 레뚜언선 (2009) đối chiếu 2.353 từ Hán Hàn với 2.670 từ Hán-Việt tương ứng và chia chúng thành bốn nhóm: đồng hình đồng nghĩa hoàn toàn, đồng hình đồng nghĩa một phần, khác hình cùng nghĩa, và đồng hình khác nghĩa. Nói cách khác: nhiều từ khớp nhau, nhưng cũng có từ chỉ khớp một phần hoặc lệch nghĩa.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — sự tương ứng âm và nghĩa giữa từ Hán Hàn và Hán-Việt được mô tả trong nghiên cứu đối chiếu ngôn ngữ; đây là mô tả từ vựng, không phải thí nghiệm đo hiệu quả học.</p>\\n<h2 id=\\"nhung-cai-bay-can-biet\\">Những cái bẫy cần biết</h2>\\n<p><strong>Từ giống âm nhưng nghĩa đã trôi.</strong> Âm khớp nhưng nghĩa trong tiếng Hàn khác hẳn tiếng Việt:</p>\\n<div class=\\"table-scroll\\"><table>\\n<thead>\\n<tr>\\n<th>Tiếng Hàn</th>\\n<th>Hán tự</th>\\n<th>Âm Hán-Việt</th>\\n<th>Nghĩa trong tiếng Hàn</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>공부</td>\\n<td>工夫</td>\\n<td>công phu</td>\\n<td>việc học, học bài</td>\\n</tr>\\n<tr>\\n<td>방학</td>\\n<td>放學</td>\\n<td>phóng học</td>\\n<td>kỳ nghỉ của trường</td>\\n</tr>\\n<tr>\\n<td>약속</td>\\n<td>約束</td>\\n<td>ước thúc</td>\\n<td>lời hẹn, lời hứa</td>\\n</tr>\\n<tr>\\n<td>인간</td>\\n<td>人間</td>\\n<td>nhân gian</td>\\n<td>con người</td>\\n</tr>\\n</tbody></table></div>\\n<p>Tiếng Việt dùng &quot;công phu&quot; để chỉ sự kỹ lưỡng, tốn công; &quot;phóng học&quot; (từ cũ) là tan học, còn 방학 là cả kỳ nghỉ hè, nghỉ đông; &quot;ước thúc&quot; là ràng buộc; &quot;nhân gian&quot; là cõi đời. Nếu chỉ dựa vào âm, bạn sẽ hiểu sai.</p>\\n<p><strong>Nhiều từ không có gốc Hán.</strong> Từ thuần Hàn (사람 người, 물 nước, 먹다 ăn) và từ ngoại lai (버스, 아르바이트) không có âm Hán-Việt để đoán. Nhiều động từ thường gặp là từ Hán ghép với 하다 thuần Hàn: 공부하다, 준비하다, 결혼하다.</p>\\n<p><strong>Một âm Hàn, nhiều chữ Hán.</strong> Âm 수 có thể là 數 (số), 水 (thủy), 手 (thủ), 首 (thủ), 授 (thụ):</p>\\n<ul>\\n<li>수학 (數學, số học): môn toán</li>\\n<li>수영 (水泳, thủy vịnh): bơi lội</li>\\n<li>가수 (歌手, ca thủ): ca sĩ</li>\\n<li>수도 (首都, thủ đô): thủ đô</li>\\n<li>수업 (授業, thụ nghiệp): giờ học</li>\\n</ul>\\n<p>Vì vậy khi đoán sai, hãy nghĩ tới chữ Hán khác cùng âm trước khi bỏ cuộc.</p>\\n<h2 id=\\"vi-sao-tu-na-na-de-nho-hon\\">Vì sao từ &quot;na ná&quot; dễ nhớ hơn</h2>\\n<p>Từ có cùng gốc giữa hai ngôn ngữ, giống cả âm lẫn nghĩa, gọi là từ cùng gốc (cognate). De Groot và Keijzer (2000) cho người học ngoại ngữ có kinh nghiệm ở Hà Lan học từ mới theo cặp: từ tiếng mẹ đẻ đi với một từ giả (pseudoword). Từ giả được tạo để giống hoặc không giống từ tiếng mẹ đẻ. Kết quả: từ cùng gốc và từ chỉ vật cụ thể dễ học hơn và ít bị quên hơn so với từ không cùng gốc và từ trừu tượng. Tần suất của từ gần như không ảnh hưởng.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — hiệu ứng từ cùng gốc được ghi nhận nhiều lần, nhưng nghiên cứu này và phần lớn nghiên cứu tương tự làm trên người học các ngôn ngữ châu Âu, trong phòng thí nghiệm. Chưa có thí nghiệm có đối chứng đo trực tiếp lợi ích của âm Hán-Việt khi người Việt học từ Hán Hàn. Việc áp dụng ở đây là suy luận hợp lý, chưa phải kết quả đã đo.</p>\\n<p>Nghiên cứu trên cho thấy lợi thế đến từ việc từ mới <strong>giống</strong> từ đã biết. Suy ra: với từ &quot;bẫy&quot; ở phần trên, chính sự giống nhau có thể kéo bạn về nghĩa sai (nghiên cứu này không thử với từ bẫy). Nên kiểm tra nghĩa là bước bắt buộc, không phải tùy chọn.</p>\\n<h2 id=\\"cach-lam-tung-buoc\\">Cách làm từng bước</h2>\\n<ol>\\n<li><strong>Gặp từ mới, đoán trước.</strong> Thấy 교통, thử nghĩ: 교 có thể là &quot;giao&quot;, 통 có thể là &quot;thông&quot;, vậy là &quot;giao thông&quot;?</li>\\n<li><strong>Kiểm tra.</strong> Tra từ điển Hàn có ghi chữ Hán (표준국어대사전 hoặc từ điển Naver ghi 한자 bên cạnh mục từ). 교통 là 交通, giao thông, đúng.</li>\\n<li><strong>Ghi đủ bốn thứ.</strong> Ghi tiếng Hàn, chữ Hán (không cần viết được, chỉ cần nhìn), âm Hán-Việt và nghĩa tiếng Hàn. Nếu nghĩa khác tiếng Việt, đánh dấu riêng.</li>\\n<li><strong>Gom theo âm tiết chung.</strong> Lập một trang cho mỗi âm tiết hay gặp: 학 (학교, 학생, 대학, 학습, 방학), 국 (한국, 외국인, 국적), 원 院 (병원, 학원, 법원; còn 원 trong 공무원 公務員 là 員, &quot;viên&quot;). Mỗi lần gặp từ mới có âm tiết đó, thêm vào trang.</li>\\n<li><strong>Học cả từ thuần Hàn bên cạnh.</strong> Nhiều khái niệm có cả hai: 집 (thuần Hàn) và 가정 (家庭, gia đình). Biết cả hai giúp bạn hiểu cả hội thoại lẫn văn bản hành chính.</li>\\n</ol>\\n<h2 id=\\"ap-dung-ngay\\">Áp dụng ngay</h2>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1pdcw53\\"><span>Mở bài KIIP đang học, gạch chân 10 từ bạn đoán là 한자어 và thử đoán âm Hán-Việt.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"nxcvf9\\"><span>Tra lại 10 từ đó trong từ điển có ghi chữ Hán, đánh dấu từ nào đoán đúng, từ nào nghĩa khác tiếng Việt.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1rrxv6z\\"><span>Lập trang gom từ cho ba âm tiết: 학, 국, 생.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1ux4icw\\"><span>Ghi riêng một danh sách &quot;từ bẫy&quot; (như 공부, 약속, 방학) và ôn lại cuối tuần.</span></label></li>\\n</ul>\\n<h2 id=\\"tren-haechivn\\">Trên HaechiVN</h2>\\n<ul>\\n<li><a href=\\"/books/step1/roadmap\\">Lộ trình KIIP có dịch từng câu</a>: đọc bài khoá và nhặt 한자어 ngay trong ngữ cảnh.</li>\\n<li><a href=\\"/tieng-han\\">Thư viện giáo trình tiếng Hàn</a>: toàn bộ sách KIIP và sách bài tập; đọc tiếp các bài khác để gặp lại âm tiết đã gom.</li>\\n<li><a href=\\"/ngu-phap\\">Ngữ pháp</a>: tra các cấu trúc KIIP Sơ cấp 1 đến Trung cấp 2 bằng tiếng Hàn hoặc tiếng Việt.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://www.korean.go.kr/poldata/realmStats/realmStatsView.do?realm_stats_no=1487\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국립국어원 (2022). 2022 숫자로 살펴보는 우리말: 표준국어대사전 어종별 현황</a> <span class=\\"source-domain\\">korean.go.kr</span></li>\\n<li><a href=\\"https://www.kci.go.kr/kciportal/ci/sereArticleSearch/ciSereArtiView.kci?sereArticleSearchBean.artiId=ART001399431\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">박종갑, 레뚜언선 (2009). 한국어와 베트남어의 한자어 어휘 대조 연구. 민족문화논총 43, 309–329</a> <span class=\\"source-domain\\">kci.go.kr</span></li>\\n<li><a href=\\"https://doi.org/10.1111/0023-8333.00110\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">De Groot, A. M. B. &amp; Keijzer, R. (2000). What is hard to learn is easy to forget: The roles of word concreteness, cognate status, and word frequency in foreign-language vocabulary learning and forgetting. Language Learning 50(1), 1–56</a> <span class=\\"source-domain\\">doi.org</span></li>\\n</ul>","headings":[{"id":"la-gi-va-chiem-bao-nhieu","text":"한자어 là gì và chiếm bao nhiêu","level":2},{"id":"quy-luat-am-giua-tieng-han-va-han-viet","text":"Quy luật âm giữa tiếng Hàn và Hán-Việt","level":2},{"id":"nhung-cai-bay-can-biet","text":"Những cái bẫy cần biết","level":2},{"id":"vi-sao-tu-na-na-de-nho-hon","text":"Vì sao từ \\"na ná\\" dễ nhớ hơn","level":2},{"id":"cach-lam-tung-buoc","text":"Cách làm từng bước","level":2},{"id":"ap-dung-ngay","text":"Áp dụng ngay","level":2},{"id":"tren-haechivn","text":"Trên HaechiVN","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":4},{"slug":"luyen-de-topik-thong-minh","title":"Luyện đề TOPIK thông minh","summary":"Dùng đề TOPIK cũ để học chứ không chỉ để chấm điểm: luyện từng phần, thi thử có giờ, ghi sổ lỗi sai và ôn lại cách quãng.","updated":"2026-10-01","facts":{"group":"Học tiếng"},"html":"<p>Nhiều người luyện TOPIK bằng cách làm hết đề này sang đề khác, xem điểm rồi bỏ qua. Điểm nhích lên một chút rồi đứng yên, vì lỗi cũ vẫn lặp lại ở đề sau. Bài này nói cách dùng đề cũ để thật sự học.</p>\\n<h2 id=\\"de-topik-gom-nhung-gi\\">Đề TOPIK gồm những gì</h2>\\n<p>Số liệu dưới đây là của bài thi trên giấy (PBT), theo trang TOPIK của 국립국제교육원 (NIIED, Viện Giáo dục Quốc tế Quốc gia, đơn vị tổ chức TOPIK), trang cập nhật ngày 17/9/2025, kiểm tra lại năm 2026.</p>\\n<p><strong>TOPIK I</strong> (초급, sơ cấp) có hai phần: 듣기 (nghe) 30 câu và 읽기 (đọc) 40 câu. Tổng thời gian 100 phút, tổng điểm 200.</p>\\n<ul>\\n<li>1급 (cấp 1): 80–139 điểm</li>\\n<li>2급 (cấp 2): 140–200 điểm</li>\\n</ul>\\n<p><strong>TOPIK II</strong> (중·고급, trung và cao cấp) có ba phần: 듣기 50 câu, 쓰기 (viết) 4 câu, 읽기 50 câu. Tổng thời gian 180 phút, tổng điểm 300.</p>\\n<ul>\\n<li>3급: 120–149 điểm</li>\\n<li>4급: 150–189 điểm</li>\\n<li>5급: 190–229 điểm</li>\\n<li>6급: 230–300 điểm</li>\\n</ul>\\n<p>Cấp được xét theo tổng điểm. Dưới 80 điểm (TOPIK I) hoặc dưới 120 điểm (TOPIK II) thì không có cấp.</p>\\n<p>Ngoài bản giấy còn có TOPIK IBT (thi trên máy tính). Bản này có số câu, thời gian và thang điểm khác hẳn (ví dụ TOPIK II IBT tính trên 600 điểm). Nếu bạn định thi IBT, hoặc muốn biết thời gian từng phần, lịch thi, lệ phí, hãy xem trực tiếp trên topik.go.kr vì định dạng có thể thay đổi.</p>\\n<h2 id=\\"lam-de-la-mot-cach-hoc-khong-chi-de-do\\">Làm đề là một cách học, không chỉ để đo</h2>\\n<p>Khi bạn cố nhớ lại một từ, một ngữ pháp để trả lời câu hỏi, việc nhớ lại đó giúp kiến thức bám lâu hơn so với đọc lại. Hiện tượng này gọi là hiệu ứng kiểm tra (testing effect).</p>\\n<p>Roediger và Karpicke (2006) cho sinh viên đọc các đoạn văn, rồi một nhóm làm bài kiểm tra nhớ lại, nhóm kia đọc lại số lần tương đương. Khi kiểm tra sau 5 phút, nhóm đọc lại nhớ tốt hơn. Nhưng khi kiểm tra sau 2 ngày và 1 tuần, nhóm làm bài kiểm tra nhớ tốt hơn rõ rệt. Nhóm đọc lại lại tự tin hơn vào trí nhớ của mình. Nghĩa là cảm giác &quot;đọc lại thấy quen&quot; dễ đánh lừa ta.</p>\\n<p>Bài tổng quan của Dunlosky và cộng sự (2013) xếp tự kiểm tra (practice testing) vào nhóm &quot;hữu ích cao&quot;, còn đọc lại và tô đậm ở nhóm &quot;hữu ích thấp&quot;.</p>\\n<p>Áp dụng: sau mỗi đề, phần học quan trọng nhất là lúc bạn xem lại từng câu sai và tự giải thích vì sao đáp án đúng là đúng.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — nhiều thí nghiệm và một bài tổng quan lớn, nhưng chủ yếu trên học sinh, sinh viên Mỹ học văn bản tiếng mẹ đẻ, chưa phải nghiên cứu riêng về TOPIK.</p>\\n<h2 id=\\"xem-lai-dap-an-ngay-sau-khi-lam\\">Xem lại đáp án ngay sau khi làm</h2>\\n<p>Với câu hỏi chọn đáp án, có một rủi ro: bạn có thể nhớ nhầm phương án sai mà mình đã chọn. Butler và Roediger (2008) cho thấy khi người học được biết đáp án đúng sau bài trắc nghiệm, dù ngay lập tức hay sau một lúc, họ trả lời đúng nhiều hơn ở bài kiểm tra sau và ít lặp lại phương án sai hơn so với khi không được biết đáp án.</p>\\n<p>Hattie và Timperley (2007) tổng quan nghiên cứu về phản hồi (feedback) và kết luận phản hồi là một trong những yếu tố ảnh hưởng mạnh tới việc học, nhưng hiệu quả tùy loại phản hồi và cách đưa ra. Chỉ biết &quot;sai 12 câu&quot; là phản hồi rất nghèo. Biết &quot;sai vì không nhận ra ngữ pháp -는 바람에 (vì… nên, thường kèm kết quả xấu)&quot; thì bạn biết phải sửa gì.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — Butler và Roediger là thí nghiệm trong phòng lab với đoạn văn tiếng Anh; Hattie và Timperley là bài tổng quan rộng về giáo dục, không riêng học ngoại ngữ.</p>\\n<h2 id=\\"hai-cach-luyen-tung-phan-va-thi-thu-co-gio\\">Hai cách luyện: từng phần và thi thử có giờ</h2>\\n<p><strong>Luyện từng phần</strong> (chỉ 듣기, chỉ 읽기, hoặc một nhóm câu cùng dạng): không bấm giờ hoặc bấm giờ lỏng, chấm ngay, xem lại từng câu. Cách này hợp khi:</p>\\n<ul>\\n<li>Còn xa ngày thi, bạn đang lấp lỗ hổng từ vựng, ngữ pháp.</li>\\n<li>Bạn thấy một dạng câu hỏi hay sai, ví dụ câu chọn ý chính hoặc câu sắp xếp thứ tự câu văn.</li>\\n<li>Bạn mới làm quen với đề, chưa biết mỗi câu hỏi gì.</li>\\n</ul>\\n<p><strong>Thi thử trọn đề có giờ</strong>: làm liền một mạch đúng thời gian thi, không dừng tra từ, chấm sau khi xong. Cách này hợp khi:</p>\\n<ul>\\n<li>Còn vài tuần trước ngày thi.</li>\\n<li>Bạn cần biết mình có làm kịp giờ không, phần nào bị dồn cuối.</li>\\n<li>Bạn cần quen giữ tập trung suốt 100 phút (TOPIK I) hoặc 180 phút (TOPIK II).</li>\\n</ul>\\n<p>Nhìn chung: học phần lớn bằng luyện từng phần, dùng thi thử để kiểm tra định kỳ và tập phân bổ thời gian.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — suy ra từ hiệu ứng kiểm tra và vai trò của phản hồi nêu ở trên; chưa có nghiên cứu so sánh trực tiếp hai cách này trên người thi TOPIK.</p>\\n<h2 id=\\"so-loi-sai-va-on-cach-quang\\">Sổ lỗi sai và ôn cách quãng</h2>\\n<p>Mỗi câu sai, ghi một dòng vào sổ (giấy hay file đều được): đề nào, câu số mấy, sai vì sao, điều đúng là gì. Chia lý do thành năm loại:</p>\\n<ol>\\n<li><strong>Từ vựng</strong>: không biết hoặc nhầm nghĩa từ.</li>\\n<li><strong>Ngữ pháp</strong>: không hiểu hoặc nhầm một cấu trúc.</li>\\n<li><strong>Không hiểu dạng câu hỏi</strong>: hiểu bài nhưng không rõ câu hỏi muốn gì.</li>\\n<li><strong>Hết giờ</strong>: không kịp làm hoặc phải đoán.</li>\\n<li><strong>Bất cẩn</strong>: biết nhưng chọn nhầm, đọc sót chữ 않는 (không).</li>\\n</ol>\\n<p>Sau vài đề, bạn sẽ thấy loại lỗi nào nhiều nhất, ví dụ nhiều lỗi hết giờ thì cần thi thử có giờ thường hơn.</p>\\n<p>Đừng ôn sổ lỗi một lần rồi thôi. Ôn lại sau vài ngày, rồi sau một tuần. Cepeda và cộng sự (2006) gộp 317 thí nghiệm về nhớ thông tin bằng lời và thấy học trải ra nhiều buổi cách nhau giúp nhớ lâu hơn học dồn một lần. Họ cũng thấy muốn nhớ càng lâu thì khoảng cách giữa các lần ôn nên càng dài.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — phân tích gộp hàng trăm thí nghiệm, chủ yếu với nhiệm vụ nhớ từ, sự kiện; khoảng cách tối ưu cụ thể cho từng người vẫn chưa có con số cố định.</p>\\n<h2 id=\\"dung-lam-di-lam-lai-mot-de-den-thuoc\\">Đừng làm đi làm lại một đề đến thuộc</h2>\\n<p>Làm lại một đề lần thứ ba, thứ tư, điểm thường tăng. Nhưng lúc đó bạn đang đo trí nhớ về đáp án, không phải khả năng nghe hiểu, đọc hiểu.</p>\\n<p>Nên làm lại theo cách khác: chỉ làm lại những câu đã sai, sau vài ngày, và phải tự nói ra lý do chọn đáp án. Khi đánh giá trình độ, dùng một đề bạn chưa làm bao giờ.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — suy ra từ hiệu ứng kiểm tra và ôn ngắt quãng; chưa có nghiên cứu đo riêng việc làm lại cùng một đề thi ngoại ngữ.</p>\\n<h2 id=\\"goi-y-ke-hoach-4-tuan-truoc-ngay-thi\\">Gợi ý kế hoạch 4 tuần trước ngày thi</h2>\\n<p>Đây chỉ là một gợi ý để bạn điều chỉnh, không phải kế hoạch đã được nghiên cứu kiểm chứng.</p>\\n<ul>\\n<li><strong>Tuần 1</strong>: thi thử một đề trọn vẹn có giờ để biết điểm xuất phát. Mở sổ lỗi sai. Những ngày còn lại luyện từng phần theo loại lỗi nhiều nhất.</li>\\n<li><strong>Tuần 2</strong>: luyện từng phần mỗi ngày (nghe một hôm, đọc một hôm; TOPIK II thêm viết). Ôn sổ lỗi của tuần 1. Cuối tuần thi thử một đề mới.</li>\\n<li><strong>Tuần 3</strong>: tiếp tục luyện từng phần với dạng câu còn yếu. Ôn lại lỗi tuần 1 và tuần 2. Cuối tuần thi thử đề mới, chú ý phân bổ thời gian.</li>\\n<li><strong>Tuần 4</strong>: một đề thi thử đầu tuần, đúng khung giờ thi thật nếu được. Những ngày sau chủ yếu ôn sổ lỗi, không học dồn nội dung mới. Ngày cuối nghỉ ngơi, chuẩn bị giấy tờ dự thi.</li>\\n</ul>\\n<h2 id=\\"ap-dung-ngay\\">Áp dụng ngay</h2>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1se3blx\\"><span>Làm phần nghe hoặc đọc của một đề chưa từng làm, chấm ngay.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1d99fij\\"><span>Mở sổ lỗi sai, ghi mỗi câu sai kèm một trong năm loại lỗi.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"gi9la1\\"><span>Đặt lịch ôn lại sổ lỗi sau 2–3 ngày và sau 1 tuần.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"87cqli\\"><span>Ghi ngày thi thử trọn đề có giờ đầu tiên vào lịch.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"32kibn\\"><span>Kiểm tra trên topik.go.kr xem bạn thi bản giấy hay IBT để luyện đúng định dạng.</span></label></li>\\n</ul>\\n<h2 id=\\"tren-haechivn\\">Trên HaechiVN</h2>\\n<ul>\\n<li><a href=\\"/exam/topik-i\\">Đề TOPIK I</a> và <a href=\\"/exam/topik-ii\\">Đề TOPIK II</a>: đề thi thật các kỳ trước. Mỗi đề có thể luyện từng phần, chấm điểm ngay, hoặc làm như một bài thi thử có giờ.</li>\\n<li><a href=\\"/ngu-phap\\">Ngữ pháp</a>: tra lại ngữ pháp bạn vừa làm sai.</li>\\n<li><a href=\\"/my\\">Góc học tập</a>: xem các điểm ngữ pháp được gợi ý ôn lại.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://www.niied.go.kr/web/niied/contents/niied_topik\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">국립국제교육원 NIIED (2025). 한국어능력시험(TOPIK): 시험 수준 및 평가 등급</a> <span class=\\"source-domain\\">niied.go.kr</span></li>\\n<li><a href=\\"https://www.topik.go.kr\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">TOPIK 한국어능력시험 (trang chính thức)</a> <span class=\\"source-domain\\">topik.go.kr</span></li>\\n<li><a href=\\"https://doi.org/10.1111/j.1467-9280.2006.01693.x\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Roediger &amp; Karpicke (2006). Test-enhanced learning: Taking memory tests improves long-term retention. Psychological Science</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1177/1529100612453266\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Dunlosky, Rawson, Marsh, Nathan &amp; Willingham (2013). Improving students&#39; learning with effective learning techniques. Psychological Science in the Public Interest</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.3758/MC.36.3.604\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Butler &amp; Roediger (2008). Feedback enhances the positive effects and reduces the negative effects of multiple-choice testing. Memory &amp; Cognition</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.3102/003465430298487\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Hattie &amp; Timperley (2007). The power of feedback. Review of Educational Research</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1037/0033-2909.132.3.354\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Cepeda, Pashler, Vul, Wixted &amp; Rohrer (2006). Distributed practice in verbal recall tasks: A review and quantitative synthesis. Psychological Bulletin</a> <span class=\\"source-domain\\">doi.org</span></li>\\n</ul>","headings":[{"id":"de-topik-gom-nhung-gi","text":"Đề TOPIK gồm những gì","level":2},{"id":"lam-de-la-mot-cach-hoc-khong-chi-de-do","text":"Làm đề là một cách học, không chỉ để đo","level":2},{"id":"xem-lai-dap-an-ngay-sau-khi-lam","text":"Xem lại đáp án ngay sau khi làm","level":2},{"id":"hai-cach-luyen-tung-phan-va-thi-thu-co-gio","text":"Hai cách luyện: từng phần và thi thử có giờ","level":2},{"id":"so-loi-sai-va-on-cach-quang","text":"Sổ lỗi sai và ôn cách quãng","level":2},{"id":"dung-lam-di-lam-lai-mot-de-den-thuoc","text":"Đừng làm đi làm lại một đề đến thuộc","level":2},{"id":"goi-y-ke-hoach-4-tuan-truoc-ngay-thi","text":"Gợi ý kế hoạch 4 tuần trước ngày thi","level":2},{"id":"ap-dung-ngay","text":"Áp dụng ngay","level":2},{"id":"tren-haechivn","text":"Trên HaechiVN","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":5},{"slug":"doc-code-truoc-viet-sau","title":"Đọc code trước, viết code sau","summary":"Vì sao người mới học lập trình nên đọc, đoán và sửa code có sẵn trước khi tự viết từ đầu, và cách làm theo từng bước với một ví dụ Java.","updated":"2026-10-01","facts":{"group":"Học lập trình"},"html":"<p>Nhiều người mới học lập trình mở trình soạn thảo trống, đọc đề bài, rồi ngồi im rất lâu, vì phải lo cùng lúc quá nhiều thứ: cú pháp, biến, vòng lặp, logic của bài. Bài này nói về một cách bắt đầu khác: đọc và hiểu code có sẵn trước, rồi mới tự viết.</p>\\n<h2 id=\\"vi-sao-trang-trang-lam-nguoi-moi-bi-ket\\">Vì sao trang trắng làm người mới bị kẹt</h2>\\n<p>Bộ nhớ làm việc (working memory) của con người chỉ xử lý được vài thông tin cùng một lúc. Người có kinh nghiệm đã có sẵn các &quot;khuôn&quot; trong đầu, ví dụ &quot;vòng lặp cộng dồn&quot;, nên nhìn một đoạn code là nhận ra ngay. Người mới chưa có khuôn nào, nên mỗi dòng là một thứ riêng phải nghĩ.</p>\\n<p>Kirschner, Sweller và Clark (2006) tổng hợp nghiên cứu và lập luận rằng với người mới, cách dạy có hướng dẫn rõ ràng hiệu quả hơn cách để người học tự khám phá. Một hiện tượng họ nhắc tới là hiệu ứng ví dụ mẫu (worked example effect): học từ lời giải mẫu chi tiết thường tốt hơn tự giải bài từ đầu, vì người học không phải mò mẫm thử sai. Bài này là bài lập luận và tổng quan, không phải một thí nghiệm, và đã bị một số nhà nghiên cứu phản biện.</p>\\n<p>Có một điều kiện quan trọng. Kalyuga và cộng sự (2003) tổng hợp các thí nghiệm cho thấy cách dạy rất có lợi cho người mới có thể mất tác dụng, thậm chí gây hại, với người đã có kinh nghiệm. Họ gọi đây là hiệu ứng đảo ngược theo trình độ (expertise reversal effect). Ví dụ, thợ cơ khí học nghề lúc mới bắt đầu học tốt hơn với ví dụ mẫu. Khi đã có kinh nghiệm, ưu thế đó mất đi, và về sau tự giải bài lại giúp học tốt hơn. Bài tổng quan này cũng dẫn các nghiên cứu cho thấy nên giảm dần phần lời giải mẫu thay vì chuyển đột ngột sang tự làm.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — hiệu ứng ví dụ mẫu và hiệu ứng đảo ngược theo trình độ được lặp lại trong nhiều thí nghiệm, phần lớn ở toán, vật lý và kỹ thuật. Áp dụng vào lập trình là suy ra từ nguyên tắc chung.</p>\\n<h2 id=\\"primm-nam-buoc-tu-doc-toi-viet\\">PRIMM: năm bước từ đọc tới viết</h2>\\n<p>PRIMM là cách tổ chức bài học lập trình gồm năm bước: Predict (đoán), Run (chạy), Investigate (tìm hiểu), Modify (sửa), Make (tự làm). Sentance, Waite và Kallia (2019) thử PRIMM với 13 giáo viên ở các trường trung học tại Anh, gồm 493 học sinh 11–14 tuổi học Python trong 8–12 tuần, so với 180 học sinh lớp đối chứng học theo cách thường ngày của trường.</p>\\n<p>Kết quả: nhóm PRIMM làm bài kiểm tra cuối tốt hơn nhóm đối chứng, có ý nghĩa thống kê, nhưng mức chênh nhỏ (hệ số r = 0,13). Học sinh không được chia nhóm ngẫu nhiên (các tác giả nêu rõ điều này), và giáo viên tham gia theo lời mời tự nguyện. Sáu giáo viên kể rằng một số học sinh dừng ở bước Modify, chưa tới được bước Make.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — một nghiên cứu bán thực nghiệm, học sinh phổ thông ở Anh, hiệu quả nhỏ. Chưa có bằng chứng riêng cho người lớn tự học.</p>\\n<p>Dưới đây là cách tự làm PRIMM với một đoạn Java.</p>\\n<pre><code class=\\"language-java\\">public class Main {\\n    public static void main(String[] args) {\\n        int[] data = { -3, 8, -4, 7, 10 };\\n        System.out.println(sumEven(data));\\n    }\\n\\n    static int sumEven(int[] numbers) {\\n        int sum = 0;\\n        for (int i = 0; i &lt; numbers.length; i++) {\\n            if (numbers[i] % 2 == 0) {\\n                sum += numbers[i];\\n            }\\n        }\\n        return sum;\\n    }\\n}\\n</code></pre>\\n<p><strong>1. Predict (đoán).</strong> Chưa chạy vội. Viết ra giấy: chương trình in ra số mấy? Ghi cả lý do, ví dụ &quot;cộng các số chẵn: 8, -4, 10&quot;.</p>\\n<p><strong>2. Run (chạy).</strong> Chạy thử. Kết quả là <code>14</code>. Nếu đoán sai, đừng bỏ qua. Tìm xem mình hiểu sai ở dòng nào.</p>\\n<p><strong>3. Investigate (tìm hiểu).</strong> Tự đặt câu hỏi cho từng phần:</p>\\n<ul>\\n<li><code>-4 % 2</code> bằng bao nhiêu? (Bằng <code>0</code>, nên -4 được cộng.)</li>\\n<li><code>-3 % 2</code> bằng bao nhiêu? Trong Java, dấu của phép chia lấy dư theo số bị chia, nên kết quả là <code>-1</code>, không phải <code>1</code>.</li>\\n<li>Nếu đổi <code>i &lt; numbers.length</code> thành <code>i &lt;= numbers.length</code> thì sao? (Chương trình báo lỗi <code>ArrayIndexOutOfBoundsException</code>, vì chỉ số cuối là <code>length - 1</code>.)</li>\\n<li>Biến <code>sum</code> có giá trị bao nhiêu sau mỗi vòng lặp? Lập bảng: ban đầu là 0, sau từng vòng là 0, 8, 4, 4, 14.</li>\\n</ul>\\n<p><strong>4. Modify (sửa).</strong> Sửa hàm để cộng các số lẻ. Nhiều người viết <code>numbers[i] % 2 == 1</code> và nhận được <code>7</code>, thiếu số -3. Câu hỏi ở bước Investigate đã gợi ý vì sao. Điều kiện đúng là <code>numbers[i] % 2 != 0</code>, cho kết quả <code>4</code>.</p>\\n<p><strong>5. Make (tự làm).</strong> Đóng ví dụ lại. Tự viết một hàm mới cùng cấu trúc nhưng làm việc khác, ví dụ đếm có bao nhiêu số lớn hơn 5 trong mảng.</p>\\n<h2 id=\\"bai-sap-xep-dong-code-parsons-problems\\">Bài sắp xếp dòng code (Parsons problems)</h2>\\n<p>Bài Parsons cho sẵn đủ các dòng code của lời giải nhưng bị xáo trộn. Người học chỉ cần sắp xếp lại đúng thứ tự và thụt lề. Một số bài có thêm dòng &quot;gây nhiễu&quot; chứa lỗi thường gặp, phải chọn giữa dòng đúng và dòng sai.</p>\\n<p>Ericson, Margulieux và Rick (2017) cho 135 sinh viên học môn lập trình nhập môn đầu tiên của ngành máy tính ở một đại học Mỹ, học Python, luyện bằng một trong ba cách: sắp xếp dòng code, sửa code có lỗi, hoặc tự viết code. Nhóm sắp xếp dòng code làm xong bài luyện nhanh hơn rõ rệt (tổng khoảng 473 giây, so với khoảng 680 và 714 giây). Điểm kiểm tra ngay sau đó và sau một tuần không khác nhau có ý nghĩa giữa ba nhóm. Các tác giả cũng lưu ý thiếu nhóm đối chứng không luyện tập, nên chưa chắc tiến bộ đến từ chính bài luyện.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — một thí nghiệm chia nhóm ngẫu nhiên, sinh viên đại học Mỹ, chỉ bốn bài luyện ngắn.</p>\\n<p>Cách tự làm: xáo thứ tự các dòng của một hàm vừa học, để vài ngày rồi sắp xếp lại.</p>\\n<h2 id=\\"tu-giai-thich-tung-dong\\">Tự giải thích từng dòng</h2>\\n<p>Chi và cộng sự (1989) ghi âm 8 sinh viên vừa nghĩ vừa nói khi đọc lời giải mẫu bài tập cơ học. Sinh viên giải bài giỏi thường tự giải thích từng bước và nối nó với nguyên lý trong sách. Sinh viên giải kém ít tự giải thích. Đây chỉ là quan sát, chưa chứng minh tự giải thích là nguyên nhân.</p>\\n<p>Chi và cộng sự (1994) thử trực tiếp hơn: 14 học sinh lớp 8 được yêu cầu tự giải thích sau mỗi câu khi đọc bài về hệ tuần hoàn, 10 học sinh khác đọc bài hai lần. Nhóm được yêu cầu tự giải thích tiến bộ nhiều hơn từ bài kiểm tra đầu đến bài kiểm tra cuối.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — hai nghiên cứu nhỏ, ở vật lý và sinh học, không phải lập trình.</p>\\n<p>Cách làm với code: viết một dòng chú thích tiếng Việt bằng lời của mình cạnh mỗi dòng. Không viết lại cú pháp (&quot;cộng sum với numbers[i]&quot;) mà viết mục đích (&quot;thêm số chẵn này vào tổng&quot;). Dòng nào không viết được thì đó là chỗ chưa hiểu.</p>\\n<h2 id=\\"khi-nao-chuyen-sang-tu-viet\\">Khi nào chuyển sang tự viết</h2>\\n<p>Theo hiệu ứng đảo ngược theo trình độ, đọc ví dụ mẫu mãi cũng không tốt. Một cách chuyển dần:</p>\\n<ol>\\n<li>Làm đủ năm bước PRIMM với một đoạn code.</li>\\n<li>Khi Modify trơn tru, làm Make với một biến thể nhỏ, không nhìn ví dụ.</li>\\n<li>Khi đã tự viết được vài biến thể, chuyển sang dự án nhỏ ghép nhiều phần lại, ví dụ chương trình quản lý danh sách chi tiêu.</li>\\n<li>Gặp khái niệm mới (lớp, interface, Stream API) thì quay lại đọc ví dụ trước.</li>\\n</ol>\\n<p>Công cụ AI có thể sinh code mẫu để đọc, nhưng bước đoán và tự giải thích vẫn phải do bạn làm.</p>\\n<h2 id=\\"ap-dung-ngay\\">Áp dụng ngay</h2>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"x4f49p\\"><span>Chọn một đoạn code ngắn trong bài vừa học, viết ra giấy kết quả dự đoán trước khi chạy.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1t4xmvz\\"><span>Đặt ít nhất ba câu hỏi &quot;nếu đổi dòng này thì sao&quot; và chạy thử từng câu.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"m2wt4f\\"><span>Viết chú thích tiếng Việt cho mỗi dòng bằng lời của mình.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"lo2mkm\\"><span>Sửa đoạn code để làm một việc khác một chút, rồi đóng ví dụ và tự viết một biến thể mới.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1tqpud9\\"><span>Xáo thứ tự các dòng của một hàm đã học và tự sắp xếp lại sau vài ngày.</span></label></li>\\n</ul>\\n<h2 id=\\"tren-haechivn\\">Trên HaechiVN</h2>\\n<ul>\\n<li><a href=\\"/java\\">Khoá Java</a> và <a href=\\"/java/java-core\\">Java Core</a>: mỗi bài có giải thích và ví dụ code để đọc, đoán kết quả; nhiều bài có câu hỏi kiểm tra cuối bài.</li>\\n<li><a href=\\"/it\\">Khoá C# .NET</a> và <a href=\\"/it/csharp-core\\">C# Core</a>: cùng cấu trúc, dùng được PRIMM nếu bạn học C#.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://doi.org/10.1207/s15326985ep4102_1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Kirschner, Sweller &amp; Clark (2006). Why minimal guidance during instruction does not work: An analysis of the failure of constructivist, discovery, problem-based, experiential, and inquiry-based teaching. Educational Psychologist</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1207/S15326985EP3801_4\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Kalyuga, Ayres, Chandler &amp; Sweller (2003). The expertise reversal effect. Educational Psychologist</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1080/08993408.2019.1608781\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Sentance, Waite &amp; Kallia (2019). Teaching computer programming with PRIMM: a sociocultural perspective. Computer Science Education</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1145/3141880.3141895\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Ericson, Margulieux &amp; Rick (2017). Solving Parsons problems versus fixing and writing code. Koli Calling 2017</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1207/s15516709cog1302_1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Chi, Bassok, Lewis, Reimann &amp; Glaser (1989). Self-explanations: How students study and use examples in learning to solve problems. Cognitive Science</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1207/s15516709cog1803_3\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Chi, de Leeuw, Chiu &amp; LaVancher (1994). Eliciting self-explanations improves understanding. Cognitive Science</a> <span class=\\"source-domain\\">doi.org</span></li>\\n</ul>","headings":[{"id":"vi-sao-trang-trang-lam-nguoi-moi-bi-ket","text":"Vì sao trang trắng làm người mới bị kẹt","level":2},{"id":"primm-nam-buoc-tu-doc-toi-viet","text":"PRIMM: năm bước từ đọc tới viết","level":2},{"id":"bai-sap-xep-dong-code-parsons-problems","text":"Bài sắp xếp dòng code (Parsons problems)","level":2},{"id":"tu-giai-thich-tung-dong","text":"Tự giải thích từng dòng","level":2},{"id":"khi-nao-chuyen-sang-tu-viet","text":"Khi nào chuyển sang tự viết","level":2},{"id":"ap-dung-ngay","text":"Áp dụng ngay","level":2},{"id":"tren-haechivn","text":"Trên HaechiVN","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":5},{"slug":"thoat-vong-xem-huong-dan","title":"Thoát vòng xem hướng dẫn","summary":"Vì sao xem và làm theo video hướng dẫn mãi vẫn chưa tự viết được chương trình, và một lộ trình năm bậc để giảm dần sự dẫn dắt, có ví dụ Java.","updated":"2026-10-01","facts":{"group":"Học lập trình"},"html":"<p>Nhiều người học lập trình đã xem hết một khoá video, gõ theo được mọi dòng, nhưng mở một dự án trống thì không biết bắt đầu từ đâu. Cách xử lý quen thuộc là tìm thêm một khoá khác, và vòng lặp cứ thế tiếp diễn. Người học gọi đây là &quot;tutorial hell&quot;. Bài <a href=\\"/cam-nang/hoc-tap/doc-code-truoc-viet-sau\\">Đọc code trước, viết code sau</a> đã nói về ví dụ mẫu, PRIMM và tự giải thích; bài này nói về bước tiếp theo: làm sao bỏ dần hướng dẫn.</p>\\n<h2 id=\\"vi-sao-lam-theo-huong-dan-cho-cam-giac-da-hoc\\">Vì sao làm theo hướng dẫn cho cảm giác đã học</h2>\\n<p>Khi xem một người giải thích trôi chảy rồi gõ lại từng dòng họ viết, mọi thứ đều hợp lý và không có chỗ nào bị kẹt. Cảm giác &quot;dễ hiểu&quot; này dễ bị nhầm thành &quot;mình làm được&quot;.</p>\\n<p>Bjork, Dunlosky và Kornell (2013) tổng quan nghiên cứu về việc người học tự quản lý việc học. Họ kết luận rằng con người thường hình dung sai về cách mình học và nhớ, nên dễ đánh giá sai và sắp xếp sai việc học. Một lý do họ phân tích: người học đánh giá mức đã học dựa vào kết quả thấy ngay lúc học và vào cảm giác trôi chảy (fluency) khi xử lý thông tin. Khi gõ theo video, kết quả lúc đó luôn tốt vì đáp án nằm sẵn trên màn hình. Cảm giác trôi chảy đó không cho biết bạn có tự làm lại được khi tắt video hay không.</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — bài tổng quan dựa trên nhiều thí nghiệm về trí nhớ và tự đánh giá của người học. Không có thí nghiệm riêng về video lập trình; áp dụng vào lập trình là suy ra từ nguyên tắc chung.</p>\\n<p>Cách kiểm tra: tắt video, đóng code mẫu, thử viết lại. Chỗ bị kẹt là chỗ chưa thật sự học.</p>\\n<h2 id=\\"rut-dan-su-dan-dat-khong-bo-dot-ngot\\">Rút dần sự dẫn dắt, không bỏ đột ngột</h2>\\n<p>Lỗi thường gặp là nhảy thẳng từ &quot;gõ theo video&quot; sang &quot;tự làm cả ứng dụng&quot;. Khoảng cách quá lớn, người học bị kẹt rồi quay lại xem video.</p>\\n<p>Renkl và Atkinson (2003) lập luận rằng lúc mới học, học từ lời giải mẫu hiệu quả hơn tự giải bài, nhưng về sau thì ngược lại. Họ đề xuất cách giảm dần (fading): ví dụ ban đầu có đủ các bước, rồi bỏ trống dần từng bước để người học tự điền, cho tới khi tự giải toàn bộ. Đây là bài lý thuyết kèm tổng hợp bằng chứng.</p>\\n<p>Atkinson, Renkl và Merrill (2003) ghi nhận rằng giảm dần các bước giải giúp làm tốt hơn bài tương tự (near transfer) so với học theo cặp &quot;một ví dụ, một bài tập&quot;, nhưng không ổn định với bài khác dạng (far transfer). Khi thêm câu hỏi yêu cầu chỉ ra nguyên lý sau mỗi bước, hai thí nghiệm cho hiệu quả từ vừa tới lớn trên cả hai loại bài, không tốn thêm thời gian học.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — vài thí nghiệm có đối chứng về học qua lời giải mẫu, không phải lập trình.</p>\\n<h2 id=\\"thu-tu-giai-truoc-khi-xem-loi-giai\\">Thử tự giải trước khi xem lời giải</h2>\\n<p>Một hướng nghiên cứu khác đi ngược thói quen &quot;xem trước, làm sau&quot;. Kapur (2008) cho học sinh lớp 11 học động học Newton: một nhóm giải bài phức tạp, không có cấu trúc rõ trước, nhóm kia chỉ giải bài có cấu trúc rõ. Nhóm đầu ban đầu thất bại, nhưng sau đó làm bài kiểm tra cá nhân tốt hơn ở cả bài tương tự lẫn bài khác dạng. Kapur gọi đây là thất bại có ích (productive failure).</p>\\n<p>Sinha và Kapur (2021) phân tích gộp 53 nghiên cứu với 166 phép so sánh giữa &quot;giải bài trước rồi mới học&quot; và &quot;học trước rồi mới giải bài&quot;. Kết quả nghiêng về cách giải bài trước, mức vừa (Hedges&#39; g = 0,36). Nhưng với học sinh nhỏ tuổi (lớp 2 đến lớp 5) và với các kỹ năng chung không gắn với môn học cụ thể, xu hướng lại nghiêng về cách học trước.</p>\\n<p>Trong phân tích gộp của Sinha và Kapur, phần tự thử luôn được nối tiếp bằng phần giảng giải. Với người chưa biết cú pháp Java, ngồi mò quá lâu dễ thành mất thời gian.</p>\\n<p><strong>Mức bằng chứng:</strong> còn tranh luận — phân tích gộp cho kết quả tích cực, nhưng phần lớn nghiên cứu ở toán và khoa học tự nhiên trong trường phổ thông, hiệu quả đổi theo lứa tuổi và loại kiến thức, và tranh luận giữa dạy có hướng dẫn và học qua khám phá vẫn chưa ngã ngũ.</p>\\n<p>Cách áp dụng: trước phần lời giải của một bài hướng dẫn, dừng video và tự thử 10–15 phút. Sai cũng được. Khi xem lời giải, bạn sẽ chú ý đúng chỗ mình bị kẹt.</p>\\n<h2 id=\\"lo-trinh-nam-bac\\">Lộ trình năm bậc</h2>\\n<p>Đây là cách sắp xếp các ý trên thành từng bậc, chưa có nghiên cứu nào thử nghiệm đúng lộ trình này.</p>\\n<p><strong>Bậc 1: Tự gõ code, không dán.</strong> Mỗi lỗi gõ là một lần đọc lại code kỹ hơn.</p>\\n<p><strong>Bậc 2: Đổi yêu cầu một chút.</strong> Khi code chạy được, tự đặt một yêu cầu gần giống rồi sửa code cho đúng.</p>\\n<p><strong>Bậc 3: Viết lại từ trí nhớ.</strong> Một hai ngày sau, mở file trống và viết lại. Bị kẹt thì chỉ xem đúng chỗ đó, rồi đóng lại và viết tiếp.</p>\\n<p><strong>Bậc 4: Dự án nhỏ có bản mô tả viết trước.</strong> Viết 5–10 dòng: chương trình nhận gì, in ra gì, có chức năng nào. Bản mô tả cho biết khi nào xong.</p>\\n<p><strong>Bậc 5: Đọc tài liệu thay vì tìm video.</strong> Cần một hàm mới thì tra Javadoc trước. Tài liệu không dắt tay từng bước, nên buộc bạn tự ghép các phần lại.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — từng bậc dựa trên các nguyên tắc ở trên (giảm dần dẫn dắt, tự nhớ lại, thử trước khi xem lời giải), nhưng cả lộ trình chưa được kiểm chứng.</p>\\n<h2 id=\\"vi-du-doi-yeu-cau-cua-mot-bai-huong-dan\\">Ví dụ: đổi yêu cầu của một bài hướng dẫn</h2>\\n<p>Bài hướng dẫn dạy hàm <code>filterByLength</code>, giữ lại các từ dài hơn một số ký tự. Yêu cầu mới tự đặt: lọc các từ bắt đầu bằng một tiền tố, không phân biệt chữ hoa chữ thường.</p>\\n<pre><code class=\\"language-java\\">import java.util.List;\\nimport java.util.Locale;\\n\\npublic class Main {\\n    public static void main(String[] args) {\\n        List&lt;String&gt; words = List.of(&quot;Spring&quot;, &quot;java&quot;, &quot;Stream&quot;, &quot;list&quot;, &quot;SQL&quot;, &quot;string&quot;);\\n\\n        // Hàm gốc trong hướng dẫn\\n        System.out.println(filterByLength(words, 5));\\n\\n        // Phiên bản tự sửa\\n        System.out.println(filterByPrefix(words, &quot;s&quot;));\\n        System.out.println(filterByPrefix(words, &quot;ST&quot;));\\n    }\\n\\n    // Hàm gốc: giữ lại các từ dài hơn minLength ký tự\\n    static List&lt;String&gt; filterByLength(List&lt;String&gt; words, int minLength) {\\n        return words.stream()\\n                .filter(w -&gt; w.length() &gt; minLength)\\n                .toList();\\n    }\\n\\n    // Yêu cầu mới: lọc theo tiền tố, không phân biệt hoa thường\\n    static List&lt;String&gt; filterByPrefix(List&lt;String&gt; words, String prefix) {\\n        String p = prefix.toLowerCase(Locale.ROOT);\\n        return words.stream()\\n                .filter(w -&gt; w.toLowerCase(Locale.ROOT).startsWith(p))\\n                .toList();\\n    }\\n}\\n</code></pre>\\n<p>Chạy bằng <code>java Main.java</code> (cần JDK 16 trở lên vì <code>Stream.toList()</code> có từ Java 16; nên dùng bản LTS như 17, 21 hoặc 25), kết quả là:</p>\\n<pre><code>[Spring, Stream, string]\\n[Spring, Stream, SQL, string]\\n[Stream, string]\\n</code></pre>\\n<p>Những điểm phải tự nghĩ ra, không có trong bài gốc:</p>\\n<ul>\\n<li>Phải đổi cả hai phía về chữ thường. Nếu chỉ đổi <code>prefix</code> thì <code>&quot;Spring&quot;</code>, <code>&quot;Stream&quot;</code> và <code>&quot;SQL&quot;</code> đều bị bỏ sót, kết quả chỉ còn <code>[string]</code>.</li>\\n<li><code>prefix</code> được đổi một lần bên ngoài <code>filter</code>, không đổi lại cho mỗi từ.</li>\\n<li><code>Locale.ROOT</code> giữ kết quả không đổi theo cài đặt ngôn ngữ của máy.</li>\\n</ul>\\n<h2 id=\\"ba-y-tuong-du-an-nho\\">Ba ý tưởng dự án nhỏ</h2>\\n<p>Cả ba chạy trên console và chỉ cần kiến thức Java Core.</p>\\n<ul>\\n<li><strong>Quản lý chi tiêu.</strong> Nhập khoản chi (ngày, loại như tiền nhà, ăn uống, số tiền theo won), in tổng theo loại và theo tháng. Mở rộng: lưu ra file CSV.</li>\\n<li><strong>Sổ từ vựng tiếng Hàn.</strong> Lưu cặp từ và nghĩa, ví dụ 출입국 (xuất nhập cảnh), 계약서 (hợp đồng). Có chức năng thêm từ, tìm từ, tự kiểm tra ngẫu nhiên. Mở rộng: hỏi lại nhiều hơn những từ hay sai.</li>\\n<li><strong>Đếm giờ làm thêm theo tuần.</strong> Nhập giờ bắt đầu và kết thúc mỗi ca, tính tổng giờ mỗi tuần và tiền theo mức lương giờ tự nhập. Mở rộng: dùng <code>LocalTime</code> và <code>Duration</code>, xử lý ca qua nửa đêm.</li>\\n</ul>\\n<p>Làm phiên bản nhỏ nhất chạy được trước, rồi mới thêm tính năng.</p>\\n<h2 id=\\"ap-dung-ngay\\">Áp dụng ngay</h2>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1ew1op0\\"><span>Chọn một bài hướng dẫn vừa xem, đóng video và viết lại code từ trí nhớ. Ghi lại những chỗ bị kẹt.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"ng6dzn\\"><span>Với bài hướng dẫn tiếp theo, dừng video trước phần lời giải và tự thử 10–15 phút.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"dnhyn1\\"><span>Đặt hai yêu cầu mới cho một đoạn code đã chạy được và sửa code cho đúng từng yêu cầu.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1o2p9lf\\"><span>Chọn một trong ba dự án ở trên và viết bản mô tả 5–10 dòng trước khi code.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1thbpwv\\"><span>Lần tới cần một hàm mới, tra tài liệu chính thức trước khi tìm video.</span></label></li>\\n</ul>\\n<h2 id=\\"tren-haechivn\\">Trên HaechiVN</h2>\\n<ul>\\n<li><a href=\\"/java\\">Khoá Java</a>: Java Core, OOP và thiết kế, cấu trúc dữ liệu và giải thuật, SQL với Oracle, kiến trúc và chất lượng code, Spring Boot Web API. Mỗi bài có giải thích và ví dụ code, dùng cho bậc 2 và 3: đổi yêu cầu của ví dụ, rồi viết lại từ trí nhớ.</li>\\n<li><a href=\\"/java/java-core\\">Java Core</a>: nền cho cả ba dự án ở trên. Nhiều bài có câu hỏi cuối bài, giúp phân biệt hiểu thật với chỉ thấy quen.</li>\\n<li><a href=\\"/it\\">Khoá C# .NET</a>: áp dụng cùng lộ trình nếu bạn học C#.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://doi.org/10.1146/annurev-psych-113011-143823\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Bjork, Dunlosky &amp; Kornell (2013). Self-regulated learning: Beliefs, techniques, and illusions. Annual Review of Psychology</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1207/S15326985EP3801_3\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Renkl &amp; Atkinson (2003). Structuring the transition from example study to problem solving in cognitive skill acquisition: A cognitive load perspective. Educational Psychologist</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1037/0022-0663.95.4.774\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Atkinson, Renkl &amp; Merrill (2003). Transitioning from studying examples to solving problems: Effects of self-explanation prompts and fading worked-out steps. Journal of Educational Psychology</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1080/07370000802212669\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Kapur (2008). Productive failure. Cognition and Instruction</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.3102/00346543211019105\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Sinha &amp; Kapur (2021). When problem solving followed by instruction works: Evidence for productive failure. Review of Educational Research</a> <span class=\\"source-domain\\">doi.org</span></li>\\n</ul>","headings":[{"id":"vi-sao-lam-theo-huong-dan-cho-cam-giac-da-hoc","text":"Vì sao làm theo hướng dẫn cho cảm giác đã học","level":2},{"id":"rut-dan-su-dan-dat-khong-bo-dot-ngot","text":"Rút dần sự dẫn dắt, không bỏ đột ngột","level":2},{"id":"thu-tu-giai-truoc-khi-xem-loi-giai","text":"Thử tự giải trước khi xem lời giải","level":2},{"id":"lo-trinh-nam-bac","text":"Lộ trình năm bậc","level":2},{"id":"vi-du-doi-yeu-cau-cua-mot-bai-huong-dan","text":"Ví dụ: đổi yêu cầu của một bài hướng dẫn","level":2},{"id":"ba-y-tuong-du-an-nho","text":"Ba ý tưởng dự án nhỏ","level":2},{"id":"ap-dung-ngay","text":"Áp dụng ngay","level":2},{"id":"tren-haechivn","text":"Trên HaechiVN","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":5},{"slug":"debug-co-phuong-phap","title":"Debug có phương pháp","summary":"Cách đọc thông báo lỗi và stack trace của Java, sửa lỗi theo vòng lặp giả thuyết thay vì sửa mò, và nhận ra bốn lỗi người mới hay gặp.","updated":"2026-10-01","facts":{"group":"Học lập trình"},"html":"<p>Chương trình báo lỗi đỏ cả màn hình, và phản xạ đầu tiên của nhiều người mới là sửa thử một dòng bất kỳ rồi chạy lại. Bài này đi qua cách đọc thông báo lỗi của Java, một quy trình sửa lỗi từng bước, và những lỗi kinh điển của người mới học.</p>\\n<h2 id=\\"debug-la-mot-ky-nang-rieng\\">Debug là một kỹ năng riêng</h2>\\n<p>Viết được code và tìm được lỗi trong code là hai việc khác nhau. McCauley và cộng sự (2008) tổng quan các nghiên cứu về dạy và học debug, có những nghiên cứu từ giữa thập niên 1970. Họ kết luận debug vẫn là kỹ năng khó học với người mới lập trình và khó dạy với giáo viên, dù đã có nhiều nghiên cứu.</p>\\n<p>Debug chậm không có nghĩa là &quot;không hợp với lập trình&quot;. Đây là kỹ năng cần luyện riêng.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — một bài tổng quan tài liệu, không phải phân tích gộp; nhận định &quot;debug khó với người mới&quot; được nhiều nghiên cứu trong đó ủng hộ, nhưng tổng quan không đo một phương pháp luyện cụ thể nào.</p>\\n<h2 id=\\"doc-stack-trace-tu-tren-xuong\\">Đọc stack trace từ trên xuống</h2>\\n<p>Chương trình dưới đây đếm số chữ cái trong mỗi tên. Mảng có một phần tử <code>null</code>.</p>\\n<pre><code class=\\"language-java\\">public class Greeting {\\n    public static void main(String[] args) {\\n        String[] names = { &quot;An&quot;, null, &quot;Binh&quot; };\\n        for (String name : names) {\\n            System.out.println(countLetters(name));\\n        }\\n    }\\n\\n    static int countLetters(String name) {\\n        String trimmed = name.trim();\\n        return trimmed.length();\\n    }\\n}\\n</code></pre>\\n<p>Chạy bằng <code>java Greeting.java</code> trên JDK 25, kết quả là:</p>\\n<pre><code>2\\nException in thread &quot;main&quot; java.lang.NullPointerException: Cannot invoke &quot;String.trim()&quot; because &quot;&lt;parameter1&gt;&quot; is null\\n\\tat Greeting.countLetters(Greeting.java:10)\\n\\tat Greeting.main(Greeting.java:5)\\n</code></pre>\\n<p>Đọc từng phần:</p>\\n<ul>\\n<li><code>2</code>: tên đầu tiên chạy đúng, lỗi xảy ra ở phần tử thứ hai.</li>\\n<li><code>Exception in thread &quot;main&quot;</code>: lỗi xảy ra trong luồng chính của chương trình.</li>\\n<li><code>java.lang.NullPointerException</code>: <strong>loại lỗi</strong>. Gọi phương thức trên một biến đang là <code>null</code>.</li>\\n<li><code>Cannot invoke &quot;String.trim()&quot; because &quot;&lt;parameter1&gt;&quot; is null</code>: <strong>thông điệp</strong>. Không gọi được <code>trim()</code> vì tham số thứ nhất của phương thức là <code>null</code>.</li>\\n<li>Các dòng <code>at</code>: <strong>đường đi của lời gọi</strong>, dòng trên cùng là nơi lỗi xảy ra. <code>countLetters</code> ở dòng 10 bị lỗi, và <code>countLetters</code> được gọi từ <code>main</code> ở dòng 5.</li>\\n</ul>\\n<p>Ở đây là <code>&lt;parameter1&gt;</code> chứ không phải tên biến <code>name</code>, vì theo JEP 358 của OpenJDK, tên biến chỉ được in khi biên dịch có thông tin debug (<code>javac -g</code>). Biên dịch <code>javac -g Greeting.java</code> rồi chạy <code>java Greeting</code>, thông điệp đổi thành:</p>\\n<pre><code>Exception in thread &quot;main&quot; java.lang.NullPointerException: Cannot invoke &quot;String.trim()&quot; because &quot;name&quot; is null\\n</code></pre>\\n<p>Nhiều khi dòng trên cùng nằm trong thư viện Java, không phải code của bạn:</p>\\n<pre><code class=\\"language-java\\">public class Age {\\n    public static void main(String[] args) {\\n        String input = &quot;12a&quot;;\\n        int age = Integer.parseInt(input);\\n        System.out.println(age);\\n    }\\n}\\n</code></pre>\\n<pre><code>Exception in thread &quot;main&quot; java.lang.NumberFormatException: For input string: &quot;12a&quot;\\n\\tat java.base/java.lang.NumberFormatException.forInputString(NumberFormatException.java:67)\\n\\tat java.base/java.lang.Integer.parseInt(Integer.java:565)\\n\\tat java.base/java.lang.Integer.parseInt(Integer.java:662)\\n\\tat Age.main(Age.java:4)\\n</code></pre>\\n<p>Ba dòng <code>at java.base/...</code> là code của thư viện chuẩn. Thư viện không sai; nó chỉ báo rằng đầu vào <code>&quot;12a&quot;</code> không phải số. Dòng đầu tiên mang tên lớp của bạn, <code>Age.main(Age.java:4)</code>, là nơi cần xem: dòng 4 đã đưa chuỗi sai vào <code>parseInt</code>.</p>\\n<p>Quy tắc ngắn: đọc loại lỗi, đọc thông điệp, rồi dò các dòng <code>at</code> từ trên xuống cho tới dòng đầu tiên thuộc code của mình.</p>\\n<h2 id=\\"thong-bao-loi-de-hieu-hon-co-giup-khong\\">Thông báo lỗi &quot;dễ hiểu hơn&quot; có giúp không?</h2>\\n<p>Một số nghiên cứu đã thử viết lại thông báo lỗi biên dịch Java cho dễ hiểu hơn, với kết quả chưa thống nhất.</p>\\n<p>Denny, Luxton-Reilly và Carpenter (2014) thử trong một khoá nhập môn lập trình Java ở Đại học Auckland (New Zealand). 83 sinh viên được chia ngẫu nhiên: 42 người nhận thông báo lỗi gốc, 41 người nhận thông báo mở rộng, có giải thích và ví dụ code sai, code đúng. Nhóm tác giả không thấy khác biệt có ý nghĩa thống kê về số lần nộp code không biên dịch được, cũng như số lần thử cần để sửa ba lỗi cú pháp phổ biến nhất. Họ cho rằng có thể sinh viên không đọc phần giải thích dài thêm.</p>\\n<p>Becker và cộng sự (2016) làm một nghiên cứu lớn hơn, khoảng 200 sinh viên với gần 50.000 lỗi, dùng một IDE riêng hiển thị thông báo lỗi Java mở rộng, so với nhóm đối chứng nhận thông báo thường. Nhóm can thiệp giảm tổng số lỗi, số lỗi trên mỗi sinh viên và một số chỉ số lỗi lặp lại. Chính bài báo này ghi nhận rằng hiệu quả của việc mở rộng thông báo lỗi đang được tranh luận.</p>\\n<p>Lưu ý phạm vi: cả hai nghiên cứu đều về lỗi biên dịch (lỗi cú pháp, lỗi kiểu), không phải stack trace lúc chạy, và đều ở sinh viên mới học lập trình. Với người tự học, việc chắc chắn làm được là đọc kỹ thông báo đang có trước khi sửa.</p>\\n<p><strong>Mức bằng chứng:</strong> còn tranh luận — hai nghiên cứu cho kết quả ngược nhau; chưa rõ thông báo mở rộng giúp được ai, trong hoàn cảnh nào.</p>\\n<h2 id=\\"vong-lap-gia-thuyet-thay-cho-sua-mo\\">Vòng lặp giả thuyết thay cho sửa mò</h2>\\n<p>Thay vì sửa ngẫu nhiên, làm theo sáu bước:</p>\\n<ol>\\n<li><strong>Tái hiện lỗi.</strong> Chạy lại và chắc chắn lỗi xuất hiện mỗi lần với cùng đầu vào.</li>\\n<li><strong>Thu hẹp.</strong> Dùng stack trace để tìm dòng của mình. Nếu không có stack trace (chương trình chạy nhưng kết quả sai), bỏ bớt dữ liệu hoặc bỏ bớt code cho tới khi còn ví dụ nhỏ nhất vẫn lỗi.</li>\\n<li><strong>Đặt một giả thuyết.</strong> Viết thành một câu, ví dụ &quot;<code>name</code> là <code>null</code> khi tới phần tử thứ hai&quot;. Chỉ một giả thuyết mỗi lần.</li>\\n<li><strong>Kiểm tra giả thuyết.</strong> In giá trị ra, hoặc đặt breakpoint trong IDE và xem biến.</li>\\n<li><strong>Sửa.</strong> Chỉ sửa đúng chỗ giả thuyết đã xác nhận.</li>\\n<li><strong>Chạy lại.</strong> Kiểm tra lỗi cũ đã hết và các trường hợp đúng trước đó vẫn đúng.</li>\\n</ol>\\n<p>Với ví dụ <code>Greeting</code>, bước 4 có thể là thêm một dòng in tạm:</p>\\n<pre><code class=\\"language-java\\">        for (String name : names) {\\n            System.out.println(&quot;DEBUG name = &quot; + name);\\n            System.out.println(countLetters(name));\\n        }\\n</code></pre>\\n<pre><code>DEBUG name = An\\n2\\nDEBUG name = null\\nException in thread &quot;main&quot; java.lang.NullPointerException: Cannot invoke &quot;String.trim()&quot; because &quot;&lt;parameter1&gt;&quot; is null\\n\\tat Greeting.countLetters(Greeting.java:11)\\n\\tat Greeting.main(Greeting.java:6)\\n</code></pre>\\n<p>Giả thuyết đúng. Số dòng trong stack trace đổi thành 11 và 6 vì đã chèn thêm một dòng. Bước 5: quyết định chương trình nên làm gì với <code>null</code>, ví dụ coi là 0 chữ cái, rồi xoá dòng <code>DEBUG</code>:</p>\\n<pre><code class=\\"language-java\\">    static int countLetters(String name) {\\n        if (name == null) {\\n            return 0;\\n        }\\n        String trimmed = name.trim();\\n        return trimmed.length();\\n    }\\n</code></pre>\\n<p>Chạy lại ra <code>2</code>, <code>0</code>, <code>4</code>. Nếu giả thuyết sai, quay lại bước 3 với một giả thuyết mới, đừng sửa thêm.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — suy rộng: tổng quan của McCauley và cộng sự (2008) cho thấy debug khó với người mới, nhưng chưa có thí nghiệm so sánh trực tiếp quy trình sáu bước với cách sửa mò.</p>\\n<h2 id=\\"bon-loi-kinh-dien-cua-nguoi-moi\\">Bốn lỗi kinh điển của người mới</h2>\\n<p><strong>Lệch một (off-by-one).</strong> Chỉ số mảng chạy từ <code>0</code> tới <code>length - 1</code>.</p>\\n<pre><code class=\\"language-java\\">public class OffByOne {\\n    public static void main(String[] args) {\\n        int[] scores = { 7, 8, 9 };\\n        int sum = 0;\\n        for (int i = 0; i &lt;= scores.length; i++) {\\n            sum += scores[i];\\n        }\\n        System.out.println(sum);\\n    }\\n}\\n</code></pre>\\n<pre><code>Exception in thread &quot;main&quot; java.lang.ArrayIndexOutOfBoundsException: Index 3 out of bounds for length 3\\n\\tat OffByOne.main(OffByOne.java:6)\\n</code></pre>\\n<p>Thông điệp nói đúng vấn đề: mảng dài 3 nhưng truy cập chỉ số 3. Đổi <code>&lt;=</code> thành <code>&lt;</code>, kết quả là <code>24</code>.</p>\\n<p><strong>So sánh chuỗi bằng <code>==</code>.</strong> Với <code>String</code>, <code>==</code> kiểm tra hai biến có trỏ cùng một đối tượng không. Muốn so nội dung thì dùng <code>equals</code>.</p>\\n<pre><code class=\\"language-java\\">import java.util.Scanner;\\n\\npublic class CompareText {\\n    public static void main(String[] args) {\\n        String expected = &quot;java&quot;;\\n        String typed = new Scanner(&quot;java&quot;).next();\\n        System.out.println(typed == expected);\\n        System.out.println(typed.equals(expected));\\n    }\\n}\\n</code></pre>\\n<pre><code>false\\ntrue\\n</code></pre>\\n<p>Hai chuỗi cùng nội dung <code>java</code>, nhưng chuỗi đọc từ <code>Scanner</code> là một đối tượng khác, nên <code>==</code> cho <code>false</code>.</p>\\n<p><strong>Chia số nguyên.</strong> Khi cả hai toán hạng đều là số nguyên (<code>int</code>), Java bỏ phần thập phân (làm tròn về phía 0).</p>\\n<pre><code class=\\"language-java\\">public class Average {\\n    public static void main(String[] args) {\\n        int total = 5;\\n        int count = 2;\\n        System.out.println(total / count);\\n        System.out.println((double) total / count);\\n    }\\n}\\n</code></pre>\\n<pre><code>2\\n2.5\\n</code></pre>\\n<p>Không có thông báo lỗi nào, chỉ có kết quả sai. Đây là lúc bước &quot;đặt giả thuyết và in giá trị&quot; có ích hơn đọc stack trace.</p>\\n<p><strong>NullPointerException.</strong> Đã gặp ở ví dụ <code>Greeting</code>. Trên JDK 25 dùng trong bài, thông điệp cho biết lời gọi nào gặp <code>null</code> và giá trị đó nằm ở tham số hay biến nào (tên biến chỉ hiện khi biên dịch với <code>javac -g</code>). Câu hỏi tiếp theo luôn là: giá trị <code>null</code> này đến từ đâu?</p>\\n<p><strong>Mức bằng chứng:</strong> mạnh — cách chia số nguyên, phép so sánh <code>==</code> và việc ném exception khi vượt chỉ số mảng được quy định trong đặc tả ngôn ngữ Java (JLS); nội dung thông điệp lỗi là của JDK (JEP 358) và đã chạy lại trên JDK 25.</p>\\n<h2 id=\\"giai-thich-code-thanh-loi\\">Giải thích code thành lời</h2>\\n<p>Khi bí, giải thích từng dòng code thành lời, cho một người bạn hoặc thậm chí cho một con vịt cao su đặt trên bàn. Lập trình viên gọi đây là &quot;rubber duck debugging&quot;. Khi phải nói rõ &quot;dòng này lấy phần tử thứ <code>i</code>, mà <code>i</code> chạy tới <code>length</code>&quot;, chỗ hiểu sai thường lộ ra.</p>\\n<p>Cách này gần với tự giải thích (self-explanation) đã nói trong bài <a href=\\"/cam-nang/hoc-tap/doc-code-truoc-viet-sau\\">Đọc code trước, viết code sau</a>. Các nghiên cứu về tự giải thích được làm ở vật lý và sinh học, không phải ở debug.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — suy rộng từ nghiên cứu tự giải thích ở vật lý và sinh học; chưa có nghiên cứu kiểm chứng trực tiếp rubber duck debugging.</p>\\n<h2 id=\\"ap-dung-ngay\\">Áp dụng ngay</h2>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1p9ttfc\\"><span>Lần tới gặp exception, chép stack trace ra và gạch chân loại lỗi, thông điệp, dòng <code>at</code> đầu tiên thuộc code của mình.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1n2xyfs\\"><span>Trước khi sửa, viết giả thuyết thành một câu và kiểm tra nó bằng một dòng in hoặc một breakpoint.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1emq357\\"><span>Cố ý gây bốn lỗi trong bài này trong một file thử, đọc thông báo của từng lỗi, rồi tự sửa.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"qpo0l9\\"><span>Khi bí quá 15 phút, giải thích từng dòng code thành lời trước khi hỏi người khác.</span></label></li>\\n</ul>\\n<h2 id=\\"tren-haechivn\\">Trên HaechiVN</h2>\\n<ul>\\n<li><a href=\\"/java\\">Khoá Java</a> và <a href=\\"/java/java-core\\">Java Core</a>: mỗi bài có giải thích và ví dụ code. Chạy thử ví dụ, cố ý sửa sai một dòng và đọc thông báo lỗi Java đưa ra.</li>\\n<li><a href=\\"/it\\">Khoá C# .NET</a>: cùng cấu trúc; stack trace của C# cũng đọc theo cách từ trên xuống tương tự.</li>\\n<li>Nhiều bài có câu hỏi kiểm tra cuối bài. Xem thêm <a href=\\"/cam-nang/hoc-tap/tu-kiem-tra-thay-vi-doc-lai\\">Tự kiểm tra thay vì đọc lại</a>.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://doi.org/10.1080/08993400802114581\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">McCauley, Fitzgerald, Lewandowski, Murphy, Simon, Thomas &amp; Zander (2008). Debugging: a review of the literature from an educational perspective. Computer Science Education</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1145/2591708.2591748\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Denny, Luxton-Reilly &amp; Carpenter (2014). Enhancing syntax error messages appears ineffectual. ITiCSE 2014</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1080/08993408.2016.1225464\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Becker, Glanville, Iwashima, McDonnell, Goslin &amp; Mooney (2016). Effective compiler error message enhancement for novice programming students. Computer Science Education</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://openjdk.org/jeps/358\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">OpenJDK: JEP 358: Helpful NullPointerExceptions</a> <span class=\\"source-domain\\">openjdk.org</span></li>\\n<li><a href=\\"https://docs.oracle.com/javase/specs/jls/se25/html/jls-15.html\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Oracle: The Java Language Specification, Java SE 25, Chương 15 (15.17.2 phép chia, 15.21.3 so sánh tham chiếu)</a> <span class=\\"source-domain\\">docs.oracle.com</span></li>\\n</ul>","headings":[{"id":"debug-la-mot-ky-nang-rieng","text":"Debug là một kỹ năng riêng","level":2},{"id":"doc-stack-trace-tu-tren-xuong","text":"Đọc stack trace từ trên xuống","level":2},{"id":"thong-bao-loi-de-hieu-hon-co-giup-khong","text":"Thông báo lỗi \\"dễ hiểu hơn\\" có giúp không?","level":2},{"id":"vong-lap-gia-thuyet-thay-cho-sua-mo","text":"Vòng lặp giả thuyết thay cho sửa mò","level":2},{"id":"bon-loi-kinh-dien-cua-nguoi-moi","text":"Bốn lỗi kinh điển của người mới","level":2},{"id":"giai-thich-code-thanh-loi","text":"Giải thích code thành lời","level":2},{"id":"ap-dung-ngay","text":"Áp dụng ngay","level":2},{"id":"tren-haechivn","text":"Trên HaechiVN","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":4},{"slug":"dung-ai-khi-hoc-lap-trinh","title":"Dùng AI khi học lập trình mà không mất kỹ năng","summary":"Nghiên cứu ban đầu nói gì về việc dùng chatbot và công cụ gợi ý code khi học lập trình, và cách đặt luật để AI giúp học thay vì làm thay.","updated":"2026-10-01","facts":{"group":"Học lập trình"},"html":"<p>Chatbot và công cụ gợi ý code bây giờ giải được phần lớn bài tập lập trình cơ bản trong vài giây. Bài làm xong nhanh hơn, nhưng đến lúc phỏng vấn, thi, hoặc gặp lỗi lạ mà không có AI bên cạnh, nhiều người mới nhận ra mình chưa tự viết được. Bài này tổng hợp vài nghiên cứu đầu tiên về chuyện đó và gợi ý cách dùng AI để học.</p>\\n<p>Lĩnh vực này còn rất mới, công cụ thay đổi từng năm, nên mọi kết luận dưới đây chỉ nên xem là tạm thời.</p>\\n<h2 id=\\"lam-bai-tot-hon-chua-chac-la-hoc-duoc-nhieu-hon\\">Làm bài tốt hơn chưa chắc là học được nhiều hơn</h2>\\n<p>Bastani và cộng sự (2025) làm một thí nghiệm chia nhóm ngẫu nhiên tại một trường trung học lớn ở Thổ Nhĩ Kỳ, gần 1.000 học sinh lớp 9 đến 11, môn toán, học kỳ mùa thu năm 2023. Mỗi buổi gồm ba phần: giáo viên ôn lại chủ đề, học sinh luyện bài tập, rồi làm bài kiểm tra không có bất kỳ tài liệu hay công cụ nào. Học sinh được chia ba nhóm khi luyện tập:</p>\\n<ul>\\n<li><strong>GPT Base</strong>: giao diện chat giống chatbot thông thường, dùng GPT-4.</li>\\n<li><strong>GPT Tutor</strong>: cũng GPT-4, nhưng có lời nhắc do giáo viên góp ý, chỉ đưa gợi ý, không đưa đáp án.</li>\\n<li><strong>Đối chứng</strong>: không có AI.</li>\\n</ul>\\n<p>Khi luyện tập có AI, điểm tăng mạnh: cao hơn nhóm đối chứng 48% với GPT Base và 127% với GPT Tutor. Nhưng ở bài kiểm tra không có AI, nhóm GPT Base thấp hơn nhóm đối chứng 17%. Nhóm GPT Tutor không khác nhóm đối chứng có ý nghĩa thống kê. Các tác giả phân tích và cho rằng học sinh nhóm GPT Base dùng AI như &quot;cây nạng&quot; để lấy đáp án, nên sau đó tự làm kém hơn. Học sinh cũng tự đánh giá quá lạc quan về việc AI giúp mình học được bao nhiêu.</p>\\n<p>Chính các tác giả nêu giới hạn: một trường, một môn (toán, không phải lập trình), thời điểm học sinh còn chưa quen chatbot.</p>\\n<p><strong>Mức bằng chứng:</strong> vừa — một thí nghiệm ngẫu nhiên lớn, nhưng ở môn toán và học sinh phổ thông. Áp dụng sang lập trình là suy ra, chưa được kiểm chứng trực tiếp.</p>\\n<h2 id=\\"voi-nguoi-moi-hoc-code-ket-qua-khong-giong-nhau\\">Với người mới học code, kết quả không giống nhau</h2>\\n<p>Kazemitabaar và cộng sự (2023) cho 69 học sinh 10–17 tuổi, mới học Python lần đầu, làm 45 bài viết code. Một nửa được dùng công cụ sinh code Codex. Sau mỗi bài viết code có một bài sửa code tự làm, không có AI.</p>\\n<p>Kết quả: nhóm có Codex hoàn thành nhiều bài hơn (gấp 1,15 lần) và điểm cao hơn (gấp 1,8 lần), đồng thời không kém hơn ở các bài sửa code tự làm. Ở bài kiểm tra sau một tuần, nhóm từng dùng Codex làm tốt hơn một chút nhưng chênh lệch không có ý nghĩa thống kê. Điểm đáng chú ý: những học sinh có điểm kiểm tra đầu vào (bằng Scratch) cao hơn thì làm bài kiểm tra sau một tuần tốt hơn rõ rệt nếu đã từng dùng Codex. Nói cách khác, người có nền tốt hơn hưởng lợi nhiều hơn.</p>\\n<p>Cần lưu ý: môi trường học trong nghiên cứu này được thiết kế riêng, bài tập đi theo thứ tự từ dễ đến khó, và luôn có bài tự làm xen kẽ. Đó không phải tình huống tự học với một chatbot mở hoàn toàn.</p>\\n<p>Prather và cộng sự (2024) quan sát 21 sinh viên môn nhập môn lập trình (CS1) tại một đại học nhỏ ở Mỹ, mỗi người giải một bài trong phòng lab với công cụ gợi ý code trong trình soạn thảo và một chatbot. Nhóm nghiên cứu ghi chép, phỏng vấn và theo dõi chuyển động mắt. 20 trên 21 người làm xong bài. Nhưng có hai nhóm rõ rệt:</p>\\n<ul>\\n<li>Sinh viên làm nhanh dùng AI để viết đúng đoạn code mình đã định viết, và bỏ qua được các gợi ý sai hoặc không hữu ích.</li>\\n<li>Sinh viên gặp khó vẫn mắc các khó khăn quen thuộc của người mới (không biết mình đang kẹt ở đâu, không biết bước tiếp theo), và AI có khi làm các khó khăn đó nặng thêm. Nhiều người nghĩ mình làm tốt hơn thực tế và kết thúc với &quot;ảo giác về năng lực&quot; (illusion of competence).</li>\\n</ul>\\n<p>Tên bài báo, &quot;khoảng cách ngày càng rộng&quot;, nói lên ý chính: AI có thể giúp người đã vững đi nhanh hơn, còn người đang gặp khó dễ tưởng mình đã hiểu.</p>\\n<p><strong>Mức bằng chứng:</strong> còn tranh luận — một thí nghiệm với học sinh nhỏ tuổi trong môi trường thiết kế riêng, một nghiên cứu quan sát 21 người. Hai nghiên cứu chưa mâu thuẫn hẳn, nhưng chưa đủ để kết luận chung cho người lớn tự học Java hay C#.</p>\\n<h2 id=\\"tu-thu-truoc-roi-moi-hoi-ai\\">Tự thử trước, rồi mới hỏi AI</h2>\\n<p>Điểm chung của các nghiên cứu trên: AI giúp hoàn thành bài trong lúc luyện, còn kỹ năng thật được đo khi không có AI. Vì vậy, nên đặt luật trước khi mở chatbot:</p>\\n<ol>\\n<li><strong>Tự làm một lần thật sự.</strong> Đọc đề, viết ra hướng giải, viết code, chạy thử. Đặt giới hạn thời gian, ví dụ 20–30 phút, rồi mới hỏi.</li>\\n<li><strong>Hỏi gợi ý, không hỏi lời giải.</strong> Đây là điểm khác giữa GPT Base và GPT Tutor trong nghiên cứu của Bastani.</li>\\n<li><strong>Không dán vào dự án đoạn code mình không giải thích được.</strong> Nếu không nói được từng dòng làm gì, coi như chưa xong.</li>\\n<li><strong>Viết lại từ trí nhớ.</strong> Một hai ngày sau, đóng chatbot, tự viết lại lời giải. Viết không được thì làm lại bài.</li>\\n</ol>\\n<p><strong>Mức bằng chứng:</strong> vừa — dựa trên kết quả GPT Tutor (chỉ gợi ý) giữ được điểm thi ngang nhóm không dùng AI, trong môn toán. Các bước cụ thể như giới hạn thời gian và viết lại từ trí nhớ là gợi ý thực hành, chưa có nghiên cứu riêng cho từng bước.</p>\\n<h2 id=\\"mau-cau-hoi-dung-duoc-ngay\\">Mẫu câu hỏi dùng được ngay</h2>\\n<p>Các công cụ AI thường làm theo yêu cầu, nên cách hỏi quyết định nó đưa lời giải hay đưa gợi ý. Bốn mẫu dưới đây có thể chép lại và sửa phần trong ngoặc vuông.</p>\\n<p><strong>Xin gợi ý bước tiếp theo:</strong></p>\\n<blockquote>\\n<p>Mình đang học Java. Đừng đưa lời giải và đừng viết code. Đây là đề bài [đề bài] và code mình đã viết [code]. Hãy chỉ ra một chỗ mình nên xem lại và đặt một câu hỏi gợi ý để mình tự nghĩ tiếp.</p>\\n</blockquote>\\n<p><strong>Giải thích thông báo lỗi:</strong></p>\\n<blockquote>\\n<p>Chương trình Java của mình báo lỗi [dán thông báo lỗi]. Hãy giải thích thông báo này nghĩa là gì và thường xảy ra trong tình huống nào. Chưa sửa code giúp mình.</p>\\n</blockquote>\\n<p><strong>Nhờ hỏi kiểm tra:</strong></p>\\n<blockquote>\\n<p>Mình vừa học [chủ đề, ví dụ vòng lặp for và mảng trong Java]. Hãy hỏi mình 5 câu, từng câu một, gồm câu đoán kết quả của đoạn code ngắn. Chờ mình trả lời xong mới chấm và giải thích.</p>\\n</blockquote>\\n<p><strong>Kiểm tra mình hiểu code AI đưa:</strong></p>\\n<blockquote>\\n<p>Đây là đoạn code [code]. Mình sẽ tự giải thích từng dòng bên dưới. Hãy chỉ ra chỗ mình giải thích sai hoặc thiếu, nhưng đừng giải thích lại toàn bộ.</p>\\n</blockquote>\\n<p>Mẫu thứ ba gắn với hiệu ứng kiểm tra (testing effect): tự nhớ lại giúp nhớ lâu hơn đọc lại. Xem thêm bài <a href=\\"/cam-nang/hoc-tap/tu-kiem-tra-thay-vi-doc-lai\\">Tự kiểm tra thay vì đọc lại</a>. Mẫu thứ tư là cách tự giải thích từng dòng, đã nói trong bài <a href=\\"/cam-nang/hoc-tap/doc-code-truoc-viet-sau\\">Đọc code trước, viết code sau</a>.</p>\\n<p>AI cũng có thể giải thích sai hoặc đưa code sai. Câu trả lời nào cũng cần chạy thử và đối chiếu với tài liệu bài học.</p>\\n<h2 id=\\"khong-dan-thong-tin-nhay-cam\\">Không dán thông tin nhạy cảm</h2>\\n<p>Nội dung gõ vào chatbot được gửi tới máy chủ của nhà cung cấp. Không dán mật khẩu, khoá API, chuỗi kết nối cơ sở dữ liệu, dữ liệu khách hàng, hay code nội bộ của công ty. Với code ở công ty, làm theo quy định của công ty về công cụ AI. Khi cần hỏi về một đoạn code có thông tin thật, thay bằng giá trị giả như <code>&quot;YOUR_API_KEY&quot;</code> trước khi dán. Nếu lỡ dán khoá thật, hãy thu hồi khoá đó và tạo khoá mới.</p>\\n<h2 id=\\"ap-dung-ngay\\">Áp dụng ngay</h2>\\n<ul>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1x02x90\\"><span>Viết ra luật riêng: tự làm ít nhất 20–30 phút trước khi hỏi AI.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"191qi13\\"><span>Lưu bốn mẫu câu hỏi ở trên vào ghi chú để dùng lại.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"1odifmk\\"><span>Với bài gần nhất có dùng AI, đóng chatbot và tự viết lại lời giải từ đầu.</span></label></li>\\n<li class=\\"check-item\\"><label><input type=\\"checkbox\\" data-check=\\"8lmy21\\"><span>Xoá mật khẩu, khoá và dữ liệu thật khỏi code trước khi dán vào bất kỳ chatbot nào.</span></label></li>\\n</ul>\\n<h2 id=\\"tren-haechivn\\">Trên HaechiVN</h2>\\n<ul>\\n<li><a href=\\"/java\\">Khoá Java</a> và <a href=\\"/java/java-core\\">Java Core</a>: mỗi bài có giải thích và ví dụ code. Đọc và làm bài trước, chỉ hỏi AI khi đã thử thật sự. Nhiều bài có câu hỏi kiểm tra cuối bài để làm mà không cần AI.</li>\\n<li><a href=\\"/it\\">Khoá C# .NET</a>: cùng cách học nếu bạn học C#.</li>\\n<li><a href=\\"/cam-nang/hoc-tap/nam-lam-tuong-ve-viec-hoc\\">Năm lầm tưởng về việc học</a>: vì sao thấy quen chưa chắc là đã nhớ.</li>\\n</ul>\\n<h2 id=\\"nguon\\">Nguồn</h2>\\n<ul>\\n<li><a href=\\"https://doi.org/10.1073/pnas.2422633122\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Bastani, Bastani, Sungu, Ge, Kabakcı &amp; Mariman (2025). Generative AI without guardrails can harm learning: Evidence from high school mathematics. Proceedings of the National Academy of Sciences, 122(26)</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1145/3544548.3580919\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Kazemitabaar, Chow, Ma, Ericson, Weintrop &amp; Grossman (2023). Studying the effect of AI code generators on supporting novice learners in introductory programming. CHI 2023</a> <span class=\\"source-domain\\">doi.org</span></li>\\n<li><a href=\\"https://doi.org/10.1145/3632620.3671116\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Prather, Reeves, Leinonen, MacNeil, Randrianasolo, Becker, Kimmel, Wright &amp; Briggs (2024). The widening gap: The benefits and harms of generative AI for novice programmers. ICER 2024</a> <span class=\\"source-domain\\">doi.org</span></li>\\n</ul>","headings":[{"id":"lam-bai-tot-hon-chua-chac-la-hoc-duoc-nhieu-hon","text":"Làm bài tốt hơn chưa chắc là học được nhiều hơn","level":2},{"id":"voi-nguoi-moi-hoc-code-ket-qua-khong-giong-nhau","text":"Với người mới học code, kết quả không giống nhau","level":2},{"id":"tu-thu-truoc-roi-moi-hoi-ai","text":"Tự thử trước, rồi mới hỏi AI","level":2},{"id":"mau-cau-hoi-dung-duoc-ngay","text":"Mẫu câu hỏi dùng được ngay","level":2},{"id":"khong-dan-thong-tin-nhay-cam","text":"Không dán thông tin nhạy cảm","level":2},{"id":"ap-dung-ngay","text":"Áp dụng ngay","level":2},{"id":"tren-haechivn","text":"Trên HaechiVN","level":2},{"id":"nguon","text":"Nguồn","level":2}],"checks":4}]}')},579189,n=>{"use strict";var t=n.i(254881);n.i(935100),t.default,n.s(["SCHOOL_FACT_LABELS",0,{nameKo:"Tên tiếng Hàn",city:"Thành phố",kind:"Loại trường",certified:"Chứng nhận quốc tế hoá",topik:"TOPIK tối thiểu",tuition:"Học phí",languageSchool:"Trường tiếng (어학당)"},"articleHref",0,function(n,t){return`/cam-nang/${n}/${t}`},"checklistId",0,function(n,t){return`${n}/${t}`},"formatSchoolFact",0,function(n,t){return"topik"===n&&/^\d$/.test(t)?"0"===t?"Không yêu cầu":`Cấp ${t}`:t},"formatUpdated",0,function(n){let t=/^(\d{4})-(\d{2})-(\d{2})$/.exec(n);return t?`${t[3]}/${t[2]}/${t[1]}`:n},"schoolRegion",0,function(n){return n?/^Seoul\b/.test(n)?"Seoul":/Gyeonggi|Incheon/.test(n)?"Gyeonggi – Incheon":"Tỉnh khác":"Tỉnh khác"},"schoolTopik",0,function(n){if(void 0===n)return null;if(/^\d$/.test(n))return Number(n);if(/^Không/i.test(n))return 0;let t=/^Cấp (\d)/.exec(n);return t?Number(t[1]):null},"schoolTuitionFrom",0,function(n){let t=n?/^(\d+(?:,\d+)?)/.exec(n):null;return t?Number(t[1].replace(",",".")):null}])}]);